INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('411d08ae-aa8b-50cf-a9b6-b77c585258fd', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 1, 1, 'በመጀመሪያ እግዚአብሔር ሰማይንና ምድርን ፈጠረ።'),
  ('86d8457f-063c-503c-a8e8-022f880ae04c', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 2, 2, 'ምድር ግን ባዶ ነበረች፤ አትታይምም ነበር፤ የተዘጋጀችም አልነበረችም፤ ጨለማም በውኃው ላይ ነበረ፤ የእግዚአብሔርም መንፈስ በውኃው ላይ ይሰፍፍ ነበር።'),
  ('876d307f-6f7b-54f7-acf8-df2172d11514', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 3, 3, 'እግዚአብሔርም፥ “ብርሃን ይሁን” አለ፤ ብርሃንም ሆነ።'),
  ('ebe579d5-7538-5186-a227-30e74399bd6c', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 4, 4, 'እግዚአብሔርም ብርሃኑ መልካም እንደሆነ አየ፤ እግዚአብሔርም በብርሃኑና በጨለማው መካከል ለየ።'),
  ('b0bc107c-85e2-58e6-a603-433e5b6e277b', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 5, 5, 'እግዚአብሔርም ብርሃኑን “ቀን፥” ጨለማውንም “ሌሊት” ብሎ ጠራው። ማታም ሆነ፤ ጥዋትም ሆነ፤ አንደኛ ቀንም ሆነ።'),
  ('9e2ab315-d62b-5d17-aa15-da8617a8825e', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 6, 6, 'እግዚአብሔርም፥ “በውኃው መካከል ጠፈር ይሁን፤ በውኃና በውኃ መካከልም ይለይ” አለ፤ እንዲሁም ሆነ።'),
  ('4df5bac6-4009-5985-a0d2-e8a2554190fe', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 7, 7, 'እግዚአብሔርም ጠፈርን አደረገ፤ ከጠፈር በላይና ከጠፈር በታች ያሉትንም ውኆች ለየ።'),
  ('e0f46b15-e71f-5ee3-a0dc-8e694ca6f9d8', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 8, 8, 'እግዚአብሔር ያን ጠፈር “ሰማይ” ብሎ ጠራው። እግዚአብሔርም ያ መልካም እንደሆነ አየ። ማታም ሆነ፤ ጥዋትም ሆነ፤ ሁለተኛም ቀን ሆነ።'),
  ('be74045d-5a27-5ae0-ab34-189c5e016f99', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 9, 9, 'እግዚአብሔርም ከሰማይ በታች ያለው ውኃ በአንድ ስፍራ ይሰብሰብ፥ የብሱም ይገለጥ አለ፤ እንዲሁም ሆነ። ከሰማይ በታች ያለው ውኃም በመጠራቀሚያው ተሰበሰበ፤ የብሱም ተገለጠ።'),
  ('374f2b8f-764c-56f3-a2be-c7014a18ee22', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 10, 10, 'እግዚአብሔርም የብሱን “ምድር” ብሎ ጠራው፤ የውኃ መጠራቀሚያውንም “ባሕር” ብሎ ጠራው። እግዚአብሔርም ያ መልካም እንደሆነ አየ።'),
  ('dcc21340-0471-512a-afb5-9c951bc175e1', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 11, 11, 'እግዚአብሔርም “ምድር በየዘሩ፥ በየወገኑና በየመልኩ ዘር የሚሰጥ ቡቃያን፥ በምድርም ላይ በየወገኑ ዘሩ በውስጡ የሚገኘውንና ፍሬ የሚያፈራውን ዛፍ ታብቅል” አለ፤ እንዲሁም ሆነ።'),
  ('7d1a8f60-c9ba-5e62-a763-69cf6c8f8878', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 12, 12, 'ምድርም በየዘሩ፥ በየወገኑና በየመልኩ የሚዘራ ቡቃያን፥ በምድር ላይ በየወገኑ ዘሩ በውስጡ የሚገኘውንና ፍሬ የሚያፈራውን ዛፍ አበቀለች። እግዚአብሔርም ያ መልካም እንደሆነ አየ።'),
  ('f55accf8-f40b-5096-aeaa-d5f8c5c744e3', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 13, 13, 'ማታም ሆነ፤ ጥዋትም ሆነ። ሦስተኛም ቀን ሆነ።'),
  ('165fe528-85fa-54f2-a647-2846e05a5437', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 14, 14, 'እግዚአብሔርም አለ፥ “በምድር ላይ ያበሩ ዘንድ፥ በቀንና በሌሊትም ይለዩ ዘንድ ብርሃናት በሰማይ ጠፈር ይሁኑ፤ ለምልክቶች፥ ለዘመናት፥ ለዕለታት፥ ለዓመታትም ይሁኑ።'),
  ('86bc30b8-3370-58bc-aff6-eea3905a2418', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 15, 15, 'በምድር ላይ ያበሩ ዘንድ፥ በሰማይ ጠፈር ለማብራት ይሁኑ፤” እንዲሁም ሆነ።'),
  ('4fced064-6531-546f-a796-ff8cfe765e6f', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 16, 16, 'እግዚአብሔርም ሁለት ታላላቅ ብርሃናትን አደረገ፤ ትልቁ ብርሃን ቀንን እንዲመግብ፥ ትንሹ ብርሃንም ከከዋክብት ጋር ሌሊትን እንዲመግብ አደረገ።'),
  ('672c8585-a3d7-5634-aa8f-83f4e2aa175f', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 17, 17, 'እግዚአብሔርም በምድር ላይ ያበሩ ዘንድ በሰማይ ጠፈር አኖራቸው፤'),
  ('b9c0f13d-0f8d-560f-a849-00191b169400', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 18, 18, 'መዓልትንና ሌሊትንም እንዲመግቡ፥ በመዓልትና በሌሊትም መካከል እንዲለዩ፤ እግዚአብሔርም ያ መልካም እንደሆነ አየ።'),
  ('4e33c57a-86ed-5b9a-ad0d-b46977368eba', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 19, 19, 'ማታም ሆነ፤ ጥዋትም ሆነ፤ አራተኛም ቀን ሆነ።'),
  ('8c1bc8cc-e003-5d66-aea9-0068946fa482', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 20, 20, 'እግዚአብሔርም አለ፥ “ውኃ የሕይወት እስትንፋስ ያላቸውን ተንቀሳቃሾችና በምድር ላይ ከሰማይ በታች የሚበርሩ አዕዋፍን ታስገኝ፥” እንዲሁም ሆነ።'),
  ('2e4b7c25-52a5-5285-a54b-81d58707a637', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 21, 21, 'እግዚአብሔርም ታላላቅ አንበሪዎችን፥ ውኃ ያስገኘውን ተንቀሳቃሽ ሕያው ፍጥረትን ሁሉ በየወገኑ፥ የሚበርሩ አዕዋፍንም ሁሉ በየወገናቸው ፈጠረ። እግዚአብሔርም ያ መልካም እንደሆነ አየ።'),
  ('f8115141-891b-5b78-a89b-9f246bce9045', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 22, 22, 'እግዚአብሔርም እንዲህ ብሎ ባረካቸው፥ “ብዙ፤ ተባዙም፤ የባሕርንም ውኃ ሙሉአት፤ ወፎችም በምድር ላይ ይብዙ።”'),
  ('839d79a9-2955-5f24-a0bf-1266ff550e0a', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 23, 23, 'ማታም ሆነ፤ ጥዋትም ሆነ፤ አምስተኛም ቀን ሆነ።'),
  ('39919169-8a0c-57f4-af5d-97f22286c4b8', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 24, 24, 'እግዚአብሔርም አለ፥ “ምድር ሕያዋን ፍጥረታትን እንደ ወገኑ፥ እንስሳትንና ተንቀሳቃሾችን፥ የምድር አራዊትንም እንደየወገኑ ታውጣ፥” እንዲሁም ሆነ።'),
  ('14e75da8-5cdf-53ee-a851-28e21c3b0f26', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 25, 25, 'እግዚአብሔርም የምድር አራዊትን እንደየወገኑ፥ እንስሳትንም እንደየወገኑ፥ በምድር የሚንቀሳቀሰውንም ሁሉ እንደየወገኑ አደረገ፤ እግዚአብሔርም ያ መልካም እንደሆነ አየ።'),
  ('4e0856ee-5d7c-50eb-a708-d25f4bb305d5', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 26, 26, 'እግዚአብሔርም አለ፥ “ሰውን በአርኣያችንና በአምሳላችን እንፍጠር፤ የባሕር ዓሣዎችንና የምድር አራዊትን፥ የሰማይ ወፎችን፥ እንስሳትንና ምድርን ሁሉ፥ በምድርም ላይ የሚንቀሳቀሱትን ሁሉ ይግዛ።”'),
  ('50c3a860-8ea9-5e10-af0c-138b0e82f69f', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 27, 27, 'እግዚአብሔርም ሰውን በእግዚአብሔር አምሳል ፈጠረው። ወንድና ሴት አድርጎ ፈጠራቸው።'),
  ('2d24543d-56d5-5a45-a0af-4eb5557df64f', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 28, 28, 'እግዚአብሔርም ባረካቸው፤ እንዲህም አላቸው፥ “ብዙ፤ ተባዙ፤ ምድርንም ሙሉአት፤ ግዙአትም፤ የባሕርን ዓሣዎችንና የምድር አራዊትን፥ የሰማይ ወፎችንና እንስሳትንም ሁሉ፥ በምድር ላይ የሚንቀሳቀሱትንም ሁሉ ግዙአቸው።”'),
  ('900b0160-7853-5cc9-ab25-26452f99c525', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 29, 29, 'እግዚአብሔርም አለ፥ “እነሆ፥ መብል ይሆናችሁ ዘንድ በየዘሩ የሚዘራውንና የሚበቅለውን፥ በምድር ሁሉ ላይ የምትዘሩትን የእህል ፍሬ፥ ዘሩ በውስጡ ያለውን ቡቃያ፥ በየፍሬውም የሚዘራውን ዛፍ ሁሉ ሰጠኋችሁ።'),
  ('7a37030c-cce1-5d39-a526-fd12b0a4c695', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 30, 30, 'ለምድር አራዊት ሁሉ፥ ለሰማይም ወፎች ሁሉ፥ ሕያው ነፍስ ላላቸው ለምድር ተንቀሳቃሾችም ሁሉ ሐመልማሉ ሁሉ መብል ይሁንላችሁ።” እንዲሁም ሆነ።'),
  ('0166f994-fb5f-59cd-aeb1-7b3e3e2e8dc3', 'e4a2323f-b8c7-5123-a96d-0c54e3590c22', '5c48898e-c58b-5d44-a325-002a7ec4f4e1', 31, 31, 'እግዚአብሔርም የፈጠረውን ሁሉ እጅግ መልካም እንደሆነ አየ። ማታም ሆነ፤ ጥዋትም ሆነ፤ ስድስተኛም ቀን ሆነ።'),
  ('ddfea9b0-5608-558a-a840-8dde70d0402c', 'f4f196fe-7af5-584b-a2ff-043b52ec4cf0', '0e120803-87df-538d-a80d-e300779693d9', 1, 1, 'ሰማይና ምድር ዓለማቸውም ሁሉ ተፈጸሙ።'),
  ('27d2b6a5-af2c-58e8-a31a-4e529c45f912', 'f4f196fe-7af5-584b-a2ff-043b52ec4cf0', '0e120803-87df-538d-a80d-e300779693d9', 2, 2, 'እግዚአብሔርም የሠራውን ሥራ በስድስተኛው ቀን ፈጸመ፤ እግዚአብሔርም በሰባተኛው ቀን ከሠራው ሥራ ሁሉ ዐረፈ።'),
  ('a1d57d70-0d7b-5700-a44f-4bb37b8353aa', 'f4f196fe-7af5-584b-a2ff-043b52ec4cf0', '0e120803-87df-538d-a80d-e300779693d9', 3, 3, 'እግዚአብሔር ሰባተኛዋን ቀን ባረካት፤ ቀደሳትም፤ ሊፈጥረው ከጀመረው ሥራ ሁሉ በእርስዋ ዐርፎአልና።'),
  ('ab52b33f-5ffb-579d-a93a-6b185d449529', 'f4f196fe-7af5-584b-a2ff-043b52ec4cf0', '0e120803-87df-538d-a80d-e300779693d9', 4, 4, 'እግዚአብሔር አምላክ ሰማይንና ምድርን በፈጠረበት ቀን፥ በተፈጠሩ ጊዜ የሰማይና የምድር ፍጥረት ይህ ነው።'),
  ('473655d5-8979-5b83-a8f5-2a1a5a8fe196', 'f4f196fe-7af5-584b-a2ff-043b52ec4cf0', '0e120803-87df-538d-a80d-e300779693d9', 5, 5, 'የሜዳ ቍጥቋጦ ሁሉ በምድር ላይ ከመኖሩ በፊት፥ የሜዳውም ቡቃያ ሁሉ ከመብቀሉ በፊት፥ አዳምም ከመፈጠሩ በፊት፥ እግዚአብሔር አምላክ በምድር ላይ አላዘነበም ነበር፤ ምድርንም የሚሠራባት ሰው አልነበረም።'),
  ('274da9ce-9cae-541c-a872-8cb6bca6a417', 'f4f196fe-7af5-584b-a2ff-043b52ec4cf0', '0e120803-87df-538d-a80d-e300779693d9', 6, 6, 'ነገር ግን የውኃ ምንጭ ከምድር ይወጣ ነበር፤ የምድርንም ፊት ሁሉ ያጠጣ ነበር።'),
  ('90fa2856-f02c-502f-ab78-d375a7dc13b8', 'f4f196fe-7af5-584b-a2ff-043b52ec4cf0', '0e120803-87df-538d-a80d-e300779693d9', 7, 7, 'እግዚአብሔር አምላክም ሰውን ከምድር አፈር ፈጠረው፤ በፊቱም የሕይወት እስትንፋስን እፍ አለበት፤ ሰውም ሕያው ነፍስ ያለው ሆነ።'),
  ('7477bf99-ff69-54c3-a916-2876801ee92e', 'f4f196fe-7af5-584b-a2ff-043b52ec4cf0', '9cc1bf86-b653-5d16-a82a-d5478d9f3d8a', 1, 8, 'እግዚአብሔር አምላክም በኤዶም በስተምሥራቅ ገነትን ተከለ፤ የፈጠረውንም ሰው በዚያ አኖረው።'),
  ('3e0ee11e-bd36-567c-a0c9-cb7c5fb094e8', 'f4f196fe-7af5-584b-a2ff-043b52ec4cf0', '9cc1bf86-b653-5d16-a82a-d5478d9f3d8a', 2, 9, 'እግዚአብሔር አምላክም ለማየት ደስ የሚያሰኘውን፥ ለመብላትም መልካም የሆነውን ዛፍ ሁሉ ደግሞ ከምድር አበቀለ፤ በገነትም መካከል የሕይወትን ዛፍ፥ መልካምንና ክፉን የሚያሳየውንና የሚያስታውቀውንም ዛፍ አበቀለ።'),
  ('e3c6fd35-5b49-502c-adfc-33988bc2c329', 'f4f196fe-7af5-584b-a2ff-043b52ec4cf0', '9cc1bf86-b653-5d16-a82a-d5478d9f3d8a', 3, 10, 'ወንዝም ገነትን ያጠጣ ዘንድ ከኤዶም ይወጣ ነበር፤ ከዚያም ለዐራት መዓዝን ይከፈል ነበር።'),
  ('ba280627-cba0-5af7-aff4-ea23e6e84e29', 'f4f196fe-7af5-584b-a2ff-043b52ec4cf0', '9cc1bf86-b653-5d16-a82a-d5478d9f3d8a', 4, 11, 'የአንደኛው ወንዝ ስም ኤፌሶን ነው፤ እርሱም ወርቅ የሚገኝበትን የኤውላጥ ምድርን ይከብባል።'),
  ('8fc4d0eb-54ab-51be-a4d0-ca9f054d3ac4', 'f4f196fe-7af5-584b-a2ff-043b52ec4cf0', '9cc1bf86-b653-5d16-a82a-d5478d9f3d8a', 5, 12, 'የዚያችም ምድር ወርቅ ጥሩ ነው።'),
  ('fb262297-a6c3-589f-a9c2-151aef40df3b', 'f4f196fe-7af5-584b-a2ff-043b52ec4cf0', '9cc1bf86-b653-5d16-a82a-d5478d9f3d8a', 6, 13, 'በዚያም የሚያበራ ዕንቍና የሚያብረቀርቅ ዕንቍ አለ። የሁለተኛውም ወንዝ ስም ግዮን ነው፤ እርሱም የኢትዮጵያን ምድር ሁሉ ይከብባል፤'),
  ('6e4f53d3-b7bb-5d02-a876-8c77dc862570', 'f4f196fe-7af5-584b-a2ff-043b52ec4cf0', '9cc1bf86-b653-5d16-a82a-d5478d9f3d8a', 7, 14, 'የሦስተኛውም ወንዝ ስም ጤግሮስ ነው፤ እርሱም በአሶር ላይ የሚሄድ ነው። አራተኛውም ወንዝ ኤፍራጥስ ነው።'),
  ('2210b652-0f1f-5efc-a213-20090aa61d24', 'f4f196fe-7af5-584b-a2ff-043b52ec4cf0', '9cc1bf86-b653-5d16-a82a-d5478d9f3d8a', 8, 15, 'እግዚአብሔር አምላክም ሰውን ወስዶ ያበጃትም፥ ይጠብቃትም ዘንድ በኤዶም ገነት አኖረው።'),
  ('8d42c9a8-8dec-58f0-a414-6b38bd5210cc', 'f4f196fe-7af5-584b-a2ff-043b52ec4cf0', '9cc1bf86-b653-5d16-a82a-d5478d9f3d8a', 9, 16, 'እግዚአብሔር አምላክም አዳምን እንዲህ ብሎ አዘዘው፥ “በገነት ካለው ዛፍ ሁሉ ብላ፤'),
  ('d17e00f9-89b1-588c-a361-7fdb7dfceec3', 'f4f196fe-7af5-584b-a2ff-043b52ec4cf0', '9cc1bf86-b653-5d16-a82a-d5478d9f3d8a', 10, 17, 'ነገር ግን መልካምንና ክፉን ከሚያሳየውና ከሚያስታውቀው ዛፍ አትብላ፤ ከእርሱ በበላህ ቀን ሞትን ትሞታለህና።”'),
  ('bafed9b2-5957-514a-a9d0-8e3ab8ee31a1', 'f4f196fe-7af5-584b-a2ff-043b52ec4cf0', '9cc1bf86-b653-5d16-a82a-d5478d9f3d8a', 11, 18, 'እግዚአብሔር አምላክም አለ፥ “ሰው ብቻውን ይኖር ዘንድ መልካም አይደለም፤ የሚረዳውን ጓደኛ እንፍጠርለት እንጂ።”'),
  ('d474eb1c-b9a8-5e40-afea-3c2fea6b8dd5', 'f4f196fe-7af5-584b-a2ff-043b52ec4cf0', '9cc1bf86-b653-5d16-a82a-d5478d9f3d8a', 12, 19, 'እግዚአብሔር አምላክም የምድር አራዊትንና የሰማይ ወፎችን ሁሉ ደግሞ ከምድር ፈጠረ፤ በምን ስም እንደሚጠራቸውም ያይ ዘንድ ወደ አዳም አመጣቸው፤ አዳምም ሕያው ነፍስ ላለው ሁሉ በስሙ እንደጠራው ስሙ ያው ሆነ።'),
  ('9b2ef8fd-0a06-5447-a8ff-f1e05a961223', 'f4f196fe-7af5-584b-a2ff-043b52ec4cf0', '9cc1bf86-b653-5d16-a82a-d5478d9f3d8a', 13, 20, 'አዳምም ለእንስሳት ሁሉ፥ ለሰማይ ወፎችም ሁሉ፥ ለምድር አራዊትም ሁሉ ስም አወጣላቸው። ነገር ግን ለአዳም እንደ እርሱ ያለ ረዳት አልተገኘለትም ነበር።'),
  ('5fb0fb9b-3b36-58aa-a267-13dc58c13cb6', 'f4f196fe-7af5-584b-a2ff-043b52ec4cf0', '9cc1bf86-b653-5d16-a82a-d5478d9f3d8a', 14, 21, 'እግዚአብሔር አምላክም በአዳም ላይ እንቅልፍን አመጣ፤ አንቀላፋም ፤ ከጎኑም አጥንቶች አንድ አጥንትን ወስዶ ስፍራውን በሥጋ መላው።'),
  ('b87e7895-4dec-556b-afd5-409ac9578805', 'f4f196fe-7af5-584b-a2ff-043b52ec4cf0', '9cc1bf86-b653-5d16-a82a-d5478d9f3d8a', 15, 22, 'እግዚአብሔር አምላክም ከአዳም የወሰዳትን አጥንት ሴት አድርጎ ሠራት፤ ወደ አዳምም አመጣት።'),
  ('249d233b-3ad7-5515-ab61-7762dbd4e62d', 'f4f196fe-7af5-584b-a2ff-043b52ec4cf0', '9cc1bf86-b653-5d16-a82a-d5478d9f3d8a', 16, 23, 'ያን ጊዜም አዳም አለ፥ “ይህች አጥንት ከአጥንቴ ናት፤ ሥጋዋም ከሥጋዬ ናት፤ እርስዋ ከባልዋ ተገኝታለችና ሚስት ትሁነኝ።”'),
  ('03a74855-81c2-5996-a910-75b5ec2436f6', 'f4f196fe-7af5-584b-a2ff-043b52ec4cf0', '9cc1bf86-b653-5d16-a82a-d5478d9f3d8a', 17, 24, 'ስለዚህ ሰው አባቱንና እናቱን ይተዋል፤ ሚስቱንም ይከተላል ፤ ሁለቱም አንድ ሥጋ ይሆናሉ።'),
  ('0095ca22-a31c-53cb-ae1c-a866d4c42296', 'f4f196fe-7af5-584b-a2ff-043b52ec4cf0', '9cc1bf86-b653-5d16-a82a-d5478d9f3d8a', 18, 25, 'አዳምና ሚስቱም ዕራቁታቸውን ነበሩ፤ አይተፋፈሩም ነበር።'),
  ('1b3d8b1b-bedc-5ca9-a21b-1054016ba1ee', '3ca65f92-2679-55c3-a21d-d4822af34dd7', '66744c33-f68a-5c68-abce-3a53c901eda0', 1, 1, 'እባብም እግዚአብሔር አምላክ ከፈጠራቸው ከምድር አራዊት ሁሉ ይልቅ ተንኰለኛ ነበር። እባብም ሴቲቱን “እግዚአብሔር በገነት ካለው ዛፍ ሁሉ አትብሉ ያላችሁ ለምንድን ነው?” አላት።'),
  ('cc1c582f-f236-5e69-a0da-0b76ae91b50d', '3ca65f92-2679-55c3-a21d-d4822af34dd7', '66744c33-f68a-5c68-abce-3a53c901eda0', 2, 2, 'ሴቲቱም ለእባቡ አለችው፥ “በገነት መካከል ካለው ከሚያፈራው ዛፍ ፍሬ እንበላለን፤'),
  ('ece09501-5a40-537f-a44c-fdf5468828ef', '3ca65f92-2679-55c3-a21d-d4822af34dd7', '66744c33-f68a-5c68-abce-3a53c901eda0', 3, 3, 'ነገር ግን በገነት መካከል ካለው ከዛፉ ፍሬ፥ እግዚአብሔር አለ፦ እንዳትሞቱ ከእርሱ አትብሉ፤ አትንኩትም።”'),
  ('fa8cc3d0-cfb6-55b8-aa7c-6dd0864f0a27', '3ca65f92-2679-55c3-a21d-d4822af34dd7', '66744c33-f68a-5c68-abce-3a53c901eda0', 4, 4, 'እባብም ለሴቲቱ አላት፥ “ሞትን አትሞቱም፤'),
  ('7c52fd23-3d0a-5fd8-a5a4-d6babd689a90', '3ca65f92-2679-55c3-a21d-d4822af34dd7', '66744c33-f68a-5c68-abce-3a53c901eda0', 5, 5, 'ከእርስዋ በበላችሁ ቀን፥ ዐይኖቻችሁ እንዲከፈቱ፥ እንደ እግዚአብሔርም እንደምትሆኑ፥ መልካምንና ክፉን እንደምታውቁ እግዚአብሔር ስለሚያውቅ ነው እንጂ።”'),
  ('d5490c49-4ad3-5687-ac37-1a62edd9b33c', '3ca65f92-2679-55c3-a21d-d4822af34dd7', '66744c33-f68a-5c68-abce-3a53c901eda0', 6, 6, 'ሴቲቱም ዛፉ ለመብላት ያማረ እንደሆነ፥ ለዐይንም ለማየት እንደሚያስጐመጅ፥ መልካምንም እንደሚያሳውቅ ባየች ጊዜ፥ ከፍሬው ወሰደችና በላች፤ ለባልዋም ደግሞ ሰጠችው፤ እርሱም ከእርስዋ ጋር በላ።'),
  ('7ecfe29a-9660-5367-acd3-63f1f2c78e10', '3ca65f92-2679-55c3-a21d-d4822af34dd7', '66744c33-f68a-5c68-abce-3a53c901eda0', 7, 7, 'የሁለቱም ዐይኖች ተከፈቱ፤ እነርሱም ዕራቁታቸውን እንደ ሆኑ ዐወቁ፤ አፈሩም፤ የበለስንም ቅጠሎች ሰፍተው ለእነርሱ ለራሳቸው ግልድም አደረጉ።'),
  ('77c6a0ec-fca2-5df6-ac6c-ac0c2e5f426f', '3ca65f92-2679-55c3-a21d-d4822af34dd7', '66744c33-f68a-5c68-abce-3a53c901eda0', 8, 8, 'እነርሱም ቀኑ በመሸ ጊዜ የእግዚአብሔርን የአምላክን ድምፅ በገነት ውስጥ ሲመላለስ ሰሙ፤ አዳምና ሚስቱም ከእግዚአብሔር ከአምላክ ፊት በገነት ዛፎች መካከል ተሸሸጉ።'),
  ('8fa7b8bb-e3fe-573c-af4f-316e51b2a3c4', '3ca65f92-2679-55c3-a21d-d4822af34dd7', '66744c33-f68a-5c68-abce-3a53c901eda0', 9, 9, 'እግዚአብሔር አምላክም አዳምን ጠርቶ፥ “አዳም፥ ወዴት አለህ?” አለው።'),
  ('ddb42299-4b6b-5530-a30a-960a9404d9c5', '3ca65f92-2679-55c3-a21d-d4822af34dd7', '66744c33-f68a-5c68-abce-3a53c901eda0', 10, 10, 'አዳምም አለ፥ “በገነት ስትመላለስ ድምፅህን ሰማሁ፤ ዕራቁቴንም ስለሆንሁ ፈራሁ፤ ተሸሸግሁም።”'),
  ('0cdf49da-1511-5172-a48b-a7900cc3c09f', '3ca65f92-2679-55c3-a21d-d4822af34dd7', '66744c33-f68a-5c68-abce-3a53c901eda0', 11, 11, 'እግዚአብሔርም አለው፥ “ዕራቁትህን እንደሆንህ ማን ነገረህ? ከእርሱ እንዳትበላ ካዘዝሁህ ዛፍ በውኑ በላህን?”'),
  ('11b343d1-653e-506b-af53-455b29db52e5', '3ca65f92-2679-55c3-a21d-d4822af34dd7', '66744c33-f68a-5c68-abce-3a53c901eda0', 12, 12, 'አዳምም አለ፥ “ከእኔ ጋር እንድትሆን የሰጠኸኝ ሴት እርስዋ ከዛፉ ሰጠችኝና በላሁ።”'),
  ('6404044c-370e-5f95-afee-b085e9c20ed2', '3ca65f92-2679-55c3-a21d-d4822af34dd7', '66744c33-f68a-5c68-abce-3a53c901eda0', 13, 13, 'እግዚአብሔር አምላክም ሴቲቱን፥ “ይህን ለምን አደረግሽ?” አላት። ሴቲቱም አለች፥ “እባብ አሳተኝና በላሁ።”'),
  ('00f08868-fde2-585e-a9d2-f37381dd926a', '3ca65f92-2679-55c3-a21d-d4822af34dd7', 'f93bfcf0-cbc9-5f34-a1f0-3076ee88f2b9', 1, 14, 'እግዚአብሔር አምላክም እባቡን አለው፥ “ይህን ስላደረግህ ከእንስሳት ሁሉ፥ ከምድር አራዊትም ሁሉ ተለይተህ አንተ የተረገምህ ሁን ፤ በደረትህና በሆድህም ትሄዳለህ፤ በሕይወትህም ዘመን ሁሉ አፈርን ትበላለህ።'),
  ('d1933cb8-52d5-5fb1-ae97-46b1fb5f70f1', '3ca65f92-2679-55c3-a21d-d4822af34dd7', 'f93bfcf0-cbc9-5f34-a1f0-3076ee88f2b9', 2, 15, 'በአንተና በሴቲቱ መካከል፥ በዘርህና በዘርዋም መካከል ጠላትነትን አደርጋለሁ፤ እርሱ ራስህን ይቀጠቅጣል፤ አንተም ሰኰናውን ትነድፋለህ።”'),
  ('2b980bfe-6750-5f9f-a2a6-f994f4c28c0a', '3ca65f92-2679-55c3-a21d-d4822af34dd7', 'f93bfcf0-cbc9-5f34-a1f0-3076ee88f2b9', 3, 16, 'ለሴቲቱም እግዚአብሔር አላት፥ “ጭንቅሽን እጅግ አበዛለሁ፤ በጭንቅ ትወልጃለሽ፤ ከወለድሽም በኋላ ፈቃድሽ ወደ ባልሽ ይሆናል፤ እርሱም ይገዛሻል።”'),
  ('115dc3a2-03c6-5dad-a9d5-f82f40fb9c99', '3ca65f92-2679-55c3-a21d-d4822af34dd7', 'f93bfcf0-cbc9-5f34-a1f0-3076ee88f2b9', 4, 17, 'እግዚአብሔርም አዳምን አለው፥ “የሚስትህን ቃል ሰምተሃልና፥ ከእርሱ እንዳትበላ ከአዘዝሁህ ከዚያ ዛፍም በልተሃልና ምድር በሥራህ የተረገመች ትሁን፤ በሕይወት ዘመንህም ሁሉ በድካም ከእርስዋ ትበላለህ፤'),
  ('1bd815d8-f8e4-5194-a08b-9aaaa8068939', '3ca65f92-2679-55c3-a21d-d4822af34dd7', 'f93bfcf0-cbc9-5f34-a1f0-3076ee88f2b9', 5, 18, 'እሾህንና አሜከላን ታበቅልብሃለች፤ የምድርንም ቡቃያ ትበላለህ።'),
  ('54ed383e-f3bb-5fb7-a8d0-a05392f95605', '3ca65f92-2679-55c3-a21d-d4822af34dd7', 'f93bfcf0-cbc9-5f34-a1f0-3076ee88f2b9', 6, 19, 'ወደ ወጣህበት መሬት እስክትመለስ ድረስ በፊትህ ወዝ እንጀራህን ትበላለህ፤ አፈር ነህና ወደ አፈርም ትመለሳለህና።”'),
  ('6fbcd1af-a14d-5194-a7e2-7540ffe6235e', '3ca65f92-2679-55c3-a21d-d4822af34dd7', 'f93bfcf0-cbc9-5f34-a1f0-3076ee88f2b9', 7, 20, 'አዳምም ለሚስቱ “ሔዋን” ብሎ ስም አወጣ፤ የሕያዋን ሁሉ እናት ናትና።'),
  ('6852930e-b7ce-570a-a310-3e64b7c8f4d1', '3ca65f92-2679-55c3-a21d-d4822af34dd7', 'f93bfcf0-cbc9-5f34-a1f0-3076ee88f2b9', 8, 21, 'እግዚአብሔር አምላክም ለአዳምና ለሚስቱ የቁርበትን ልብስ አደረገላቸው፥ አለበሳቸውም።'),
  ('2ab09c85-75dd-5794-a391-c6465aa2b36a', '3ca65f92-2679-55c3-a21d-d4822af34dd7', 'e8f10b88-ddcb-522c-a360-433a85d9d44d', 1, 22, 'እግዚአብሔር አምላክም አለ፥ “እነሆ፥ አዳም መልካምንና ክፉን ለማወቅ ከእኛ እንደ አንዱ ሆነ፤ አሁንም እጁን እንዳይዘረጋ፥ ደግሞም ከሕይወት ዛፍ ወስዶ እንዳይበላ፥ ለዘለዓለምም ሕያው ሆኖ እንዳይኖር፥”'),
  ('2a398aca-f18e-5b9d-a515-be7f4042d394', '3ca65f92-2679-55c3-a21d-d4822af34dd7', 'e8f10b88-ddcb-522c-a360-433a85d9d44d', 2, 23, 'ስለዚህ የተገኘባትን መሬት ያርስ ዘንድ እግዚአብሔር አምላክ ደስታ ከሚገኝባት ገነት አስወጣው።'),
  ('15c5a4a7-01fa-5908-af02-fd5c7692ec7f', '3ca65f92-2679-55c3-a21d-d4822af34dd7', 'e8f10b88-ddcb-522c-a360-433a85d9d44d', 3, 24, 'አዳምንም አስወጣው፤ ደስታ በሚገኝባት በገነት አንጻርም አኖረው፤ ወደ ሕይወት ዛፍ የሚወስደውንም መንገድ ለመጠበቅ የምትገለባበጥ የነበልባል ሰይፍን በእጃቸው የያዙ ኪሩቤልን አዘዛቸው።'),
  ('390146e9-4c15-50f8-a0f0-7558c8d1954b', 'a316a3e6-70db-5c64-a808-c32c207f4fd3', '1356cd78-aa88-54ac-ad14-8124e8edffd1', 1, 1, 'አዳምም ሚስቱን ሔዋንን ዐወቃት፤ ፀነሰችም፤ ቃየልንም ወለደችው።'),
  ('66ac4f53-dee6-57ab-ae3e-9e3834e4d86b', 'a316a3e6-70db-5c64-a808-c32c207f4fd3', '1356cd78-aa88-54ac-ad14-8124e8edffd1', 2, 2, 'እርስዋም “ወንድ ልጅ ከእግዚአብሔር አገኘሁ” አለች። ደግሞም ወንድሙን አቤልን ወለደችው። አቤልም በግ ጠባቂ ሆነ፤ ቃየልም ምድርን የሚያርስ ሆነ።'),
  ('cd49c3da-618c-55f4-a283-3894da795228', 'a316a3e6-70db-5c64-a808-c32c207f4fd3', '1356cd78-aa88-54ac-ad14-8124e8edffd1', 3, 3, 'ከብዙ ቀን በኋላም እንዲህ ሆነ፤ ቃየል ከምድር ፍሬ ለእግዚአብሔር መሥዋዕትን አቀረበ፤'),
  ('fd70b222-935f-54cf-a123-95b1b7992859', 'a316a3e6-70db-5c64-a808-c32c207f4fd3', '1356cd78-aa88-54ac-ad14-8124e8edffd1', 4, 4, 'አቤልም ደግሞ ከበጎቹ መጀመሪያ የተወለደውንና ከሰቡት አቀረበ። እግዚአብሔርም ወደ አቤልና ወደ መሥዋዕቱ ተመለከተ፤'),
  ('baa47a38-6ad7-5dde-ac1f-2bdc2b76ae43', 'a316a3e6-70db-5c64-a808-c32c207f4fd3', '1356cd78-aa88-54ac-ad14-8124e8edffd1', 5, 5, 'ወደ ቃየልና ወደ መሥዋዕቱ ግን አልተመለከተም። ቃየልንም እጅግ አሳዘነው፤ ፊቱም ጠቈረ።'),
  ('322afc44-9f94-5ae6-a0de-63a8d60ad0e8', 'a316a3e6-70db-5c64-a808-c32c207f4fd3', '1356cd78-aa88-54ac-ad14-8124e8edffd1', 6, 6, 'እግዚአብሔር አምላክም ቃየልን አለው፥ “ለምን ታዝናለህ? ለምንስ ፊትህ ጠቈረ?'),
  ('cab2fe43-c160-5fbb-abc1-36666eda0b65', 'a316a3e6-70db-5c64-a808-c32c207f4fd3', '1356cd78-aa88-54ac-ad14-8124e8edffd1', 7, 7, 'በእውነት ያመጣህልኝ አይደለም፤ አግባብስ በእውነት ታመጣልኝ ዘንድ ነበር። በደልህ፤ እንግዲህ ዝም በል፤ የወንድምህ መመለሻው ወደ አንተ ነው፤ አንተም ትሰለጥንበታለህ።”'),
  ('e5871937-ddad-5ed2-ad49-b3c69940247a', 'a316a3e6-70db-5c64-a808-c32c207f4fd3', '1356cd78-aa88-54ac-ad14-8124e8edffd1', 8, 8, 'ቃየልም ወንድሙን አቤልን፥ “ና ወደ ሜዳ እንሂድ” አለው። በሜዳም ሳሉ ቃየል በወንድሙ በአቤል ላይ ተነሣበት፤ ገደለውም።'),
  ('8f38d529-5f5b-5ae4-a9af-d2bd4a11c858', 'a316a3e6-70db-5c64-a808-c32c207f4fd3', '1356cd78-aa88-54ac-ad14-8124e8edffd1', 9, 9, 'እግዚአብሔርም ቃየልን አለው፥ “ወንድምህ አቤል ወዴት ነው?” ቃየልም አለ፥ “አላውቅም፤ በውኑ የወንድሜ ጠባቂው እኔ ነኝን?”'),
  ('2455337b-9ff1-5679-a17c-dcae1c46a3f0', 'a316a3e6-70db-5c64-a808-c32c207f4fd3', '1356cd78-aa88-54ac-ad14-8124e8edffd1', 10, 10, 'እግዚአብሔርም አለው፥ “ቃየል! ምን አደረግህ? የወንድምህ የአቤል የደሙ ድምፅ ከምድር ወደ እኔ ይጮሃል።'),
  ('0b803498-f664-5af3-ae29-14d636350bc6', 'a316a3e6-70db-5c64-a808-c32c207f4fd3', '1356cd78-aa88-54ac-ad14-8124e8edffd1', 11, 11, 'አሁንም የወንድምህን ደም ከእጅህ ለመቀበል አፍዋን በከፈተች በምድር ላይ አንተ የተረገምህ ነህ።'),
  ('cf2bf764-03a8-5902-aa83-d514e369bed6', 'a316a3e6-70db-5c64-a808-c32c207f4fd3', '1356cd78-aa88-54ac-ad14-8124e8edffd1', 12, 12, 'ምድርንም ባረስህ ጊዜ እንግዲህ ኀይልዋን አትሰጥህም፤ በምድር ላይ ኮብላይና ተቅበዝባዥ ትሆናለህ።”'),
  ('bf8faee2-c82f-5b18-a58d-3966c1b32b23', 'a316a3e6-70db-5c64-a808-c32c207f4fd3', '1356cd78-aa88-54ac-ad14-8124e8edffd1', 13, 13, 'ቃየልም እግዚአብሔርን አለው፥ “ኀጢአቴ ይቅር የማትባል ታላቅ ናትን?'),
  ('92bec8b5-80b6-5211-abbe-3db65b4b00f0', 'a316a3e6-70db-5c64-a808-c32c207f4fd3', '1356cd78-aa88-54ac-ad14-8124e8edffd1', 14, 14, 'እነሆ፥ ዛሬ ከምድር ፊት ከአሳደድኸኝ፥ ከፊትህ እሰወራለሁ፤ በምድርም ላይ ኮብላይና ተቅበዝባዥ እሆናለሁ፤ የሚያገኘኝም ሁሉ ይገድለኛል።”'),
  ('a9a30f15-3a4a-58ce-a656-7474275a9afa', 'a316a3e6-70db-5c64-a808-c32c207f4fd3', '1356cd78-aa88-54ac-ad14-8124e8edffd1', 15, 15, 'እግዚአብሔርም አለው፥ “እንዲህ አይደለም፤ እንግዲህ ቃየልን የገደለ ሁሉ ሰባት እጥፍ ይበቀልበታል።” እግዚአብሔርም ቃየልን ያገኘው ሁሉ እንዳይገድለው ምልክት አደረገለት።'),
  ('5e875e63-3c72-5888-a8d7-aac96d4bd96d', 'a316a3e6-70db-5c64-a808-c32c207f4fd3', '379202e4-1096-5d52-ab38-91da740dc9bf', 1, 16, 'ቃየልም ከእግዚአብሔር ፊት ወጣ፤ በኤዶም አንጻር ባለችው ኖድ በምትባለው ምድርም ኖረ።'),
  ('3b337f3b-e6f8-5863-a550-c247bac332e8', 'a316a3e6-70db-5c64-a808-c32c207f4fd3', '379202e4-1096-5d52-ab38-91da740dc9bf', 2, 17, 'ቃየልም ሚስቱን ዐወቃት፤ ፀነስችም፤ ሄኖሕንም ወለደች። ከተማም ሠራ፤ የከተማይቱንም ስም በልጁ ስም “ሄኖሕ” አላት።'),
  ('1aeaa20c-6f00-5202-ab64-dcaaeaa08ab3', 'a316a3e6-70db-5c64-a808-c32c207f4fd3', '379202e4-1096-5d52-ab38-91da740dc9bf', 3, 18, 'ሄኖሕም ጋይዳድን ወለደ፤ ጋይዳድም ሜኤልን ወለደ፤ ሜኤልም ማቱሳኤልን ወለደ፤ ማቱሳኤልም ላሜሕን ወለደ።'),
  ('5917d4ba-5186-5aaf-aa4a-481463c6d0ac', 'a316a3e6-70db-5c64-a808-c32c207f4fd3', '379202e4-1096-5d52-ab38-91da740dc9bf', 4, 19, 'ላሜሕም ለራሱ ሁለት ሚስቶችን አገባ፤ የአንዲቱ ስም ዓዳ፥ የሁለተኛይቱ ስም ሴላ ነበር።'),
  ('1bf9f330-7fde-5c50-a8eb-631e0729dde2', 'a316a3e6-70db-5c64-a808-c32c207f4fd3', '379202e4-1096-5d52-ab38-91da740dc9bf', 5, 20, 'ዓዳም ዮቤልን ወለደች፤ እርሱም በድንኳን የሚቀመጡት የዘላኖች አባት ነበረ።'),
  ('8478eb15-af34-5951-aad4-244fce76cf93', 'a316a3e6-70db-5c64-a808-c32c207f4fd3', '379202e4-1096-5d52-ab38-91da740dc9bf', 6, 21, 'የወንድሙም ስም ኢዮቤል ነበር፤ እርሱም በገናንና መሰንቆን አስተማረ።'),
  ('8d7d6cb1-b9ca-53c4-a34e-7d5ddd925a96', 'a316a3e6-70db-5c64-a808-c32c207f4fd3', '379202e4-1096-5d52-ab38-91da740dc9bf', 7, 22, 'ሴላም ደግሞ ቶቤልን ወለደች። እርሱም ናስና ብረትን የሚሠራ ሆነ። የእኅቱም ስም ኖሄም ነበረ።'),
  ('b47f2d94-ac9d-5498-a6e5-1a6075995599', 'a316a3e6-70db-5c64-a808-c32c207f4fd3', '379202e4-1096-5d52-ab38-91da740dc9bf', 8, 23, 'ላሜሕም ለሚስቶቹ ለዓዳና ለሴላ አላቸው፥ “እናንት የላሜሕ ሚስቶች ቃሌን ስሙ፤ ነገሬንም አድምጡ፤ እኔ ጐልማሳውን ስለ መቍሰሌ፤ ብላቴናውንም ስለ መወጋቴ ገድየዋለሁና፤'),
  ('8c933759-208f-55c1-a778-8b96c26ae153', 'a316a3e6-70db-5c64-a808-c32c207f4fd3', '379202e4-1096-5d52-ab38-91da740dc9bf', 9, 24, 'ቃየልን ሰባት እጥፍ ይበቀሉታል፤ ላሜሕን ግን ሰባ ጊዜ ሰባት።”'),
  ('f387f1be-c68f-59b3-a505-dc3fe39704bb', 'a316a3e6-70db-5c64-a808-c32c207f4fd3', '35e27cb2-b016-5f38-a44f-a8610fe42b91', 1, 25, 'አዳምም ዳግመኛ ሚስቱን ዐወቃት፤ ፀነሰችም፤ ወንድ ልጅንም ወለደች። ስሙንም ቃየል በገደለው በአቤል ፈንታ እግዚአብሔር ሌላ ዘር ተክቶልኛል ስትል ሴት አለችው።'),
  ('9fb5e560-050e-5fd9-abc0-c2c5cd81c3ca', 'a316a3e6-70db-5c64-a808-c32c207f4fd3', '35e27cb2-b016-5f38-a44f-a8610fe42b91', 2, 26, 'ሴትም ወንድ ልጅ ወለደ። ስሙንም ሄኖስ አለው፤ እርሱም የእግዚአብሔርን ስም መጥራት የጀመረ ነው።'),
  ('cd31f5ed-1fdf-5721-a8c6-d6fa55e8c63d', '22f22b76-2bf2-5b03-af8e-d5f536c1e24d', 'ee5eb77f-27be-514e-ac27-659a0b12e07b', 1, 1, 'የሰዎች የትውልድ መጽሐፍ ይህ ነው። እግዚአብሔር አዳምን በፈጠረ ቀን በእግዚአብሔር ምሳሌ አደረገው፤'),
  ('aff0727d-04a5-5245-ae7e-aa2eff9c9265', '22f22b76-2bf2-5b03-af8e-d5f536c1e24d', 'ee5eb77f-27be-514e-ac27-659a0b12e07b', 2, 2, 'ወንድና ሴት አድርጎ ፈጠራቸው፤ ባረካቸውም። እነርሱንም በፈጠረበት ቀን ስሙን አዳም ብሎ ጠራው።'),
  ('0e2232f5-2e5d-59ad-a23e-b4fe6c26e625', '22f22b76-2bf2-5b03-af8e-d5f536c1e24d', 'ee5eb77f-27be-514e-ac27-659a0b12e07b', 3, 3, 'አዳምም ሁለት መቶ ሠላሳ ዓመት ኖረ፤ ልጅንም እንደ ምሳሌው እንደ መልኩ ወለደ፤ ስሙንም ሴት ብሎ ጠራው።'),
