  ('0da0a60e-a3a0-5a67-a1d9-8727a361f6c4', '22f22b76-2bf2-5b03-af8e-d5f536c1e24d', 'ee5eb77f-27be-514e-ac27-659a0b12e07b', 25, 25, 'ማቱሳላም መቶ ሰማንያ ሰባት ዓመት ኖረ፤ ላሜሕንም ወለደ፤'),
  ('51cefe3a-f1a4-568c-ada6-6bbf8087baff', '22f22b76-2bf2-5b03-af8e-d5f536c1e24d', 'ee5eb77f-27be-514e-ac27-659a0b12e07b', 26, 26, 'ማቱሳላም ላሜሕን ከወለደ በኋላ ሰባት መቶ ሰማንያ ሁለት ዓመት ኖረ፤ ወንዶችንም፥ ሴቶችንም ወለደ።'),
  ('a28aad7b-a909-5024-a2ed-5f5446957eb3', '22f22b76-2bf2-5b03-af8e-d5f536c1e24d', 'ee5eb77f-27be-514e-ac27-659a0b12e07b', 27, 27, 'ማቱሳላም የኖረበት ዘመን ሁሉ ዘጠኝ መቶ ስድሳ ዘጠኝ ዓመት ሆነ፤ ሞተም።'),
  ('65eca6cb-9677-5792-a378-7a360484aa0b', '22f22b76-2bf2-5b03-af8e-d5f536c1e24d', 'ee5eb77f-27be-514e-ac27-659a0b12e07b', 28, 28, 'ላሜሕም መቶ ሰማንያ ሁለት ዓመት ኖረ፤ ልጅንም ወለደ።'),
  ('f2d97382-c49b-5b0f-a1ca-cd0936d94ff6', '22f22b76-2bf2-5b03-af8e-d5f536c1e24d', 'ee5eb77f-27be-514e-ac27-659a0b12e07b', 29, 29, 'ስሙንም ከሥራዬ፥ ከእጄ ድካምና እግዚአብሔር ከረገማት ምድር ይህ ያሳርፈኝ ዘንድ አለው ሲል “ኖኅ” ብሎ ጠራው።'),
  ('1f055616-fd99-5d9c-aaa6-ce6d17046745', '22f22b76-2bf2-5b03-af8e-d5f536c1e24d', 'ee5eb77f-27be-514e-ac27-659a0b12e07b', 30, 30, 'ላሜሕም ኖኅን ከወለደ በኋላ አምስት መቶ ስድሳ አምስት ዓመት ኖረ፤ ወንዶችንም ሴቶችንም ወለደ።'),
  ('caa83487-698f-5660-ac0c-68f2f6abca6f', '22f22b76-2bf2-5b03-af8e-d5f536c1e24d', 'ee5eb77f-27be-514e-ac27-659a0b12e07b', 31, 31, 'ላሜሕም የኖረበት ዘመን ሁሉ ሰባት መቶ አርባ ሰባት ዓመት ሆነ፤ ሞተም።'),
  ('c28ea089-43a5-5748-a1be-93b21a37ea5a', '22f22b76-2bf2-5b03-af8e-d5f536c1e24d', 'ee5eb77f-27be-514e-ac27-659a0b12e07b', 32, 32, 'ለኖኅም አምስት መቶ ዓመት ሆነው፤ ኖህም ሦስት ልጆችን ወለደ፤ እነርሱም ሴም፥ ካምና ያፌት ናቸው።'),
  ('07d2916e-49c7-5051-a7e0-8b624b2336f9', '5ab91124-bbc8-53db-aa46-0688b93472be', '308b0d46-0b94-596a-ab25-98bf0a9d1bcb', 1, 1, 'እንዲህም ሆነ፤ ሰዎች በምድር ላይ መብዛት በጀመሩ ጊዜ መልከ መልካሞች ሴቶች ልጆች ተወለዱላቸው፤'),
  ('8efbd8cb-d647-5c0c-a664-766301fe5c7f', '5ab91124-bbc8-53db-aa46-0688b93472be', '308b0d46-0b94-596a-ab25-98bf0a9d1bcb', 2, 2, 'የእግዚአብሔር ልጆችም የሰውን ሴቶች ልጆች መልካሞች እንደሆኑ አዩ፤ ከመረጡአቸውም ሁሉ ሚስቶችን ለራሳቸው ወሰዱ።'),
  ('371fc345-ef80-511b-a264-368e3b48a7e5', '5ab91124-bbc8-53db-aa46-0688b93472be', '308b0d46-0b94-596a-ab25-98bf0a9d1bcb', 3, 3, 'እግዚአብሔርም፥ “መንፈሴ በሰው ላይ ለዘለዓለም አይኖርም፤ እነርሱ ሥጋ ናቸውና፤ ዘመናቸውም መቶ ሃያ ዓመት ይሆናል” አለ።'),
  ('9d7a25c6-0655-5c16-a345-c04aaebf7519', '5ab91124-bbc8-53db-aa46-0688b93472be', '308b0d46-0b94-596a-ab25-98bf0a9d1bcb', 4, 4, 'በእነዚያም ወራት ረዓይት በምድር ላይ ነበሩ። ከዚያም በኋላ የእግዚአብሔር ልጆች ወደ ሰው ሴቶች ልጆች በገቡ ጊዜ ልጆችን ወለዱላቸው፤ እነርሱም በዱሮ ዘመን ስማቸውን ያስጠሩ ኀያላን ሰዎች ሆኑ።'),
  ('526236d8-89e7-5973-aacf-a8a62fdbcc2f', '5ab91124-bbc8-53db-aa46-0688b93472be', '308b0d46-0b94-596a-ab25-98bf0a9d1bcb', 5, 5, 'እግዚአብሔርም የሰዎች ክፉ ሥራ በምድር ላይ እንደበዛ፥ የልባቸው ዐሳብ ምኞትም ሁል ጊዜ ፈጽሞ ክፉ እንደሆነ አየ።'),
  ('f54b2d50-1a9d-51d6-a522-80ddd70a66ff', '5ab91124-bbc8-53db-aa46-0688b93472be', '308b0d46-0b94-596a-ab25-98bf0a9d1bcb', 6, 6, 'እግዚአብሔርም ሰውን በምድር ላይ በመፍጠሩ ተጸጸተ፤ በልቡም አዘነ።'),
  ('3bc6ae87-78c3-5e4c-a81a-987faf57843e', '5ab91124-bbc8-53db-aa46-0688b93472be', '308b0d46-0b94-596a-ab25-98bf0a9d1bcb', 7, 7, 'እግዚአብሔርም፥ “የፈጠርሁትን ሰው ከምድር ላይ አጠፋለሁ፤ ከሰው እስከ እንስሳና አራዊት፥ እስከ ተንቀሳቃሽም፥ እስከ ሰማይ ወፍም ድረስ፤ ስለ ፈጠርኋቸው ተጸጽቻለሁና” አለ።'),
  ('987ce2d6-b821-5d99-a887-5f2cd7c94806', '5ab91124-bbc8-53db-aa46-0688b93472be', '308b0d46-0b94-596a-ab25-98bf0a9d1bcb', 8, 8, 'ኖኅ ግን በእግዚአብሔር ፊት ሞገስን አገኘ።'),
  ('e36ddfd4-16bd-51cd-a246-831529b317eb', '5ab91124-bbc8-53db-aa46-0688b93472be', '73fade1a-0d6a-5f15-a543-33f63041c53b', 1, 9, 'የኖኅ ትውልድ እንዲህ ነው። ኖኅም በትውልዱ ጻድቅ፥ ፍጹምም ሰው ነበረ፤ ኖኅም እግዚአብሔርን ደስ አሰኘው።'),
  ('a473d69c-42a5-557e-a62b-4c745aed1d0c', '5ab91124-bbc8-53db-aa46-0688b93472be', '73fade1a-0d6a-5f15-a543-33f63041c53b', 2, 10, 'ኖኅም ሦስት ልጆችን ሴምን፥ ካምን ያፌትንም ወለደ።'),
  ('13f30a4c-ff1b-57e9-a122-6fbe467f45d7', '5ab91124-bbc8-53db-aa46-0688b93472be', '73fade1a-0d6a-5f15-a543-33f63041c53b', 3, 11, 'ምድርም በእግዚአብሔር ፊት ተበላሸች፤ ምድርም ግፍን ተመላች።'),
  ('f5115464-6073-5250-a6b8-961d3948c9ae', '5ab91124-bbc8-53db-aa46-0688b93472be', '73fade1a-0d6a-5f15-a543-33f63041c53b', 4, 12, 'እግዚአብሔርም ምድርን እንደ ተበላሸች፥ ሥጋን የለበሱ ሁሉም በምድር ላይ መንገዳቸውን እንደ አበላሹ አየ።'),
  ('b58941b6-19f1-5b5d-a4aa-912db138e1af', '5ab91124-bbc8-53db-aa46-0688b93472be', '73fade1a-0d6a-5f15-a543-33f63041c53b', 5, 13, 'እግዚአብሔር አምላክም ኖኅን አለው፥ “የሰው ሁሉ ጊዜው በፊቴ ደርሶአል፤ ከእነርሱ የተነሣ ምድር በግፍ ተመልታለችና፤ እኔም እነሆ፥ ከምድር ጋር አጠፋቸዋለሁ።'),
  ('0c276d00-f896-59fd-ad72-e7005b42f207', '5ab91124-bbc8-53db-aa46-0688b93472be', '73fade1a-0d6a-5f15-a543-33f63041c53b', 6, 14, 'ባለ አራት መዓዝን የዕንጨት መርከብን ለአንተ ሥራ፤ በመርከቢቱም ክፍሎችን አድርግ፤ በውስጥም፥ በውጭም በቅጥራን ለቅልቃት።'),
  ('e42447c8-58a2-5cf4-a97a-b2e069cada26', '5ab91124-bbc8-53db-aa46-0688b93472be', '73fade1a-0d6a-5f15-a543-33f63041c53b', 7, 15, 'መርከብዋንም እንዲህ ታደርጋታለህ፤ የመርከቢቱ ርዝመት ሦስት መቶ ክንድ፥ ወርድዋ አምሳ ክንድ፥ ከፍታዋ ሠላሳ ክንድ ይሁን።'),
  ('d809e1b9-8ee4-542c-a7cc-c4724f18b24d', '5ab91124-bbc8-53db-aa46-0688b93472be', '73fade1a-0d6a-5f15-a543-33f63041c53b', 8, 16, 'ለመርከቢቱም መስኮትን ታደርጋለህ፤ ከቁመቷም ክንድ ሙሉ ትተህ ጨርሳት፤ የመርከቢቱንም በር በጎንዋ አድርግ፤ ታችኛውንም፥ ሁለተኛውንም፥ ሦስተኛውንም ደርብ ታደርግላታለህ።'),
  ('18ff9b47-f455-55ee-ac2b-9af67f4442bf', '5ab91124-bbc8-53db-aa46-0688b93472be', '73fade1a-0d6a-5f15-a543-33f63041c53b', 9, 17, 'እኔም እነሆ፥ ከሰማይ በታች የሕይወት ነፍስ ያለውን ሥጋ ሁሉ ለማጥፋት በምድር ላይ የጥፋት ውኃን አመጣለሁ፤ በምድር ያለው ሁሉ ይጠፋል።'),
  ('2574f13c-461e-5b26-a7e3-14fcad82627a', '5ab91124-bbc8-53db-aa46-0688b93472be', '73fade1a-0d6a-5f15-a543-33f63041c53b', 10, 18, 'ቃል ኪዳኔንም ከአንተ ጋር አጸናለሁ፤ ወደ መርከብም አንተ ልጆችህንና ሚስትህን፥ የልጆችህንም ሚስቶች ይዘህ ትገባለህ።'),
  ('c2a747d2-a7fa-55c9-a71b-9e99fb6982c0', '5ab91124-bbc8-53db-aa46-0688b93472be', '73fade1a-0d6a-5f15-a543-33f63041c53b', 11, 19, 'ከእንስሳ ሁሉ፥ ከተንቀሳቃሽ አራዊትም ሁሉ፥ ሥጋ ካለው ሁሉ ከአንተ ጋር ትመግባቸው ዘንድ ከሁሉም ሁለት ሁለት ወደ መርከብ ታገባለህ፤ ተባትና እንስት ይሁን።'),
  ('590f10a9-6b18-5e53-a13f-7a8b7874b95a', '5ab91124-bbc8-53db-aa46-0688b93472be', '73fade1a-0d6a-5f15-a543-33f63041c53b', 12, 20, 'ከወፎች ሁሉ በየወገናቸው፥ ከእንስሳም ሁሉ በየወገናቸው፥ በምድር ላይ ከሚሳቡ ተንቀሳቃሾች ሁሉ በየወገናቸው ከአንተ ጋር ይመገቡ ዘንድ ከሁሉም ሁለት ሁለት ወንድና ሴት እየሆኑ ወደ አንተ ይግቡ።'),
  ('80a43e0b-cda8-5faf-a915-476fb1ad01d4', '5ab91124-bbc8-53db-aa46-0688b93472be', '73fade1a-0d6a-5f15-a543-33f63041c53b', 13, 21, 'ከሚበላውም የመብል ዓይነት ሁሉ ለአንተ ውሰድ፤ ወደ አንተ ትሰበስባለህ፤ እርሱም ለአንተ፥ ለእነርሱም መብል ይሆናል።”'),
  ('38829d73-b72b-5c32-a3ee-901b08dc7fad', '5ab91124-bbc8-53db-aa46-0688b93472be', '73fade1a-0d6a-5f15-a543-33f63041c53b', 14, 22, 'ኖኅም እግዚአብሔር አምላክ ያዘዘውን ሁሉ አደረገ፤ እንዲሁ አደረገ።'),
  ('c59c234f-4c22-5f46-a513-606a68f90104', 'e706c1d6-5757-5dfb-a63c-c7d14f88cca6', '73cb65ce-f3ba-515b-a18f-ed85dc84a0dd', 1, 1, 'እግዚአብሔር አምላክም ኖኅን አለው፥ “አንተ ቤተሰቦችህን ሁሉ ይዘህ ወደ መርከብ ግባ፤ በዚህ ትውልድ በፊቴ ጻድቅ ሆነህ አይችሃለሁና።'),
  ('dae25b76-8693-573b-acfa-2042cfc2cb0e', 'e706c1d6-5757-5dfb-a63c-c7d14f88cca6', '73cb65ce-f3ba-515b-a18f-ed85dc84a0dd', 2, 2, 'ከንጹሕ እንስሳ ሁሉ ሰባት ስባት ተባትና እንስት፥ ንጹሕ ካልሆነም እንስሳ ሁለት ሁለት ተባትና እንስት፤'),
  ('59a29360-e7e6-54a0-a5bd-629b9fd92b34', 'e706c1d6-5757-5dfb-a63c-c7d14f88cca6', '73cb65ce-f3ba-515b-a18f-ed85dc84a0dd', 3, 3, 'ከንጹሕ የሰማይ ወፍ ደግሞ ሰባት ሰባት ተባትና እንስት፥ ንጹሕ ካልሆነ የሰማይ ወፍም ሁለት ሁለት ተባትና እንስት እያደረግህ በምድር ላይ ለምግብና ለዘር ይቀር ዘንድ ለአንተ ትወስዳለህ።'),
  ('a8969c41-60ef-52f2-aac3-55e4a04733ef', 'e706c1d6-5757-5dfb-a63c-c7d14f88cca6', '73cb65ce-f3ba-515b-a18f-ed85dc84a0dd', 4, 4, 'ከሰባት ቀን በኋላ አርባ ቀንና አርባ ሌሊት በምድር ላይ ዝናብ አዘንባለሁና፤ የፈጠርሁትንም ፍጥረት ሁሉ ከምድር ሁሉ ላይ አጠፋለሁና።”'),
  ('b4e2caac-88cb-5b8e-a1e5-fb97069e6b74', 'e706c1d6-5757-5dfb-a63c-c7d14f88cca6', '73cb65ce-f3ba-515b-a18f-ed85dc84a0dd', 5, 5, 'ኖኅም እግዚአብሔር አምላክ ያዘዘውን ሁሉ አደረገ።'),
  ('7f4dd482-d1de-582f-a242-c97080c292e9', 'e706c1d6-5757-5dfb-a63c-c7d14f88cca6', '73cb65ce-f3ba-515b-a18f-ed85dc84a0dd', 6, 6, 'ኖኅም የጥፋት ውኃ በምድር ላይ በሆነ ጊዜ የስድስት መቶ ዓመት ዕድሜ ነበረ።'),
  ('a5135236-6107-5563-ae9a-068d4c4c9112', 'e706c1d6-5757-5dfb-a63c-c7d14f88cca6', '73cb65ce-f3ba-515b-a18f-ed85dc84a0dd', 7, 7, 'ኖኅም ስለ ጥፋት ውኃ ልጆቹንና ሚስቱን፥ የልጆቹንም ሚስቶች ይዞ ወደ መርከብ ገባ።'),
  ('7f6e7f55-c341-58f5-af42-4109493f456d', 'e706c1d6-5757-5dfb-a63c-c7d14f88cca6', '73cb65ce-f3ba-515b-a18f-ed85dc84a0dd', 8, 8, 'ከንጹሓን ወፎችና ንጹሓን ካልሆኑ ወፎች፥ ከንጹሕ እንስሳ፥ ንጹሕም ካልሆነው እንስሳ፥ በምድር ላይ ከሚንቀሳቀሰው ሁሉ፥'),
  ('628dd9c0-57eb-5419-ad65-43c31b7fe393', 'e706c1d6-5757-5dfb-a63c-c7d14f88cca6', '73cb65ce-f3ba-515b-a18f-ed85dc84a0dd', 9, 9, 'እግዚአብሔር ኖኅን እንዳዘዘው፥ ሁለት ሁለት ተባትና እንስት እየሆኑ ወደ ኖኅ ወደ መርከብ ውስጥ ገቡ።'),
  ('639d0387-1644-5123-a87b-3650a6b77c31', 'e706c1d6-5757-5dfb-a63c-c7d14f88cca6', '73cb65ce-f3ba-515b-a18f-ed85dc84a0dd', 10, 10, 'ከሰባት ቀን በኋላም የጥፋት ውኃ በምድር ላይ ሆነ።'),
  ('e1838d31-b5d6-56ab-a352-1b9f1a57cd16', 'e706c1d6-5757-5dfb-a63c-c7d14f88cca6', '73cb65ce-f3ba-515b-a18f-ed85dc84a0dd', 11, 11, 'በኖኅ ዕድሜ በስድስተኛው መቶ ዓመት በሁለተኛው ወር ከወሩም በዐሥራ ሰባተኛው ዕለት፥ በዚያው ቀን የታላቁ ቀላይ ምንጮች ሁሉ ተነደሉ፤ የሰማይ መስኮቶችም ተከፈቱ፤'),
  ('f1a88b82-7f35-5e53-a7aa-408356a73259', 'e706c1d6-5757-5dfb-a63c-c7d14f88cca6', '73cb65ce-f3ba-515b-a18f-ed85dc84a0dd', 12, 12, 'ዝናቡም አርባ ቀንና አርባ ሌሊት በምድር ላይ ሆነ።'),
  ('0ceb8dec-d338-53fb-a48c-664ce42daead', 'e706c1d6-5757-5dfb-a63c-c7d14f88cca6', '73cb65ce-f3ba-515b-a18f-ed85dc84a0dd', 13, 13, 'በዚያውም ቀን ኖኅ ወደ መርከብ ገባ፤ የኖኅ ልጆችም ሴም፥ ካም፥ ያፌትና የኖኅ ሚስት፥ ሦስቱም የልጆቹ ሚስቶች ከእርሱ ጋር ገቡ።'),
  ('4ac6cdc2-0028-58ac-a3ca-46641da586c7', 'e706c1d6-5757-5dfb-a63c-c7d14f88cca6', '73cb65ce-f3ba-515b-a18f-ed85dc84a0dd', 14, 14, 'አራዊትም ሁሉ በየወገናቸው፥ እንስሳትም ሁሉ በየወገናቸው፥ በምድር ላይ የሚንቀሳቀሱ ተንቀሳቃሾችም ሁሉ በየወገናቸው፥ ወፎችም ሁሉ በየወገናቸው፥ የሚበሩ ወፎችም ሁሉ፥'),
  ('514840d9-e4e5-5694-ad2d-e7d86a17a4ee', 'e706c1d6-5757-5dfb-a63c-c7d14f88cca6', '73cb65ce-f3ba-515b-a18f-ed85dc84a0dd', 15, 15, 'ሥጋ ያላቸው ሕያዋን ሁሉ ሁለት ሁለት እየሆኑ ወደ ኖኅ መርከብ ውስጥ ገቡ።'),
  ('40401810-49e4-5131-a08c-5e53fec77413', 'e706c1d6-5757-5dfb-a63c-c7d14f88cca6', '73cb65ce-f3ba-515b-a18f-ed85dc84a0dd', 16, 16, 'ሥጋ ካለው ሁሉ የገቡትም ተባትና እንስት እግዚአብሔር ኖኅን እንዳዘዘው ገቡ፤ እግዚአብሔር አምላክም መርከብዋን በስተውጭ ዘጋት።'),
  ('732c80ef-cb9d-5333-a825-f6b95e0f8e26', 'e706c1d6-5757-5dfb-a63c-c7d14f88cca6', '73cb65ce-f3ba-515b-a18f-ed85dc84a0dd', 17, 17, 'የጥፋት ውኃ በምድር ላይ አርባ ቀንና አርባ ሌሊት ነበረ፤ ውኃውም በዛ፤ መርከቢቱንም አነሣ፤ ከምድርም ወደ ላይ ከፍ ከፍ አለች።'),
  ('1d0a90bb-09d6-5f60-a181-a1fd73000fd9', 'e706c1d6-5757-5dfb-a63c-c7d14f88cca6', '73cb65ce-f3ba-515b-a18f-ed85dc84a0dd', 18, 18, 'ውኃውም አሸነፈ፤ በምድር ላይም እጅግ በዛ፤ መርከቢቱም በውኃ ላይ ተንሳፈፈች።'),
  ('5de98b84-6149-55d3-ae09-6ff2d1cbca3e', 'e706c1d6-5757-5dfb-a63c-c7d14f88cca6', '73cb65ce-f3ba-515b-a18f-ed85dc84a0dd', 19, 19, 'ውኃውም በምድር ላይ እጅግ በጣም አሸነፈ፤ ከሰማይ በታች ያሉ ረዣዥም ተራሮችን ሁሉ ሸፈነ።'),
  ('c3e38ee5-9bde-5667-abf6-e2c8d13002c6', 'e706c1d6-5757-5dfb-a63c-c7d14f88cca6', '73cb65ce-f3ba-515b-a18f-ed85dc84a0dd', 20, 20, 'ውኃው ወደ ላይ ዐሥራ አምስት ክንድ ከፍ ከፍ አለ፤ ረዣዥም ተራሮችንም ሸፈነ።'),
  ('54d448a2-4954-56c2-aa01-ddabc21056ea', 'e706c1d6-5757-5dfb-a63c-c7d14f88cca6', '73cb65ce-f3ba-515b-a18f-ed85dc84a0dd', 21, 21, 'በምድር ላይ ሥጋ ያለው የሚንቀሳቀሰው ሁሉ ወፉም፥ እንስሳውም፥ አራዊቱም፥ በምድር ላይ የሚርመሰመሰው ተንቀሳቃሹምሁሉ፥ ሰውም ሁሉ ጠፋ።'),
  ('a7a98205-d323-5c3f-a3b2-b1ccd5c2f485', 'e706c1d6-5757-5dfb-a63c-c7d14f88cca6', '73cb65ce-f3ba-515b-a18f-ed85dc84a0dd', 22, 22, 'የሕይወት እስትንፋስ ያለው ሁሉ፥ በየብስም ያለው ሁሉ ሞተ።'),
  ('29184243-38f4-5423-ae2f-7850c56e2d3f', 'e706c1d6-5757-5dfb-a63c-c7d14f88cca6', '73cb65ce-f3ba-515b-a18f-ed85dc84a0dd', 23, 23, 'በምድር ላይ የነበረውም ሁሉ ከሰው ጀምሮ እስከ እንስሳ፥ እስከሚርመሰመሰውም ሁሉ ድረስ፥ እስከ ሰማይ ወፍም ድረስ ተደመሰሰ፤ ከምድርም ተደመሰሱ። ኖኅም አብረውት በመርከብ ከነበሩት ጋር ብቻውን ቀረ።'),
  ('e76dd6ae-60aa-58a9-afe9-cda35561f379', 'e706c1d6-5757-5dfb-a63c-c7d14f88cca6', '73cb65ce-f3ba-515b-a18f-ed85dc84a0dd', 24, 24, 'ውኃውም መቶ አምሳ ቀን በምድር ላይ ሞላ።'),
  ('0824f485-0e5c-5d2e-a181-fbb104e04487', 'b97eac3f-4057-558e-a075-fc36bac273d9', '596a487a-4100-5611-a6bb-ba5b7a961261', 1, 1, 'እግዚአብሔርም ኖኅን፥ በመርከብም ከእርሱ ጋር የነበረውን አራዊቱን ሁሉ፥ እንስሳውንም ሁሉ፥ አዕዋፍንም ሁሉ፥ የሚንቀሳቀሰውንም ሁሉ ዐሰበ፤ እግዚአብሔርም በምድር ላይ ነፋስን አመጣ፤ ውኃውም ጐደለ፤'),
  ('62148371-2eae-52c4-a59f-7614b5936c59', 'b97eac3f-4057-558e-a075-fc36bac273d9', '596a487a-4100-5611-a6bb-ba5b7a961261', 2, 2, 'የቀላዩም ምንጮች፥ የሰማይም መስኮቶች ተደፈኑ፤ ዝናብም ከሰማይ ተከለከለ፤'),
  ('41b3e5e2-3ff2-521b-a155-9a08ac79735d', 'b97eac3f-4057-558e-a075-fc36bac273d9', '596a487a-4100-5611-a6bb-ba5b7a961261', 3, 3, 'ውኃውም ከምድር ላይ እያደር እየቀለለ ይሄድ ጀመረ፤ ከመቶ አምሳ ቀንም በኋላ ውኃው ጐደለ።'),
  ('b04a5b86-ce20-53ec-a6bd-82c5005dde26', 'b97eac3f-4057-558e-a075-fc36bac273d9', '596a487a-4100-5611-a6bb-ba5b7a961261', 4, 4, 'መርከቢቱም በሰባተኛው ወር ከወሩም በሃያ ሰባተኛው ቀን በአራራት ተራሮች ላይ ተቀመጠች።'),
  ('6efa4ff6-b819-5eab-aefa-4a5d5a555c52', 'b97eac3f-4057-558e-a075-fc36bac273d9', '596a487a-4100-5611-a6bb-ba5b7a961261', 5, 5, 'ውኃውም እስከ ዐሥረኛው ወር ድረስ ይጐድል ነበር፤ በዐሥራ አንደኛው ወር ከወሩም በመጀመሪያው ቀን የተራሮቹ ራሶች ተገለጡ።'),
  ('f60348c0-c627-5ff9-a365-3d8b8f630fe6', 'b97eac3f-4057-558e-a075-fc36bac273d9', '596a487a-4100-5611-a6bb-ba5b7a961261', 6, 6, 'ከአርባ ቀን በኋላም ኖኅ የሠራውን የመርከቢቱን መስኮት ከፈተ፤'),
  ('87d38d21-1f25-5a5a-aaa8-531e966448f7', 'b97eac3f-4057-558e-a075-fc36bac273d9', '596a487a-4100-5611-a6bb-ba5b7a961261', 7, 7, 'ከምድርም ላይ ውኃዉ ጐድሎ እንደሆነ ያይ ዘንድ ቁራውን ላከው፤ እርሱም ሄደ፤ ነገር ግን ውኃው ከምድር ላይ እስኪደርቅ ድረስ አልተመለሰም።'),
  ('e958abcb-0c87-5636-a38a-f76d23113bea', 'b97eac3f-4057-558e-a075-fc36bac273d9', '596a487a-4100-5611-a6bb-ba5b7a961261', 8, 8, 'ርግብንም ውኃው ከምድር ፊት ጐድሎ እንደ ሆነ እንድታይ ከእርሱ በኋላ ላካት።'),
  ('93aea7cf-cbb9-58d3-a71c-ac6b98fb92c2', 'b97eac3f-4057-558e-a075-fc36bac273d9', '596a487a-4100-5611-a6bb-ba5b7a961261', 9, 9, 'ነገር ግን ርግብ እግርዋን የምታሳርፍበት ስፍራ አላገኘችም፤ ወደ እርሱም ወደ መርከብ ተመለሰች፤ ውኃው በምድር ላይ ሁሉ ነበረና፤ እጁን ዘረጋና ተቀበላት፤ ወደ እርሱም ወደ መርከብ ውስጥ አገባት።'),
  ('d2ef46c0-1aed-56bb-a97a-0a935bf71254', 'b97eac3f-4057-558e-a075-fc36bac273d9', '596a487a-4100-5611-a6bb-ba5b7a961261', 10, 10, 'ከዚያም በኋላ ደግሞ ሰባት ቀን ቆይቶ፥ ርግብን እንደገና ከመርከብ ላካት።'),
  ('b3680c0b-695b-57ba-a58b-d957c32f92b8', 'b97eac3f-4057-558e-a075-fc36bac273d9', '596a487a-4100-5611-a6bb-ba5b7a961261', 11, 11, 'ርግብም በማታ ጊዜ ወደ እርሱ ተመለሰች፤ በአፍዋም እነሆ፥ የለመለመ የወይራ ቅጠል ይዛ ነበር። ኖኅም ከምድር ላይ ውኃው እንደ ጐደለ ዐወቀ።'),
  ('80b0a47b-26a9-5099-ab3c-38b4ba1053d7', 'b97eac3f-4057-558e-a075-fc36bac273d9', '596a487a-4100-5611-a6bb-ba5b7a961261', 12, 12, 'ደግሞ ሰባት ቀን ቆይቶ፥ ርግብን ላካት፤ ዳግመኛም ወደ እርሱ አልተመለሰችም።'),
  ('2eb6f2ef-5e69-520a-a7ce-ffd569e6c873', 'b97eac3f-4057-558e-a075-fc36bac273d9', '596a487a-4100-5611-a6bb-ba5b7a961261', 13, 13, 'በኖኅ ዕድሜ በስድስት መቶ አንድ ዓመት በመጀመሪያው ወር ከወሩም በመጀመሪያው ቀን ውኃው ከምድር ላይ ደረቀ፤ ኖኅም የሠራትን የመርከቢቱን ክዳን አነሣ፤ እነሆም፥ ውኃው ከምድር ፊት እንደ ደረቀ አየ።'),
  ('38b57370-7dc6-5bf6-a712-b9be25317b7a', 'b97eac3f-4057-558e-a075-fc36bac273d9', '596a487a-4100-5611-a6bb-ba5b7a961261', 14, 14, 'በሁለተኛውም ወር ከወሩም በሃያ ሰባተኛው ቀን ምድር ደረቀች።'),
  ('dbbb2030-a110-5907-a22d-5983ecb6c8c0', 'b97eac3f-4057-558e-a075-fc36bac273d9', '596a487a-4100-5611-a6bb-ba5b7a961261', 15, 15, 'እግዚአብሔርም ለኖኅ እንዲህ ብሎ ነገረው፤'),
  ('a9244588-32c7-55c4-aa6c-ed2ca6649c19', 'b97eac3f-4057-558e-a075-fc36bac273d9', '596a487a-4100-5611-a6bb-ba5b7a961261', 16, 16, '“አንተ ሚስትህንና ልጆችህን፥ የልጆችህንም ሚስቶች ይዘህ ከመርከብ ውጣ።'),
  ('0893f0d7-830e-5b6d-a59f-d90bf3ec5a87', 'b97eac3f-4057-558e-a075-fc36bac273d9', '596a487a-4100-5611-a6bb-ba5b7a961261', 17, 17, 'ከአንተ ጋር ያሉትን አራዊት ሁሉ፥ ሥጋ ያላቸውን ሁሉ፥ ወፎችንና እንስሶችን ሁሉ፥ በምድር ላይ የሚንቀሳቀሱትንም ሁሉ ከአንተ ጋር አውጣቸው፤ በምድርም ላይ ብዙ፤ ተባዙ። ምድርንም ሙሉአት።”'),
  ('375b0595-bb79-52e7-a284-6f99867682ed', 'b97eac3f-4057-558e-a075-fc36bac273d9', '596a487a-4100-5611-a6bb-ba5b7a961261', 18, 18, 'ኖኅም ሚስቱን፥ ልጆቹንና የልጆቹንም ሚስቶች ከእርሱ ጋር ይዞ ወጣ፤'),
  ('3e4d9629-bd50-5c42-a4dd-8e4f165b4f02', 'b97eac3f-4057-558e-a075-fc36bac273d9', '596a487a-4100-5611-a6bb-ba5b7a961261', 19, 19, 'አራዊት ሁሉ፥ እንስሳም ሁሉ፥ ወፎችም ሁሉ፥ በምድር ላይ የሚርመሰመሰው ሁሉ በየወገናቸው ከመርከብ ወጡ።'),
  ('b1d0e603-1df7-5094-a996-c32087850f69', 'b97eac3f-4057-558e-a075-fc36bac273d9', '5d37a7ff-f07f-56e2-ab6b-92419a74633d', 1, 20, 'ኖኅም ለእግዚአብሔር መሠውያዉን ሠራ፥ ከንጹሕም እንስሳ ሁሉ፥ ከንጹሓን ወፎችም ሁሉ ወሰደ፤ በመሠውያውም ላይ መሥዋዕትን አቀረበ።'),
  ('5a5be23f-a6a6-5d83-ab9b-8e4c9c3c4652', 'b97eac3f-4057-558e-a075-fc36bac273d9', '5d37a7ff-f07f-56e2-ab6b-92419a74633d', 2, 21, 'እግዚአብሔር አምላክም መልካሙን መዓዛ አሸተተ፤ እግዚአብሔርም በልቡ አለ፥ “ምድርን ዳግመኛ ስለ ሰዎች ሥራ አልረግምም፤ በሰው ልብ ከታናሽነቱ ጀምሮ ክፋት ሁል ጊዜ ይኖራል፤ ደግሞም ከዚህ ቀደም እንዳደረግሁት ሕያዋንን ሁሉ እንደገና አልመታም።'),
  ('f5eae0cd-bdf0-519f-a1fe-e898e45b110d', 'b97eac3f-4057-558e-a075-fc36bac273d9', '5d37a7ff-f07f-56e2-ab6b-92419a74633d', 3, 22, 'በምድር ዘመን ሁሉ መዝራትና ማጨድ፥ ብርድና ሙቀት፥ በጋና ክረምት፥ ቀንና ሌሊት አያቋርጡም።”'),
  ('1739fc40-690d-5a7f-aad9-faab53292294', '4fb41a0a-a558-55e5-a6e5-4342fae6d87f', 'd538de99-3543-5b88-a25b-12d2d5dde441', 1, 1, 'እግዚአብሔርም ኖኅንና ልጆቹን ባረካቸው፤ እንዲህም አላቸው፥ “ብዙ፤ ተባዙ፤ ምድርንም ሙሉአት፤ ግዙአትም።'),
  ('36897d6a-993a-58a9-a754-212b389c2480', '4fb41a0a-a558-55e5-a6e5-4342fae6d87f', 'd538de99-3543-5b88-a25b-12d2d5dde441', 2, 2, 'አስፈሪነታችሁና አስደንጋጭነታችሁ በምድር አራዊት፥ በሰማይ ወፎች፥ በምድር ላይ በሚንቀሳቀሱትም፥ በባሕር ዓሦችም ሁሉ ላይ ይሁን፤ እነርሱንም በእጃችሁ ሰጠኋችሁ።'),
  ('116195ff-cffd-5813-a428-c1ed42891b2a', '4fb41a0a-a558-55e5-a6e5-4342fae6d87f', 'd538de99-3543-5b88-a25b-12d2d5dde441', 3, 3, 'ሕይወት ያለው ተንቀሳቃሽ ሁሉ መብል ይሁናችሁ፤ ሁሉንም እንደ ለመለመ ቡቃያ ሰጠኋችሁ።'),
  ('facf02df-9e50-54a1-aa92-0ca32e980e76', '4fb41a0a-a558-55e5-a6e5-4342fae6d87f', 'd538de99-3543-5b88-a25b-12d2d5dde441', 4, 4, 'ነገር ግን ደመ ነፍስ ያለበትን ሥጋ አትብሉ፤'),
  ('d3bec479-7fab-5c46-a955-47840a3cf5ad', '4fb41a0a-a558-55e5-a6e5-4342fae6d87f', 'd538de99-3543-5b88-a25b-12d2d5dde441', 5, 5, 'ነፍሳችሁ ያለችበትን ደማችሁን ከአራዊት ሁሉ እጅ እሻዋለሁ፤ ከሰውም እጅ፥ ከሰው ወንድም እጅ፥ የሰውን ነፍስ እሻለሁ።'),
  ('7d365d6c-1b22-50ee-a912-e879cd7f3fd5', '4fb41a0a-a558-55e5-a6e5-4342fae6d87f', 'd538de99-3543-5b88-a25b-12d2d5dde441', 6, 6, 'የሰውን ደም የሚያፈስስ ሁሉ ስለዚያ ደም ፈንታ ደሙ ይፈስሳል፤ ሰውን በእግዚአብሔር መልክ ፈጥሬዋለሁና።'),
  ('01079e30-eb21-5a7e-a5c4-e6d48814e6bd', '4fb41a0a-a558-55e5-a6e5-4342fae6d87f', 'd538de99-3543-5b88-a25b-12d2d5dde441', 7, 7, 'እናንተም ብዙ፤ ተባዙ፤ ምድርንም ሙሉአት፤ ግዙአትም።”'),
  ('ba4310dd-e1d7-52ae-aa27-c8175af535c9', '4fb41a0a-a558-55e5-a6e5-4342fae6d87f', 'd538de99-3543-5b88-a25b-12d2d5dde441', 8, 8, 'እግዚአብሔርም ለኖኅ፥ ከእርሱም ጋር ለልጆቹ እንዲህ ብሎ ተናገረ፦'),
  ('aad84cfb-cc3e-5d4d-acd5-7f523ebab592', '4fb41a0a-a558-55e5-a6e5-4342fae6d87f', 'd538de99-3543-5b88-a25b-12d2d5dde441', 9, 9, '“እኔም እነሆ፥ ቃል ኪዳኔን ከእናንተ ጋር፥ ከእናንተም በኋላ ከዘራችሁ ጋር አጸናለሁ፤'),
  ('8811c9d2-57f6-571f-a1ca-84722f7dc43b', '4fb41a0a-a558-55e5-a6e5-4342fae6d87f', 'd538de99-3543-5b88-a25b-12d2d5dde441', 10, 10, 'ከእናንተ ጋር ላሉትም፥ ሕያው ነፍስ ላላቸው ሁሉ፥ ከእናንተ ጋር ከመርከብ ለወጡት ለወፎች፥ ለእንስሳትም፥ ለምድር አራዊትም ሁሉ፥ ለማንኛውም ለምድር አራዊት ሁሉ ይሆናል።'),
  ('d8954c45-9e1b-5e65-aa97-7cb6e9f22634', '4fb41a0a-a558-55e5-a6e5-4342fae6d87f', 'd538de99-3543-5b88-a25b-12d2d5dde441', 11, 11, 'ቃል ኪዳኔንም ከእናንተ ጋር አጸናለሁ፤ ሥጋ ያለውም ሁሉ ዳግመኛ በጥፋት ውኃ አይጠፋም፤ ምድርንም ለማጥፋት ዳግመኛ የጥፋት ውኃ አይሆንም።”'),
  ('86fb9ee2-c1b9-5293-a5b7-e83b75245274', '4fb41a0a-a558-55e5-a6e5-4342fae6d87f', 'd538de99-3543-5b88-a25b-12d2d5dde441', 12, 12, 'እግዚአብሔር አምላክም ለኖኅ አለው፥ “በእኔና በእናንተ መካከል፥ ከእናንተም ጋር ባለው በሕያው ነፍስ ሁሉ መካከል፥ ለዘለዓለም ትውልድ የማደርገው የቃል ኪዳኔ ምልክት ይህ ነው፤'),
  ('9ad1d548-8dd4-524b-a1ee-555b26baefe5', '4fb41a0a-a558-55e5-a6e5-4342fae6d87f', 'd538de99-3543-5b88-a25b-12d2d5dde441', 13, 13, 'ቀስቴን በደመና አኖራለሁ፤ የቃል ኪዳኔም ምልክት በእኔና በምድር መካከል ይሆናል።'),
  ('90dd73bb-942b-550f-ab2d-108e7ce7974f', '4fb41a0a-a558-55e5-a6e5-4342fae6d87f', 'd538de99-3543-5b88-a25b-12d2d5dde441', 14, 14, 'በምድር ላይ ደመናን በጋረድሁ ጊዜ ቀስቴ በደመናው ትታያለች፤'),
  ('80ad4f3e-2422-52aa-aaa3-ea304d74f176', '4fb41a0a-a558-55e5-a6e5-4342fae6d87f', 'd538de99-3543-5b88-a25b-12d2d5dde441', 15, 15, 'በእኔና በእናንተ መካከል፥ ሕያው ነፍስ ባለውም ሥጋ ሁሉ መካከል ያለውን ቃል ኪዳኔን አስባለሁ፤ ሥጋ ያለውንም ሁሉ ያጠፋ ዘንድ ዳግመኛ የጥፋት ውኃን አላመጣም።'),
  ('636e53cd-b140-5c8e-a72e-6ba7e2aba902', '4fb41a0a-a558-55e5-a6e5-4342fae6d87f', 'd538de99-3543-5b88-a25b-12d2d5dde441', 16, 16, 'ቀስቴም በደመና ትሆናለች፤ በእኔና በምድር መካከል፥ በምድር ላይ በሚኖር ሥጋ ባለው በሕያው ነፍስ ሁሉ መካከል ያለውን የዘለዓለም ቃል ኪዳን ለማሰብ አያታለሁ።”'),
  ('79fbcc95-2dd1-51e1-a4a2-eff824ca23b2', '4fb41a0a-a558-55e5-a6e5-4342fae6d87f', 'd538de99-3543-5b88-a25b-12d2d5dde441', 17, 17, 'እግዚአብሔርም ኖኅን፥ “በእኔና በምድር ላይ በሚኖር፥ ሥጋ ባለው ሁሉ መካከል ያጸናሁት የቃል ኪዳን ምልክት ይህ ነው” አለው።'),
  ('4dc448b5-5d1d-5595-a28e-e3b787b6f54c', '4fb41a0a-a558-55e5-a6e5-4342fae6d87f', '649eb97f-78ac-546f-accd-07d91a9e3db1', 1, 18, 'ከመርከብ የወጡት የኖኅ ልጆችም እነዚህ ናቸው፤ ሴም፥ ካም፥ ያፌት፤ ካምም የከነዓን አባት ነው።'),
  ('65b73be8-6f8c-5b06-a387-ecb462bcb4f6', '4fb41a0a-a558-55e5-a6e5-4342fae6d87f', '649eb97f-78ac-546f-accd-07d91a9e3db1', 2, 19, 'በምድር ሁሉ ላይ የተበተኑ የኖኅ ልጆች እነዚህ ሦስቱ ናቸው።'),
  ('8983b9b5-0333-56ab-a471-4381165a61fb', '4fb41a0a-a558-55e5-a6e5-4342fae6d87f', '649eb97f-78ac-546f-accd-07d91a9e3db1', 3, 20, 'ኖኅም ገበሬ መሆን ጀመረ፤ ወይንም ተከለ።'),
  ('80fe38d0-0ee6-5af4-a660-056bc6c2bb87', '4fb41a0a-a558-55e5-a6e5-4342fae6d87f', '649eb97f-78ac-546f-accd-07d91a9e3db1', 4, 21, 'ከወይን ጠጁም ጠጣና ሰከረ፤ በድንኳኑም ውስጥ ዕራቁቱን ሆነ።'),
  ('665c2e62-2425-584c-a728-f6b5c7a1c9c2', '4fb41a0a-a558-55e5-a6e5-4342fae6d87f', '649eb97f-78ac-546f-accd-07d91a9e3db1', 5, 22, 'የከነዓን አባት ካምም የአባቱን ዕራቁትነት አየ፤ ወደ ውጭም ወጥቶ ለሁለቱ ወንድሞቹ ነገራቸው።'),
  ('dfa8a9d1-9809-5810-a07f-0fd4168d856d', '4fb41a0a-a558-55e5-a6e5-4342fae6d87f', '649eb97f-78ac-546f-accd-07d91a9e3db1', 6, 23, 'ሴምና ያፌትም ልብስ ወስደው በጫንቃቸው ላይ አደረጉ፤ የኋሊትም ሄደው የአባታቸውን ዕራቁትነት አለበሱ፤ ፊታቸውም ወደ ኋላ ነበር፤ የአባታቸውንም ዕራቁትነት አላዩም።'),
  ('63e3b927-58a4-504b-a688-122c897c96b5', '4fb41a0a-a558-55e5-a6e5-4342fae6d87f', '649eb97f-78ac-546f-accd-07d91a9e3db1', 7, 24, 'ኖኅም ከወይኑ ስካር በነቃ ጊዜ፥ ታናሹ ልጁ ያደረገበትን ዐወቀ።'),
  ('6a153308-98f7-51ae-aac5-8af37e0b3497', '4fb41a0a-a558-55e5-a6e5-4342fae6d87f', '649eb97f-78ac-546f-accd-07d91a9e3db1', 8, 25, 'ኖኅም እንዲህ አለ፥ “ከነዓን ርጉም ይሁን፤ ለወንድሞቹም የባሪያዎች ባሪያ ይሁን።”'),
  ('466ca3df-2986-5615-aa5f-136a26386fdf', '4fb41a0a-a558-55e5-a6e5-4342fae6d87f', '649eb97f-78ac-546f-accd-07d91a9e3db1', 9, 26, 'እንዲህም አለ፥ “የሴም አምላክ እግዚአብሔር ይባረክ፤ ከነዓንም ለእርሱ ባሪያ ይሁን።'),
  ('1c861cd3-ec3f-5baa-ac15-ee0ab5fdd87a', '4fb41a0a-a558-55e5-a6e5-4342fae6d87f', '649eb97f-78ac-546f-accd-07d91a9e3db1', 10, 27, 'እግዚአብሔር የያፌትን ሀገር ያስፋ፤ በሴምም ድንኳን ይደር፤ ከነዓንም ለእርሱ ባሪያ ይሁን።”'),
  ('043c62ce-29e1-5289-a40e-036a9e839f74', '4fb41a0a-a558-55e5-a6e5-4342fae6d87f', '649eb97f-78ac-546f-accd-07d91a9e3db1', 11, 28, 'ኖኅም ከጥፋት ውኃ በኋላ ሦስት መቶ አምሳ ዓመት ኖረ።'),
  ('77f1935e-610f-5264-a55a-191b4d93ef5b', '4fb41a0a-a558-55e5-a6e5-4342fae6d87f', '649eb97f-78ac-546f-accd-07d91a9e3db1', 12, 29, 'ኖኅም የኖረበት ዘመን ሁሉ ዘጠኝ መቶ አምሳ ዓመት ሆነ፤ ሞተም።'),
  ('7292cbb6-65fe-5e9e-a784-86d88e0bed3c', '5322c977-de0b-592a-ab43-062873c135f2', '9af5cd8f-39cd-5265-a431-62349912e2ca', 1, 1, 'የኖኅ ልጆች የሴም፥ የካምና፥ የያፌት ትውልድ ይህ ነው፤ ከጥፋት ውኃም በኋላ ልጆች ተወለዱላቸው።'),
  ('d08205e0-e9ed-5379-a246-e45593516491', '5322c977-de0b-592a-ab43-062873c135f2', '7dba81cc-cb0c-52e9-aa63-f416a2b145dd', 1, 2, 'የያፌት ልጆች ጋሜር፥ ማጎግ፥ ማዴ፥ ይህያን፥ ይልሳ፥ ቶቤል፥ሞሳሕ፥ ቴራስ ናቸው።'),
  ('d4bb0c2c-c0c9-59f1-a78b-f8568fc0993a', '5322c977-de0b-592a-ab43-062873c135f2', '7dba81cc-cb0c-52e9-aa63-f416a2b145dd', 2, 3, 'የጋሜርም ልጆች አስከናዝ፥ ሪፋት፥ ቴርጋማ ናቸው።'),
  ('f04f7ebb-a27a-56bd-a562-baa52f073c01', '5322c977-de0b-592a-ab43-062873c135f2', '7dba81cc-cb0c-52e9-aa63-f416a2b145dd', 3, 4, 'የይህያንም ልጆች ኤልሳ፥ ተርሴስ፥ ኬቲም፥ ሮድኢ ናቸው።'),
  ('a75f4e26-a370-5a48-a1bf-b72fc22a6ae8', '5322c977-de0b-592a-ab43-062873c135f2', '7dba81cc-cb0c-52e9-aa63-f416a2b145dd', 4, 5, 'ከእነዚህም የአሕዛብ ደሴቶች ሁሉ በየምድራቸው፥ በየቋንቋቸው፥ በየነገዳቸው፥ በየሕዝባቸው ተከፋፈሉ።'),
  ('41216cf9-16e6-517f-ae7d-166f75aaa452', '5322c977-de0b-592a-ab43-062873c135f2', '41695203-15a0-5b00-ab86-aeb464d68988', 1, 6, 'የካምም ልጆች ኩሽ፥ ምስራይም፥ ፉጥ፥ ከነዓን ናቸው።'),
  ('aae594a4-2c93-531b-ab19-ced9f7fb2360', '5322c977-de0b-592a-ab43-062873c135f2', '41695203-15a0-5b00-ab86-aeb464d68988', 2, 7, 'የኩሽም ልጆች ሳባ፥ ኤውላጥ፥ ሰብታ፥ ሬጌም፥ ሰበቅታ ናቸው። የሬጌም ልጆችም ሳባ፥ ዮድዳን ናቸው።'),
  ('ce322dbc-06bb-5d7a-a8e7-c53fe8e3fb46', '5322c977-de0b-592a-ab43-062873c135f2', '41695203-15a0-5b00-ab86-aeb464d68988', 3, 8, 'ኩሽም ናምሩድን ወለደ፤ እርሱም በምድር ላይ ኀያል መሆን ጀመረ።'),
  ('77112d62-e9e4-51af-ae03-8fcb2d9e9377', '5322c977-de0b-592a-ab43-062873c135f2', '41695203-15a0-5b00-ab86-aeb464d68988', 4, 9, 'እርሱም በእግዚአብሔር ፊት ኀያል አዳኝ ነበረ፤ ስለዚህም በእግዚአብሔር ፊት ኀያል አዳኝ እንደ ናምሩድ ተባለ።'),
  ('1b98424a-44ea-59af-adaa-7bf05623e9ca', '5322c977-de0b-592a-ab43-062873c135f2', '41695203-15a0-5b00-ab86-aeb464d68988', 5, 10, 'የግዛቱም መጀመሪያ በሰናዖር ሀገር ባቢሎን፥ ኦሬክ፥ አርካድ፥ ካሌድን ናቸው።'),
  ('68eea909-b152-5f3e-ada6-540456fefe20', '5322c977-de0b-592a-ab43-062873c135f2', '41695203-15a0-5b00-ab86-aeb464d68988', 6, 11, 'አሦርም ከዚያች ሀገር ወጣ፤ ነነዌን፥ ረሆቦት የተባለችውን ከተማ ካለህን፥'),
  ('5fee06b3-36d5-5dfc-aefb-48f4151016a3', '5322c977-de0b-592a-ab43-062873c135f2', '41695203-15a0-5b00-ab86-aeb464d68988', 7, 12, 'በነነዌና በካለህ መካከልም ዳስን ሠራ፤ እርስዋም ታላቂቱ ከተማ ናት።'),
  ('1864d6f6-e402-5c8d-ab52-cbb5bf17d4e2', '5322c977-de0b-592a-ab43-062873c135f2', '41695203-15a0-5b00-ab86-aeb464d68988', 8, 13, 'ምስራይምም ሉዲምን፥ ኢኒሜቲምን፥ ላህቢምን፥ ንፍታሌምን፥ ጳጥሮሶኒምን፥'),
  ('327a1c77-9082-50a1-aa32-52f2cd529ea5', '5322c977-de0b-592a-ab43-062873c135f2', '41695203-15a0-5b00-ab86-aeb464d68988', 9, 14, 'ከእነርሱ የፍልስጥኤም ሰዎች የወጡባቸውን ከስሎሂምንና ቀፍቶሪምንም ወለደ።'),
  ('63562cba-05c6-5360-aef7-1c936089e0f9', '5322c977-de0b-592a-ab43-062873c135f2', '41695203-15a0-5b00-ab86-aeb464d68988', 10, 15, 'ከነዓንም የበኵር ልጁን ሲዶንን፥ ኬጤዎንን፥')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('dcea13a6-9310-5208-a817-332bf08b5b1d', '5322c977-de0b-592a-ab43-062873c135f2', '41695203-15a0-5b00-ab86-aeb464d68988', 11, 16, 'ኢያቡሴዎንን፥ አሞሬዎንን፥ ጌርጌሴዎንን፥'),
  ('a5b08197-90df-57a7-aae2-3859d66c2ebb', '5322c977-de0b-592a-ab43-062873c135f2', '41695203-15a0-5b00-ab86-aeb464d68988', 12, 17, 'ኤዌዎንን፥ አሩቄዎንን፥ ኤሴኒዎንን፥'),
  ('b8693488-1634-5f78-ae29-89b4d85405a9', '5322c977-de0b-592a-ab43-062873c135f2', '41695203-15a0-5b00-ab86-aeb464d68988', 13, 18, 'አራዲዎንን፥ ሰማርዮንን፥ አማቲንን ወለደ። ከዚህም በኋላ የከነዓናውያን ነገድ ተበተኑ።'),
  ('2ae2cb49-3d8e-5e6a-addd-64bcda4453bb', '5322c977-de0b-592a-ab43-062873c135f2', '41695203-15a0-5b00-ab86-aeb464d68988', 14, 19, 'የከነዓናውያንም ወሰን ከሲዶን እስከ ጌራራና ጋዛ ድረስ ነው፤ ወደ ሰዶምና ወደ ገሞራ፥ ወደ አዳማና ወደ ሴባዮም እስከ ላሳ ይደርሳል።'),
  ('8aa26087-3344-52e2-abb1-9ad99780a631', '5322c977-de0b-592a-ab43-062873c135f2', '41695203-15a0-5b00-ab86-aeb464d68988', 15, 20, 'የካም ልጆች በየነገዳቸውና በየቋንቋቸው፥ በየምድራቸውና በየሕዝባቸው እነዚህ ናቸው።'),
  ('ce1e0b28-0254-5f2e-ae22-2b9dbed7eed7', '5322c977-de0b-592a-ab43-062873c135f2', '97798ec7-835e-5f8e-a8cf-04796479b3b3', 1, 21, 'ለሴምም ደግሞ ልጆች ተወለዱለት፤ እርሱም የያፌት ታላቅ ወንድምና የዔቦር ልጆች ሁሉ አባት የሆነው ነው።'),
  ('59ccc26d-0ab8-5475-a24d-eab9647f828e', '5322c977-de0b-592a-ab43-062873c135f2', '97798ec7-835e-5f8e-a8cf-04796479b3b3', 2, 22, 'የሴምም ልጆች ኤላም፥ አሦር፥ አርፋክስድ፥ ሉድ፥ አራም፥ ቃይናን።'),
  ('781a869e-2c08-5f03-affa-341f6ff5ab82', '5322c977-de0b-592a-ab43-062873c135f2', '97798ec7-835e-5f8e-a8cf-04796479b3b3', 3, 23, 'የአራምም ልጆች ዑፅ፥ ሁል፥ ጋቴር፥ ሞሳሕ ናቸው።'),
  ('cf1fbdbf-6fd8-502d-ad2f-750d3ae94ddd', '5322c977-de0b-592a-ab43-062873c135f2', '97798ec7-835e-5f8e-a8cf-04796479b3b3', 4, 24, 'አርፋክስድም ቃይናንን ወለደ፤ ቃይናንም ሳላን፥ ሳላም ዔቦርን ወለደ።'),
  ('94de16f4-2cb0-564e-a694-cff05d0ea333', '5322c977-de0b-592a-ab43-062873c135f2', '97798ec7-835e-5f8e-a8cf-04796479b3b3', 5, 25, 'ለዔቦርም ሁለት ልጆች ተወለዱለት፤ የአንደኛው ስሙ ፋሌቅ ነው፤ ምድር በዘመኑ ተከፍላለችና፤ የወንድሙም ስም ዮቅጣን ነው።'),
  ('87535e66-ad09-5304-a7ea-eb24a17fd653', '5322c977-de0b-592a-ab43-062873c135f2', '97798ec7-835e-5f8e-a8cf-04796479b3b3', 6, 26, 'ዮቅጣንም ኤልሞዳድን፥ ሳሌፍንም፥ ሐሰረሞትንም፥ ያራሕንም፥'),
  ('1dd013f4-060c-5825-a794-d0bc78b8483b', '5322c977-de0b-592a-ab43-062873c135f2', '97798ec7-835e-5f8e-a8cf-04796479b3b3', 7, 27, 'ሀዶራምንም፥ አዚላንም፥ ደቅላንም፥'),
  ('0694bff0-1c04-5b30-ad07-98ea267a18ec', '5322c977-de0b-592a-ab43-062873c135f2', '97798ec7-835e-5f8e-a8cf-04796479b3b3', 8, 28, 'ዖባልንም፥ አቤማኤልንም፥ ሳባንም፥'),
  ('3cc8b077-f762-57b8-abf2-2d4a5e786fb9', '5322c977-de0b-592a-ab43-062873c135f2', '97798ec7-835e-5f8e-a8cf-04796479b3b3', 9, 29, 'አፌርንም፥ ኤውላጥንም፥ ዮባብንም ወለደ፤ እነዚህ ሁሉ የዮቅጣን ልጆች ናቸው።'),
  ('5a1ec3af-ff2e-58f5-a6a8-1e07e1a53557', '5322c977-de0b-592a-ab43-062873c135f2', '97798ec7-835e-5f8e-a8cf-04796479b3b3', 10, 30, 'ስፍራቸውም ከማሲ አንስቶ ወደ ስፋር ሲል እስከ ምሥራቅ ተራራ ድረስ ነው።'),
  ('13c0d555-f1bc-523b-a2fd-2bf7d9659f65', '5322c977-de0b-592a-ab43-062873c135f2', '97798ec7-835e-5f8e-a8cf-04796479b3b3', 11, 31, 'የሴም ልጆች በየነገዳቸውና በየቋንቋቸው፥ በየምድራቸውና በየሕዝባቸው እነዚህ ናቸው።'),
  ('595e3fd3-f3eb-54cd-a43b-8c7cc7e5f83e', '5322c977-de0b-592a-ab43-062873c135f2', '97798ec7-835e-5f8e-a8cf-04796479b3b3', 12, 32, 'የኖኅ የልጆቹ ነገዶች እንደ ትውልዳቸው በየሕዝባቸው እነዚህ ናቸው። ከእነዚህም ከጥፋት ውኃ በኋላ ሕዝቦች በምድር ላይ ተዘሩ።'),
  ('33ca8239-813b-586d-a7ea-4c6972601ae1', 'd27621ea-2c75-5e98-a2b4-c42348e3e780', 'fbce5586-8833-5c29-a15b-347bec20f131', 1, 1, 'የዓለም ሁሉ ቋንቋ አንድ፥ ንግግሩም አንድ ነበረ።'),
  ('5bb2838e-89bf-5d08-a22d-184847df4d12', 'd27621ea-2c75-5e98-a2b4-c42348e3e780', 'fbce5586-8833-5c29-a15b-347bec20f131', 2, 2, 'እንዲህም ሆነ፤ ከምሥራቅም ተነሥተው በሄዱ ጊዜ በሰናዖር ምድር አንድ ሜዳ አገኙ፤ በዚያም ተቀመጡ።'),
  ('e507eb34-b062-5e33-a3dc-c67d098d7402', 'd27621ea-2c75-5e98-a2b4-c42348e3e780', 'fbce5586-8833-5c29-a15b-347bec20f131', 3, 3, 'እርስ በርሳቸውም፥ “ኑ ጡብ እንሥራ፤ በእሳትም እንተኵሰው” ተባባሉ። ጡባቸውም እንደ ድንጋይ፥ ጭቃቸውም እንደ ዝፍት ሆነላቸው።'),
  ('31baa22b-fadb-55cf-affb-c40517e97e89', 'd27621ea-2c75-5e98-a2b4-c42348e3e780', 'fbce5586-8833-5c29-a15b-347bec20f131', 4, 4, 'እርስ በርሳቸውም፥ “ኑ ለእኛ ከተማና ራሱ ወደ ሰማይ የሚደርስ ግንብ እንሥራ፤ በምድር ፊት ሁሉ ላይ ሳንበተን ስማችንን እናስጠራው” ተባባሉ።'),
  ('092f3795-d1fe-5ab3-a0b6-72c8e694577f', 'd27621ea-2c75-5e98-a2b4-c42348e3e780', 'fbce5586-8833-5c29-a15b-347bec20f131', 5, 5, 'እግዚአብሔርም የሰዎች ልጆች የሠሩትን ከተማና ግንብ ለማየት ወረደ።'),
  ('d3fc5aee-8b2c-57d3-a0a2-37b5b7ac5b20', 'd27621ea-2c75-5e98-a2b4-c42348e3e780', 'fbce5586-8833-5c29-a15b-347bec20f131', 6, 6, 'እግዚአብሔርም አለ፥ “እነሆ፥ እነርሱ አንድ ወገን ናቸው፤ ለሁሉም አንድ ቋንቋ አላቸው፤ ይህንም ለማድረግ ጀመሩ፤ አሁንም ያሰቡትን ሁሉ መሥራትን አይተዉም።'),
  ('da7f3c51-e702-56c6-a20d-79c2bd16ae30', 'd27621ea-2c75-5e98-a2b4-c42348e3e780', 'fbce5586-8833-5c29-a15b-347bec20f131', 7, 7, 'ኑ እንውረድ፤ አንዱ የሌላውን ነገር እንዳይሰማው ቋንቋቸውን በዚያ እንደባልቀው።”'),
  ('50976491-50c2-5958-ab82-eba39da91e98', 'd27621ea-2c75-5e98-a2b4-c42348e3e780', 'fbce5586-8833-5c29-a15b-347bec20f131', 8, 8, 'እግዚአብሔርም ቋንቋቸውን ለያየ፤ ከዚያም በምድር ፊት ሁሉ ላይ በተናቸው፤ ከዚያም በኋላ ከተማዪቱንና ግንቡን መሥራትን ተዉ።'),
  ('910de81b-68f4-5246-aa6f-1e8e32fe7c1d', 'd27621ea-2c75-5e98-a2b4-c42348e3e780', 'fbce5586-8833-5c29-a15b-347bec20f131', 9, 9, 'ስለዚህም ስምዋ ባቢሎን ተባለ፤ እግዚአብሔር በዚያ የምድርን ቋንቋ ሁሉ ደባልቆአልና፤ ከዚያም እግዚአብሔር በምድር ሁሉ ፊት ላይ እነርሱን በትኖአቸዋል።'),
  ('152f283f-1936-5fdb-a17c-be6d1dae7b5e', 'd27621ea-2c75-5e98-a2b4-c42348e3e780', '0be85c41-07ea-5a59-a49b-b25f839526b0', 1, 10, 'የሴም ትውልድ ይህ ነው። ሴም ከጥፋት ውኃ በኋላ በሁለተኛው ዓመት አርፋክስድን በወለደ ጊዜ የመቶ ዓመት ሰው ነበረ።'),
  ('0f739fbd-cb38-5e9b-a3ec-43df9b17c64e', 'd27621ea-2c75-5e98-a2b4-c42348e3e780', '0be85c41-07ea-5a59-a49b-b25f839526b0', 2, 11, 'ሴምም አርፋክስድን ከወለደ በኋላ አምስት መቶ ዓመት ኖረ፤ ወንዶችንም፥ ሴቶችንም ወለደ፤ ሞተም።'),
  ('25f2520f-e4b6-5afe-a6c7-a42a378ee332', 'd27621ea-2c75-5e98-a2b4-c42348e3e780', '0be85c41-07ea-5a59-a49b-b25f839526b0', 3, 12, 'አርፋክስድም መቶ ሠላሳ አምስት ዓመት ኖረ፤ ቃይናንንም ወለደ፤'),
  ('9745717b-855a-571b-a554-83d31a7a2cf1', 'd27621ea-2c75-5e98-a2b4-c42348e3e780', '0be85c41-07ea-5a59-a49b-b25f839526b0', 4, 13, 'አርፋክስድም ቃይናንን ከወለደ በኋላ አራት መቶ አርባ ዓመት ኖረ፤ ወንዶችንም፥ ሴቶችንም ወለደ፤ ሞተም። ቃይናንም መቶ ሠላሳ ዓመት ኖረ፤ ሳላንም ወለደ፤ ቃይናንም ሳላን ከወለደ በኋላ አራት መቶ ሠላሳ ዓመት ኖረ፤ ወንዶችንም፥ ሴቶችንም ልጆች ወለደ፤ ሞተም።'),
  ('3b00326a-17a9-52d4-af91-4b9826ee8f67', 'd27621ea-2c75-5e98-a2b4-c42348e3e780', '0be85c41-07ea-5a59-a49b-b25f839526b0', 5, 14, 'ሳላም መቶ ሠላሳ ዓመት ኖረ፤ ዔቦርንም ወለደ፤'),
  ('96fe1927-8734-50e8-ab1a-f4a11fc70f25', 'd27621ea-2c75-5e98-a2b4-c42348e3e780', '0be85c41-07ea-5a59-a49b-b25f839526b0', 6, 15, 'ሳላም ዔቦርን ከወለደ በኋላ አራት መቶ ሠላሳ ዓመት ኖረ፤ ወንዶችንም ሴቶችንም ወለደ፤ ሞተም።'),
