  ('798c82f5-782b-589d-a2b2-6113e7ad08dc', 'd27621ea-2c75-5e98-a2b4-c42348e3e780', '0be85c41-07ea-5a59-a49b-b25f839526b0', 9, 18, 'ፋሌቅም መቶ ሠላሳ ዓመት ኖረ፤ ራግውንም ወለደ፤'),
