  ('f9076144-ed22-5951-a533-319da251727f', 'd27621ea-2c75-5e98-a2b4-c42348e3e780', '0be85c41-07ea-5a59-a49b-b25f839526b0', 14, 23, 'ሴሮሕም ናኮርን ከወለደ በኋላ ሁለት መቶ ዓመት ኖረ፤ ወንዶችንም፥ ሴቶችንም ወለደ፤ ሞተም።'),
  ('dfb29134-9135-572a-a257-ec37e3aeb7bd', 'd27621ea-2c75-5e98-a2b4-c42348e3e780', '0be85c41-07ea-5a59-a49b-b25f839526b0', 15, 24, 'ናኮርም መቶ ዘጠኝ ዓመት ኖረ፤ ታራንም ወለደ፤'),
