  ('9568a25e-2cd5-5574-a2ce-69bb26de4882', 'd27621ea-2c75-5e98-a2b4-c42348e3e780', '730dc5bb-5190-53de-af87-243be3d4f6a3', 1, 26, 'ታራም መቶ ዓመት ኖረ፥ አብራምንና ናኮርን፥ አራንንም ወለደ።'),
  ('7e6cdc7e-bfa9-5a6f-a844-a2070f5cbbfc', 'd27621ea-2c75-5e98-a2b4-c42348e3e780', '730dc5bb-5190-53de-af87-243be3d4f6a3', 2, 27, 'አራንም ሎጥን ወለደ።'),
  ('55a4e01c-c9f7-516f-ae31-7ea8f6ff0be8', 'd27621ea-2c75-5e98-a2b4-c42348e3e780', '730dc5bb-5190-53de-af87-243be3d4f6a3', 3, 28, 'አራንም በተወለደባት ሀገር በከለዳውያን ምድር በአባቱ በታራ ፊት ሞተ።'),
  ('b811025c-4570-5822-a3ee-903a299b911f', 'd27621ea-2c75-5e98-a2b4-c42348e3e780', '730dc5bb-5190-53de-af87-243be3d4f6a3', 4, 29, 'አብራምና ናኮርም ሚስቶችን አገቡ፤ የአብራም ሚስት ስምዋ ሦራ ነው፤ የናኮርም ሚስት የአራን ልጅ ሚልካ ናት፤ አራንም የሚልካና የዮስካ አባት ነው።'),
  ('8a4f7bea-b1e0-524f-a612-98de95472777', 'd27621ea-2c75-5e98-a2b4-c42348e3e780', '730dc5bb-5190-53de-af87-243be3d4f6a3', 5, 30, 'ሦራም መካን ነበረች፤ ልጆችም አልነበሩአትም።'),
  ('c374de09-7328-5e90-a351-95f5e054883f', 'd27621ea-2c75-5e98-a2b4-c42348e3e780', '730dc5bb-5190-53de-af87-243be3d4f6a3', 6, 31, 'ታራም ልጁን አብራምንና የልጅ ልጁን የአራንን ልጅ ሎጥን፥ የልጁንም የአብራምን ሚስት ምራቱን ሦራን ወሰደ፤ ከእርሱም ጋር ወደ ከነዓን ምድር ይሄዱ ዘንድ ከከለዳውያን ምድር አወጣቸው። ወደ ካራንም መጡ፤ በዚያም ተቀመጡ።'),
  ('dd62c378-8482-560c-a507-a0594eec864a', 'd27621ea-2c75-5e98-a2b4-c42348e3e780', '730dc5bb-5190-53de-af87-243be3d4f6a3', 7, 32, 'ታራም በካራን ምድር የኖረበት ዘመን ሁለት መቶ አምስት ዓመት ሆነ፤ ታራም በካራን ሞተ።'),
  ('613cac52-979a-51f7-ae98-dc780f79ce32', 'bb4049b6-05c3-5c7f-a2ca-af38dad22941', 'd6b74b17-df57-5b7f-ad23-e760589f00c0', 1, 1, 'እግዚአብሔርም አብራምን አለው፥ “ከሀገርህ፥ ከዘመዶችህም፥ ከአባትህም ቤት ተለይተህ ውጣ፤ እኔ ወደማሳይህም ምድር ሂድ።'),
  ('73d8863e-6452-5c9c-a1b2-bb52b7449166', 'bb4049b6-05c3-5c7f-a2ca-af38dad22941', 'd6b74b17-df57-5b7f-ad23-e760589f00c0', 2, 2, 'ታላቅ ሕዝብም አደርግሃለሁ፤ እባርክሃለሁ፤ ስምህንም ከፍ ከፍ አደርጋለሁ፤ ቡሩክም ትሆናለህ፤ የሚባርኩህንም እባርካለሁ፤'),
  ('fb9ef6d4-7262-59b0-af45-095762f10301', 'bb4049b6-05c3-5c7f-a2ca-af38dad22941', 'd6b74b17-df57-5b7f-ad23-e760589f00c0', 3, 3, 'የሚረግሙህንም እረግማለሁ፤ የምድር ነገዶችም ሁሉ በአንተ ይባረካሉ።”'),
  ('3bd96459-75ce-58c5-ab6f-d2b15bc44920', 'bb4049b6-05c3-5c7f-a2ca-af38dad22941', 'd6b74b17-df57-5b7f-ad23-e760589f00c0', 4, 4, 'አብራምም እግዚአብሔር እንደ ነገረው ሄደ፤ ሎጥም ከእርሱ ጋር ሄደ፤ አብራምም ከካራን በወጣ ጊዜ ሰባ አምስት ዓመት ሆኖት ነበረ።'),
  ('0ccd98b4-36f8-5d1d-a05d-66757b5e221a', 'bb4049b6-05c3-5c7f-a2ca-af38dad22941', 'd6b74b17-df57-5b7f-ad23-e760589f00c0', 5, 5, 'አብራምም ሚስቱን ሦራንና የወንድሙን ልጅ ሎጥን፥ ያገኙትን ከብት ሁሉና በካራን ያገኙአቸውን ሰዎች ይዞ ወደ ከነዓን ምድር ለመሄድ ወጣ፤ ወደ ከነዓንም ምድር ገቡ።'),
  ('7e8f9aa6-b826-5dc4-adf2-a17acad2638a', 'bb4049b6-05c3-5c7f-a2ca-af38dad22941', 'd6b74b17-df57-5b7f-ad23-e760589f00c0', 6, 6, 'አብራምም እስከ ሴኬም ስፍራ እስከ ታላቁ ዛፍ ድረስ በዚያች ምድር አለፈ፤ የከነዓን ሰዎችም በዚያን ጊዜ በዚያች ምድር ነበሩ።'),
  ('42a2654a-117e-5015-a0c8-d19341c4e32b', 'bb4049b6-05c3-5c7f-a2ca-af38dad22941', 'd6b74b17-df57-5b7f-ad23-e760589f00c0', 7, 7, 'እግዚአብሔርም ለአብራም ተገለጠለትና፥ “ይህችን ምድር ለዘርህ እሰጣለሁ” አለው። አብራምም ለእርሱ ለተገለጠለት ለእግዚአብሔር በዚያ መሠውያን ሠራ።'),
  ('e11383e6-f49b-50c9-a504-46f562d051c8', 'bb4049b6-05c3-5c7f-a2ca-af38dad22941', 'd6b74b17-df57-5b7f-ad23-e760589f00c0', 8, 8, 'ከዚያም በቤቴል ምሥራቅ ወዳለው ተራራ ወጣ፤ በዚያም ቤቴልን ወደ ምዕራብ፥ ጋይን ወደ ምሥራቅ አድርጎ ድንኳኑን ተከለ፤ በዚያም ለእግዚአብሔር መሠውያን ሠራ፤ የእግዚአብሔርንም ስም ጠራ።'),
  ('425db93f-d741-5e9c-a1bd-9c41b43992f1', 'bb4049b6-05c3-5c7f-a2ca-af38dad22941', 'd6b74b17-df57-5b7f-ad23-e760589f00c0', 9, 9, 'አብራምም ከዚያ ተነሣ፤ እየተጓዘም ወደ አዜብ ሄደ፤ በዚያም ኖረ።'),
  ('a8720673-52c3-5a3f-afd8-7a3e7357d4c2', 'bb4049b6-05c3-5c7f-a2ca-af38dad22941', 'de5a2431-a228-5218-afdb-42f5e7e3abcf', 1, 10, 'በምድርም ራብ ሆነ፤ አብራምም በዚያ በእንግድነት ይቀመጥ ዘንድ ወደ ግብፅ ወረደ፤ በምድር ራብ ጠንቶ ነበረና።'),
  ('064c0a4c-10dc-5a50-a6be-6422c457fb25', 'bb4049b6-05c3-5c7f-a2ca-af38dad22941', 'de5a2431-a228-5218-afdb-42f5e7e3abcf', 2, 11, 'እንዲህም ሆነ፤ አብራም ወደ ግብፅ ለመግባት በቀረበ ጊዜ ሚስቱን ሦራን እንዲህ አላት፥ “አንቺ መልከ መልካም ሴት እንደ ሆንሽ እነሆ እኔ አውቃለሁ፤'),
  ('22cd1ef8-ee38-574f-a98b-3e10429814fd', 'bb4049b6-05c3-5c7f-a2ca-af38dad22941', 'de5a2431-a228-5218-afdb-42f5e7e3abcf', 3, 12, 'የግብፅ ሰዎች ያዩሽ እንደ ሆነ ሚስቱ ናት ይላሉ፤ እኔንም ይገድሉኛል፤ አንቺንም በሕይወት ይተዉሻል።'),
  ('d23e4317-ee1f-54e3-a8ed-691a19fa9533', 'bb4049b6-05c3-5c7f-a2ca-af38dad22941', 'de5a2431-a228-5218-afdb-42f5e7e3abcf', 4, 13, 'እንግዲህ በአንቺ ምክንያት መልካም ይሆንልኝ ዘንድ፥ ስለ አንቺም ነፍሴ ትድን ዘንድ እኅቱ ነኝ በዪ።”'),
  ('76cffda9-ab81-575b-a088-fc12ac4a608a', 'bb4049b6-05c3-5c7f-a2ca-af38dad22941', 'de5a2431-a228-5218-afdb-42f5e7e3abcf', 5, 14, 'እንዲህም ሆነ፤ አብራም ወደ ግብፅ በገባ ጊዜ የግብፅ ሰዎች ሴቲቱን እጅግ ውብ እንደ ሆነች አዩ፤'),
  ('4ffd4ffb-2472-5993-a180-b55bd49c7f32', 'bb4049b6-05c3-5c7f-a2ca-af38dad22941', 'de5a2431-a228-5218-afdb-42f5e7e3abcf', 6, 15, 'የፈርዖንም አለቆች አዩአት፤ በፈርዖንም ፊት አደነቁአት፤ ወደ ፈርዖን ቤትም ወሰዱአት።'),
  ('73c8af8c-723c-51f4-a5d4-62529c228de3', 'bb4049b6-05c3-5c7f-a2ca-af38dad22941', 'de5a2431-a228-5218-afdb-42f5e7e3abcf', 7, 16, 'ለአብራምም ስለ እርስዋ መልካም አደረጉለት፤ ለእርሱ በጎችም፥ በሬዎችም፥ አህዮችም፥ በቅሎዎችም፥ ወንዶችና ሴቶች ባሪያዎችም፥ ግመሎችም ነበሩት።'),
  ('49669207-dd94-5932-a515-c748ba02da8e', 'bb4049b6-05c3-5c7f-a2ca-af38dad22941', 'de5a2431-a228-5218-afdb-42f5e7e3abcf', 8, 17, 'እግዚአብሔርም በአብራም ሚስት በሦራ ምክንያት ፈርዖንንና የቤቱን ሰዎች በታላቅ መቅሠፍት መታ።'),
  ('40a5642d-a707-530f-a0ae-af794989b97f', 'bb4049b6-05c3-5c7f-a2ca-af38dad22941', 'de5a2431-a228-5218-afdb-42f5e7e3abcf', 9, 18, 'ፈርዖንም አብራምን ጠርቶ አለው፥ “ይህ ያደረግህብኝ ምንድን ነው? እርስዋ ሚስትህ እንደ ሆነች ለምን አልገለጥህልኝም?'),
  ('497d4910-ed89-55d0-add3-b6e751d2a5eb', 'bb4049b6-05c3-5c7f-a2ca-af38dad22941', 'de5a2431-a228-5218-afdb-42f5e7e3abcf', 10, 19, 'ለምንስ ‘እኅቴ ናት’ አልህ? ለእኔ ሚስት ትሆነኝ ዘንድ ወስጃት ነበር። አሁንም እነኋት፥ ሚስትህ በፊትህ ናት፤ ይዘሃትም ሂድ።”'),
  ('c4612029-09ea-5a2e-af80-e262004ee3d9', 'bb4049b6-05c3-5c7f-a2ca-af38dad22941', 'de5a2431-a228-5218-afdb-42f5e7e3abcf', 11, 20, 'ፈርዖንም ሰዎቹን ስለ አብራም አዘዘ፤ እርሱንም፥ ሚስቱንም፥ የነበረውንም ሁሉ ሸኙአቸው።'),
  ('b23faf93-4efa-54c4-a14f-f07de1a4206f', '71e89936-80ef-5f05-af44-c373713fca90', '6f4a095a-a1f5-5e42-a9b7-a6c290ae3f8f', 1, 1, 'አብራምም ከግብፅ ወጣ፤ እርሱና ሚስቱ፥ ለእርሱ የነበረውም ሁሉ፥ ሎጥም ከእርሱ ጋር ወደ አዜብ ወጡ።'),
  ('c84c8815-77de-59e4-acb5-456f9e6c07bd', '71e89936-80ef-5f05-af44-c373713fca90', '6f4a095a-a1f5-5e42-a9b7-a6c290ae3f8f', 2, 2, 'አብራምም በከብት፥ በብርና በወርቅ እጅግ በለጸገ።'),
  ('3e215440-67ed-527f-ae05-344a986f27b6', '71e89936-80ef-5f05-af44-c373713fca90', '6f4a095a-a1f5-5e42-a9b7-a6c290ae3f8f', 3, 3, 'ከአዜብ ባደረገው በጕዞውም ወደ ቤቴል ሄደ፤ ያም ስፍራ አስቀድሞ በቤቴልና በጋይ መካከል ድንኳን ተክሎበት የነበረው ነው፤'),
  ('b0ffcc31-98f4-5b8c-a530-cdd640712a4c', '71e89936-80ef-5f05-af44-c373713fca90', '6f4a095a-a1f5-5e42-a9b7-a6c290ae3f8f', 4, 4, 'ስፍራውም አስቀድሞ መሠውያ የሠራበት ነው፤ በዚያም አብራም የእግዚአብሔርን ስም ጠራ።'),
  ('c78ceec3-9c32-5be7-ac3f-6ecbf2321378', '71e89936-80ef-5f05-af44-c373713fca90', '6f4a095a-a1f5-5e42-a9b7-a6c290ae3f8f', 5, 5, 'ከአብራም ጋር የሄደው ሎጥ ደግሞ የላምና የበግ መንጋ ድንኳኖችም ነበሩት።'),
  ('a9f0f1b5-1233-51e4-a6ed-d73944fd4f7f', '71e89936-80ef-5f05-af44-c373713fca90', '6f4a095a-a1f5-5e42-a9b7-a6c290ae3f8f', 6, 6, 'በአንድነትም ይቀመጡ ዘንድ ምድር አልበቃቸውም፤ ንብረታቸው ብዙ ነበርና፤ ስለዚህም ባንድነት ይቀመጡ ዘንድ ምድር አልበቃቻቸውም።'),
  ('0ac36a0c-cdb0-5a2f-ac38-588ac8a7b2c7', '71e89936-80ef-5f05-af44-c373713fca90', '6f4a095a-a1f5-5e42-a9b7-a6c290ae3f8f', 7, 7, 'በአብራምና በሎጥ መንጎች ጠባቆች መካከልም ጠብ ሆነ፤ በዚያ ዘመን ከነዓናውያንና ፌርዛውያን በዚያች ምድር ተቀምጠው ነበር።'),
  ('a83cbd5b-16de-588e-a426-233ecbd7800c', '71e89936-80ef-5f05-af44-c373713fca90', '6f4a095a-a1f5-5e42-a9b7-a6c290ae3f8f', 8, 8, 'አብራምም ሎጥን አለው፥ “እኛ ወንድማማች ነንና በእኔና በአንተ፥ በእረኞቼና በእረኞችህ መካከል ጠብ አይሁን።'),
  ('c15f6b3f-1069-5ef6-ace9-0b0f29380698', '71e89936-80ef-5f05-af44-c373713fca90', '6f4a095a-a1f5-5e42-a9b7-a6c290ae3f8f', 9, 9, 'እነሆ፥ ምድር ሁሉ በፊትህ አይደለችምን? ከእኔ ትለይ ዘንድ እለምንሃለሁ፤ አንተ ወደ ግራው ብትሄድ እኔ ወደ ቀኝ እሄዳለሁ፤ አንተም ወደ ቀኙ ብትሄድ እኔ ወደ ግራ እሄዳለሁ።”'),
  ('44dfa901-dd7b-5469-a84a-9a7d226bef20', '71e89936-80ef-5f05-af44-c373713fca90', '6f4a095a-a1f5-5e42-a9b7-a6c290ae3f8f', 10, 10, 'ሎጥም ዓይኖቹን አነሣ፤ በዮርዳኖስ ዙሪያ ያለውንም ሀገር ሁሉ ውኃ የሞላበት መሆኑን አየ፤ እግዚአብሔር ሰዶምንና ገሞራን ከማጥፋቱ አስቀድሞ እስከ ሴጎር ድረስ እንደ እግዚአብሔር ገነትና እንደ ግብፅ ምድር እንደ ነበረ አየ።'),
  ('03863f9c-0094-5c13-ae2c-46f416b90acf', '71e89936-80ef-5f05-af44-c373713fca90', '6f4a095a-a1f5-5e42-a9b7-a6c290ae3f8f', 11, 11, 'ሎጥም ለራሱ በዮርዳኖስ ዙሪያ ያለውን ሀገር ሁሉ መረጠ፤ ሎጥም ወደ ምሥራቅ ተጓዘ፤ አንዱም ከሌላው እርስ በርሳቸው ተለያዩ።'),
  ('c092b813-8b4c-5401-a76a-c67fbce2f70f', '71e89936-80ef-5f05-af44-c373713fca90', '6f4a095a-a1f5-5e42-a9b7-a6c290ae3f8f', 12, 12, 'አብራም በከነዓን ምድር ተቀመጠ፤ ሎጥም በጎረቤት ሕዝቦች ከተማ ተቀመጠ፤ ድንኳኑንም በሰዶም ተከለ፤'),
  ('764d8b61-c69a-555f-a195-047374833fd6', '71e89936-80ef-5f05-af44-c373713fca90', '6f4a095a-a1f5-5e42-a9b7-a6c290ae3f8f', 13, 13, 'የሰዶም ሰዎች ግን ክፉዎችና በእግዚአብሔር ፊት እጅግ ኀጢአተኞች ነበሩ።'),
  ('e2ae5c8d-4557-58ab-a855-5001efbf6434', '71e89936-80ef-5f05-af44-c373713fca90', 'f2f59160-da93-58ed-a26a-83e17a296aee', 1, 14, 'ሎጥ ከተለየው በኋላም እግዚአብሔር አብራምን አለው፥ “ዐይንህን አንሣና አንተ ካለህበት ስፍራ ወደ መስዕና ወደ አዜብ፥ ወደ ምሥራቅና ወደ ምዕራብ እይ፤'),
  ('833b28aa-a2fd-51f6-a8c9-45b4f80a3c73', '71e89936-80ef-5f05-af44-c373713fca90', 'f2f59160-da93-58ed-a26a-83e17a296aee', 2, 15, 'የምታያትን ምድር ሁሉ ለአንተና ለዘርህ ለዘለዓለም እሰጣለሁና።'),
  ('edd4009a-7b4a-57fe-a484-f388e55211a9', '71e89936-80ef-5f05-af44-c373713fca90', 'f2f59160-da93-58ed-a26a-83e17a296aee', 3, 16, 'ዘርህንም እንደ ባሕር አሸዋ አደርጋለሁ፤ የባሕር አሸዋን ይቈጥር ዘንድ የሚችል ሰው ቢኖር ዘርህ ደግሞ ይቈጠራል።'),
  ('8898031d-a539-5468-a6bc-073073c99ca9', '71e89936-80ef-5f05-af44-c373713fca90', 'f2f59160-da93-58ed-a26a-83e17a296aee', 4, 17, 'ተነሣ፤ በምድር በርዝመቷም፥ በስፋቷም ዙር፤ እርስዋን ለአንተና ለዘርህ ለዘለዓለም እሰጣለሁና።”'),
  ('2633af7b-0992-5455-a47c-b705d42fe5ab', '71e89936-80ef-5f05-af44-c373713fca90', 'f2f59160-da93-58ed-a26a-83e17a296aee', 5, 18, 'አብራምም ድንኳኑን ነቀለ፤ መጥቶም በኬብሮን ባለው የመምሬ ዛፍ ተቀመጠ፤ በዚያም ለእግዚአብሔር መሠውያን ሠራ።'),
  ('8760376f-d53e-5f54-adda-6385690d0435', '97b3adbb-3a22-594c-a444-8aa220e4f38b', '72fd31b8-32d5-504f-ac20-6cd208053b38', 1, 1, 'በሰናዖር ንጉሥ በአሚሮፌል፥ በእላሳር ንጉሥ በአርዮክ፥ በኤላም ንጉሥ በኮሎዶጎሞር፥ በአሕዛብ ንጉሥ በቴሮጋል ዘመን እንዲህ ሆነ፤'),
  ('4e5544c5-ce29-5009-ad09-ab66e8edb418', '97b3adbb-3a22-594c-a444-8aa220e4f38b', '72fd31b8-32d5-504f-ac20-6cd208053b38', 2, 2, 'ከሰዶም ንጉሥ ከባላ፥ ከገሞራ ንጉሥ ከበርሳ፥ ከአዳማ ንጉሥ ከሰናአር፥ ከሲባዮ ንጉሥ ከሲምቦር፤ ሴጎር ከተባለች ከባላ ንጉሥም ጋር ጦርነት አደረጉ።'),
  ('6bf3ca0a-1ff2-5e22-a9de-0f030a1170f2', '97b3adbb-3a22-594c-a444-8aa220e4f38b', '72fd31b8-32d5-504f-ac20-6cd208053b38', 3, 3, 'እነዚህ ሁሉ በኤሌቄን ሸለቆ ተሰብስበው ተባበሩ፤ ይኸውም የጨው ባሕር ነው።'),
  ('5c41b9dd-8ebb-5bc5-ac36-5ef447b415b1', '97b3adbb-3a22-594c-a444-8aa220e4f38b', '72fd31b8-32d5-504f-ac20-6cd208053b38', 4, 4, 'ዐሥራ ሁለት ዓመት ለኮሎዶጎሞር ተገዙ፤ በዐሥራ ሦስተኛውም ዓመት ዐመፁ።'),
  ('86ef633f-7788-5400-a233-ebfe225a7b72', '97b3adbb-3a22-594c-a444-8aa220e4f38b', '72fd31b8-32d5-504f-ac20-6cd208053b38', 5, 5, 'በዐሥራ አራተኛውም ዓመት ኮሎዶጎሞርና ከእርሱ ጋር የነበሩት ነገሥታት መጡ፤ ረዐይትን በአስጣሮት ቃርናይም፥ ከእነርሱም ጋር ጽኑዓን ሰዎችንና ኦሚዎስን በሴዊ ከተማ ገደሉአቸው፤'),
  ('f34d7d2f-3a28-5922-adfb-6057703479bb', '97b3adbb-3a22-594c-a444-8aa220e4f38b', '72fd31b8-32d5-504f-ac20-6cd208053b38', 6, 6, 'በሴይር ተራራዎች ያሉ የኬሬዎስ ሰዎችንም በበረሃ አጠገብ እስከ አለችው እስከ ፋራን ዛፍ ድረስ መቱአቸው።'),
  ('3a7193da-89b8-5ee3-a2df-c731876ed36f', '97b3adbb-3a22-594c-a444-8aa220e4f38b', '72fd31b8-32d5-504f-ac20-6cd208053b38', 7, 7, 'ተመልሰውም ቃዴስ ወደ ተባለች ወደ ፍርድ ምንጭ መጡ፤ የአማሌቅን አለቆች ሁሉና በአሳሶን ታማር የሚኖሩ አሞራውያንንም ገደሉአቸው።'),
  ('f5a7cd20-5721-57a5-ab98-c775a2b7137c', '97b3adbb-3a22-594c-a444-8aa220e4f38b', '72fd31b8-32d5-504f-ac20-6cd208053b38', 8, 8, 'የሰዶም ንጉሥና የገሞራ ንጉሥ፥ የአዳማ ንጉሥና የሲባዮን ንጉሥ፥ ሴጎር የተባለች የባላቅ ንጉሥም ወጡ፤ እነዚህ ሁሉ በጨው ሸለቆ በእነርሱ ላይ ለሰልፍ ወጡ፤'),
  ('1b911467-7042-5a5f-a35a-c356d8ee72e7', '97b3adbb-3a22-594c-a444-8aa220e4f38b', '72fd31b8-32d5-504f-ac20-6cd208053b38', 9, 9, 'ከኤላም ንጉሥ ከኮሎዶጎሞር፥ ከአሕዛብ ንጉሥ ከቴሮጋል፥ ከሰናዖር ንጉሥ ከአሜሮፌል፥ ከእላሳር ንጉሥ ከአርዮክ ጋር ተጋጠሙ። እነዚህ አራቱ ነገሥታት ከአምስቱ ነገሥታት ጋር ተዋጉ።'),
  ('aaabfc13-d67e-52cc-a9ed-44b97307f036', '97b3adbb-3a22-594c-a444-8aa220e4f38b', '72fd31b8-32d5-504f-ac20-6cd208053b38', 10, 10, 'ያም የጨው ሸለቆ የዝፍት ጕድጓዶች ነበሩበት። የሰዶም ንጉሥና የገሞራ ንጉሥም ሸሹና በዚያ ወደቁ፤ የቀሩትም ወደ ተራራማው ሀገር ሸሹ።'),
  ('a433c3b7-5110-51a4-a5a4-8c3f2a0c560b', '97b3adbb-3a22-594c-a444-8aa220e4f38b', '72fd31b8-32d5-504f-ac20-6cd208053b38', 11, 11, 'የሰዶምንና የገሞራን ፈረሶች ሁሉ፥ ስንቃቸውንም ሁሉ ይዘው ሄዱ።'),
  ('1e99e7b4-9e81-5b86-afbc-4d1ace55f126', '97b3adbb-3a22-594c-a444-8aa220e4f38b', '72fd31b8-32d5-504f-ac20-6cd208053b38', 12, 12, 'እነርሱም የአብራምን የወንድም ልጅ ሎጥንና ገንዘቡን ይዘው ሄዱ። እርሱ በሰዶም ይኖር ነበርና።'),
  ('dc762f4d-63c1-52b7-a913-f5c2793ce93c', '97b3adbb-3a22-594c-a444-8aa220e4f38b', '72fd31b8-32d5-504f-ac20-6cd208053b38', 13, 13, 'ከአመለጡትም አንድ ሰው መጣ፤ ለዕብራዊው ለአብራምም ነገረው፤ እርሱም የኤስኮል ወንድምና የአውናን ወንድም በሆነ በአሞራዊው የመምሬ ዛፍ ይኖር ነበር፤ እነዚያም ከአብራም ጋር ቃል ኪዳን ገብተው ነበር።'),
  ('e5a91f20-f3fd-5c36-a95f-b28f4438741e', '97b3adbb-3a22-594c-a444-8aa220e4f38b', '72fd31b8-32d5-504f-ac20-6cd208053b38', 14, 14, 'አብራምም የወንድሙ ልጅ ሎጥ እንደ ተማረከ በሰማ ጊዜ ወገኖቹንና ቤተሰቦቹን ሁሉ ቈጠራቸው፤ እነርሱም ሦስት መቶ ዐሥራ ስምንት ሆኑ፤ እስከ ዳን ድረስ ተከትሎ አሳደዳቸው።'),
  ('e41f3744-69ee-5a8d-a398-2952cd09ad15', '97b3adbb-3a22-594c-a444-8aa220e4f38b', '72fd31b8-32d5-504f-ac20-6cd208053b38', 15, 15, 'እርሱም ከብላቴኖቹ ጋር በሌሊት ደረሰባቸው፤ መታቸውም፤ በደማስቆ ግራ እስካለችውም እስከ ሖባ ድረስ አሳደዳቸው።'),
  ('a4b81a3f-2a5d-52b9-af15-83dd0ba9d632', '97b3adbb-3a22-594c-a444-8aa220e4f38b', '72fd31b8-32d5-504f-ac20-6cd208053b38', 16, 16, 'የሰዶምን ፈረሶች ሁሉ አስመለሰ፤ ደግሞም የወንድሙን ልጅ ሎጥንና ንብረቱን፥ ሴቶችንና ሕዝቡንም አስመለሰ።'),
  ('efa20249-8402-5efc-a121-9ce5b4799f59', '97b3adbb-3a22-594c-a444-8aa220e4f38b', '39522bfb-6b93-589c-a844-6cae71429823', 1, 17, 'ኮሎዶጎሞርንና ከእርሱ ጋር የነበሩትን ነገሥታት ወግቶ ከተመለሰም በኋላ የሰዶም ንጉሥ የንጉሥ ሜዳ በሆነ በሴዊ ሸለቆ ሊቀበለው ወጣ።'),
  ('52cdec65-2bb1-5f26-aca1-231bcd46c21f', '97b3adbb-3a22-594c-a444-8aa220e4f38b', '39522bfb-6b93-589c-a844-6cae71429823', 2, 18, 'የሳሌም ንጉሥ መልከ ጼዴቅም እንጀራንና የወይን ጠጅን አወጣ፤ እርሱም የልዑል እግዚአብሔር ካህን ነበረ።'),
  ('7664d9e4-2170-5da1-a8ff-4b1980b450bf', '97b3adbb-3a22-594c-a444-8aa220e4f38b', '39522bfb-6b93-589c-a844-6cae71429823', 3, 19, 'አብራምንም ባረከው፤ “አብራም ሰማይንና ምድርን ለፈጠረ ለልዑል እግዚአብሔር የተባረከ ነው፤'),
  ('c91a0b9a-17f6-5aaa-a63e-413173f9b59b', '97b3adbb-3a22-594c-a444-8aa220e4f38b', '39522bfb-6b93-589c-a844-6cae71429823', 4, 20, 'ጠላቶችህን በእጅህ የጣለልህ ልዑል እግዚአብሔርም ቡሩክ ነው” አለው። አብራምም ከሁሉ ዐሥራትን ሰጠው።'),
  ('f95d3982-954c-5675-a37e-46d1fc874428', '97b3adbb-3a22-594c-a444-8aa220e4f38b', '39522bfb-6b93-589c-a844-6cae71429823', 5, 21, 'የሰዶም ንጉሥም አብራምን፥ “ሰዎቹን ስጠኝ፤ ፈረሶቹን ግን ለአንተ ውሰድ” አለው።'),
  ('cb9c9a67-0450-5813-a23a-edb019ead8fc', '97b3adbb-3a22-594c-a444-8aa220e4f38b', '39522bfb-6b93-589c-a844-6cae71429823', 6, 22, 'አብራምም የሰዶምን ንጉሥ አለው፥ “ሰማይንና ምድርን ወደ ፈጠረ ወደ ልዑል እግዚአብሔር እጄን ከፍ አደርጋለሁ፤'),
  ('3bfee484-38fc-5872-a65a-396c4a8a3575', '97b3adbb-3a22-594c-a444-8aa220e4f38b', '39522bfb-6b93-589c-a844-6cae71429823', 7, 23, 'አንተ፦ አብራምን ባለጠጋ አደረግሁት እንዳትል፥ ከአንተ ገንዘብ ሁሉ ፈትልም ቢሆን፥ የጫማ ማዘቢያም ቢሆን እንዳልወስድ፥'),
  ('43db0441-c6c8-57dd-a1cf-da6ccb0b852d', '97b3adbb-3a22-594c-a444-8aa220e4f38b', '39522bfb-6b93-589c-a844-6cae71429823', 8, 24, 'ብላቴኖች ከበሉት እህልና ከእኔ ጋር ከመጡት ድርሻ በቀር፥ አውናን፥ ኤስኮልም፥ መምሬም እነርሱ ድርሻቸውን ይውሰዱ።”'),
  ('da9fa3ba-6639-5a89-a2a3-d020320d8a34', '0940489c-46af-5d94-af62-f40c50eeb9f8', 'a04ce7b5-8ec6-539b-a4e8-9e668ac249f1', 1, 1, 'ከዚህም ነገር በኋላ የእግዚአብሔር ቃል በራእይ ወደ አብራም መጣ፤ እንዲህ ሲል፥ “አብራም ሆይ፥ አትፍራ፤ እኔ ጋሻ እሆንሃለሁ፤ ዋጋህም በእኔ ዘንድ እጅግ ብዙ ነው።”'),
  ('39d8e937-0e71-5559-a7cf-563e6368f176', '0940489c-46af-5d94-af62-f40c50eeb9f8', 'a04ce7b5-8ec6-539b-a4e8-9e668ac249f1', 2, 2, 'አብራምም፥ “አቤቱ እግዚአብሔር ሆይ፥ ምን ትሰጠኛለህ? እነሆ፥ ልጅ ሳልወልድ እሞታለሁ፤ የቤቴም ወራሽ ከዘመዴ ወገን የሚሆን የደማስቆ ሰው የማሴቅ ልጅ ይህ ኢያውብር ነው” አለ።'),
  ('d735dbb0-4fa4-5b4c-ad35-015b9f2986a8', '0940489c-46af-5d94-af62-f40c50eeb9f8', 'a04ce7b5-8ec6-539b-a4e8-9e668ac249f1', 3, 3, 'አብራምም፥ “ለእኔ ዘር አልሰጠኸኝም፤ የዘመዴ ልጅ እርሱ ይወርሰኛል” አለ።'),
  ('bdb3889c-a669-51fe-ad0d-f5ae76432909', '0940489c-46af-5d94-af62-f40c50eeb9f8', 'a04ce7b5-8ec6-539b-a4e8-9e668ac249f1', 4, 4, 'ያን ጊዜም የአግዚአብሔር ቃል ወደ አብራም እንዲህ ሲል መጣ፤ “እርሱ አይወርስህም፤ ነገር ግን ከአብራክህ የሚወጣው እርሱ ይወርስሃል።”'),
  ('3f9ee2f4-a206-50e9-ae01-cd767b6c751c', '0940489c-46af-5d94-af62-f40c50eeb9f8', 'a04ce7b5-8ec6-539b-a4e8-9e668ac249f1', 5, 5, 'ወደ ሜዳም አወጣውና “ወደ ላይ ወደ ሰማይ ተመልከት፤ ልትቈጥራቸው ትችል እንደሆነ ከዋክብትን ቍጠራቸው። ዘርህም እንደዚሁ ነው” አለው።'),
  ('8e4c9d61-7fed-5da9-a018-cfd2518e50eb', '0940489c-46af-5d94-af62-f40c50eeb9f8', 'a04ce7b5-8ec6-539b-a4e8-9e668ac249f1', 6, 6, 'አብራምም በእግዚአብሔር አመነ፤ ጽድቅም ሆኖ ተቈጠረለት።'),
  ('2c537e73-81e8-551b-aa3c-d1998a04bf52', '0940489c-46af-5d94-af62-f40c50eeb9f8', 'a04ce7b5-8ec6-539b-a4e8-9e668ac249f1', 7, 7, '“ይህችን ምድር ትወርሳት ዘንድ እንድሰጥህ ከከለዳውያን ምድር ያወጣሁህ አምላክህ እግዚአብሔር እኔ ነኝ” አለው።'),
  ('85f7f993-bf2a-5531-a060-4cbac2bb6df1', '0940489c-46af-5d94-af62-f40c50eeb9f8', 'a04ce7b5-8ec6-539b-a4e8-9e668ac249f1', 8, 8, '“አቤቱ እግዚአብሔር ሆይ፥ እንደምወርሳት በምን አውቃለሁ?” አለው።'),
  ('98b2cc64-02c4-5137-ab2a-e43cfe8dcc60', '0940489c-46af-5d94-af62-f40c50eeb9f8', 'a04ce7b5-8ec6-539b-a4e8-9e668ac249f1', 9, 9, 'እርሱም አለው፥ “የሦስት ዓመት ላም፥ የሦስት ዓመት ፍየልም፥ የሦስት ዓመት በግም፥ ዋኖስም፥ ርግብም አምጣ፤ እኒህንም ሁሉ አምጥተህ ከሁለት ከሁለት ቍረጣቸው፤ ወፎችን ግን አትቍረጣቸው።”'),
  ('a0f4c096-2fb1-5092-a53b-a120795c17d2', '0940489c-46af-5d94-af62-f40c50eeb9f8', 'a04ce7b5-8ec6-539b-a4e8-9e668ac249f1', 10, 10, 'እንዲሁም እነዚህን ሁሉ ወሰደለት፤ በየሁለትም ከፈላቸው፤ የተከፈሉትንም በየወገኑ ትይዩ አደረጋቸው፤ ወፎችን ግን አልቈረጣቸውም።'),
  ('50fcce17-001a-5866-a791-f741044c0452', '0940489c-46af-5d94-af62-f40c50eeb9f8', 'a04ce7b5-8ec6-539b-a4e8-9e668ac249f1', 11, 11, 'አሞራዎችም በተቈረጠው ሥጋቸው ላይ ወረዱ፤ አብራምም በእነርሱ ዘንድ ተቀምጦ አባረራቸው።'),
  ('316f4e08-d28d-5e76-a7fb-e70f7947d6f7', '0940489c-46af-5d94-af62-f40c50eeb9f8', 'a04ce7b5-8ec6-539b-a4e8-9e668ac249f1', 12, 12, 'ፀሐይም በገባ ጊዜ በአብራም ድንጋጤ መጣበት፤ እነሆም፥ የሚያስፈራ ጽኑዕ ጨለማ መጣበት፤'),
  ('2ad7c64c-b49b-5013-aeb4-bff3990456e7', '0940489c-46af-5d94-af62-f40c50eeb9f8', 'a04ce7b5-8ec6-539b-a4e8-9e668ac249f1', 13, 13, 'እግዚአብሔርም አብራምን አለው፥ “ዘርህ ለእነርሱ ባልሆነች ምድር ስደተኞች እንዲሆኑ በእርግጥ ዕወቅ፤ አራት መቶ ዓመታትም ባሪያዎች አድርገው ይገዙአቸዋል፤ ያሠቃዩአቸዋል፤ ያስጨንቋቸዋልም።'),
  ('166edf89-c95a-55fb-a7d6-9a095865dda1', '0940489c-46af-5d94-af62-f40c50eeb9f8', 'a04ce7b5-8ec6-539b-a4e8-9e668ac249f1', 14, 14, 'ደግሞም የሚያሠቃዩአቸውን እኔ እፈርድባቸዋለሁ። ከዚህም በኋላ ከብዙ ገንዘብ ጋር ወደዚህ ይወጣሉ።'),
  ('cc7edc67-82fe-55bd-a07b-d42fc1c08aa0', '0940489c-46af-5d94-af62-f40c50eeb9f8', 'a04ce7b5-8ec6-539b-a4e8-9e668ac249f1', 15, 15, 'አንተ ግን ወደ አባቶችህ በሰላም ትሄዳለህ፤ በመልካም ሽምግልናም ትቀበራለህ።'),
  ('9280ea37-c148-5637-a901-996dc4180fdc', '0940489c-46af-5d94-af62-f40c50eeb9f8', 'a04ce7b5-8ec6-539b-a4e8-9e668ac249f1', 16, 16, 'በአራተኛው ትውልድ ግን ወደዚህ ይመለሳሉ፤ እስከ ዛሬ ድረስ የአሞራውያን ኀጢአት አልተፈጸመምና።”'),
  ('1ee31804-5a16-5563-ac86-474a962efa53', '0940489c-46af-5d94-af62-f40c50eeb9f8', 'a04ce7b5-8ec6-539b-a4e8-9e668ac249f1', 17, 17, 'እንዲህም ሆነ፤ ፀሐይም በገባ ጊዜ ነበልባል መጣ፤ የእሳት መብራትና የሚጤስ ምድጃም መጣ፤ በዚያም በተከፈለው መካከል አለፈ።'),
  ('a771f1f3-b9c8-5cbe-a09c-0dfca0479ac0', '0940489c-46af-5d94-af62-f40c50eeb9f8', 'a04ce7b5-8ec6-539b-a4e8-9e668ac249f1', 18, 18, 'በዚያችም ቀን እግዚአብሔር ለአብራም ተስፋ ያደረገለትን ቃል ኪዳን አጸና፤ እንዲህም አለው፥ “ከግብፅ ወንዝ ጀምሮ እስከ ትልቁ ወንዝ እስከ ኤፍራጥስ ወንዝ ድረስ ይህችን ምድር ለዘርህ እሰጣታለሁ፤'),
  ('1cbe9fd7-bc60-5dfd-a1aa-fd717813b883', '0940489c-46af-5d94-af62-f40c50eeb9f8', 'a04ce7b5-8ec6-539b-a4e8-9e668ac249f1', 19, 19, 'ቀኔዎሳውያንን፥ ቄኔዜዎሳውያንን፥ ቄኔሚሎሳውያንን፥'),
  ('d82c55a7-605a-5831-a833-95d641a02b2e', '0940489c-46af-5d94-af62-f40c50eeb9f8', 'a04ce7b5-8ec6-539b-a4e8-9e668ac249f1', 20, 20, 'ኬጤዎናውያንንም፥ ፌርዜዎናውያንንም፥ ፈራዮናውያንንም፤'),
  ('b0e4f47a-556e-52df-a370-7cb87eeec7bb', '0940489c-46af-5d94-af62-f40c50eeb9f8', 'a04ce7b5-8ec6-539b-a4e8-9e668ac249f1', 21, 21, 'አሞሬዎናውያንንም፥ ከናኔዎናውያንንም፥ ጌርጌሴዎናውያንንም፥ ኢያቡሴዎናውያንንም።”'),
  ('a42aa7c4-c2f1-539c-a263-3aba29e3994b', 'a4c1ceec-3d89-5970-aca0-561ea0ad23ed', 'e37d3ae9-826b-54e5-a909-3c513f74b8ab', 1, 1, 'የአብራም ሚስት ሦራ ግን ልጅ አልወለደችለትም ነበር፤ ስምዋ አጋር የተባለ ግብፃዊት አገልጋይም ነበረቻት።'),
  ('6b187c48-839a-50a6-ab5c-d8c2b3800d64', 'a4c1ceec-3d89-5970-aca0-561ea0ad23ed', 'e37d3ae9-826b-54e5-a909-3c513f74b8ab', 2, 2, 'ሦራም አብራምን፥ “እነሆ፥ እንዳልወልድ እግዚአብሔር ዘጋኝ፤ ከእርስዋ ትወልድ ዘንድ ወደ አገልጋዬ ሂድ” አለችው። አብራምም የሚስቱን የሦራን ቃል ሰማ።'),
  ('67286c74-4eac-5e81-af09-37eb560bed8a', 'a4c1ceec-3d89-5970-aca0-561ea0ad23ed', 'e37d3ae9-826b-54e5-a909-3c513f74b8ab', 3, 3, 'አብራምም በከነዓን ምድር ዐሥር ዓመት ከተቀመጠ በኋላ፥ የአብራም ሚስት ሦራ ግብፃዊት አገልጋይዋን አጋርን ወስዳ ለአብራም ሚስት ትሆነው ዘንድ ሰጠችው።'),
  ('3a3f8e85-97e5-521a-aaed-66be0b4044b5', 'a4c1ceec-3d89-5970-aca0-561ea0ad23ed', 'e37d3ae9-826b-54e5-a909-3c513f74b8ab', 4, 4, 'አብራምም ወደ አጋር ገባ፤ ፀነሰችም፤ እንደ ፀነሰችም ባየች ጊዜ እመቤቷን ማክበርዋን ተወች።'),
  ('02409b85-101f-5996-ad80-2c2f7e0b8887', 'a4c1ceec-3d89-5970-aca0-561ea0ad23ed', 'e37d3ae9-826b-54e5-a909-3c513f74b8ab', 5, 5, 'ሦራም አብራምን፥ “ከአንተ የተነሣ እገፋለሁ፤ እኔ አገልጋዬን በብብትህ ሰጠሁህ፤ እንደ ፀነሰችም ባየች ጊዜ እኔን ማክበርን ተወች፤ እግዚአብሔር በእኔና በአንተ መካከል ይፍረድ” አለችው።'),
  ('ac737ece-b987-5446-a18e-f64e2dda9e54', 'a4c1ceec-3d89-5970-aca0-561ea0ad23ed', 'e37d3ae9-826b-54e5-a909-3c513f74b8ab', 6, 6, 'አብራምም ሚስቱን ሦራን፥ “እነሆ፥ አገልጋይሽ በእጅሽ ናት፤ እንደ ወደድሽ አድርጊባት” አላት። ሦራም አጋርን አሠቃየቻት፤ ከእርስዋም ኰበለለች።'),
  ('0d69f844-cd6f-5554-ade9-207e0e08ad1b', 'a4c1ceec-3d89-5970-aca0-561ea0ad23ed', 'e37d3ae9-826b-54e5-a909-3c513f74b8ab', 7, 7, 'የእግዚአብሔር መልአክም በውኃ ምንጭ አጠገብ በሱር በረሃ በመንገድ አገኛት።'),
  ('92dcd85c-e608-558a-a3af-d5e3ca8141a7', 'a4c1ceec-3d89-5970-aca0-561ea0ad23ed', 'e37d3ae9-826b-54e5-a909-3c513f74b8ab', 8, 8, 'የእግዚአብሔርም መልአክ፥ “የሦራ አገልጋይ አጋር ሆይ፥ ከወዴት መጣሽ? ወዴትስ ትሄጂያለሽ?” አላት። እርስዋም፥ “እኔ ከእመቤቴ ከሦራ ፊት እኰበልላለሁ” አለች።'),
  ('bf7f9e27-e162-5745-a84b-806729e5a434', 'a4c1ceec-3d89-5970-aca0-561ea0ad23ed', 'e37d3ae9-826b-54e5-a909-3c513f74b8ab', 9, 9, 'የእግዚአብሔር መልአክም፥ “ወደ እመቤትሽ ተመለሺ፤ ከእጅዋም በታች ራስሽን ዝቅ አድርጊ” አላት።'),
  ('b3f77e6b-c40c-5ce1-a225-5b1ee1cdb97c', 'a4c1ceec-3d89-5970-aca0-561ea0ad23ed', 'e37d3ae9-826b-54e5-a909-3c513f74b8ab', 10, 10, 'እግዚአብሔርም “ከብዛቱ የተነሣ እስከማይቈጠር ድረስ ዘርሽን እጅግ አበዛለሁ፥” አላት።'),
  ('24538801-615b-5032-af30-4297ae03e676', 'a4c1ceec-3d89-5970-aca0-561ea0ad23ed', 'e37d3ae9-826b-54e5-a909-3c513f74b8ab', 11, 11, 'የእግዚአብሔር መልአክም አላት፥ “እነሆ፥ አንቺ ፀንሰሻል፤ ወንድ ልጅንም ትወልጃለሽ፤ ስሙንም ይስማኤል ብለሽ ትጠሪዋለሽ፤ እግዚአብሔር ሥቃይሽን ሰምቶአልና።'),
  ('42060073-09e1-5966-ae2b-f42761bed302', 'a4c1ceec-3d89-5970-aca0-561ea0ad23ed', 'e37d3ae9-826b-54e5-a909-3c513f74b8ab', 12, 12, 'እርሱም የበረሃ ሰው ይሆናል፤ እጁ በሁሉ ላይ ይሆናል፤ የሁሉም እጅ ደግሞ በእርሱ ላይ ይሆናል፤ እርሱም በወንድሞቹ ሁሉ ፊት ይኖራል።”'),
  ('8dfd1417-ea51-513e-a11a-46c3510f6abf', 'a4c1ceec-3d89-5970-aca0-561ea0ad23ed', 'e37d3ae9-826b-54e5-a909-3c513f74b8ab', 13, 13, 'አጋርም ይናገራት የነበረውን የእግዚአብሔርን ስም ጠራች፤ “አቤቱ የራራህልኝ አንተ ነህ፤ የተገለጠልኝን በፊቴ አይችዋለሁና።”'),
  ('8fa1ed93-9969-5736-afb4-2fb0b549c038', 'a4c1ceec-3d89-5970-aca0-561ea0ad23ed', 'e37d3ae9-826b-54e5-a909-3c513f74b8ab', 14, 14, 'ስለዚህም የዚያን ጕድጓድ ስም “በፊቴ የተገለጠልኝ የእርሱ ጕድጓድ” ብላ ጠራችው፤ እርሱም በቃዴስና በባሬድ መካከል ነው። አጋርም ተመለሰች።'),
  ('1e519fdf-00fa-54ad-a996-97b2a2e94315', 'a4c1ceec-3d89-5970-aca0-561ea0ad23ed', 'e37d3ae9-826b-54e5-a909-3c513f74b8ab', 15, 15, 'ከዚህም በኋላ አጋር ለአብራም ወንድ ልጅን ወለደችለት፤ አብራምም አጋር የወለደችለትን የሕፃኑን ስም ይስማኤል ብሎ ጠራው።'),
  ('4bcc275c-da83-59ed-a528-829819c9fda0', 'a4c1ceec-3d89-5970-aca0-561ea0ad23ed', 'e37d3ae9-826b-54e5-a909-3c513f74b8ab', 16, 16, 'አጋር ይስማኤልን በወለደችለት ጊዜ አብራም የሰማንያ አምስት ዓመት ሰው ነበረ።'),
  ('a3994aa2-6bc7-57e3-a8d9-425d344050ec', 'b1f39a7c-6c74-5df8-a775-cfe4b98df10e', '455026e4-87f2-5f6a-a502-243be6d141ce', 1, 1, 'ከዚህም በኋላ አብራም የዘጠና ዘጠኝ ዓመት ሰው በሆነ ጊዜ እግዚአብሔር ለአብራም ተገለጠለት፤ እንዲህም አለው “በፊትህ የሄድሁ ፈጣሪህ እግዚአብሔር እኔ ነኝ፤ በፊቴ መልካም አድርግ፤ ንጹሕም ሁን፤'),
  ('be5e10ed-8c43-58b9-a5a4-6c3a04368452', 'b1f39a7c-6c74-5df8-a775-cfe4b98df10e', '455026e4-87f2-5f6a-a502-243be6d141ce', 2, 2, 'ቃል ኪዳኔንም በእኔና በአንተ መካከል አጸናለሁ፤ እጅግም አበዛሃለሁ።”'),
  ('5c2df8ae-4d8f-524f-a776-85b60964ef13', 'b1f39a7c-6c74-5df8-a775-cfe4b98df10e', '455026e4-87f2-5f6a-a502-243be6d141ce', 3, 3, 'አብራምም በግንባሩ ወደቀ፤ እግዚአብሔርም አብራምን እንዲህ አለው፦'),
  ('9419cb53-7e93-5f23-adfb-380b41b995f8', 'b1f39a7c-6c74-5df8-a775-cfe4b98df10e', '455026e4-87f2-5f6a-a502-243be6d141ce', 4, 4, '“እነሆ፥ ቃል ኪዳኔን በእኔና በአንተ መካከል አጸናለሁ፤ ለብዙ አሕዛብም አባት ትሆናለህ።'),
  ('9dcc9f0b-2ced-5473-aa26-f61155d11579', 'b1f39a7c-6c74-5df8-a775-cfe4b98df10e', '455026e4-87f2-5f6a-a502-243be6d141ce', 5, 5, 'እንግዲህ ስምህ አብራም አይባልም ‘አብርሃም’ ይባላል እንጂ፤ ለብዙ አሕዛብ አባት አድርጌሃለሁና።'),
  ('d5264a13-f918-55cb-a12f-c63ee56b11e0', 'b1f39a7c-6c74-5df8-a775-cfe4b98df10e', '455026e4-87f2-5f6a-a502-243be6d141ce', 6, 6, 'እጅግም በጣም አበዛሃለሁ፤ ሕዝብም፥ ነገሥታትም ከአንተ እንዲወጡ አደርግሃለሁ።'),
  ('0b49d82e-8336-58c8-a63d-38dc7282a025', 'b1f39a7c-6c74-5df8-a775-cfe4b98df10e', '455026e4-87f2-5f6a-a502-243be6d141ce', 7, 7, 'ቃል ኪዳኔንም በእኔና በአንተ መካከል፥ ከአንተም በኋላ በዘርህ መካከል በትውልዳቸው ለዘለዓለም ኪዳን አቆማለሁ፤ ለአንተና ከአንተም በኋላ ለዘርህ አምላክ እሆን ዘንድ።'),
  ('98d3f36b-ff6a-5338-a9f6-e7334438b1fc', 'b1f39a7c-6c74-5df8-a775-cfe4b98df10e', '455026e4-87f2-5f6a-a502-243be6d141ce', 8, 8, 'በውስጥዋ የምትኖርባትን ይህችን ምድር፥ የከነዓንን ምድር ሁሉ፥ ለዘለዓለም ይገዙአት ዘንድ ለዘርህ እሰጣለሁ፤ አምላክም እሆናቸዋለሁ።”'),
  ('22dded90-f52e-5866-a70d-02464598c0fe', 'b1f39a7c-6c74-5df8-a775-cfe4b98df10e', '455026e4-87f2-5f6a-a502-243be6d141ce', 9, 9, 'እግዚአብሔርም አብርሃምን አለው፥ “አንተ ደግሞ ቃል ኪዳኔን ትጠብቃለህ፤ አንተ፥ ከአንተም በኋላ ዘርህ በትውልዳቸው።'),
  ('4d4aeff5-6372-5155-a8bb-7627d43a101f', 'b1f39a7c-6c74-5df8-a775-cfe4b98df10e', '455026e4-87f2-5f6a-a502-243be6d141ce', 10, 10, 'በእኔና በአንተ መካከል፥ ከአንተም በኋላ በዘርህ መካከል የምትጠብቋት ቃል ኪዳኔ ይህች ናት፤ ከእናንተ ወንድ ሁሉ ይገረዝ።'),
  ('bf7403cd-39c5-5ca2-a9d8-5e07c2a1a49a', 'b1f39a7c-6c74-5df8-a775-cfe4b98df10e', '455026e4-87f2-5f6a-a502-243be6d141ce', 11, 11, 'የሰውነታችሁን ቍልፈት ትገረዛላችሁ፤ በእኔና በእናንተ መካከል ላለውም ቃል ኪዳን ምልክት ይሆናል።'),
  ('dcbc9320-4a69-5f2e-aa44-8054be0b711e', 'b1f39a7c-6c74-5df8-a775-cfe4b98df10e', '455026e4-87f2-5f6a-a502-243be6d141ce', 12, 12, 'ሕፃኑንም በስምንተኛው ቀን ትገርዙታላችሁ፤ በቤት የተወለደ ወይም ከዘራችሁ ያይደለ፥ በብርም ከእንግዳ ሰው የተገዛ ወንድ ሁሉ በትውልዳችሁ ይገረዝ።'),
  ('4dbe3260-5ddd-55e4-afd4-3111e998ecdf', 'b1f39a7c-6c74-5df8-a775-cfe4b98df10e', '455026e4-87f2-5f6a-a502-243be6d141ce', 13, 13, 'በቤትህም የተወለደ፥ በብርም የተገዛ ፈጽሞ ይገረዝ። ቃል ኪዳኔም በሥጋችሁ የዘለዓለም ቃል ኪዳን ይሆናል።'),
  ('33849b61-630d-5940-a77a-929ab5dd008d', 'b1f39a7c-6c74-5df8-a775-cfe4b98df10e', '455026e4-87f2-5f6a-a502-243be6d141ce', 14, 14, 'በስምንተኛው ቀን የሥጋውን ቍልፈት ያልተገረዘ፥ ያች ነፍስ ከወገንዋ ተለይታ ትጥፋ፤ ቃል ኪዳኔን አፍርሳለችና።”'),
  ('6e697907-e64d-5ba4-a839-3f501561e53d', 'b1f39a7c-6c74-5df8-a775-cfe4b98df10e', '455026e4-87f2-5f6a-a502-243be6d141ce', 15, 15, 'እግዚአብሔርም አብርሃምን አለው፥ “ሚስትህ ሦራ እንግዲህ ሦራ ተብላ አትጠራም፤ ስምዋ ‘ሣራ’ ይሆናል እንጂ።'),
  ('4e69e56a-8d9a-5dc0-a60c-7dcd17e504cc', 'b1f39a7c-6c74-5df8-a775-cfe4b98df10e', '455026e4-87f2-5f6a-a502-243be6d141ce', 16, 16, 'እባርካታለሁና፥ ከአንተም ልጆችን እሰጣታለሁና፤ አሕዛብና የአሕዛብ ነገሥታት ከእርስዋ ይወጣሉ።”'),
  ('0d732e43-7559-54ff-abef-40f0aad246fc', 'b1f39a7c-6c74-5df8-a775-cfe4b98df10e', '455026e4-87f2-5f6a-a502-243be6d141ce', 17, 17, 'አብርሃምም በግንባሩ ወደቀ፤ ሳቀም፤ በልቡም እንዲህ ብሎ አሰበ፥ “የመቶ ዓመት ሰው ስሆን በውኑ እኔ ልጅ እወልዳለሁን? ዘጠና ዓመት የሆናትም ሣራ ትወልዳለችን?”'),
  ('81ae8595-f339-53a6-a4d0-0eeddcc0fef5', 'b1f39a7c-6c74-5df8-a775-cfe4b98df10e', '455026e4-87f2-5f6a-a502-243be6d141ce', 18, 18, 'አብርሃምም እግዚአብሔርን አለው፥ “ይህ ይስማኤል ብቻ በፊትህ ይኖርልኝ ዘንድ አቤቱ፥ እማልድሃለሁ።”'),
  ('069e331d-9cda-58cf-a9cc-1861cf7990f5', 'b1f39a7c-6c74-5df8-a775-cfe4b98df10e', '455026e4-87f2-5f6a-a502-243be6d141ce', 19, 19, 'እግዚአብሔርም አብርሃምን አለው፥ “እሺ እነሆ፥ ሚስትህ ሣራ ወንድ ልጅን ትወልድልሃለች፤ ስሙንም ይስሐቅ ብለህ ትጠራዋለህ፤ ለእርሱና ከእርሱ በኋላ ለዘሩ አምላክ እሆን ዘንድ ቃል ኪዳኔን ለዘለዓለም ቃል ኪዳን ከእርሱ ጋር አቆማለሁ።'),
  ('26434273-53fd-5997-ad2d-c87fc9b04d03', 'b1f39a7c-6c74-5df8-a775-cfe4b98df10e', '455026e4-87f2-5f6a-a502-243be6d141ce', 20, 20, 'ስለ ይስማኤልም እነሆ፥ ሰምቼሃለሁ፤ እባርከዋለሁ፤ አበዛዋለሁ፤ እጅግም አበዛዋለሁ፤ ዐሥራ ሁለት አለቆችንም ይወልዳል፤ ታላቅ ሕዝብም አደርገዋለሁ።'),
  ('9b2bc7d7-6210-5890-a889-0f28b0c4ef84', 'b1f39a7c-6c74-5df8-a775-cfe4b98df10e', '455026e4-87f2-5f6a-a502-243be6d141ce', 21, 21, 'ቃል ኪዳኔን ግን በሚመጣው ዓመት በዚሁ ጊዜ ሣራ ከምትወልድልህ ከይስሐቅ ጋር አቆማለሁ።”'),
  ('5fbcf11e-3388-5fef-ae82-1da31d0e52b7', 'b1f39a7c-6c74-5df8-a775-cfe4b98df10e', '455026e4-87f2-5f6a-a502-243be6d141ce', 22, 22, 'እግዚአብሔርም ንግግሩን ከእርሱ ጋር በፈጸመ ጊዜ ከአብርሃም ተለይቶ ወጣ።'),
  ('b39d9c6b-4bb5-5e5c-ad5d-68cd9a9c5267', 'b1f39a7c-6c74-5df8-a775-cfe4b98df10e', '455026e4-87f2-5f6a-a502-243be6d141ce', 23, 23, 'አብርሃምም ልጁን ይስማኤልን፥ በቤቱም የተወለዱትን ሁሉ፥ በወርቅም የገዛውን ወንድ ሁሉ፥ ከቤተ ሰቡም ወንዶቹን ሁሉ ወሰደ። የሥጋቸውንም ቍልፈት እግዚአብሔር እንዳለው በዚያው ቀን ገረዘ።'),
  ('e7453b8e-2e9e-5c1f-a590-c65db2d17695', 'b1f39a7c-6c74-5df8-a775-cfe4b98df10e', '455026e4-87f2-5f6a-a502-243be6d141ce', 24, 24, 'አብርሃምም የሥጋውን ቍልፈት በተገረዘ ጊዜ ዘጠና ዘጠኝ ዓመት ሆኖት ነበረ፤'),
  ('1adfd635-fde5-53db-ae06-79b2d38ba97a', 'b1f39a7c-6c74-5df8-a775-cfe4b98df10e', '455026e4-87f2-5f6a-a502-243be6d141ce', 25, 25, 'ልጁ ይስማኤልም የሥጋውን ቍልፈት በተገረዘ ጊዜ ዐሥራ ሦስት ዓመት ሆኖት ነበረ።'),
  ('1d50b3a7-3347-598b-a277-6438a947d7a4', 'b1f39a7c-6c74-5df8-a775-cfe4b98df10e', '455026e4-87f2-5f6a-a502-243be6d141ce', 26, 26, 'በዚያም ቀን አብርሃም ተገረዘ፤ ልጁ ይስማኤልም።'),
  ('90fa4ab0-3d5b-5111-a09b-65092d6fdb9f', 'b1f39a7c-6c74-5df8-a775-cfe4b98df10e', '455026e4-87f2-5f6a-a502-243be6d141ce', 27, 27, 'በቤት የተወለዱትና በብር ከእንግዶች የተገዙት፥ የቤቱ ወንዶች ሁሉ ከእርሱ ጋር ተገረዙ።'),
  ('9422d30c-6934-5dbc-ad44-87b64a3c4ef7', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '11050ebb-98a3-5c54-a40e-22815bb532b6', 1, 1, 'በቀትርም ጊዜ አብርሃም በድንኳኑ ደጃፍ ተቀምጦ ሳለ እግዚአብሔር በመምሬ ዛፍ ሥር ተገለጠለት።'),
  ('1adb5468-312e-576d-a831-29aa3b9a476c', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '11050ebb-98a3-5c54-a40e-22815bb532b6', 2, 2, 'ዐይኑንም በአነሣ ጊዜ እነሆ፥ ሦስት ሰዎች በፊቱ ቆመው አየ፤ ባያቸውም ጊዜ ሊቀበላቸው ከድንኳኑ ደጃፍ ተነሥቶ ሮጠ፤ ወደ ምድርም ሰገደ፤'),
  ('fe865a95-ee01-512e-a2c3-20ce128ba6ae', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '11050ebb-98a3-5c54-a40e-22815bb532b6', 3, 3, 'እንዲህም አለ፥ “አቤቱ በፊትህስ ባለሟልነትን አግኝቼ እንደ ሆነ ባሪያህን አትለፈው፤'),
  ('71cf1e88-159f-5b08-aa0c-67e98430a154', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '11050ebb-98a3-5c54-a40e-22815bb532b6', 4, 4, 'ውኃ እናምጣላችሁ፤ እግራችሁንም እንጠባችሁ።'),
  ('c0058c91-4a84-5866-a8b3-58880013187d', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '11050ebb-98a3-5c54-a40e-22815bb532b6', 5, 5, 'ከዛፉም ሥር ዕረፉ፤ እንጀራም እናምጣላችሁና ብሉ፤ ከዚያም በባሪያችሁ ዘንድ ከአረፋችሁ በኋላ፥ ወደ ዐሰባችሁት ትሄዳላችሁ።” እነርሱም፥ “እንዳልህ እንዲሁ አድርግ” አሉት።'),
  ('10dd8a6a-f8ed-54c8-a4cc-59ec07e20c4b', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '11050ebb-98a3-5c54-a40e-22815bb532b6', 6, 6, 'አብርሃምም ወደ ድንኳን ወደ ሚስቱ ወደ ሣራ ፈጥኖ ገባና፥ “ሦስት መስፈሪያ የተሰለቀ ዱቄት ፈጥነሽ ለውሺ፤ እንጎቻም አድርጊ” አላት።'),
  ('fbd9b224-19ba-5b47-a313-046b2438a95b', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '11050ebb-98a3-5c54-a40e-22815bb532b6', 7, 7, 'አብርሃምም ወደ ላሞቹ ሮጠ፤ እጅግ የሰባም ታናሽ ጥጃ ያዘና ለብላቴናው ሰጠው፤ ያዘጋጅም ዘንድ ተቻኮለ።'),
  ('2a9903a7-84eb-56bd-a6a7-17f4bce649cf', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '11050ebb-98a3-5c54-a40e-22815bb532b6', 8, 8, 'እርጎና መዓር፥ ያን ያዘጋጀውንም ጥጃ አመጣ፤ በፊታቸውም አቀረበው፤ እርሱም ከዛፉ በታች በፊታቸው ቆሞ ያሳልፍላቸው ነበር፤ እነርሱም በሉ።'),
  ('9bce6921-47f1-5cdb-a718-7dfd21723a5f', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '0d578278-c6dc-549f-afc8-8c4dd0339a08', 1, 9, 'እርሱም፥ “ሚስትህ ሣራ ወዴት ናት?” አለው። እርሱም፥ “በድንኳኑ ውስጥ ናት” አለው።'),
  ('ec2b89a2-94c0-55b5-a96c-d93c838b9e39', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '0d578278-c6dc-549f-afc8-8c4dd0339a08', 2, 10, 'እርሱም፥ “የዛሬ ዓመት እንደ ዛሬው ወደ አንተ ተመልሼ እመጣለሁ፤ ሚስትህ ሣራም ልጅን ታገኛለች” አለ።'),
  ('6ba06a40-8220-5fbf-abf3-b63870246dbd', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '0d578278-c6dc-549f-afc8-8c4dd0339a08', 3, 11, 'ሣራም በድንኳኑ ደጃፍ በስተኋላው ቆማ ሳለች ይህን ሰማች። አብርሃምና ሣራም በዕድሜያቸው ሸምግለው ፈጽመው አርጅተው ነበር፤ በሴቶች የሚሆነውም ልማድ ከሣራ ተቋርጦ ነበር።'),
  ('6da5319a-23b2-5935-a057-d2760115c5bf', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '0d578278-c6dc-549f-afc8-8c4dd0339a08', 4, 12, 'ሣራም ለብቻዋ በልብዋ እንዲህ ስትል ሳቀች፥ “እስከ ዛሬ ገና ነኝን? ጌታዬም ፈጽሞ ሽምግሎአል።”'),
  ('4971f3c8-3176-57ea-adbe-9e5eef0cfb1d', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '0d578278-c6dc-549f-afc8-8c4dd0339a08', 5, 13, 'እግዚአብሔርም አብርሃምን አለው፥ “ሣራን ለብቻዋ በልብዋ ምን አሳቃት? እስከ ዛሬ ገና ነኝን? በእውነትስ እወልዳለሁን? ጌታዬም አርጅትዋል እነሆ፥ እኔም አርጅቻለሁ ብላለችና።'),
  ('d2e2ace2-8986-5388-ab15-316cdb655497', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '0d578278-c6dc-549f-afc8-8c4dd0339a08', 6, 14, 'በውኑ ለእግዚአብሔር የሚሳነው ነገር አለን? የዛሬ ዓመት እንደ ዛሬው ጊዜ ወደ አንተ እመለሳለሁ፤ ሣራም ልጅን ታገኛለች።”'),
  ('1926b5c4-6719-5e11-a237-78e79f7ab684', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '0d578278-c6dc-549f-afc8-8c4dd0339a08', 7, 15, 'ሣራም ስለ ፈራች “አልሳቅሁም” ብላ ካደች። እርሱም፥ “አይደለም፥ ሳቅሽ እንጂ” አላት።'),
  ('dcc56bb1-6652-5be4-acec-a8ad8a18121c', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '2ceeb04d-cca4-5cd4-aa6a-f3b5c17be311', 1, 16, 'እነዚያም ሰዎች ከዚያ ተነሥተው ወደ ሰዶምና ወደ ገሞራ አቀኑ፤ አብርሃምም ሊሸኛቸው አብሮአቸው ሄደ፤ አብርሃምም ተመልሶ በእግዚአብሔር ፊት ቆመ።'),
  ('147c6bf5-0fb0-5f1f-aff9-2ab858db7e74', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '2ceeb04d-cca4-5cd4-aa6a-f3b5c17be311', 2, 17, 'እግዚአብሔርም አለ፥ “እኔ የማደርገውን ከወዳጄ አብርሃም አልሰውርም፤'),
  ('3ac7ee7b-e991-5b6f-a4ab-7533ad7eb1b9', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '2ceeb04d-cca4-5cd4-aa6a-f3b5c17be311', 3, 18, 'አብርሃም በእውነት ታላቅና ብርቱ ሕዝብ ይሆናልና፤ የምድር ሕዝቦችም ሁሉ በእርሱ ይባረካሉና።'),
  ('d1c73073-7abd-58db-a812-0e8fd67c1735', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '2ceeb04d-cca4-5cd4-aa6a-f3b5c17be311', 4, 19, 'ጽድቅንና ፍርድን በማድረግ የእግዚአብሔርን መንገድ ይጠብቁ ዘንድ፥ ልጆቹንና ቤቱን ያዝዛቸው ዘንድ እንዳለው አውቃለሁና፤ ይህም እግዚአብሔር ለአብርሃም የተናገረውን ሁሉ ያደርግላቸው ዘንድ ነው።”'),
  ('5e3cb92c-a3d1-5b23-ab7c-d5d9c48e276c', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '2ceeb04d-cca4-5cd4-aa6a-f3b5c17be311', 5, 20, 'እግዚአብሔርም ለአብርሃም አለው፥ “የሰዶምና የገሞራ ጩኸት በእኔ ዘንድ በዛ፤ ኀጢአታቸውም እጅግ ከበደች፤'),
  ('6deed7cf-6057-55de-a866-3ebfa0d0f4fc', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '2ceeb04d-cca4-5cd4-aa6a-f3b5c17be311', 6, 21, 'እንግዲህስ ወደ እኔ እንደ መጣች እንደ ጩኸቷ ይፈጽሙአት እንደ ሆነ አይ ዘንድ እወርዳለሁ፤ እንዲሁም ባይሆን አውቃለሁ።”'),
  ('2e6b12d3-4d83-508b-a449-4ed1a1dd7ca8', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '2ceeb04d-cca4-5cd4-aa6a-f3b5c17be311', 7, 22, 'ሰዎቹም ከዚያ በተመለሱ ጊዜ ወደ ሰዶም መጡ፤ አብርሃም ግን በእግዚአብሔር ፊት ገና ቆሞ ነበር።'),
  ('162d715b-1e61-508d-aca7-56f8826a9a6a', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '2ceeb04d-cca4-5cd4-aa6a-f3b5c17be311', 8, 23, 'አብርሃምም ቀረበ፤ አለም፥ “አቤቱ፥ ጻድቃንን ከኃጥኣን ጋር አታጥፋ፤ ጻድቁ እንደ ኃጥኡ አይሁን።'),
  ('1bf88f6e-3dd2-54cb-ae2c-3996ebe0ab05', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '2ceeb04d-cca4-5cd4-aa6a-f3b5c17be311', 9, 24, 'አምሳ ጻድቃን በከተማዪቱ ውስጥ ቢገኙ በውኑ ሁሉን ታጠፋለህን? ከተማዪቱንስ በእርስዋ ስለሚገኙ አምሳ ጻድቃን አትምርምን?'),
  ('ed8e3d71-f7e6-5969-a053-f0838504d88f', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '2ceeb04d-cca4-5cd4-aa6a-f3b5c17be311', 10, 25, 'አቤቱ ይህ ለአንተ አግባብ አይደለም፤ ይህን ነገር አታድርግ፤ ጻድቃንን ከኃጥኣን ጋር አታጥፋ፤ ምድርን ሁሉ የምትገዛ ይህን ፍርድ ታደርግ ዘንድ ለአንተ አግባብ አይደለም።”'),
  ('681c1921-57d6-5601-a041-9e59df571262', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '2ceeb04d-cca4-5cd4-aa6a-f3b5c17be311', 11, 26, 'እግዚአብሔርም አብርሃምን አለው፥ “በሰዶም ከተማ ውስጥ አምሳ ጻድቃን ባገኝ ከተማውን ሁሉ ስለ እነርሱ አድናለሁ።”'),
  ('53186bca-4f42-5866-afec-38b5499310a2', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '2ceeb04d-cca4-5cd4-aa6a-f3b5c17be311', 12, 27, 'አብርሃምም መለሰ፤ አለም፥ “እኔ አፈርና አመድ ስሆን ከጌታዬ ከእግዚአብሔር ጋር እናገር ዘንድ አሁን ጀመርሁ፤'),
  ('de929ead-c23c-519b-aaa2-d164e4c16498', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '2ceeb04d-cca4-5cd4-aa6a-f3b5c17be311', 13, 28, 'ከእነዚያ አምሳ ጻድቃን አምስት ቢጐድሉ ከተማዪቱን ሁሉ በጐደሉት በአምስቱ ምክንያት ታጠፋለህን?” እግዚአብሔርም፥ “ከዚያ አርባ አምስት ባገኝ ስለ እነርሱ አላጠፋትም” አለው።'),
  ('a8eb33ec-e405-5636-a294-009aa09dbb20', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '2ceeb04d-cca4-5cd4-aa6a-f3b5c17be311', 14, 29, 'አብርሃምም አለው፥ “ከዚያ አርባ ቢገኙሳ?” እግዚአብሔርም፥ “ለአርባው ስል አላጠፋትም” አለው።'),
  ('72563dfc-bece-59ee-ae04-b220b60e2728', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '2ceeb04d-cca4-5cd4-aa6a-f3b5c17be311', 15, 30, 'አብርሃምም እንደገና ነገሩን ደገመ፤ እንዲህም አለው፥ “ከዚያ ሠላሳ ቢገኙሳ?” እርሱም፥ “ስለ ሠላሳው አላጠፋትም” አለው።'),
  ('2a0be539-67b8-54fe-a117-63ccd49ad157', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '2ceeb04d-cca4-5cd4-aa6a-f3b5c17be311', 16, 31, 'ደግሞም፥ “እነሆ፥ ከጌታዬ ከእግዚአብሔር ጋር እነጋገር ዘንድ ባለሟልነትን ካገኘሁ ከዚያ ሃያ ቢገኙሳ?” አለው። እርሱም፥ “ስለ ሃያው አላጠፋትም” አለው።'),
  ('4e8bf10d-9d2b-5ae9-a5f8-aafa497899d0', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '2ceeb04d-cca4-5cd4-aa6a-f3b5c17be311', 17, 32, 'አብርሃምም አለው፥ “አቤቱ እንደገና እናገር ዘንድ ፍቀድልኝ፤ ከዚያ ዐሥር ቢገኙሳ?” እርሱም፥ “ስለ ዐሥሩ አላጠፋትም” አለው።'),
  ('13f400c6-14c3-53c6-a06d-4a539eff68f1', '988f9fb2-8082-5f0a-a73b-ed8639dc0b25', '2ceeb04d-cca4-5cd4-aa6a-f3b5c17be311', 18, 33, 'እግዚአብሔርም ከአብርሃም ጋር ንግግሩን በጨረሰ ጊዜ ሄደ፤ አብርሃምም ወደ ስፍራው ተመለሰ።'),
  ('ed9e058e-e8a3-5f87-ace4-6de82ae8fcd4', 'c7e21055-ce73-554a-adaf-d88db32408a3', 'dfd6b19b-bd30-52c0-af68-8e4db7f81ce6', 1, 1, 'ሁለቱም መላእክት በመሸ ጊዜ ወደ ሰዶም ደረሱ፤ ሎጥም በሰዶም ከተማ በር ተቀምጦ ነበር። ሎጥም ባያቸው ጊዜ ሊቀበላቸው ተነሣ፤ ፊቱንም ወደ ምድር ደፍቶ ሰገደላቸው፤'),
  ('d99b4dab-3cfd-54a0-a819-e45394d80438', 'c7e21055-ce73-554a-adaf-d88db32408a3', 'dfd6b19b-bd30-52c0-af68-8e4db7f81ce6', 2, 2, 'አላቸውም፥ “ጌቶች ሆይ፥ ወደ ባሪያችሁ ቤት ገብታችሁ እደሩ፤ እግራችሁንም ታጠቡ፤ ነገም ማልዳችሁ መንገዳችሁን ትሄዳላችሁ።” እነርሱም፥ “በአደባባዩ እናድራለን እንጂ፥ አይሆንም” አሉት።'),
  ('079aea55-408a-5532-af9c-0d3daeb63dee', 'c7e21055-ce73-554a-adaf-d88db32408a3', 'dfd6b19b-bd30-52c0-af68-8e4db7f81ce6', 3, 3, 'እርሱም ግድ አላቸው፤ ወደ እርሱም አቀኑ፤ ወደ ቤቱም ገቡ፤ ቂጣንም አስጋገረላቸው፤ እነርሱም በሉ።'),
  ('4de61a65-a5e6-588a-a68e-62925217884e', 'c7e21055-ce73-554a-adaf-d88db32408a3', 'dfd6b19b-bd30-52c0-af68-8e4db7f81ce6', 4, 4, 'ገና ሳይተኙም የዚያች ከተማ ሰዎች፥ ታናሹም፥ ታላቁም ቤቱን በአንድነት ከበቡት።'),
  ('ebc0e74f-487d-5caa-a8a5-37910399a41d', 'c7e21055-ce73-554a-adaf-d88db32408a3', 'dfd6b19b-bd30-52c0-af68-8e4db7f81ce6', 5, 5, 'ሎጥንም ጠርተው እንዲህ አሉት፥ “በሌሊት ወደ አንተ የገቡት ሰዎች ወዴት ናቸው? እናውቃቸው ዘንድ ወደ እኛ አውጣቸው።”'),
  ('e9d47778-bff5-560c-a1df-0bb7d07eb57b', 'c7e21055-ce73-554a-adaf-d88db32408a3', 'dfd6b19b-bd30-52c0-af68-8e4db7f81ce6', 6, 6, 'ሎጥም ወደ እነርሱ ወደ ደጅ ፊት ለፊት ወጣ፤ መዝጊያውንም በስተኋላው ዘጋው፤'),
  ('810ee370-afdd-5ac3-a2d7-2a37048cee87', 'c7e21055-ce73-554a-adaf-d88db32408a3', 'dfd6b19b-bd30-52c0-af68-8e4db7f81ce6', 7, 7, 'እንዲህም አላቸው፥ “ወንድሞች ሆይ፥ ለእናንተ አግባባችሁ አይደለም፤ በእነዚህ ላይ ክፉ አታድርጉ፤'),
  ('fed6c8de-160c-506b-a918-545d0558858c', 'c7e21055-ce73-554a-adaf-d88db32408a3', 'dfd6b19b-bd30-52c0-af68-8e4db7f81ce6', 8, 8, 'እነሆ፥ ወንድን ያላወቁ ሁለት ሴቶች ልጆች አሉኝ፤ እነርሱን ላውጣላችሁ፤ እንደ ወደዳችሁም አድርጉአቸው፤ በእነዚህ ሰዎች ብቻ ምንም በደል አታድርጉ፤ እነርሱ በቤቴ ጥላ ሥር ገብተዋልና።”'),
  ('5cf7bcc3-6b80-5d99-a9b0-fdcf757c9cd8', 'c7e21055-ce73-554a-adaf-d88db32408a3', 'dfd6b19b-bd30-52c0-af68-8e4db7f81ce6', 9, 9, 'እነርሱም፥ “ወዲያ ሂድ፤ ከእኛ ጋር ልትኖር መጣህ እንጂ ልትገዛን አይደለም፤ አሁንም ከእነርሱ ይልቅ አንተን እናሠቃይሃለን” አሉት።'),
  ('77bb2e08-addb-5105-a93b-307250a19acc', 'c7e21055-ce73-554a-adaf-d88db32408a3', 'dfd6b19b-bd30-52c0-af68-8e4db7f81ce6', 10, 10, 'እጅግም ተጋፉት፤ የደጁንም መዝጊያ ለመስበር ቀረቡ። እነዚያም ሰዎች እጃቸውን ዘርግተው ሎጥን ወደ እነርሱ ዘንድ ወደ ቤት ስበው አገቡት፤ መዝጊያውንም ዘጉት።'),
  ('45396615-31b9-56bd-a5e6-9cab471697f1', 'c7e21055-ce73-554a-adaf-d88db32408a3', 'dfd6b19b-bd30-52c0-af68-8e4db7f81ce6', 11, 11, 'በቤቱ ደጃፍ የነበሩትንም ሰዎች ከታናሻቸው ጀምሮ እስክ ታላቃቸው ድረስ ዐይናቸውን አሳወሩአቸው፤ ደጃፉንም ሲፈልጉ ደከሙ፤ አጡትም።'),
  ('1bc2b60f-7e86-5042-ae61-87d7b71d7467', 'c7e21055-ce73-554a-adaf-d88db32408a3', '15247f40-b23f-5494-a238-7b6a60f829a7', 1, 12, 'እነዚያም መላእክት ሎጥን አሉት፥ “ከዚህ ሌላ ማን አለህ? አማችም ቢሆን፥ ወንድ ልጅም ቢሆን፥ ሴት ልጅም ብትሆን፥ በዚህ ከተማ የምታውቀው ወዳጅ ቢኖርህ ያለህን ሁሉ ከዚህ ስፍራ አስወጣቸው፤'),
  ('94b2784e-33b3-51c1-a482-263398cb3f95', 'c7e21055-ce73-554a-adaf-d88db32408a3', '15247f40-b23f-5494-a238-7b6a60f829a7', 2, 13, 'እኛ ይህችን ስፍራ እናጠፋታለንና፥ ጩኸታቸው በእግዚአብሔር ፊት ትልቅ ሆኖአልና፤ እናጠፋትም ዘንድ እግዚአብሔር ልኮናል።”'),
  ('15f337de-f1ff-50fa-ad7f-5f1f97284f06', 'c7e21055-ce73-554a-adaf-d88db32408a3', '15247f40-b23f-5494-a238-7b6a60f829a7', 3, 14, 'ሎጥም ወጣ፤ ልጆቹን ለሚያገቡት ለአማቾቹም አላቸው፥ “ተነሡ፤ ከዚች ስፍራ ውጡ፤ እግዚአብሔር ይህችን ከተማ ያጠፋታልና።” ለአማቾቹ ግን የሚያፌዝባቸው መሰላቸው።'),
  ('0528da40-1961-53bc-af67-10eb1f33859c', 'c7e21055-ce73-554a-adaf-d88db32408a3', '15247f40-b23f-5494-a238-7b6a60f829a7', 4, 15, 'ጎህም በቀደደ ጊዜ መላእክት ሎጥን፥ “ተነሣ፤ ሚስትህንና ከዚህ ያሉትን ሁለቱን ሴቶች ልጆችህን ውሰድ፤ አንተም በከተማዪቱ ሰዎች ኀጢአት እንዳትጠፋ” እያሉ ያስቸኩሉት ነበር።'),
  ('e3518523-82a1-5100-af18-3820fba339e4', 'c7e21055-ce73-554a-adaf-d88db32408a3', '15247f40-b23f-5494-a238-7b6a60f829a7', 5, 16, 'እርሱም በዘገየ ጊዜ እነዚያ መላእክት የእርሱን እጅ፥ የሚስቱንም እጅ፥ የሁለቱን ሴቶች ልጆቹንም እጅ ይዘው አወጡአቸው፤ እግዚአብሔር ራርቶላቸዋልና።'),
  ('acc4db8b-c4c9-5838-a430-8cc2af60779c', 'c7e21055-ce73-554a-adaf-d88db32408a3', '15247f40-b23f-5494-a238-7b6a60f829a7', 6, 17, 'ወደ ሜዳም በወጡ ጊዜ እንዲህ አሉት፥ “ራስህን አድን፤ ወደ ኋላም አትመልከት፤ አንተንም መከራ እንዳታገኝህ በዚች ሀገር በዳርቻዋና በተራራዋ አትቁም።”'),
  ('560cbd12-74dd-5766-aef3-9ddbe930059c', 'c7e21055-ce73-554a-adaf-d88db32408a3', '15247f40-b23f-5494-a238-7b6a60f829a7', 7, 18, 'ሎጥም አላቸው፥ “ጌቶች ሆይ፥ በጀ በሉኝ፤'),
  ('9fdffdc4-7293-5e04-a37e-e9ad4a725a78', 'c7e21055-ce73-554a-adaf-d88db32408a3', '15247f40-b23f-5494-a238-7b6a60f829a7', 8, 19, 'እነሆ፥ ባሪያህ በፊትህ ምሕረትን አግኝቼ እንደሆነ፥ ሰውነቴንም ታድናት ዘንድ፥ ቸርነትህን አብዝተህልኝ እንደ ሆነ፥ መከራ አግኝቶኝ እንዳልጠፋ ወደ ተራራ ሸሽቼ ራሴን ማዳን አልችልም።'),
  ('aa0ea83f-3295-50b4-a9fe-ff73ca869b68', 'c7e21055-ce73-554a-adaf-d88db32408a3', '15247f40-b23f-5494-a238-7b6a60f829a7', 9, 20, 'እነሆ፥ ይህች ከተማ ወደ እርስዋ ሸሽቶ ለማምለጥ ቅርብ ናት፤ እርስዋም ትንሽ ናት፤ ነፍሴን ለማዳን ወደ እርስዋ ሸሽቼ ራሴን ላድን፤ ሰውነቴም ከዳነች ትንሽ አይደለችም፤”'),
  ('15caeea2-be10-56f6-ac32-2d6d9cb40ba5', 'c7e21055-ce73-554a-adaf-d88db32408a3', '15247f40-b23f-5494-a238-7b6a60f829a7', 10, 21, 'እርሱም አለው፥ “ስለ እርስዋ የነገርኸኝን ያችን ከተማ እንዳላጠፋት እነሆ፥ እንዳልኸው ልመናህን ተቀብዬሃለሁ፤'),
  ('d2288581-744c-524f-a29b-5786f8d944a5', 'c7e21055-ce73-554a-adaf-d88db32408a3', '15247f40-b23f-5494-a238-7b6a60f829a7', 11, 22, 'እንግዲህ ፍጠንና በዚያ ራስህን አድን፤ ወደዚያ እስክትደርስ ድረስ ምንም አደርግ ዘንድ አልችልምና።” ስለዚህም የዚያች ከተማ ስም ሴጎር ተባለ።'),
  ('35fcf959-7d44-554f-abd6-23805dd591ca', 'c7e21055-ce73-554a-adaf-d88db32408a3', '3c8e1a93-5070-57c1-a409-bee67a94fc85', 1, 23, 'ፀሐይ በምድር ላይ ወጣች፤ ሎጥም ወደ ሴጎር ገባ።'),
  ('6b0bbbfe-c15e-5bcb-a0af-501e28157ee9', 'c7e21055-ce73-554a-adaf-d88db32408a3', '3c8e1a93-5070-57c1-a409-bee67a94fc85', 2, 24, 'እግዚአብሔርም በሰዶምና በገሞራ ላይ ከእግዚአብሔር ዘንድ ከሰማይ እሳትና ዲን አዘነበ፤'),
  ('6804e1bd-5400-53b1-af5a-f70ed27e7921', 'c7e21055-ce73-554a-adaf-d88db32408a3', '3c8e1a93-5070-57c1-a409-bee67a94fc85', 3, 25, 'እነዚያንም ከተሞች፥ በዙሪያቸው ያለውንም ሁሉ፥ በከተሞችም የሚኖሩትን ሁሉ፥ የምድሩንም ቡቃያ ሁሉ ገለበጠ።'),
  ('02d05fd8-833d-548b-a3fd-ce92d6353629', 'c7e21055-ce73-554a-adaf-d88db32408a3', '3c8e1a93-5070-57c1-a409-bee67a94fc85', 4, 26, 'የሎጥም ሚስት ወደ ኋላዋ ተመለከተች፤ የጨው ሐውልትም ሆነች።'),
  ('13e170c8-cbdf-5bfb-ad8a-f0a81de8db07', 'c7e21055-ce73-554a-adaf-d88db32408a3', '3c8e1a93-5070-57c1-a409-bee67a94fc85', 5, 27, 'አብርሃምም በእግዚአብሔር ፊት ቆሞ ወደ ነበረበት ስፍራ ለመሄድ ማልዶ ተነሣ፤'),
  ('8d645fa1-02cd-5854-acfb-1cb2c24b7b07', 'c7e21055-ce73-554a-adaf-d88db32408a3', '3c8e1a93-5070-57c1-a409-bee67a94fc85', 6, 28, 'ወደ ሰዶምና ገሞራ፥ ወደ አውራጃዎችዋም ሁሉ ተመለከተ፤ እነሆም፥ ነበልባል ከምድር እንደ ምድጃ ጢስ ሲወጣ አየ።'),
  ('9f2fc6d5-bca0-57b0-af0d-4b92ce7105d3', 'c7e21055-ce73-554a-adaf-d88db32408a3', '3c8e1a93-5070-57c1-a409-bee67a94fc85', 7, 29, 'እግዚአብሔርም እነዚያን ከተሞችና ሎጥ የሚኖርባቸውን አውራጃዎችዋን ሁሉ ባጠፋ ጊዜ አብርሃምን ዐሰበው፤ ሎጥንም ከጥፋት መካከል አወጣው።'),
  ('59175231-08bf-582b-a1cf-d303697b6282', 'c7e21055-ce73-554a-adaf-d88db32408a3', 'dc288cd5-21d3-5adc-aa11-8593ff437e1e', 1, 30, 'ሎጥም ከሴጎር ወጣ፤ ከሁለቱም ሴቶች ልጆቹ ጋር በተራራ ተቀመጠ፤ በሴጎር መቀመጥን ፈርቶአልና እርሱና ሁለቱ ሴቶች ልጆቹ በዋሻ ተቀመጡ።'),
  ('9ab0c35f-c46f-5ed3-a63c-3ee39af3ccd1', 'c7e21055-ce73-554a-adaf-d88db32408a3', 'dc288cd5-21d3-5adc-aa11-8593ff437e1e', 2, 31, 'ታላቂቱም ታናሺቱን አለቻት፥ “አባታችን ሽማግሌ ነው፤ በምድርም ሁሉ እንዳለው ልማድ ሊገናኘን የሚችል ሰው በምድር ላይ የለም።'),
  ('48e06712-ae69-5ec8-ab7e-1317c8a598c7', 'c7e21055-ce73-554a-adaf-d88db32408a3', 'dc288cd5-21d3-5adc-aa11-8593ff437e1e', 3, 32, 'ነዪ፥ አባታችንን ወይን እናጠጣውና ከእርሱ ጋር እንተኛ፤ ከአባታችንም ዘር እናስቀር።”'),
  ('858eaed6-736c-51ec-a750-78158ebd60f6', 'c7e21055-ce73-554a-adaf-d88db32408a3', 'dc288cd5-21d3-5adc-aa11-8593ff437e1e', 4, 33, 'በዚያችም ሌሊት አባታቸውን ወይን አጠጡት፤ ታላቂቱም ገባች፤ በዚያችም ሌሊት ከአባቷ ጋር ተኛች፤ እርሱም ስትተኛም፥ ስትነሣም አላወቀም።'),
  ('85d32ddc-0ecd-5129-ad9c-8ef299add644', 'c7e21055-ce73-554a-adaf-d88db32408a3', 'dc288cd5-21d3-5adc-aa11-8593ff437e1e', 5, 34, 'በነጋውም ታላቂቱ ታናሺቱን አለቻት፥ “እነሆ፥ ትናንት ከአባቴ ጋር ተኛሁ፤ ዛሬ ሌሊት ደግሞ ወይን እናጠጣው፤ አንቺም ግቢና ከእርሱ ጋር ተኚ፤ ከአባታችንም ዘር እናስቀር።”'),
  ('367a2bd0-a109-5c2a-a635-ae07e01ff9d5', 'c7e21055-ce73-554a-adaf-d88db32408a3', 'dc288cd5-21d3-5adc-aa11-8593ff437e1e', 6, 35, 'አባታቸውንም በዚያች ሌሊት ደግሞ ወይን አጠጡት፤ ታናሺቱም ገብታ ከአባቷ ጋር ተኛች፤ እርሱም ስትተኛም ስትነሣም አላወቀም።'),
  ('44fa8a22-044e-59cd-af4d-91eafc1ed041', 'c7e21055-ce73-554a-adaf-d88db32408a3', 'dc288cd5-21d3-5adc-aa11-8593ff437e1e', 7, 36, 'የሎጥም ሁለቱ ሴቶች ልጆች ከአባታቸው ፀነሱ።'),
  ('9d1cefa4-3a59-597a-aeb7-c3042d49a815', 'c7e21055-ce73-554a-adaf-d88db32408a3', 'dc288cd5-21d3-5adc-aa11-8593ff437e1e', 8, 37, 'ታላቂቱም ወንድ ልጅ ወለደች፤ ስሙንም ሞዓብ ብላ ጠራችው፤ ይህም ከአባቴ የወለድሁት ማለት ነው። እርሱም እስከ ዛሬ የሞዓባውያን አባት ነው።'),
  ('3d0edd9d-86ae-5e37-add0-63d20473ec8d', 'c7e21055-ce73-554a-adaf-d88db32408a3', 'dc288cd5-21d3-5adc-aa11-8593ff437e1e', 9, 38, 'ታናሺቱም ደግሞ ወንድ ልጅ ወለደች፤ ስሙንም የወገኔ ልጅ ስትል አሞን ብላ ጠራችው፤ እርሱም እስከ ዛሬ የአሞናውያን አባት ነው።'),
  ('ef54db41-a116-5c63-a569-9f095be46158', '68684ecb-c7ce-5dc4-a902-a9e27e658e8d', '04103e13-15eb-56f6-ac6f-65b34e973cbf', 1, 1, 'አብርሃምም ከዚያ ተነሥቶ ወደ አዜብ ምድር አቅጣጫ ሄደ፤ በቃዴስና በሱር መካከልም ኖረ፤ በጌራራም በእንግድነት ተቀመጠ።'),
  ('c668d46c-d6af-5425-aac7-e24544f089d9', '68684ecb-c7ce-5dc4-a902-a9e27e658e8d', '04103e13-15eb-56f6-ac6f-65b34e973cbf', 2, 2, 'አብርሃምም ሚስቱን ሣራን “እኅቴ ናት” አላቸው፤ የከተማዪቱ ሰዎች ስለ እርስዋ እንዳይገድሉት “ሚስቴ” ናት ማለትን ፈርቶአልና፤ የጌራራ ንጉሥ አቤሜሌክም ላከና ሣራን ወሰዳት።'),
  ('05ccf7ff-42b0-5db6-a66e-6844981f8c25', '68684ecb-c7ce-5dc4-a902-a9e27e658e8d', '04103e13-15eb-56f6-ac6f-65b34e973cbf', 3, 3, 'በዚያች ሌሊትም አቤሜሌክ ተኝቶ ሳለ እግዚአብሔር በሕልም ወደ እርሱ መጣ፤ እንዲህም አለው፥ “እነሆ፥ አንተ ስለ ወሰድሃት ሴት ትሞታለህ፤ እርስዋ ባለ ባል ናትና።”'),
  ('a417e810-ce65-539b-a604-84aec7fa89f4', '68684ecb-c7ce-5dc4-a902-a9e27e658e8d', '04103e13-15eb-56f6-ac6f-65b34e973cbf', 4, 4, 'አቤሜሌክ ግን አልቀረባትም ነበር፤ አቤሜሌክም እንዲህ አለ፥ “አቤቱ ያላወቀውን ሕዝብ በእውነት ታጠፋለህን?')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('6c7e84b5-e2f7-5f0e-a11d-9a28891ad5b6', '68684ecb-c7ce-5dc4-a902-a9e27e658e8d', '04103e13-15eb-56f6-ac6f-65b34e973cbf', 5, 5, 'እኅቴ ናት ያለኝ እርሱ አይደለምን? እርስዋ ደግሞ ራስዋ ወንድሜ ነው አለች፤ በልቤ ቅንነትና በእጄ ንጹሕነት ይህን አደረግሁት።”'),
  ('bc705a02-aa9c-56a5-ab22-921f0c6ebfb2', '68684ecb-c7ce-5dc4-a902-a9e27e658e8d', '04103e13-15eb-56f6-ac6f-65b34e973cbf', 6, 6, 'እግዚአብሔርም በሕልም አለው፥ “ይህን በልብህ ቅንነት እንዳደረግህ እኔ ዐወቅሁ፤ እኔም ደግሞ በፊቴ ኀጢአትን እንዳትሠራ ጠበቅሁህ፤ ስለዚህም ትቀርባት ዘንድ አልተውሁህም።'),
  ('99df889f-4744-55bb-a00f-c49270478c81', '68684ecb-c7ce-5dc4-a902-a9e27e658e8d', '04103e13-15eb-56f6-ac6f-65b34e973cbf', 7, 7, 'አሁንም የሰውየውን ሚስት መልስ፤ ነቢይ ነውና፥ ስለ አንተም ይጸልያል፤ ትድናለህም። ባትመልሳት ግን አንተ እንድትሞት፥ ለአንተ የሆነውም ሁሉ እንዲሞት በርግጥ ዕወቅ።”'),
  ('dfdf105c-c673-5083-a34f-1cb53f439707', '68684ecb-c7ce-5dc4-a902-a9e27e658e8d', '04103e13-15eb-56f6-ac6f-65b34e973cbf', 8, 8, 'አቤሜሌክም በጥዋት ተነሣ፤ ብላቴኖቹንም ሁሉ ጠራ፤ ይህንም ነገር ሁሉ በጆሮአቸው ተናገረ፤ ቤተ ሰዎቹም ሁሉ እግዚአብሔርን እጅግ ፈሩ።'),
  ('f6131d52-564d-518c-a0d7-2d7d50823e3e', '68684ecb-c7ce-5dc4-a902-a9e27e658e8d', '04103e13-15eb-56f6-ac6f-65b34e973cbf', 9, 9, 'አቤሜሌክም አብርሃምን ጠርቶ አለው፥ “ይህ ያደረግህብን ምንድን ነው? ምንስ ክፉ ሠራሁብህ? በእኔና በመንግሥቴ ላይ ትልቅ ኀጢአት አውርደሃልና፤ ማንም የማያደርገው የማይገባ ሥራ በእኔ ሠራህብኝ።”'),
  ('a1fd3c6d-37ea-5383-a01d-30a6384f6ecd', '68684ecb-c7ce-5dc4-a902-a9e27e658e8d', '04103e13-15eb-56f6-ac6f-65b34e973cbf', 10, 10, 'አቤሜሌክም አብርሃምን አለው፥ “ይህን ነገር ማድረግህ ምን አይተህ ነው?”'),
  ('6c59f677-36f3-5e58-ada2-7bae58d076d5', '68684ecb-c7ce-5dc4-a902-a9e27e658e8d', '04103e13-15eb-56f6-ac6f-65b34e973cbf', 11, 11, 'አብርሃምም አለ፥ “ምንአልባት በዚህ ስፍራ እግዚአብሔርን መፍራት ስለሌለ በሚስቴ ምክንያት ይገድሉኛል ብዬ ነው።'),
  ('a1d104ad-2931-5eb6-ae7e-77455faf8da3', '68684ecb-c7ce-5dc4-a902-a9e27e658e8d', '04103e13-15eb-56f6-ac6f-65b34e973cbf', 12, 12, 'እርስዋም ደግሞ በእናቴ ወገን አይደለችም እንጂ በእውነት በአባቴ ወገን እኅቴ ናት፤ ለእኔም ሚስት ሆነች።'),
  ('87085576-0648-566c-a182-c89a0537697c', '68684ecb-c7ce-5dc4-a902-a9e27e658e8d', '04103e13-15eb-56f6-ac6f-65b34e973cbf', 13, 13, 'እግዚአብሔርም ከአባቴ ቤት ባወጣኝ ጊዜ አልኋት፥ ‘ይህን ጽድቅ አድርጊልኝ፤ በገባንበት ሀገር ሁሉ ወንድሜ ነው በዪ።’ ”'),
  ('d9783ca9-6606-5357-acaa-75240b9561d7', '68684ecb-c7ce-5dc4-a902-a9e27e658e8d', '04103e13-15eb-56f6-ac6f-65b34e973cbf', 14, 14, 'አቤሜሌክም አንድ ሺህ ምዝምዝ ብርን በጎችንና ላሞችን፥ ወንዶችና ሴቶች ባሪያዎችን አመጣ፤ ለአብርሃምም ሰጠው፤ ሚስቱን ሣራንም መለሰለት።'),
  ('4d1d8a09-2cab-5a8e-a6e6-8b815adf4fa4', '68684ecb-c7ce-5dc4-a902-a9e27e658e8d', '04103e13-15eb-56f6-ac6f-65b34e973cbf', 15, 15, 'አቤሜሌክም አብርሃምን አለው፥ “እነሆ፥ ምድሬ በፊትህ ናት፤ በወደድኸው ተቀመጥ።”'),
  ('92b3b18a-be38-5d67-a120-fd6bda207377', '68684ecb-c7ce-5dc4-a902-a9e27e658e8d', '04103e13-15eb-56f6-ac6f-65b34e973cbf', 16, 16, 'ሣራንም አላት “እነሆ፥ ለወንድምሽ አንድ ሺህ ምዝምዝ ብር ሰጠሁት፤ ይህም ለፊትሽ ክብር ይሁንሽ፤ በሁሉም እውነትን ተናገራት።”'),
  ('f9b9e056-9fd3-50a7-a34c-da8b5b598427', '68684ecb-c7ce-5dc4-a902-a9e27e658e8d', '04103e13-15eb-56f6-ac6f-65b34e973cbf', 17, 17, 'አብርሃምም ወደ እግዚዘብሔር ጸለየ፤ እግዚአብሔርም አቤሜሌክን፥ ሚስቱንም፥ ሴቶች ልጆቹንም፥ በቤቱ ውስጥ ያሉ ሴቶች አገልጋዮቹንም ፈወሳቸው፤ እነርሱም ወለዱ፤'),
  ('a7d8247c-cfe4-5daf-ad36-3fb9a7823f61', '68684ecb-c7ce-5dc4-a902-a9e27e658e8d', '04103e13-15eb-56f6-ac6f-65b34e973cbf', 18, 18, 'እግዚአብሔር በአብርሃም ሚስት በሣራ ምክንያት በአቤሜሌክ ቤት ማኅፀኖችን ሁሉ በፍጹም ዘግቶ ነበርና።'),
  ('f8b2b8b9-db1b-50b5-ab7d-8a1158dbda22', '7ba9f22d-160e-5b8e-a551-575972887b84', 'b517b9ca-3107-55d3-ac8a-9488bf31f349', 1, 1, 'እግዚአብሔርም እንደ ተናገረው ሣራን ጐበኛት፤ እግዚአብሔርም እንደ ተናገረው ለሣራ አደረገላት።'),
  ('d4753efe-ddb4-540c-ac0c-87f8429d8607', '7ba9f22d-160e-5b8e-a551-575972887b84', 'b517b9ca-3107-55d3-ac8a-9488bf31f349', 2, 2, 'ሣራም ፀነሰች፤ እግዚአብሔርም በተናገረው ወራት ለአብርሃም በእርጅናዋ ወንድ ልጅን ወለደችለት።'),
  ('c4f87431-72d1-51be-a855-6b1e42f2a6bd', '7ba9f22d-160e-5b8e-a551-575972887b84', 'b517b9ca-3107-55d3-ac8a-9488bf31f349', 3, 3, 'አብርሃምም ሣራ የወለደችለትን የልጁን ስም ይስሐቅ ብሎ ጠራው።'),
  ('e0e66d3d-787e-570b-a023-90484c799d91', '7ba9f22d-160e-5b8e-a551-575972887b84', 'b517b9ca-3107-55d3-ac8a-9488bf31f349', 4, 4, 'አብርሃምም ልጁን ይስሐቅን እግዚአብሔር እንዳዘዘው በስምንተኛው ቀን ገረዘው።'),
  ('40876531-f2bb-5e4f-a9ad-6587f52a0a27', '7ba9f22d-160e-5b8e-a551-575972887b84', 'b517b9ca-3107-55d3-ac8a-9488bf31f349', 5, 5, 'አብርሃምም ልጁ ይስሕቅ በተወለደለት ጊዜ መቶ ዓመቱ ነበረ።'),
  ('57c1d6ab-9630-58e6-a18a-09e5c1fb5742', '7ba9f22d-160e-5b8e-a551-575972887b84', 'b517b9ca-3107-55d3-ac8a-9488bf31f349', 6, 6, 'ሣራም፥ “እግዚአብሔር ደስ አሰኘኝ፤ ይህን የሚሰማ ሁሉ በእኔ ምክንያት ደስ ይሰኛልና” አለች።'),
  ('f6cdd2f1-2bab-5b14-a908-70f289212477', '7ba9f22d-160e-5b8e-a551-575972887b84', 'b517b9ca-3107-55d3-ac8a-9488bf31f349', 7, 7, 'ደግሞም ሣራ “በእርጅናዋ የወለደችውን ሕፃን እንድታጠባ ለአብርሃም ማን በነገረው?” አለች።'),
  ('a9295edd-d684-511a-a00a-02f7d960259c', '7ba9f22d-160e-5b8e-a551-575972887b84', 'b517b9ca-3107-55d3-ac8a-9488bf31f349', 8, 8, 'ሕፃኑም አደገ፤ ጡትንም አስጣሉት፤ አብርሃምም ይስሐቅን ጡት ባስጣለበት ቀን ትልቅ ግብዣን አደረገ።'),
  ('8c0a11d6-0cc8-51a2-a62a-6ce03825c1c7', '7ba9f22d-160e-5b8e-a551-575972887b84', '5210a11c-1bdb-56e2-aa22-766c38132c26', 1, 9, 'ሣራም ግብፃዊቱ አጋር ለአብርሃም የወለደችለትን ልጅ ይስማኤልን ከልጅዋ ከይስሐቅ ጋር ሲጫወት አየችው።'),
  ('4e908b41-7b89-51c1-aa68-4f8c49ffa6b6', '7ba9f22d-160e-5b8e-a551-575972887b84', '5210a11c-1bdb-56e2-aa22-766c38132c26', 2, 10, 'ሣራም አብርሃምን አለችው፥ “ይህችን ባሪያ ከነልጅዋ አባርራት፤ የዚህች ባሪያ ልጅ ከልጄ ከይስሐቅ ጋር አይወርስምና።”'),
  ('58db7a13-ee2e-5b73-a251-419066789eb1', '7ba9f22d-160e-5b8e-a551-575972887b84', '5210a11c-1bdb-56e2-aa22-766c38132c26', 3, 11, 'ይህም ነገር በአብርሃም ዘንድ ስለ ልጁ እጅግ ችግር ሆነበት።'),
  ('09f7bf29-3de6-50df-aff4-081532eef908', '7ba9f22d-160e-5b8e-a551-575972887b84', '5210a11c-1bdb-56e2-aa22-766c38132c26', 4, 12, 'እግዚአብሔርም አብርሃምን አለው፥ “ስለዚች አገልጋይህና ስለ ሕፃኑ አትዘን፤ ሣራም የምትነግርህን ቃል ሁሉ ስማ፤ በይስሐቅ ዘር ይጠራልሃልና።'),
  ('6fb39f1b-2502-5508-a04f-97708ca8047b', '7ba9f22d-160e-5b8e-a551-575972887b84', '5210a11c-1bdb-56e2-aa22-766c38132c26', 5, 13, 'የባሪያዪቱን ልጅ ደግሞ ታላቅ ሕዝብ አደርገዋለሁ፤ ዘርህ ነውና።”'),
  ('0897a471-fa8b-5106-af5f-e7564b8d8212', '7ba9f22d-160e-5b8e-a551-575972887b84', '5210a11c-1bdb-56e2-aa22-766c38132c26', 6, 14, 'አብርሃምም ማልዶ ተነሣ፤ እንጀራንም ወሰደ፤ የውኃ አቍማዳንም ለአጋር በትከሻዋ አሸከማት፤ ሕፃኑንም ሰጥቶ አስወጣት፤ እርስዋም ሄደች፤ በዐዘቅተ መሐላም በኩል ባለው ምድረ በዳ ተቅበዘበዘች።'),
  ('bc506c30-cbb3-5de4-a638-6d031d06c23c', '7ba9f22d-160e-5b8e-a551-575972887b84', '5210a11c-1bdb-56e2-aa22-766c38132c26', 7, 15, 'ውኃውም ከአቍማዳው አለቀ፤ ሕፃኑንም ከአንድ ቍጥቋጦ ሥር ጥላው ሄደች፤'),
  ('6791d314-7d2b-5449-abaa-d3185b96b7f7', '7ba9f22d-160e-5b8e-a551-575972887b84', '5210a11c-1bdb-56e2-aa22-766c38132c26', 8, 16, 'ልጄ ሲሞት አላየውም ብላ ቀስት ተወርውሮ የሚደርስበትን ያህል ርቃ በአንጻሩ እየተመለከተች፥ ፊት ለፊት ተቀመጠች፤ ቃልዋንም አሰምታ አለቀሰች።'),
  ('d5314a51-3c0c-505a-a45d-ee4866e94da1', '7ba9f22d-160e-5b8e-a551-575972887b84', '5210a11c-1bdb-56e2-aa22-766c38132c26', 9, 17, 'እግዚአብሔርም የሕፃኑን ጩኸት ሰማ፤ የእግዚአብሔርም መልአክ ከሰማይ አጋርን እንዲህ ሲል ጠራት፥ “አጋር ሆይ፥ ምን ሆንሽ? እግዚአብሔር የልጅሽን ድምፅ ባለበት ስፍራ ሰምቶአልና አትፍሪ።'),
  ('8bd2a260-d352-5d24-aeba-6a1aa29bebc0', '7ba9f22d-160e-5b8e-a551-575972887b84', '5210a11c-1bdb-56e2-aa22-766c38132c26', 10, 18, 'ተነሺ፤ ልጅሽንም አንሺ፤ በእጅሽም አጽኚው፤ ትልቅ ሕዝብ አደርገዋለሁና።”'),
  ('6b49a219-98c6-5ee8-ab4f-70ff8b6d041e', '7ba9f22d-160e-5b8e-a551-575972887b84', '5210a11c-1bdb-56e2-aa22-766c38132c26', 11, 19, 'እግዚአብሔርም ለአጋር ዐይንዋን ከፈተላት፤ የውኃ ጕድጓድንም አየች፤ ሄዳም አቍማዳውን በውኃ ሞላች፤ ልጅዋንም አጠጣችው።'),
  ('39cd434b-7fae-5342-a80d-b3d9e6a153a5', '7ba9f22d-160e-5b8e-a551-575972887b84', '5210a11c-1bdb-56e2-aa22-766c38132c26', 12, 20, 'እግዚአብሔርም ከዚያ ሕፃን ጋር ነበረ፤ አደገም፤ በምድረ በዳም ተቀመጠ፤ ቀስተኛም ሆነ።'),
  ('a16d73a2-f4ef-5bab-ad4d-ac9ecf6704fd', '7ba9f22d-160e-5b8e-a551-575972887b84', '5210a11c-1bdb-56e2-aa22-766c38132c26', 13, 21, 'በፋራን ምድረ በዳም ተቀመጠ፤ እናቱም ከምድረ ግብፅ ሚስት ወሰደችለት።'),
  ('73c67cc4-7e8b-5d9c-a099-ed10e5fdb562', '7ba9f22d-160e-5b8e-a551-575972887b84', 'f2e8d990-4766-5aeb-aff7-47e82aba5501', 1, 22, 'በዚያ ዘመን አቤሜሌክ፥ ሚዜው አኮዘትና የሠራዊቱ አለቃ ፋኮል ወደ አብርሃም ሄደው አሉት፥ “በምታደርገው ሁሉ እግዚአብሔር ከአንተ ጋር ነው፤'),
  ('8e622f73-55ed-55c9-a2ae-3ffa923a09af', '7ba9f22d-160e-5b8e-a551-575972887b84', 'f2e8d990-4766-5aeb-aff7-47e82aba5501', 2, 23, 'አሁንም በእኔም፥ በልጄም፥ በወገኔም፥ ከእኔም ጋር ባለ ክፉ እንዳታደርግብኝ በእግዚአብሔር ማልልኝ፤ ነገር ግን በእንግድነት መጥተህ ለአንተ ቸርነት እንዳደረግሁ አንተም ለእኔ፥ ለተቀምጥህባትም ምድር ቸርነትን ታደርጋለህ።”'),
  ('04769a79-e102-5b1d-a2f6-cc33e1ccf8a5', '7ba9f22d-160e-5b8e-a551-575972887b84', 'f2e8d990-4766-5aeb-aff7-47e82aba5501', 3, 24, 'አብርሃምም፥ “እሺ እኔ እምላለሁ” አለ።'),
  ('ec6b81cf-8e16-5dfc-a18c-236a00eee803', '7ba9f22d-160e-5b8e-a551-575972887b84', 'f2e8d990-4766-5aeb-aff7-47e82aba5501', 4, 25, 'አብርሃምም አቤሜሌክን ብላቴኖቹ በቀሙት በውኃ ጕድጓድ ምክንያት ወቀሰው።'),
  ('8ab58f7a-7b52-57b2-a989-e2500afa2625', '7ba9f22d-160e-5b8e-a551-575972887b84', 'f2e8d990-4766-5aeb-aff7-47e82aba5501', 5, 26, 'አቤሜሌክም አለ፥ “ይህን ነገር ማን እንዳደረገው አላወቅሁም፤ አንተም ደግሞ ምንም አልነገርኸኝም፤ እኔም ከዛሬ በቀር አልሰማሁም።”'),
  ('55d6c462-5f2b-5c1e-a925-354568d3aaa9', '7ba9f22d-160e-5b8e-a551-575972887b84', 'f2e8d990-4766-5aeb-aff7-47e82aba5501', 6, 27, 'አብርሃምም በጎችንና ላሞችን አምጥቶ ለአቤሜሌክ ሰጠው፤ ሁለቱም ቃል ኪዳን አደረጉ።'),
  ('c1e84070-051a-5380-ad65-1ae19f1019ec', '7ba9f22d-160e-5b8e-a551-575972887b84', 'f2e8d990-4766-5aeb-aff7-47e82aba5501', 7, 28, 'አብርሃምም ሰባ ቄቦች በጎችን ለብቻቸው አቆመ።'),
  ('56e4475f-a578-56eb-aead-cba25b5e85fd', '7ba9f22d-160e-5b8e-a551-575972887b84', 'f2e8d990-4766-5aeb-aff7-47e82aba5501', 8, 29, 'አቤሜሌክም አብርሃምን፥ “ለብቻቸው ያቆምሃቸው እነዚያ ሰባ ቄቦች በጎች ምንድን ናቸው?” አለው።'),
  ('1fdec1c9-83c7-5519-ad4b-b9f62313cf18', '7ba9f22d-160e-5b8e-a551-575972887b84', 'f2e8d990-4766-5aeb-aff7-47e82aba5501', 9, 30, 'እርሱም፥ “እኔ ይህችን የውኃ ጕድጓድ እንደቈፈርሁ ምስክር ይሆኑልኝ ዘንድ እነዚህን ሰባ ቄቦች በጎች ከእጄ ትወስዳለህ” አለው።'),
  ('0126ab7e-e7c4-5779-a72b-2eaaf090dbd1', '7ba9f22d-160e-5b8e-a551-575972887b84', 'f2e8d990-4766-5aeb-aff7-47e82aba5501', 10, 31, 'ስለዚህም ያን ጕድጓድ ዐዘቅተ መሐላ ብሎ ጠራው፤ በዚያ እርስ በርሳቸው ተማምለዋልና።'),
  ('fac088ed-eff3-5da0-a8a8-660014c26c45', '7ba9f22d-160e-5b8e-a551-575972887b84', 'f2e8d990-4766-5aeb-aff7-47e82aba5501', 11, 32, 'በዐዘቅተ መሐላ አጠገብም ቃል ኪዳንን አደረጉ። አቤሜሌክና ሚዜው አኮዞት፥ የሠራዊቱ አለቃ ፋኮልም ተነሥተው ወደ ፍልስጥኤም ምድር ተመለሱ።'),
  ('264aa7a7-8f1b-507d-a8c6-bf88e55c66c1', '7ba9f22d-160e-5b8e-a551-575972887b84', 'f2e8d990-4766-5aeb-aff7-47e82aba5501', 12, 33, 'አብርሃምም በዐዘቅተ መሐላ አጠገብ የተምር ዛፍን ተከለ፤ በዚያም የዘለዓለሙን አምላክ የእግዚአብሔርን ስም ጠራ።'),
  ('964c04e6-181f-593a-aa95-ea80b55c5e8b', '7ba9f22d-160e-5b8e-a551-575972887b84', 'f2e8d990-4766-5aeb-aff7-47e82aba5501', 13, 34, 'አብርሃምም በፍልስጥኤም ምድር ብዙ ቀን እንግዳ ሆኖ ተቀመጠ።'),
  ('d444e9c9-c34f-597f-a213-329eb7dd1583', 'af72bca7-c42b-5275-a557-07e5cbe33a75', '48dc4bf9-28bf-5aaf-afc0-13f90e9c345d', 1, 1, 'ከእነዚህም ነገሮች በኋላ እንዲህ ሆነ። እግዚአብሔር አብርሃምን ፈተነው፤ እንዲህም አለው፥ “አብርሃም! አብርሃም ሆይ፥” እርሱም፥ “እነሆ፥ አለሁ” አለ።'),
  ('7c4c3a72-28bb-5644-ae41-6cc5689042be', 'af72bca7-c42b-5275-a557-07e5cbe33a75', '48dc4bf9-28bf-5aaf-afc0-13f90e9c345d', 2, 2, '“የምትወድደውን አንድ ልጅህን ይስሐቅን ይዘህ ወደ ከፍተኛው ተራራ ሂድ፤ እኔም በምነግርህ በአንድ ተራራ ላይ በዚያ መሥዋዕት አድርገህ ሠዋው” አለው።'),
  ('48f63cd7-5519-58ef-acf3-62e04fc6d626', 'af72bca7-c42b-5275-a557-07e5cbe33a75', '48dc4bf9-28bf-5aaf-afc0-13f90e9c345d', 3, 3, 'አብርሃምም በማለዳ ተነሥቶ አህያውን ጫነ፤ ሁለቱንም ሎሌዎቹንና ልጁን ይስሐቅን ከእርሱ ጋር ወሰደ፤ ዕንጨትንም ለመሥዋዕት ሰነጠቀ፤ ተነሥቶም እግዚአብሔር ወዳለው ቦታ ሄደ፤ በሦስተኛውም ቀን ደረሰ።'),
  ('0f437aa1-a371-5b7b-a94b-f2c057d0e621', 'af72bca7-c42b-5275-a557-07e5cbe33a75', '48dc4bf9-28bf-5aaf-afc0-13f90e9c345d', 4, 4, 'አብርሃምም ዐይኑን አነሣና ቦታውን ከሩቅ አየ።'),
  ('34c0b81e-7037-50d2-a8ef-6d3e0ff668d0', 'af72bca7-c42b-5275-a557-07e5cbe33a75', '48dc4bf9-28bf-5aaf-afc0-13f90e9c345d', 5, 5, 'አብርሃምም ሎሌዎቹን አላቸው፥ “አህያውን ይዛችሁ በዚህ ቈዩ፤ እኔና ልጄ ወደዚያ ተራራ ሄደን እንሰግዳለን፤ ሰግደንም ወደ እናንተ እንመለሳለን።”'),
  ('d9d8e445-bed3-5441-a447-358ff885aac5', 'af72bca7-c42b-5275-a557-07e5cbe33a75', '48dc4bf9-28bf-5aaf-afc0-13f90e9c345d', 6, 6, 'አብርሃምም የመሥዋዕቱን ዕንጨት አንሥቶ ለልጁ ለይስሐቅ አሸከመው፤ እርሱም እሳቱንና ቢላዋዉን በእጁ ያዘ፤ ሁለቱም አብረው ሄዱ።'),
  ('25e4bba4-b3b9-5f0e-adb0-3c81899ed77d', 'af72bca7-c42b-5275-a557-07e5cbe33a75', '48dc4bf9-28bf-5aaf-afc0-13f90e9c345d', 7, 7, 'ይስሐቅም አባቱን አብርሃምን ተናገረው፥ “አባቴ ሆይ፥” አለ፤ እርሱም፥ “ልጄ፥ ምንድን ነው?” አለው። “እሳቱና ዕንጨቱ ይኸው አለ፤ የመሥዋዕቱ በግ ግን ወዴት አለ?” አለው።'),
  ('bf3fc77a-4e79-5fe9-ae1a-7175e9d5f140', 'af72bca7-c42b-5275-a557-07e5cbe33a75', '48dc4bf9-28bf-5aaf-afc0-13f90e9c345d', 8, 8, 'አብርሃምም፥ “ልጄ ሆይ፥ የመሥዋዕቱን በግ እግዚአብሔር ያዘጋጃል” አለው፤ ሁለቱም አብረው ሄዱ።'),
  ('bb2e647e-d1b5-5858-a127-3c4fda88d7f7', 'af72bca7-c42b-5275-a557-07e5cbe33a75', '48dc4bf9-28bf-5aaf-afc0-13f90e9c345d', 9, 9, 'እግዚአብሔር ወዳለውም ወደዚያ ቦታ ደረሱ፤ አብርሃምም በዚያ መሠዊያዉን ሠራ፤ ዕንጨትንም ረበረበ፤ ልጁን ይስሐቅንም አስሮ በመሠዊያዉ በዕንጨቱ ላይ በልቡ አስተኛው።'),
  ('5be9fc91-8481-5ce5-a4f7-012d3cdb8709', 'af72bca7-c42b-5275-a557-07e5cbe33a75', '48dc4bf9-28bf-5aaf-afc0-13f90e9c345d', 10, 10, 'አብርሃምም እጁን ዘረጋ፤ ልጁንም ያርድ ዘንድ ቢላዋ አነሣ።'),
  ('38c983f5-4a4f-5d6e-a6ea-fd9a7d906858', 'af72bca7-c42b-5275-a557-07e5cbe33a75', '48dc4bf9-28bf-5aaf-afc0-13f90e9c345d', 11, 11, 'የእግዚአብሔር መልአክም ከሰማይ ጠራና፥ “አብርሃም! አብርሃም” አለው፤ እርሱም፥ “እነሆኝ” አለ።'),
  ('a84e4e90-ca9b-5281-a9eb-ec7ac2834d05', 'af72bca7-c42b-5275-a557-07e5cbe33a75', '48dc4bf9-28bf-5aaf-afc0-13f90e9c345d', 12, 12, 'እርሱም፥ “በብላቴናው ላይ እጅህን አትዘርጋ፤ አንዳችም አታድርግበት፤ ለምትውድደው ልጅህ ከእኔ አልራራህለትምና አንተ እግዚአብሔርን የምትፈራ እንደሆንህ አሁን ዐውቄአለሁ” አለው።'),
  ('d9afa55f-5612-58f3-a0fa-489a38a6739b', 'af72bca7-c42b-5275-a557-07e5cbe33a75', '48dc4bf9-28bf-5aaf-afc0-13f90e9c345d', 13, 13, 'አብርሃምም ዐይኖቹን አቅንቶ በተመለከተ ጊዜ፥ በኋላው እነሆ፥ አንድ በግ ቀንዶቹ በዕፀ ሳቤቅ ተይዞ አየ፤ አብርሃምም ሄዶ በጉን ወሰደው፤ በልጁ በይስሐቅ ፈንታም ሠዋው።'),
  ('ff22b899-9a85-5542-a23c-b75ba81df1c5', 'af72bca7-c42b-5275-a557-07e5cbe33a75', '48dc4bf9-28bf-5aaf-afc0-13f90e9c345d', 14, 14, 'አብርሃምም ዛሬ በዚህ ተራራ እግዚአብሔር ፈጽሞ ታየኝ ሲል ያን ቦታ “ራእየ እግዚአብሔር” ብሎ ጠራው።'),
  ('57b49ce1-dff7-5d7a-a9d9-fb264f93fdc4', 'af72bca7-c42b-5275-a557-07e5cbe33a75', '48dc4bf9-28bf-5aaf-afc0-13f90e9c345d', 15, 15, 'የእግዚአብሔር መልአክም አብርሃምን ከሰማይ ሁለተኛ ጊዜ ጠራው፤ እንዲህም አለው፦'),
  ('01a90fff-fcd2-5152-ab3d-617cee6f3fcd', 'af72bca7-c42b-5275-a557-07e5cbe33a75', '48dc4bf9-28bf-5aaf-afc0-13f90e9c345d', 16, 16, '“እግዚአብሔር በራሴ ማልሁ ይላል፤ ይህን ነገር አድርገሃልና፥ ለምትወድደው ልጅህም ከእኔ አልራራህምና መባረክን እባርክሃለሁ፤'),
  ('25a11473-ae1f-50da-a410-c4821b31f6bb', 'af72bca7-c42b-5275-a557-07e5cbe33a75', '48dc4bf9-28bf-5aaf-afc0-13f90e9c345d', 17, 17, 'ዘርህንም እንደ ሰማይ ከዋክብትና በባሕር ዳር እንዳለ አሸዋ ፈጽሞ አበዛዋለሁ፤ ዘርህም የጠላት ሀገሮችን ይወርሳሉ፤'),
  ('842b8d78-5752-5354-af2d-aa8f8f4ab8cc', 'af72bca7-c42b-5275-a557-07e5cbe33a75', '48dc4bf9-28bf-5aaf-afc0-13f90e9c345d', 18, 18, 'የምድር አሕዛብ ሁሉም በዘርህ ይባረካሉ፤ ቃሌን ሰምተሃልና።”'),
  ('7fb50087-caab-5b12-a720-fc87e98cae75', 'af72bca7-c42b-5275-a557-07e5cbe33a75', '48dc4bf9-28bf-5aaf-afc0-13f90e9c345d', 19, 19, 'አብርሃምም ወደ ብላቴኖቹ ተመለሰ፤ ተነሥተውም ወደ ዐዘቅተ መሐላ አብረው ሄዱ፤ አብርሃምም በዐዘቅተ መሐላ ተቀመጠ።'),
  ('9ea0387c-1979-53b1-a0df-ccbb6aa8a242', 'af72bca7-c42b-5275-a557-07e5cbe33a75', 'c28db88e-f75c-542c-a8f2-84b9c4835137', 1, 20, 'እንዲህም ሆነ፤ ከዚህ ነገር በኋላ ለአብርሃም እንዲህ ተብሎ ተነገረ፥ “እነሆ፥ ሚልካ ደግሞ ለወንድምህ ለናኮር ልጆችን ወለደች፤'),
  ('25528ecd-079f-5241-a030-60ca959fbf08', 'af72bca7-c42b-5275-a557-07e5cbe33a75', 'c28db88e-f75c-542c-a8f2-84b9c4835137', 2, 21, 'እነርሱም በኵሩ ዑፅ፥ ወንድሙ በዋክሲ፤ የአራም አባት ቀማኤል፥'),
  ('fb465c42-fc56-53c2-a0f4-a99cfd4c1590', 'af72bca7-c42b-5275-a557-07e5cbe33a75', 'c28db88e-f75c-542c-a8f2-84b9c4835137', 3, 22, 'አኮዛት፥ ኤዝራው፥ ፌልዳስ፥ ዮፋትና ባቱኤል” ናቸው።'),
  ('aeb8f26f-38f1-5b65-a130-2a35dce62d68', 'af72bca7-c42b-5275-a557-07e5cbe33a75', 'c28db88e-f75c-542c-a8f2-84b9c4835137', 4, 23, 'ባቱኤልም ርብቃን ወለደ፤ ሚልካ ለአብርሃም ወንድም ለናኮር የወለደችለት ስምንቱ ልጆች እነዚህ ናቸው።'),
  ('32fd66b0-8e7d-5d0f-a13c-fcc65a1acbae', 'af72bca7-c42b-5275-a557-07e5cbe33a75', 'c28db88e-f75c-542c-a8f2-84b9c4835137', 5, 24, 'ሬሕማ የሚሉአት ዕቅብቱ ደግሞ ጥባህን፥ ቤካን፥ ጠኮንና ሜካን ወለደች።'),
  ('6fc8862d-b178-522a-a519-580416ff5c26', '6fcd8b9b-9d4a-5841-ab61-dd62147f75eb', '7a87dc04-8220-5075-a21d-07aada9356c6', 1, 1, 'የሣራም ዕድሜ መቶ ሃያ ሰባት ዓመት ሆነ።'),
  ('ff68b5fb-21ec-57f3-a613-7755964073fd', '6fcd8b9b-9d4a-5841-ab61-dd62147f75eb', '7a87dc04-8220-5075-a21d-07aada9356c6', 2, 2, 'ሣራም በቈላ ውስጥ ባለች አርባቅ በምትባል ከተማ ሞተች፤ እርስዋም በከነዓን ምድር ያለች ኬብሮን ናት፤ አብርሃምም ለሣራ ሊያዝንላትና ሊያለቅስላት ተነሣ።'),
  ('14842dd2-9140-5632-a7f3-3014ca233a0a', '6fcd8b9b-9d4a-5841-ab61-dd62147f75eb', '7a87dc04-8220-5075-a21d-07aada9356c6', 3, 3, 'አብርሃምም ከሬሳው አጠገብ ተነሣ፤ ለኬጢ ልጆችም እንዲህ ሲል ተናገረ፦'),
  ('1c0536ad-c764-5aea-a5b6-2697a9307d1b', '6fcd8b9b-9d4a-5841-ab61-dd62147f75eb', '7a87dc04-8220-5075-a21d-07aada9356c6', 4, 4, '“እኔ በእናንተ ዘንድ ስደተኛና መጻተኛ ነኝ፤ በእናንተ ዘንድ እንድገዛ የመቃብር ርስት ስጡኝ፤ ሬሳዬንም እንደ እናንተ ልቅበር።”'),
  ('0da48731-08e3-5c43-a190-a9eae844a4b1', '6fcd8b9b-9d4a-5841-ab61-dd62147f75eb', '7a87dc04-8220-5075-a21d-07aada9356c6', 5, 5, 'የኬጢ ልጆችም ለአብርሃም መለሱ፤ አሉትም፦'),
  ('ddda9fa6-446b-504c-a9fb-2266461c97ed', '6fcd8b9b-9d4a-5841-ab61-dd62147f75eb', '7a87dc04-8220-5075-a21d-07aada9356c6', 6, 6, '“አይሆንም፥ ጌታ ሆይ፥ ስማን፤ አንተ ከእግዚአብሔር ዘንድ ለእኛ ንጉሥ ነህና ከመቃብር ስፍራችን በመረጥኸው ቦታ ሬሳህን ቅበር፤ ሬሳህን በዚያ ትቀብር ዘንድ ከእኛ መቃብሩን የሚከለክልህ የለም።”'),
  ('0408134a-1015-59c5-aeec-5e2e1f22a4d7', '6fcd8b9b-9d4a-5841-ab61-dd62147f75eb', '7a87dc04-8220-5075-a21d-07aada9356c6', 7, 7, 'አብርሃምም ተነሣ፤ በሀገሩ ሕዝብ ፊትም ለኬጢ ልጆች ሰገደ።'),
  ('40ee2630-6324-58ab-a95d-a447c78651c8', '6fcd8b9b-9d4a-5841-ab61-dd62147f75eb', '7a87dc04-8220-5075-a21d-07aada9356c6', 8, 8, 'እንዲህም አላቸው፥ “ሬሳዬን ከፊቴ አርቄ እንድቀብር ከወደዳችሁስ ስሙኝ፤ ለሰዓር ልጅ ለኤፍሮንም ስለ እኔ ንገሩት፤'),
  ('293a70bb-4281-5747-a626-9ae1d6cf37dd', '6fcd8b9b-9d4a-5841-ab61-dd62147f75eb', '7a87dc04-8220-5075-a21d-07aada9356c6', 9, 9, 'በእርሻው ዳር ያለችውን ድርብ ክፍል ያላትን ዋሻውን ይስጠኝ፤ መቃብሩ የእኔ ርስት እንዲሆን በሚገባው ዋጋ በመካከላችሁ ይስጠኝ፤ ከእርሱም እገዛለሁ።”'),
  ('d38557d2-c36d-5170-aa8d-bd52aaffbeae', '6fcd8b9b-9d4a-5841-ab61-dd62147f75eb', '7a87dc04-8220-5075-a21d-07aada9356c6', 10, 10, 'ኤፍሮንም በኬጢ ልጆች መካከል ተቀምጦ ነበር፤ የኬጢ ሰው ኤፍሮንም የኬጢ ልጆችና ወደ ከተማ የሚገቡ ሁሉ ሲሰሙ ለአብርሃም እንዲህ ሲል መለሰለት፦'),
  ('34d7c8bf-7afc-5fdc-a183-f29a596351fc', '6fcd8b9b-9d4a-5841-ab61-dd62147f75eb', '7a87dc04-8220-5075-a21d-07aada9356c6', 11, 11, '“አይደለም፥ ጌታዬ፥ ቀርበህ ስማኝ፤ እርሻውን፥ በውስጡም ያለውን ዋሻውን ሰጥቼሃለሁ፤ በወገኔ ልጆች ፊት ሰጥቼሃለሁ፤ ሬሳህን ቅበር።”'),
  ('c4428d2d-3523-538a-a8bc-7502fb5b1f2a', '6fcd8b9b-9d4a-5841-ab61-dd62147f75eb', '7a87dc04-8220-5075-a21d-07aada9356c6', 12, 12, 'አብርሃምም በሀገሩ ሕዝብ ሁሉ ፊት ሰገደ፤'),
  ('21209a2e-ecdd-55f5-a0de-4e7fab421ba4', '6fcd8b9b-9d4a-5841-ab61-dd62147f75eb', '7a87dc04-8220-5075-a21d-07aada9356c6', 13, 13, 'የሀገሩ ሕዝብም ሲሰሙ ለኤፍሮን እንዲህ ሲል ተናገረ፥ “ከእኔ ቅርብ ነህና ስማኝ፤ የእርሻህንም ዋጋ ከእኔ ውሰድ፤ ሬሳዬንም በዚያ እቀብራለሁ።”'),
  ('c0eea6c2-53a4-58d1-a93d-606c3ee70440', '6fcd8b9b-9d4a-5841-ab61-dd62147f75eb', '7a87dc04-8220-5075-a21d-07aada9356c6', 14, 14, 'ኤፍሮንም ለአብርሃም እንዲህ ሲል መለሰለት፥ “አይሆንም፤ ጌታዬ ሆይ፥ እኔን ስማኝ፤'),
  ('d438b734-174f-5313-ae3e-e5e0737b5ca8', '6fcd8b9b-9d4a-5841-ab61-dd62147f75eb', '7a87dc04-8220-5075-a21d-07aada9356c6', 15, 15, 'የአራት መቶ ምዝምዝ ብር ዋጋ ምድር በእኔና በአንተ መካከል ምንድን ነው? እንግዲህ ሬሳህን በዚያ ቅበር።”'),
  ('23d2f68c-0c1a-5ee6-aad1-74aa77b5a93f', '6fcd8b9b-9d4a-5841-ab61-dd62147f75eb', '7a87dc04-8220-5075-a21d-07aada9356c6', 16, 16, 'አብርሃምም የኤፍሮንን ነገር ሰማ፤ አብርሃምም በኬጢ ልጆች ፊት የነገረውንና ተቀባይነት ያለውን ግብዝ ያይደለ አራት መቶ ምዝምዝ ብር መዝኖ ለኤፍሮን ሰጠው።'),
  ('797a3805-0f0a-5c78-af6e-1b84cb0dacb4', '6fcd8b9b-9d4a-5841-ab61-dd62147f75eb', '7a87dc04-8220-5075-a21d-07aada9356c6', 17, 17, 'በመምሬ ፊት ያለው ባለ ድርብ ክፍል የሆነው የኤፍሮን እርሻም ለአብርሃም ጸና፤ እርሻው፥ በእርሱም ያለ ዋሻው፥ በእርሻውም ውስጥ በዙሪያውም ያለው ዕንጨት ሁሉ፤'),
  ('6720da56-c2d1-5076-ac5f-65a45c46cefc', '6fcd8b9b-9d4a-5841-ab61-dd62147f75eb', '7a87dc04-8220-5075-a21d-07aada9356c6', 18, 18, 'በኬጢ ልጆችና በከተማዪቱ በር በሚገቡ ሁሉ ፊት ለአብርሃም ርስቱ ሆነ።'),
  ('5bb6d2a5-b63c-5cd0-a5af-9ce206614b05', '6fcd8b9b-9d4a-5841-ab61-dd62147f75eb', '7a87dc04-8220-5075-a21d-07aada9356c6', 19, 19, 'ከዚህም በኋላ አብርሃም ኬብሮን በምትባል በመምሬ ፊት በከነዓን ምድር ባለው እርሻ ባለ ድርብ ክፍል በሆነው ዋሻ ውስጥ ሚስቱን ሣራን ቀበረ።'),
  ('782aac88-3d60-5d12-a220-edfffb440fd9', '6fcd8b9b-9d4a-5841-ab61-dd62147f75eb', '7a87dc04-8220-5075-a21d-07aada9356c6', 20, 20, 'እርሻውና በእርሱ ያለው ዋሻም በኬጢ ልጆች ዘንድ ለአብርሃም የመቃብር ርስት ሆኖ ጸና።'),
  ('80109bef-242b-5765-acab-3d5655e73d54', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 1, 1, 'አብርሃምም ሸመገለ፤ ዘመኑም አለፈ፤ እግዚአብሔርም አብርሃምን በሁሉ ባረከው።'),
  ('716aadc9-75d1-5c45-a254-e75d9eec00b3', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 2, 2, 'አብርሃምም ሎሌውን፥ የቤቱን ሽማግሌ፥ የከብቱን ሁሉ አዛዥ አለው፦'),
  ('5e011d42-57c8-53d3-abaf-00275fe530a8', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 3, 3, '“እጅህን በእጄ ላይ አድርግ፤ እኔም አብሬ ከምኖራቸው ከከነዓን ሴቶች ልጆች ለልጄ ለይስሐቅ ሚስት እንዳትወስድለት በሰማይና በምድር አምላክ በእግዚአብሔር አምልሃለሁ፤'),
  ('4e81779b-5541-5fa3-af6a-14b20f209ecd', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 4, 4, 'ነገር ግን ወደ ተወለድሁበት ወደ ሀገሬና ወደ ተወላጆች ሂድ፤ ለልጄ ለይስሐቅም ከዚያ ሚስትን አምጣለት።”'),
  ('72c6f4f2-eaab-50e4-a631-319d228597cc', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 5, 5, 'ሎሌውም፥ “ሴቲቱ ምናልባት ወደዚህ ሀገር ከእኔ ጋር ለመምጣት ባትወድድስ ልጅህን ወደ መጣህበት ሀገር ልመልሰውን?” አለው።'),
  ('57b7c409-fae6-598f-ae9b-2a2fe0d27e38', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 6, 6, 'አብርሃምም አለው፥ “ልጄን ወደዚያ እንዳትመልስ ተጠንቀቅ፤'),
  ('dcfbbc23-46e2-54ff-adfe-3ec3c7b955cd', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 7, 7, 'ከአባቴ ቤት፥ ከተወለድሁባት ምድር ያወጣኝ፦ ‘ይህችንም ምድር ለአንተና ለዘርህ እሰጥሃለሁ’ ብሎ የነገረኝና የማለልኝ የሰማይና የምድር አምላክ እግዚአብሔር፥ እርሱ መልአኩን በፊትህ ይሰድዳል፤ ከዚያም ለልጄ ሚስትን ትወስዳለህ።'),
  ('04ec90a4-c077-5ac6-a7c3-f47bec89015a', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 8, 8, 'ሴቲቱም ከአንተ ጋር ወደዚች ምድር ለመምጣት ባትፈቅድ አንተ ከዚህ መሐላ ንጹሕ ነህ፤ ልጄን ግን ወደዚያ እንዳትመልሰው ተጠንቀቅ።”'),
  ('91cbbe56-3052-5fb8-a71f-6763e80a8af5', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 9, 9, 'ሎሌውም በጌታው በአብርሃም እጅ ላይ እጁን አደረገ፤ ስለዚሁም ነገር ማለለት።'),
  ('6a03b1b6-29a2-51d6-a09e-5d32468b2eb3', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 10, 10, 'ሎሌውም ከጌታው ግመሎች መካከል ዐሥር ግመሎችን ወስዶ፥ ከጌታውም ዕቃ መልካም መልካሙን ይዞ ተነሣ፤ ተነሥቶም ወደ ሦርያ ወንዞች መካከል ወደ ናኮር ከተማ ሄደ።'),
  ('e4cd3694-6729-5d38-aa5f-37bc4867ef25', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 11, 11, 'ሲመሽም ውኃ ቀጂዎች ውኃ ሊቀዱ በሚመጡበት ጊዜ ከከተማዪቱ ውጪ በውኃ ጕድጓድ አጠገብ ግመሎቹን አሳረፈ።'),
  ('1db299be-810f-50c7-a13d-b730fb051835', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 12, 12, 'እንዲህም አለ፥ “የጌታዬ የአብርሃም አምላክ እግዚአብሔር ሆይ፥ እማልድሃለሁ፤ መንገዴን ዛሬ በፊቴ አቅናልኝ፤ ለጌታዬም ለአብርሃም ምሕረትን አድርግ።'),
  ('cfd97267-f44e-525b-a026-c631baddddfb', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 13, 13, 'እነሆ፥ በውኃው ጕድጓድ አጠገብ ቆሜአለሁ፤ የከተማዋ ሰዎች ሴቶች ልጆችም ውኃውን ሊቀዱ ይወጣሉ፤'),
  ('fd71013d-0a5e-5a3f-ae42-4ef3dbee45e5', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 14, 14, 'እንስራሽን አዘንብለሽ ውኃ አጠጭኝ የምላት እርስዋም፦ ‘አንተ ጠጣ፥ ግመሎችህን ደግሞ እስኪረኩ አጠጣለሁ’ የምትለኝ ድንግል፥ እርስዋ ለባሪያህ ለይስሐቅ ያዘጋጀሃት ትሁን፤ በዚህም ለጌታዬ ለአብርሃም ምሕረትን እንዳደረግህ አውቃለሁ።”'),
  ('081971d1-64ed-500e-aa1e-e1dda9a9c207', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 15, 15, 'እንደዚህ በልቡ ያሰበውን መናገሩን ሳይፈጽም እንዲህ ሆነ፦ የአብርሃም ወንድም የናኮር ሚስት የሚልካ ልጅ የባቱኤል ሴት ልጅ ርብቃ እነሆ፥ መጣች፥ እንስራዋንም በጫንቃዋ ተሸክማ ነበር።'),
  ('678d60a3-25e6-55ae-ac7a-d07fab2d3c95', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 16, 16, 'ብላቴናይቱም መልክዋ እጅግ ያማረ፥ ወንድ የማታውቅ ድንግል ነበረች። ወደ ውኃው ጕድጓድም ወረደች፤ ውኃም ቀዳች፤ እንስራዋንም ሞልታ ወጣች።'),
  ('7a2c91f8-c9ef-5d59-a083-c9682dee4109', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 17, 17, 'ያም ሰው ሊገናኛት ሮጠና፥ “ከእንስራሽ ጥቂት ውኃ አጠጪኝ” አላት።'),
  ('6e48eef3-936e-5d9f-ae3e-f6b5d76c78a3', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 18, 18, 'እርስዋም፥ “ጌታዬ ሆይ፥ ጠጣ” አለችው፤ ፈጥናም እንስራዋን ከጫንቃዋ በእጅዋ አውርዳ እስኪረካ አጠጣችው።'),
  ('49bd2207-c279-54e9-ae8c-2c501ff33000', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 19, 19, 'እርሱንም ከአጠጣች በኋላ፦ “ለግመሎችህ ደግሞ ሁሉም እስኪረኩ ድረስ ውኃ እቀዳለሁ” አለችው።'),
  ('0d475aa5-dad6-503f-a593-b7f759c4ee69', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 20, 20, 'ፈጥናም ውኃውን ከእንስራዋ በማጠጫው ውስጥ ገለበጠችው፤ ደግሞም ልትቀዳ ወደ ጕድጓዱ ሮጠች፤ ለግመሎቹም ሁሉ ውኃ ቀዳች።'),
  ('a5b6e18a-4b14-5804-abad-db49442315dc', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 21, 21, 'ሰውየውም ትክ ብሎ ይመለከታት ነበር፤ እግዚአብሔር መንገዱን አቅንቶለት እንደ ሆነ ወይም እንዳልሆነ ለማወቅም ዝም አለ።'),
  ('30e23150-a2e9-560a-abdb-cb13a8257c07', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 22, 22, 'ግመሎቹም ከጠጡ በኋላ እንዲህ ሆነ፤ ሰውዬው አንድ አንድ ወቄት የሚመዝን የወርቅ ጉትቻ፥ ለእጆችዋም ዐሥር ወቄት የሚመዝን ጥንድ የወርቅ አምባር አወጣ፤'),
  ('5a4ccb63-1dcc-532e-aebb-7d69c1e16d9f', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 23, 23, 'ጠርቶም እንዲህ አላት፥ “አንቺ የማን ልጅ ነሽ? በአባትሽ ቤት የምናድርበት ስፍራ እንዳለ እስኪ ንገሪኝ፤”'),
  ('863d59a0-49f4-5f70-a445-ce50221b57ad', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 24, 24, 'አለችውም፥ “እኔ ሚልካ ለናኮር የወለደችለት የባቱኤል ልጅ ነኝ።'),
  ('61641988-d22e-526f-a6ba-26d360130e6b', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 25, 25, 'በእኛ ዘንድ ለግመሎችህ ሣርና ገለባ የሚበቃ ያህል አለ፤ ማደሪያም አለን።”'),
  ('8463c1da-b5b4-53b4-a5fb-b4370169815f', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 26, 26, 'ሰውየውም ደስ አለው፤ ለእግዚአብሔርም ሰገደ።'),
  ('61be2f69-04ad-54cb-a46d-a58eabd5cfa8', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 27, 27, 'እንዲህም አለ፥ “ቸርነቱንና እውነቱን ከጌታዬ ያላራቀ የጌታዬ የአብርሃም አምላክ እግዚአብሔር ይመስገን፤ ለእኔም ወደ ጌታዬ ወደ አብርሃም ወንድም ቤት መንገዴን አቀናልኝ።”'),
  ('c2db4d61-3fa1-5c8e-aecf-5be209a14daa', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 28, 28, 'ብላቴናዪቱም ሮጠች፥ ለእናቷም ቤት ይህን ሁሉ ነገር ተናገረች።'),
  ('3bdb2775-8854-5785-a601-d4e1c6689789', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 29, 29, 'ለርብቃም ስሙ ላባ የተባለ ወንድም ነበራት፤ ላባም ወደ ውጪ ወደ ውኃው ጕድጓድ ወደ ሰውዬው ሮጠ።'),
  ('c9300929-e8eb-5776-ad74-5dba9e93eb69', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 30, 30, 'ጉትቻውንና አምባሮቹን በእኅቱ እጅ ባየ ጊዜ፥ የእኅቱንም የርብቃን ነገር፦ ያ ሰው እንዲህ አለኝ ያለችውን በሰማ ጊዜ፥ እርሱ ወደዚያ ሰው መጣ፤ እነሆም በውኃው ጕድጓድ አጠገብ ከግመሎቹ ዘንድ ቆሞ ነበር።'),
  ('48fd82f5-bffe-5164-aeb9-738c97ec259f', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 31, 31, 'እርሱም አለው፥ “አንተ የእግዚአብሔር ቡሩክ፥ ግባ ስለምን አንተ በውጪ ቆመሃል? እኛም ቤትን፥ ለግመሎችህም ማደሪያን አዘጋጅተናል።”'),
  ('27130dfa-b872-57df-a87d-b1271321c940', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 32, 32, 'ሰውዬውም ወደ ቤት ገባ፤ ግመሎቹንም አራገፈ፤ ለግመሎቹም ሣርና ገለባ አቀረቡላቸው፤ እግሩን ይታጠብ ዘንድ ውኃ አመጡለት፤ ከእርሱ ጋር ላሉ ሰዎችም አመጡላቸው።'),
  ('85d5011b-7c17-5775-a18d-8ddcf4224d2e', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 33, 33, 'ይበላም ዘንድ እንጀራን አቀረቡለት፤ እርሱ ግን “ነገሬን እስክናገር ደረስ አልበላም” አለ። እነርሱም “ተናገር” አሉት።'),
  ('a29b46bc-b2c5-5a70-aca2-b7eb227e0e03', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 34, 34, 'እርሱም አለ፥ “እኔ የአብርሃም ሎሌ ነኝ።'),
  ('158b9cad-03df-5e34-ac54-34b099341ec9', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 35, 35, 'እግዚአብሔርም ጌታዬን እጅግ ባረከው፤ አገነነውም፤ ላሞችንና በጎችን፥ ወርቅንና ብርን፥ ወንዶች ባሪያዎችንና ሴቶች ባሪያዎችን፥ ግመሎችንና አህዮችንም ሰጠው።'),
  ('b8795883-f0e4-5cc5-a02c-657636915127', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 36, 36, 'የጌታዬ የአብርሃም ሚስት ሣራም በእርጅናዋ ለጌታዬ ወንድ ልጅን ወለደች፤ የነበረውንም ሁሉ ሰጠው።”'),
  ('34cf7cd5-5b0c-5d46-a653-b6af8d549db4', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 37, 37, 'ጌታዬ እንዲህ ሲል አማለኝ፥ “እኔ ካለሁበት ሀገር ከከነዓናውያን ሴቶች ልጆች ለልጄ ሚስትን አትውሰድ፤'),
  ('cf31ef57-3145-506b-a1bf-dcf5b72b3de4', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 38, 38, 'ነገር ግን ወደ አባቴ ቤት ወደ ወገኔም ሂድ፤ ለልጄም ከዚያ ሚስትን ውሰድለት።'),
  ('7c0b2d57-0db3-58ab-a05f-1842bb86e1f1', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 39, 39, 'ጌታዬንም ሴቲቱ ምናልባት ከእኔ ጋር መምጣትን ባትፈቅድስ አልሁት።'),
  ('fae4283e-66fe-55f6-ad8e-276199c827d7', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 40, 40, 'እርሱም አለኝ፦ አካሄዴን በፊቱ ያደረግሁለት እግዚአብሔር መልአኩን ከአንተ ጋር ይልካል። መንገድህንም ያቀናል፤ ለልጄም ከወገኖች ከአባቴም ቤት ሚስትን ትወስዳለህ፤'),
  ('ec6399ef-7636-534b-ad78-211fe206d1b9', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 41, 41, 'የዚያን ጊዜ ከመሐላዬ ንጹሕ ትሆናለህ፤ ወደ ዘመዶች ሄደህ እነርሱ ባይሰጡህ ካማልሁህ መሐላ ንጹሕ ትሆናለህ።”'),
  ('5339b458-a825-5d5d-ad4d-64e6fcae09e3', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 42, 42, 'ዛሬም ወደ ውኃው ጕድጓድ መጣሁ፤ እንዲህም አልሁ፥ “የጌታዬ የአብርሃም አምላክ እግዚአብሔር ሆይ፥ ዛሬ የምሄድበትን መንገዴን ብታቀናልኝ፥'),
  ('608bc0f4-97d9-5ac0-a0a8-645c7490702d', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 43, 43, 'እነሆ፥ እኔ በውኃው ጕድጓድ አጠገብ ቆሜአለሁ፤ የከተማዋ ሰዎች ሴቶች ልጆችም ውኃን ሊቀዱ ይወጣሉ፤ ጥቂት ውኃ ከእንስራሽ አጠጪኝ ስላት፥'),
  ('063432b2-3884-5a1d-ac91-f3e6716d8dc3', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 44, 44, 'እርስዋም ፦ ‘አንተ ጠጣ፤ ደግሞም ለግመሎችህ እቀዳለሁ’ የምትለኝ ድንግል፥ እግዚአብሔር ለጌታዬ ልጅ ለባሪያዉ ለይስሐቅ ያዘጋጃት ሚስት እርስዋ ትሁን። በዚህም ለጌታዬ ምሕረትን እንዳደረግህ አውቃለሁ።”'),
  ('362a86fb-64b1-580c-ab32-2c9509dc7244', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 45, 45, 'እኔም በልቤ ያሰብሁትን ሳልፈጽም እንዲህ ሆነ፤ ያን ጊዜ ርብቃ እንስራዋን በትከሻዋ ተሸክማ ወጣች፥ ወደ ምንጭም ወርዳ ውኃ ቀዳች፤ እኔም “እስቲ ውኃ አጠጪኝ” አልኋት።'),
  ('d109056b-f7bf-537d-a902-8353c259a691', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 46, 46, 'ፈጥናም እንስራዋን ከትከሻዋ አወረደችና፥ “አንተ ጠጣ፤ ግመሎችህን ደግሞ አጠጣለሁ” አለችኝ፤ እኔም ጠጣሁ፤ ግመሎችንም ደግሞ አጠጣች።'),
  ('46574cae-85f9-59f2-a4a0-00f84a0f701a', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 47, 47, 'እኔም “አንቺ የማን ልጅ ነሽ? ንገሪኝ” ብዬ ጠየቅኋት። እርስዋም፥ “ሚልካ የወለደችለት የናኮር ልጅ የባቱኤል ልጅ ነኝ” አለችኝ፤'),
  ('466ac8ee-2c52-50fb-ae65-b966d3abee58', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 48, 48, 'ይህንም ነገር ከአንደበቷ በሰማሁ ጊዜ እጅግ ደስ አሰኘችኝ። ለጆሮዎችዋም ጉትቻዎችን ለእጆችዋም አምባሮችን አድርጌ አስጌጥኋት። ደስ ባሰኘችኝም ጊዜ፥ ለእግዚአብሔር ሰገድሁ፤ የጌታዬን የወንድሙን ልጅ ለልጁ እወስድ ዘንድ በቀና መንገድ የመራኝን የጌታዬን የአብርሃምን አምላክ እግዚአብሔርን አመሰገንሁ።'),
  ('24cee8b9-ecf4-5cf6-a2a3-388d01ca5609', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 49, 49, 'አሁንም ቸርነትንና እውነትን ለጌታዬ ትሠሩ እንደ ሆነ ንገሩኝ፤ ይህም ባይሆን ንገሩኝ፤ ወደ ቀኝ ወይም ወደ ግራ እመለስ ዘንድ።'),
  ('37a34d33-ae65-58fa-ac97-5327195a1944', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 50, 50, 'ባቱኤልና ላባም መለሱ፤ እንዲህም አሉ፥ “ነገሩ ከእግዚአብሔር ዘንድ መጥቶአል፤ ክፉ ወይም በጎ ልንመልስልህ አንችልም።'),
  ('604449fd-f60e-582b-adc0-9ec78b35530e', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 51, 51, 'ርብቃ እንኋት፤ በፊትህ ናት፤ ይዘሃት ሂድ፥ እግዚአብሔር እንደ ተናገረ ለጌታህ ልጅ ሚስት ትሁን።”'),
  ('4c30f2f8-e186-5cc1-a1e9-845731a5f1f5', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 52, 52, 'የአብርሃምም ሎሌ ነገራቸውን በሰማ ጊዜ ወደ ምድር ወድቆ ለእግዚአብሔር ሰገደ።'),
  ('c507bfba-89bf-5a96-a4b1-657c7cceaac2', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 53, 53, 'ሎሌውም የብርና የወርቅ ጌጥ፥ ልብስም አወጣ፤ ለርብቃም ሰጣት፤ ዳግመኛም ለአባቷና ለእናቷ እጅ መንሻ ሰጣቸው።'),
  ('beda2d15-5c9c-58c3-ace2-d3189de14938', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 54, 54, 'ከዚህም ሁሉ በኋላ እርሱ፥ ከእርሱ ጋር ያሉትም በሉ፤ ጠጡም፤ በዚያም አደሩ፤ በማለዳም ተነሥቶ፥ “ወደ ጌታዬ እሄድ ዘንድ አሰናብቱኝ” አላቸው።'),
  ('77c4644e-8ecf-5b11-aa72-2cc5f8dcd188', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 55, 55, 'አባቷ እናቷና ወንድምዋ፦ “ብላቴናዪቱ ዐሥር ቀን ያህል እንኳ በእኛ ዘንድ ትቀመጥ፤ ከዚያም በኋላ ትሄዳለች” አሉ።'),
  ('1ad4e468-b3db-50e3-acac-fbac8ac65359', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 56, 56, 'እርሱም፥ “እግዚአብሔር መንገዴን አቅንቶልኝ ሳለ አታዘግዩኝ፤ ወደ ጌታዬ እሄድ ዘንድ አሰናብቱኝ” አላቸው።'),
  ('9673220e-1073-5758-a3c7-d3ffd008f530', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 57, 57, 'እነርሱም፥ “ብላቴናዪቱን እንጥራና ከአፍዋ እንጠይቅ” አሉ።'),
  ('7b5a7f83-a1b2-56a8-a1aa-a6dc7f787d3c', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 58, 58, 'ርብቃንም ጠርተው፥ “ከዚህ ሰው ጋር ትሄጃለሽን?” አሉአት። እርስዋም፥ “አዎን እሄዳለሁ” አለች።'),
  ('b17df33a-4e2a-502f-a5f7-c4e291f65a62', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 59, 59, 'እኅታቸውንም ርብቃን ሞግዚቷንም ከገንዘብ ጋር፥ የአብርሃምን ሎሌና ሰዎቹንም አሰናበቱአቸው።'),
  ('11402bdd-70fb-582a-a702-12a62d583399', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 60, 60, 'እኅታቸው ርብቃንም መረቁአትና፥ “አንቺ እኅታችን፥ እልፍ አእላፋት ሁኚ፤ ዘርሽም የጠላት ሀገሮችን ይውረስ” አሉአት።'),
  ('54402e73-c4b1-5839-a562-bd3c7321495e', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 61, 61, 'ርብቃም ተነሣች፤ ደንገጥሮችዋም፥ በግመሎችዋ ላይ ተቀምጠው ከሰውዬው ጋር አብረው ሄዱ፤ ሎሌውም ርብቃን ተቀብሎ ሄደ።'),
  ('87676c9f-da1d-5e67-add9-eba3f4ffba1d', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 62, 62, 'ይስሐቅም በዐዘቅተ ራእይ በኩል ወደ ምድረ በዳ ይመለከት ነበር፤ በአዜብ በኩል ባለው ምድር ተቀምጦ ነበርና።'),
  ('1e47a003-f54e-5dd4-abea-b0e1cd2baa19', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 63, 63, 'ይስሐቅም በመሸ ጊዜ በልቡ እያሰላሰለ ወደ ሜዳ ወጥቶ ነበር፤ ዓይኖቹንም አቀና፤ እነሆም ግመሎች ሲመጡ አየ።'),
  ('2a14fa74-b1f0-5c3c-afa2-b08da2918e03', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 64, 64, 'ርብቃም ዓይኖችዋን አቀናች፤ ይስሐቅንም አየች፤ ከግመልም ወረደች።'),
  ('ceca3df0-7b5d-5599-afc5-1fe2f03c5a0b', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 65, 65, 'ሎሌውንም፥ “ሊቀበለን በሜዳ የሚመጣ ይህ ሰው ማነው?” አለችው። ሎሌውም፥ “እርሱ ጌታዬ ነው” አላት፤ እርስዋም ቀጸላዋን ወስዳ ተከናነበች።'),
  ('eb8d35c2-57b2-5a92-a530-b2942c13f902', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 66, 66, 'ሎሌውም ያደረገውን ነገር ሁሉ ለይስሐቅ ነገረው።'),
  ('41796b5c-2be9-55a4-aaf1-60dd79c39397', '626ff7e6-4384-565d-ade0-2f74c066e9db', '528954be-0797-5cc5-a952-8abfc9779a3b', 67, 67, 'ይስሐቅም ወደ እናቱ ቤት ገባ፤ ርብቃንም ወሰዳት፤ ሚስትም ሆነችው፤ ወደዳት፤ ይስሐቅም ስለ እናቱ ስለ ሣራ ተጽናና።'),
  ('0f6c4ad5-07cf-5d32-a4e3-2c007bffe899', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', 'edd148a2-1d82-5d5f-ac47-1da1c989de81', 1, 1, 'አብርሃምም ደግሞ ስምዋ ኬጡራ የተባለች ሚስት አገባ።'),
  ('e28705ad-aa99-5703-a995-983ebdd17085', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', 'edd148a2-1d82-5d5f-ac47-1da1c989de81', 2, 2, 'እርስዋም ዘንበሪን፥ ዮቃጤንን፥ ሜዳንን፥ ዮብቅን፥ ምድያምንና ሴሂን ወለደችለት።'),
  ('4659363b-c8f3-5d00-a26e-2c14e75de8ff', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', 'edd148a2-1d82-5d5f-ac47-1da1c989de81', 3, 3, 'ዮቃጤንም ሶቤቅን፥ ቲማንንና ድዳንን ወለደ። የድዳንም ልጆች ራጉኤል፥ ንበከዝ፥ እስራኦምና ሎአም ናቸው።'),
  ('8b6958c4-e2e6-5176-a3c4-354df37b8b12', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', 'edd148a2-1d82-5d5f-ac47-1da1c989de81', 4, 4, 'የምድያምም ልጆች ጌፌር፥ ዔፋር፥ ሄኖኅ፥ አቢሮንና ቲያሮስ ናቸው። እነዚህም ሁሉ የኬጡራ ልጆች ናቸው።'),
  ('ed60e614-0e4d-5d56-ae4d-396780714062', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', 'edd148a2-1d82-5d5f-ac47-1da1c989de81', 5, 5, 'አብርሃምም በሕይወቱ ሳለ ገንዘቡን ሁሉ ለልጁ ለይስሐቅ ሰጠው፤'),
  ('e8659045-52e8-5e52-a7ca-3eb5b9c41d0d', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', 'edd148a2-1d82-5d5f-ac47-1da1c989de81', 6, 6, 'አብርሃምም ለቁባቶቹ ልጆች ሀብትን ሰጣቸው፤ እርሱም ገና በሕይወቱ ሳለ ከልጁ ከይስሐቅ ለይቶ ወደ ምሥራቅ ሀገር ሰደዳቸው።'),
  ('33490d9e-ecf3-5e6d-a663-7556184b8026', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', '3ea3d985-96ca-5c02-ae89-25dc20071fc9', 1, 7, 'አብርሃምም የኖረበት የዕድሜው ዓመታት እነዚህ ናቸው፤ መቶ ሰባ አምስት ዓመት ኖረ።'),
  ('3a55737d-2f28-5e1f-af0f-8c19e32465f4', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', '3ea3d985-96ca-5c02-ae89-25dc20071fc9', 2, 8, 'አብርሃምም መልካም ሽምግልናን ሸምግሎ፥ ዘመኑንም ፈጽሞ ሞተ፤ ወደ ወገኖቹም ተጨመረ።'),
  ('d42786fa-0f6b-569d-aa6b-e0d393c67a7b', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', '3ea3d985-96ca-5c02-ae89-25dc20071fc9', 3, 9, 'ልጆቹ ይስሐቅና ይስማኤልም በመምሬ ፊት ለፊት ባለው በኬጢያዊው በሰዓር ልጅ በኤፍሮን እርሻ ላይ ባለ ድርብ ክፍል በሆነው ዋሻ ውስጥ ቀበሩት።'),
  ('7839c263-d2e4-57ac-a4b3-2229de6e0581', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', '3ea3d985-96ca-5c02-ae89-25dc20071fc9', 4, 10, 'ይህም አብርሃም ከኬጢ ልጆች የገዛው እርሻ ነው፤ አብርሃምንና ሚስቱን ሣራን በዚያ ቀበሩአቸው።'),
  ('1a1c5567-048f-5176-a1a2-c7958bfcbb61', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', '3ea3d985-96ca-5c02-ae89-25dc20071fc9', 5, 11, 'እንዲህም ሆነ፥ አብርሃምም ከሞተ በኋላ እግዚአብሔር ልጁን ይስሐቅን ባረከው፤ ይስሐቅም ዐዘቅተ ራእይ ተብሎ በሚጠራው ምንጭ አጠገብ ኖረ።'),
  ('65c3b82d-8265-5028-a8c6-fb5208183fa1', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', '3989ee95-8ba6-50b5-abb4-fa21243a47ec', 1, 12, 'የሣራ ባሪያ ግብፃዊቱ አጋር ለአብርሃም የወለደችለት የአብርሃም ልጅ የይስማኤል ትውልድ ይህ ነው፤'),
  ('0a3b7049-a5ac-5512-a998-ca09c417c7f0', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', '3989ee95-8ba6-50b5-abb4-fa21243a47ec', 2, 13, 'የይስማኤልም የልጆቹ ስም በየስማቸውና በየትውልዳቸው እንዲህ ነው።'),
  ('576679a5-5476-56c8-aacf-f3d043b96f16', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', '3989ee95-8ba6-50b5-abb4-fa21243a47ec', 3, 14, 'የይስማኤል የበኵር ልጁ ናቡአት፥ ቄዳር፥ ነብዳኤል፥ መብሳን፥'),
  ('664d0128-0524-544a-acb5-4ccd688c14fb', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', '3989ee95-8ba6-50b5-abb4-fa21243a47ec', 4, 15, 'ማሴሜ፥ ዱማ፥ ማሤን፥ ኩዳን፥ ቴማን፥ ኤያጤር፥ ናፌስ፥ ቄድን።'),
  ('20c1dbb2-516f-5b1b-a73f-40e09ee52763', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', '3989ee95-8ba6-50b5-abb4-fa21243a47ec', 5, 16, 'የይስማኤል ልጆች እነዚህ ናቸው፤ ስማቸውም በየመንደራቸውና በየሰፈራቸው ይህ ነው፤ በየወገናቸውም ዐሥራ ሁለት አለቆች ናቸው።'),
  ('0e87f4ce-377e-5c45-ab1e-9e48586aad14', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', '3989ee95-8ba6-50b5-abb4-fa21243a47ec', 6, 17, 'እርሱም ከኤውላጥ አንሥቶ በግብፅ ፊት ለፊት እስከምትገኝ እስከ ሴይር ባለው ሀገር ኖረ፤ ወደ አሦርዮንም ደረሰ፤ እንዲህም ከወንድሞቹ ሁሉ ፊት ተቀመጠ።'),
  ('747e590e-bd57-5bf4-a7e7-5a321d9c1f5a', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', '3989ee95-8ba6-50b5-abb4-fa21243a47ec', 7, 18, 'ይስማኤልም የኖረበት የዕድሜው ዘመን መቶ ሠላሳ ሰባት ዓመት ነው ፤ ሸምግሎ ሞተ፤ ወደ ወገኖቹም ተጨመረ።'),
  ('efe4ce15-df2a-5fa5-af9d-be6c194f7d9c', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', '03c29a3d-e02a-5c89-a47f-4a962df088ea', 1, 19, 'የአብርሃም ልጅ የይስሐቅ ትውልድም ይህ ነው፤ አብርሃም ይስሐቅን ወለደ፥'),
  ('5da030c4-83c0-5258-a8d9-0f3c171f2520', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', '03c29a3d-e02a-5c89-a47f-4a962df088ea', 2, 20, 'ይስሐቅም ሚስት ትሆነው ዘንድ የሶርያዊውን የላባን እኅት፥ የሶርያዊውን የባቱኤልን ልጅ ርብቃን ከሁለቱ ከሶርያ ወንዞች መካከል በወሰዳት ጊዜ አርባ ዓመት ሆኖት ነበር።'),
  ('f16108f8-0aa3-5911-a2ae-ae0d0346e8b6', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', '03c29a3d-e02a-5c89-a47f-4a962df088ea', 3, 21, 'ይስሐቅም ስለ ሚስቱ ርብቃ ወደ እግዚአብሔር ለመነ፤ መካን ነበረችና፤ እግዚአብሔርም ሰማው፤ ሚስቱ ርብቃም ፀነሰች።'),
  ('47c3ccb3-512b-5fd9-a890-75a208cd90d2', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', '03c29a3d-e02a-5c89-a47f-4a962df088ea', 4, 22, 'ልጆችዋም በሆድዋ ውስጥ ይንቀሳቀሱ ነበር ፤ እርስዋም፥ “እንዲህ እሆን ዘንድ ካለኝ ይህ ለእኔ ምኔ ነው?” አለች። ወደ እግዚአብሔርም ትለምን ዘንድ ሄደች።'),
  ('0ca72af0-6103-5eb3-ac3d-a4d124c071ca', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', '03c29a3d-e02a-5c89-a47f-4a962df088ea', 5, 23, 'እግዚአብሔርም አላት፥ “ሁለት ሕዝቦች በማኅፀንሽ አሉ፤ ሁለቱም ሕዝብ ከሆድሽ ይወለዳሉ፤ ሕዝብም ከሕዝብ ይበረታል፤ ታላቁም ለታናሹ ይገዛል።”'),
  ('a47fbac6-5b83-5452-a952-c1973d50a5eb', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', '03c29a3d-e02a-5c89-a47f-4a962df088ea', 6, 24, 'የምትወልድበትም ወራት ተፈጸመ፤ በማኅፀንዋም መንታ ነበሩ።'),
  ('78e91fd6-ab20-566a-a75f-c6149ca7bab5', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', '03c29a3d-e02a-5c89-a47f-4a962df088ea', 7, 25, 'የበኵር ልጅዋም ወጣ፤ እንደ ጽጌረዳም ቀይ ነበረ፤ ሁለንተናውም ጠጕራም ነበር፤ ስሙንም ዔሳው ብላ ጠራችው።'),
  ('1980d31f-193f-58e8-ae69-fe7b6503a549', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', '03c29a3d-e02a-5c89-a47f-4a962df088ea', 8, 26, 'ከዚያም በኋላ ወንድሙ ወጣ፤ በእጁም የዔሳውን ተረከዝ ይዞ ነበር፤ ስሙንም ያዕቆብ ብላ ጠራችው። ርብቃ ዔሳውንና ያዕቆብን በወለደቻቸው ጊዜ ይስሐቅ ስድሳ ዓመት ሆኖት ነበር።'),
  ('27ecc320-5040-5780-a630-3893544d61a0', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', 'f3b7ee67-9afd-5884-af00-a3373b6b787a', 1, 27, 'ብላቴኖቹም አደጉ፤ ጐለመሱም፤ ዔሳውም አደን የሚያውቅ የበረሃ ሰው ሆነ፤ ያዕቆብ ግን ጭምት ሰው ነበረ፤ በቤትም ይቀመጥ ነበር።'),
  ('ebcd0653-e0a9-559a-aca6-8eda183e30e1', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', 'f3b7ee67-9afd-5884-af00-a3373b6b787a', 2, 28, 'ይስሐቅም ዔሳውን ይወድ ነበር፤ እርሱ ከአደነው ይበላ ነበርና። ርብቃ ግን ያዕቆብን ትወድ ነበረች።'),
  ('323005d8-ce3e-5ec9-a154-6917bf932e9f', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', 'f3b7ee67-9afd-5884-af00-a3373b6b787a', 3, 29, 'ለያዕቆብም የምስር ንፍሮ ቀቀለችለት፤ ዔሳውም ደክሞ ከበረሃ ገባ፤'),
  ('429e9900-eb6b-5f2d-a2fa-587a8c24237a', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', 'f3b7ee67-9afd-5884-af00-a3373b6b787a', 4, 30, 'ዔሳውም ያዕቆብን፥ “ከምስር ንፍሮህ አብላኝ፤ እኔ እጅግ ደክሜአለሁና” አለው፤ ስለዚህም ስሙ ኤዶም ተባለ።'),
  ('3f3efd6e-2b28-52d9-a9a2-3356b50b03e6', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', 'f3b7ee67-9afd-5884-af00-a3373b6b787a', 5, 31, 'ያዕቆብም ዔሳውን፥ “ዛሬ ብኵርናህን ስጠኝ” አለው።'),
  ('3e581943-32ce-50b5-a258-e502dd417200', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', 'f3b7ee67-9afd-5884-af00-a3373b6b787a', 6, 32, 'ዔሳውም፥ “እነሆ፥ እኔ ልሞት ነኝ፤ ይህች ብኵርና ለምኔ ናት?” አለ።'),
  ('d908d604-49a5-51b5-a6f8-1ef4a61b8c1d', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', 'f3b7ee67-9afd-5884-af00-a3373b6b787a', 7, 33, 'ያዕቆብም፥ “ብኵርናህን ትሰጠኝ ዘንድ እስኪ ዛሬ ማልልኝ” አለው። ዔሳውም ማለለት፤ ብኵርናውንም ለያዕቆብ ሸጠ።'),
  ('65bde1ab-25c8-54b5-a125-a42dd123d9f3', 'b723d577-ed7a-52b0-a7b2-52b9fdef15a2', 'f3b7ee67-9afd-5884-af00-a3373b6b787a', 8, 34, 'ያዕቆብም ለዔሳው እንጀራና የምስር ንፍሮ ሰጠው፤ በላ፥ ጠጣ፥ ተነሥቶም ሄደ፤ ዔሳውም ብኵርናውን አቃለላት።'),
  ('8f70c090-5082-5e5f-a553-c98a43e6405c', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'f66fdf51-df78-565e-a899-ca90565587f8', 1, 1, 'በምድርም ቀድሞ በአብርሃም ዘመን ከሆነው ራብ ሌላ ራብ ሆነ፤ ይስሐቅም ወደ ፍልስጥኤም ንጉሥ ወደ አቤሜሌክ ወደ ጌራራ ሄደ።'),
  ('19d97610-7521-5f0a-a877-01d4aad4603c', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'f66fdf51-df78-565e-a899-ca90565587f8', 2, 2, 'እግዚአብሔርም ተገለጠለት፤ እንዲህም አለው፥ “ወደ ግብፅ አትውረድ፤ እኔ በምልህ ምድር ተቀመጥ።'),
  ('6512c7ea-168b-5a2d-a1fb-1cf640335ff7', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'f66fdf51-df78-565e-a899-ca90565587f8', 3, 3, 'በዚህች ምድር ተቀመጥ፤ ከአንተ ጋርም እሆናለሁ፤ እባርክሃለሁም፤ ይህችን ምድር ሁሉ ለአንተም፥ ለዘርህም እሰጣለሁና፥ ለአባትህም ለአብርሃም የማልሁለትን መሐላ ከአንተ ጋር አጸናለሁ።'),
  ('19365ef8-086a-56f8-aa0f-4bd328e8bf49', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'f66fdf51-df78-565e-a899-ca90565587f8', 4, 4, 'ዘርህንም እንደ ሰማይ ከዋክብት አበዛዋለሁ፤ ይህችንም ምድር ሁሉ ለዘርህ እሰጣለሁ፤ የምድርም ሕዝቦች ሁሉ በዘርህ ይባረካሉ፤'),
  ('b40dd8c0-7de2-5ae9-aad4-42ec218d628c', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'f66fdf51-df78-565e-a899-ca90565587f8', 5, 5, 'አባትህ አብርሃም ቃሌን ሰምቶአልና፤ ትእዛዜንና ፍርዴን፥ ሥርዐቴንና ሕጌንም ጠብቆአልና።”'),
  ('874cba79-5386-5573-a5e2-c64e90bfe680', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'f66fdf51-df78-565e-a899-ca90565587f8', 6, 6, 'ይስሐቅም በጌራራ ተቀመጠ። የዚያም ስፍራ ሰዎች ስለ ሚስቱ ስለ ርብቃ ጠየቁት፤ እርሱም፥ “እኅቴ ናት” አላቸው፤'),
  ('ebc389b0-0705-5678-a9e0-fcca4808ec77', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'f66fdf51-df78-565e-a899-ca90565587f8', 7, 7, 'የዚህ ስፍራ ሰዎች ለርብቃ ሲሉ እንዳይገድሉኝ ብሎ ሚስቴ ናት ማለትን ፈርቶአልና፤ እርስዋም ውብ ነበረችና።'),
  ('998bb292-3363-57ce-a4ae-6969ca0bef41', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'f66fdf51-df78-565e-a899-ca90565587f8', 8, 8, 'በዚያም ብዙ ቀን ተቀመጠ። የፍልስጥኤም ንጉሥ አቤሜሌክም በመስኮት ሆኖ በተመለከተ ጊዜ ይስሐቅን ከሚስቱ ከርብቃ ጋር ሲጫወት አየው።'),
  ('ec12afd7-7747-59d7-adae-9ad5c4d449d1', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'f66fdf51-df78-565e-a899-ca90565587f8', 9, 9, 'አቤሜሌክም ይስሐቅን ጠራ፤ እንዲህም አለው፥ “እነሆ፥ ሚስትህ ናት፤ እንዴትስ እርስዋን፦ ‘እኅቴ ናት’ አልህ?” ይስሐቅም፥ “በእርስዋ ምክንያት እንዳልሞት ብዬ ነው” አለው።'),
  ('c51161d1-7ed3-5c50-aa51-445bd3b712f6', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'f66fdf51-df78-565e-a899-ca90565587f8', 10, 10, 'አቤሜሌክም አለ፥ “ይህ ያደረግህብን ምንድን ነው? ከሕዝቡ አንዱ ባለማወቅ ከሚስትህ ጋር ሊተኛ ጥቂት በቀረው ነበር፤ ኀጢአትንም ልታመጣብን ነበር።”'),
  ('678b32ae-c2c2-5fb0-af44-8044c4b2d39f', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'f66fdf51-df78-565e-a899-ca90565587f8', 11, 11, 'አቤሜሌክም ሕዝቡን ሁሉ፥ “ይህን ሰው፥ ሚስቱንም የሚነካ ፍርዱ ክፉ ሞት ነው” ብሎ አዘዘ።'),
  ('6b2ec3b5-cbc4-525f-a130-a298970dc838', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'f66fdf51-df78-565e-a899-ca90565587f8', 12, 12, 'ይስሐቅም በዚያች ምድር ዘርን ዘራ፤ በዚያች ዓመትም መቶ እጥፍ ገብስ አገኘ፤ እግዚአብሔርም ባረከው።'),
  ('a4f5d26b-7f22-5943-a31e-e0b6b366f43e', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'f66fdf51-df78-565e-a899-ca90565587f8', 13, 13, 'ከፍ ከፍም አለ፤ እጅግም ታላቅ እስኪሆን ድረስ እየጨመረ ይበዛ ነበር፤'),
  ('72dd6e8f-dbdc-54e4-a601-669a0af87b4d', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'f66fdf51-df78-565e-a899-ca90565587f8', 14, 14, 'ወንዶችና ሴቶች አገልጋዮችን፥ ብዙ በጎችንና ላሞችን፥ የእርሻ መሬትንም ገዛ፤ የፍልስጥኤም ሰዎችም ቀኑበት።'),
  ('b445ba02-3fb6-527a-a486-0eb84b1255b8', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'f66fdf51-df78-565e-a899-ca90565587f8', 15, 15, 'በአባቱ በአብርሃም ዘመን የአባቱ ሎሌዎች የማሱአቸውን ጕድጓዶች ሁሉ የፍልስጥኤም ሰዎች ደፈኑአቸው፤ አፈርንም ሞሉባቸው።'),
  ('db19d0c8-272f-538c-ac05-3fd0f64054cb', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'f66fdf51-df78-565e-a899-ca90565587f8', 16, 16, 'አቤሜሌክም ይስሐቅን፥ “ከእኛ ተለይተህ ሂድ፤ ከእኛ ይልቅ እጅግ በርትተሃልና” አለው።'),
  ('b732a2e7-cf32-5462-ac98-669d8df54347', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'f66fdf51-df78-565e-a899-ca90565587f8', 17, 17, 'ይስሐቅም ከዚያ ሄደ፤ በጌራራም ሸለቆ ሰፈረ፤ በዚያም ተቀመጠ።'),
  ('a4384a6e-6fb9-54a1-acb3-84dcaa1f108b', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'f66fdf51-df78-565e-a899-ca90565587f8', 18, 18, 'ይስሐቅም የአባቱ የአብርሃም አገልጋዮች ቈፍረዋቸው የነበሩትን የውኃ ጕድጓዶች ደግሞ አስቈፈረ፤ አባቱ አብርሃም ከሞተ በኋላ የፍልስጥኤም ሰዎች ደፍነዋቸው ነበርና፤ አባቱም አብርሃም ይጠራቸው በነበረው ስም ጠራቸው።'),
  ('6097aef1-2f5d-5b7e-a8ef-2c8aa4882511', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'f66fdf51-df78-565e-a899-ca90565587f8', 19, 19, 'የይስሐቅ ሎሌዎችም በጌራራ ሸለቆ ውስጥ ጕድጓድ ቈፈሩ፤ በዚያም ጣፋጭ የውኃ ምንጭ አገኙ።'),
  ('d548c95d-4a5b-53ff-a41d-f6f3af08e24e', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'f66fdf51-df78-565e-a899-ca90565587f8', 20, 20, 'የጌራራ እረኞች ከይስሐቅ እረኞች ጋር፥ “ውኃው የእኛ ነው” ሲሉ ተጣሉ፤ የዚያችንም ጕድጓድ ስም “ዐዘቅተ ዐመፃ” ብሎ ጠራት፤ እነርሱ በድለውታልና።'),
  ('97a6e369-9bde-5192-a1be-b9e0534a5dd5', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'f66fdf51-df78-565e-a899-ca90565587f8', 21, 21, 'ይስሐቅም ከዚያ ሄደ በዚያም ሌላ ጕድጓድ ማሰ፥ ስለ እርስዋም ደግሞ ተጣሉት፤ ስምዋንም “ጽልእ” ብሎ ጠራት።'),
  ('a04679b5-0de9-5306-aba7-f8cde613946f', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'f66fdf51-df78-565e-a899-ca90565587f8', 22, 22, 'ከዚያም እልፍ ብሎ ሌላ ጕድጓድ ቈፈረ፤ ስለ እርስዋም አልተጣሉትም፤ ስምዋንም “መርኅብ” ብሎ ጠራት፤ እንዲህ ሲል፥ “አሁን እግዚአብሔር አሰፋልን፤ በምድርም አበዛን።”'),
  ('55e8fa98-5932-5b1a-a65f-ec1283f93e07', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'f66fdf51-df78-565e-a899-ca90565587f8', 23, 23, 'ከዚያም ወደ ዐዘቅተ መሐላ ሄደ።'),
  ('7564a8ec-eb1b-5275-a97d-d74f829e3315', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'f66fdf51-df78-565e-a899-ca90565587f8', 24, 24, 'በዚያችም ሌሊት እግዚአብሔር ተገለጠለት፤ እንዲህም አለው፥ “እኔ የአባትህ የአብርሃም አምላክ ነኝ፤ አትፍራ፤ እኔ ከአንተ ጋር ነኝና፤ እባርክሃለሁ፤ ስለ አባትህ ስለ አብርሃም ዘርህን አበዛዋለሁ።”'),
  ('354d48a9-7e1c-5d66-a834-1cb41dba4ffe', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'f66fdf51-df78-565e-a899-ca90565587f8', 25, 25, 'በዚያም ለአምላኩ ለእግዚአብሔር መሠውያን ሠራ፤ የእግዚአብሔርንም ስም ጠራ፤ በዚያም ድንኳን ተከለ፤ የይስሐቅም ሎሌዎች በዚያ ጕድጓድ ማሱ።'),
  ('44e15451-e47c-558a-abbe-98b9fd04d268', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'fff4593d-d1d6-508c-ac73-9af443cceb05', 1, 26, 'አቤሜሌክና ሚዜው አኮዘት፥ የሠራዊቱም አለቃ ፋኮል ከጌራራ ወደ እርሱ ሄዱ።'),
  ('88e7bbfa-bf6d-5565-a9e5-d41c565588b1', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'fff4593d-d1d6-508c-ac73-9af443cceb05', 2, 27, 'ይስሐቅም፥ “ለምን ወደ እኔ መጣችሁ? እናንተ ጠልታችሁኛል፤ ከእናንተም ለይታችሁ አሳድዳችሁኛልና” አላቸው።'),
  ('48cb8544-41e2-5b20-a237-b7065d592d01', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'fff4593d-d1d6-508c-ac73-9af443cceb05', 3, 28, 'እነርሱም አሉት፥ “እኛ የጠላንህ አይደለም፤ በመልካም አኑረን፥ በመልካም አሰናበትንህ እንጂ፥ አሁንም አንተ ለአምላክህ ለእግዚአብሔር ቡሩክ ነህ።'),
  ('7eb7cfe3-107f-5607-a424-ceff91f16546', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'fff4593d-d1d6-508c-ac73-9af443cceb05', 4, 29, 'አምላክህ እግዚአብሔርም ከአንተ ጋር እንደ አለ በአየን ጊዜ በአንተና በእኛ መካከል መሐላ ይሁን፤ አንተ በእኛ ላይ ክፉ እንዳታደርግ፤ እኛም በአንተ ላይ ክፉ እንዳናደርግ እንማማላለን።”'),
  ('574a582b-56a9-5f75-a5e2-9aa5762b8dc4', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'fff4593d-d1d6-508c-ac73-9af443cceb05', 5, 30, 'ይስሐቅም ማዕድ አቀረበላቸው፤ በሉም፤ ጠጡም።'),
  ('d95dd920-ca40-5acf-af2e-4f6516d9c704', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'fff4593d-d1d6-508c-ac73-9af443cceb05', 6, 31, 'ማልደውም ተነሡ፤ እርስ በርሳቸውም ተማማሉ፤ ይስሐቅም አሰናበታቸው፤ ከእርሱም በደኅና ሄዱ።'),
  ('ca3c6945-7fb7-54cd-af41-9878e576e371', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'fff4593d-d1d6-508c-ac73-9af443cceb05', 7, 32, 'በዚያም ቀን የይስሐቅ ሎሌዎች መጡ፤ ስለ ቈፈሩአትም ጕድጓድ፥ ውኃ አገኘን ብለው ነገሩት።'),
  ('bc69a396-edd5-58dd-a495-bab3e250c57a', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', 'fff4593d-d1d6-508c-ac73-9af443cceb05', 8, 33, 'ስምዋንም “መሐላ” ብሎ ጠራት፤ ስለዚህም የከተማዪቱ ስም እስከ ዛሬ ድረስ “ዐዘቅተ መሐላ” ይባላል።'),
  ('005e1a49-54df-57ad-a273-67f30aa8ef04', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', '1cfe2314-3daa-5f46-a94b-42acc16d9d22', 1, 34, 'ዔሳውም አርባ ዓመት ሲሆነው የኬጢያዊው የብኤልን ልጅ ዮዲትን፥ የኬጢያዊው የኤሎንን ልጅ ቤሴሞትንም ሚስቶች አድርጎ አገባ፤'),
  ('eb6d0d67-1efd-5429-a899-d51b5df43025', 'dd5cb3d2-1ea0-5064-a918-4317e7bc7918', '1cfe2314-3daa-5f46-a94b-42acc16d9d22', 2, 35, 'እነርሱም ይስሐቅንና ርብቃን ያሳዝኑ ነበር።'),
  ('82948939-bf98-5c10-aa7f-c761c58f2d24', '15dd107e-c14f-5752-ae60-46eb9c3e6453', 'c116f4f9-19a4-5dbe-acf1-efe5252ac349', 1, 1, 'እንዲህም ሆነ፦ ይስሐቅ ፈጽሞ ከአረጀ በኋላ ዐይኖቹ ፈዝዘው አያይም ነበር። ታላቁን ልጁን ዔሳውንም ጠርቶ፥ “ልጄ ሆይ፥” አለው፤ እርሱም፥ “እነሆ አለሁ” አለው።'),
  ('fd20f1b4-d712-5c44-a583-d21820defe5e', '15dd107e-c14f-5752-ae60-46eb9c3e6453', 'c116f4f9-19a4-5dbe-acf1-efe5252ac349', 2, 2, 'እርሱም አለው፥ “እነሆ እኔ አረጀሁ፤ የምሞትበትን ቀን አላውቅም።'),
  ('0e9d3eb1-50af-5291-ad8b-554231893f55', '15dd107e-c14f-5752-ae60-46eb9c3e6453', 'c116f4f9-19a4-5dbe-acf1-efe5252ac349', 3, 3, 'አሁንም ማደኛህን የፍላጻህን አፎትና ቀስትህን ውሰድ፤ ወደ ምድረ በዳም ውጣ፤ አደንም አድንልኝ፤'),
  ('2a2ffad5-b8ee-5161-a862-d3787e72797b', '15dd107e-c14f-5752-ae60-46eb9c3e6453', 'c116f4f9-19a4-5dbe-acf1-efe5252ac349', 4, 4, 'ሳልሞትም ነፍሴ እንድትባርክህ እኔ እንደምወደው መብል አዘጋጅተህ እበላ ዘንድ አምጣልኝ።”'),
  ('d923a728-f2dc-5c2b-a8c0-26b781891883', '15dd107e-c14f-5752-ae60-46eb9c3e6453', 'c116f4f9-19a4-5dbe-acf1-efe5252ac349', 5, 5, 'ርብቃም ይስሐቅ ለልጁ ለዔሳው እንደዚህ ሲነግር ትሰማ ነበር። ዔሳውም ለአባቱ አደን ሊያድን ወደ ምድረ በዳ ሄደ።'),
  ('4063434a-84fe-51ba-aab2-fab9b0166123', '15dd107e-c14f-5752-ae60-46eb9c3e6453', 'c116f4f9-19a4-5dbe-acf1-efe5252ac349', 6, 6, 'ርብቃም ታናሹ ልጅዋን ያዕቆብን እንዲህ አለችው፦'),
  ('cb421d09-5153-5774-a93e-e7e241fec14f', '15dd107e-c14f-5752-ae60-46eb9c3e6453', 'c116f4f9-19a4-5dbe-acf1-efe5252ac349', 7, 7, '“እነሆ፥ አባትህ ለወንድምህ ለዔሳው፦ እንዲህ ሲለው ሰማሁ፤ ‘ሂድና ከአደንኸው መብል አዘጋጅተህ አምጣልኝ፤ ሳልሞትም በልች በእግዚአብሔር ፊት ልባርክህ።’'),
  ('bb9344da-dc37-5247-a437-9157aeae7dfc', '15dd107e-c14f-5752-ae60-46eb9c3e6453', 'c116f4f9-19a4-5dbe-acf1-efe5252ac349', 8, 8, 'አሁንም ልጄ ሆይ፥ እኔ እንደማዝዝህ ስማኝ፤'),
  ('26f89d6d-9ca1-5864-a515-b2c06314e4a5', '15dd107e-c14f-5752-ae60-46eb9c3e6453', 'c116f4f9-19a4-5dbe-acf1-efe5252ac349', 9, 9, 'ወደ በጎቻችን ሄደህ ሁለት መልካም ጠቦቶች አምጣልኝ፤ እነርሱንም ለአባትህ እንደሚወደው መብል አደርጋቸዋለሁ፤'),
  ('7d31b872-95f7-5a49-ae65-abddad092724', '15dd107e-c14f-5752-ae60-46eb9c3e6453', 'c116f4f9-19a4-5dbe-acf1-efe5252ac349', 10, 10, 'ለአባትህም ሳይሞት እንዲባርክህ፥ ይበላ ዘንድ ትወስድለታለህ።”'),
  ('3e8d0301-e451-5589-a745-cc3e7253fcee', '15dd107e-c14f-5752-ae60-46eb9c3e6453', 'c116f4f9-19a4-5dbe-acf1-efe5252ac349', 11, 11, 'ያዕቆብም እናቱን ርብቃን፥ “እነሆ ዔሳው ወንድሜ ጠጕራም ሰው ነው፥ እኔ ግን ለስላሳ ነኝ፤'),
  ('57fb593b-a8f4-5708-ad25-8035f9adaf1f', '15dd107e-c14f-5752-ae60-46eb9c3e6453', 'c116f4f9-19a4-5dbe-acf1-efe5252ac349', 12, 12, 'ምናልባት አባቴ ቢዳስሰኝ በፊቱ እንደምንቀው እሆናለሁ፤ መርገምን በላዬ አመጣለሁ፤ በረከትንም አይደለም።”'),
  ('dfb72132-cf1d-579d-afc9-d9964abcda44', '15dd107e-c14f-5752-ae60-46eb9c3e6453', 'c116f4f9-19a4-5dbe-acf1-efe5252ac349', 13, 13, 'እናቱም አለችው፥ “ልጄ ሆይ፥ መርገምህ በእኔ ላይ ይሁን፥ ቃሌን ብቻ ስማኝ፤ ሂድና ያልሁህን አምጣልኝ።”'),
  ('056dc185-75e8-5b4c-a0c5-16616ec2b9e7', '15dd107e-c14f-5752-ae60-46eb9c3e6453', 'c116f4f9-19a4-5dbe-acf1-efe5252ac349', 14, 14, 'ሄዶም አመጣ፤ ለእናቱም ሰጣት፤ እናቱም መብልን አባቱ እንደሚወድደው አደረገች።'),
  ('105e52c4-307e-5121-a356-376f024e5d01', '15dd107e-c14f-5752-ae60-46eb9c3e6453', 'c116f4f9-19a4-5dbe-acf1-efe5252ac349', 15, 15, 'ርብቃም ከእርስዋ ዘንድ በቤት የነበረውን የታላቁን ልጅዋን የዔሳውን መልካሙን ልብስ አመጣች፤ ለታናሹ ልጅዋ ለያዕቆብም አለበሰችው፤'),
  ('50a11457-ec15-53d2-a349-0d96b2510df1', '15dd107e-c14f-5752-ae60-46eb9c3e6453', 'c116f4f9-19a4-5dbe-acf1-efe5252ac349', 16, 16, 'የጠቦቶችንም ለምድ በእጆቹና በለስላሳው አንገቱ ላይ አደረገች፤'),
  ('2ba47b2a-fb65-54a3-a057-63f3a477308d', '15dd107e-c14f-5752-ae60-46eb9c3e6453', 'c116f4f9-19a4-5dbe-acf1-efe5252ac349', 17, 17, 'ያን የሠራችውን መብልና እንጀራውን ለልጅዋ ለያዕቆብ በእጁ ሰጠችው።'),
  ('ea1fd75e-c06a-508e-aa54-c04f120d7a0d', '15dd107e-c14f-5752-ae60-46eb9c3e6453', 'c116f4f9-19a4-5dbe-acf1-efe5252ac349', 18, 18, 'ወደ አባቱም አግብቶ፥ “አባቴ ሆይ፥” አለው፦ እርሱም፥ “እነሆኝ፤ ልጄ ሆይ፥ አንተ ማን ነህ?” አለ።'),
  ('875b51d2-b05b-57c9-ae02-2102b61190f9', '15dd107e-c14f-5752-ae60-46eb9c3e6453', 'c116f4f9-19a4-5dbe-acf1-efe5252ac349', 19, 19, 'ያዕቆብም አባቱን አለው፥ “የበኵር ልጅህ እኔ ዔሳው ነኝ፤ እንዳዘዝኸኝ አደረግሁ፤ ነፍስህ ትባርከኝ ዘንድ ቀና ብለህ ተቀመጥ፤ ካደንሁትም ብላ።”'),
  ('0fd91222-2dbd-5b02-af34-0edbdd8bf686', '15dd107e-c14f-5752-ae60-46eb9c3e6453', 'c116f4f9-19a4-5dbe-acf1-efe5252ac349', 20, 20, 'ይስሐቅም ልጁን፥ “ልጄ ሆይ፥ ፈጥነህ ያገኘኸው ይህ ምንድን ነው?” አለው። እርሱም፥ “አምላክህ እግዚአብሔር በፊቴ የሰጠኝ ነው” አለ።'),
  ('6d7bbbed-ed25-5bcc-aaa8-eebf953bcdee', '15dd107e-c14f-5752-ae60-46eb9c3e6453', 'c116f4f9-19a4-5dbe-acf1-efe5252ac349', 21, 21, 'ይስሐቅም ያዕቆብን፥ “ልጄ ሆይ፥ አንተ ልጄ ዔሳው እንደ ሆንህ ወይም እንዳልሆንህ ቅረበኝና ልዳስስህ” አለው።'),
  ('b1cf0dd5-c9f9-5cfb-a759-142b53a91640', '15dd107e-c14f-5752-ae60-46eb9c3e6453', 'c116f4f9-19a4-5dbe-acf1-efe5252ac349', 22, 22, 'ያዕቆብም ወደ አባቱ ወደ ይስሐቅ ቀረበ፤ ዳሰሰውም፤ እንዲህም አለው፥ “ይህ ድምፅ የያዕቆብ ድምፅ ነው፥ እጆች ግን የዔሳው እጆች ናቸው” አለው።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('ec85fce0-a82f-554a-ad06-ca5ec6f84015', '15dd107e-c14f-5752-ae60-46eb9c3e6453', 'c116f4f9-19a4-5dbe-acf1-efe5252ac349', 23, 23, 'እርሱም አላወቀውም ነበር፤ እጆቹ እንደ ወንድሙ እንደ ዔሳው እጆች ጠጕራም ነበሩና፤ ይስሐቅም ባረከው ።'),
  ('9ac5503c-0a28-5ede-a8e7-850b2e9813a5', '15dd107e-c14f-5752-ae60-46eb9c3e6453', 'c116f4f9-19a4-5dbe-acf1-efe5252ac349', 24, 24, 'አለውም፥ “አንተ ልጄ ዔሳው ነህን?” እርሱም፥ “እኔ ነኝ” አለ።'),
  ('16978661-4acb-53e0-a801-3cafdc873567', '15dd107e-c14f-5752-ae60-46eb9c3e6453', 'c116f4f9-19a4-5dbe-acf1-efe5252ac349', 25, 25, 'እርሱም፥ “ልጄ ሆይ፥ ከአደንኸው እንድበላና ነፍሴ እንድትባርክህ አምጣልኝ” አለው። አቀረበለትም፤ በላም፤ ወይንም አመጣለት፤ እርሱም ጠጣ።'),
  ('7d18e581-86d9-5e49-abf2-9f659bb08dd7', '15dd107e-c14f-5752-ae60-46eb9c3e6453', 'c116f4f9-19a4-5dbe-acf1-efe5252ac349', 26, 26, 'አባቱ ይስሐቅም፥ “ልጄ ሆይ፥ ወደ እኔ ቅረብ፤ ሳመኝም” አለው።'),
  ('81bd675c-12cd-5477-a0c3-900806f11556', '15dd107e-c14f-5752-ae60-46eb9c3e6453', 'c116f4f9-19a4-5dbe-acf1-efe5252ac349', 27, 27, 'ወደ እርሱም ቀረበ፤ ሳመውም፤ የልብሱንም ሽታ አሸተተ፤ ባረከውም፤ እንዲህም አለ፥ “የልጄ ሽታ እግዚአብሔር እንደ ባረከው የእርሻ ሽታ ነው፤'),
  ('538aeb92-6f76-5479-aba3-2e0958ea06e4', '15dd107e-c14f-5752-ae60-46eb9c3e6453', 'c116f4f9-19a4-5dbe-acf1-efe5252ac349', 28, 28, 'እግዚአብሔርም ከሰማይ ጠል፥ ከምድርም ስብ፥ የእህልንም፥ የወይንንም፥ የዘይትንም ብዛት ይስጥህ፤'),
  ('5b5162cf-53c8-5e5c-a6a9-89cf1f7dce17', '15dd107e-c14f-5752-ae60-46eb9c3e6453', 'c116f4f9-19a4-5dbe-acf1-efe5252ac349', 29, 29, 'አሕዛብ ይገዙልህ፤ አለቆችም ይስገዱልህ፤ ለወንድምህ ጌታ ሁን፤ የአባትህም ልጆች ይስገዱልህ፤ የሚረግምህ እርሱ ርጉም ይሁን፤ የሚባርክህም ቡሩክ ይሁን።”'),
  ('bd936db1-989e-5948-a0da-ae1624eb5286', '15dd107e-c14f-5752-ae60-46eb9c3e6453', '4884c9ba-39db-5b4f-ab96-9abe893bcbbb', 1, 30, 'ይስሐቅም ያዕቆብን ባርኮ ከፈጸመ በኋላ፥ ያዕቆብ ከአባቱ ከይስሐቅ ፊት ወጣ፥ ወንድሙ ዔሳውም ከአደኑ መጣ፤'),
  ('fd108cde-aa90-555b-ab65-85ad2a332d83', '15dd107e-c14f-5752-ae60-46eb9c3e6453', '4884c9ba-39db-5b4f-ab96-9abe893bcbbb', 2, 31, 'እርሱም ደግሞ መብል አዘጋጀ፥ ለአባቱም አመጣ፤ አባቱንም፥ “አባቴ ተነሥ፤ ነፍስህም ትባርከኝ ዘንድ ልጅህ ከአደነው ብላ” አለው።'),
  ('82ab02c8-a638-59be-a44d-a314784fda95', '15dd107e-c14f-5752-ae60-46eb9c3e6453', '4884c9ba-39db-5b4f-ab96-9abe893bcbbb', 3, 32, 'አባቱ ይስሐቅም፥ “አንተ ማን ነህ?” አለው። እርሱም፥ “እኔ የበኵር ልጅህ ዔሳው ነኝ” አለው።'),
  ('79851eca-00ec-5200-ac17-c69f6ab5df47', '15dd107e-c14f-5752-ae60-46eb9c3e6453', '4884c9ba-39db-5b4f-ab96-9abe893bcbbb', 4, 33, 'ይስሐቅም እጅግ ደነገጠ፤ እንዲህም አለ፥ “ያደነውን አደን ወደ እኔ ያመጣው ማን ነው? አንተ ሳትመጣም ከሁሉ በላሁ፤ ባረክሁትም፤ እርሱም የተባረከ ነው።”'),
  ('51a224e1-4652-50bf-a10c-ac3f2e6c7ce6', '15dd107e-c14f-5752-ae60-46eb9c3e6453', '4884c9ba-39db-5b4f-ab96-9abe893bcbbb', 5, 34, 'ዔሳውም የአባቱን ቃል በሰማ ጊዜ ታላቅ፥ እጅግም መራራ ጩኸት ጮኸ፤ አባቱንም፥ “አባቴ ሆይ፥ እኔንም ደግሞ ባርከኝ” አለው።'),
  ('e88fbf58-7893-50f1-a62c-645522f8a20c', '15dd107e-c14f-5752-ae60-46eb9c3e6453', '4884c9ba-39db-5b4f-ab96-9abe893bcbbb', 6, 35, 'ይስሐቅም ዔሳውን አለው፥ “ወንድምህ በተንኰል መጥቶ በረከትህን ወሰደብህ።”'),
  ('15ca7759-0262-5ab1-abc2-86323728a09a', '15dd107e-c14f-5752-ae60-46eb9c3e6453', '4884c9ba-39db-5b4f-ab96-9abe893bcbbb', 7, 36, 'ዔሳውም አለ፥ “በእውነት ስሙ ያዕቆብ ተባለ፤ ሁለት ጊዜ አሰናክሎኛልና፤ መጀመሪያ ብኵርናዬን ወሰደ፤ አሁንም እነሆ በረከቴን ወሰደ።” ዔሳውም አባቱን አለው፥ “ደግሞም አባቴ ሆይ፥ ለእኔ በረከትን አላስቀረህልኝምን?”'),
  ('60649fc1-e93a-5868-ab60-3abf0e6a68a0', '15dd107e-c14f-5752-ae60-46eb9c3e6453', '4884c9ba-39db-5b4f-ab96-9abe893bcbbb', 8, 37, 'ይስሐቅም መለሰ ዔሳውንም አለው፥ “እነሆ ጌታህ አደረግሁት፤ ወንድሞቹንም ሁሉ ለእርሱ ተገዦች አደረግኋቸው፤ እህሉን፥ ወይኑንና ዘይቱንም አበዛሁለት፤ ለአንተ ግን፥ ልጄ ሆይ፥ ምን ላድርግልህ?”'),
  ('e2904e5c-050c-5128-a916-620bb2b0bf0a', '15dd107e-c14f-5752-ae60-46eb9c3e6453', '4884c9ba-39db-5b4f-ab96-9abe893bcbbb', 9, 38, 'ዔሳውም አባቱን ይስሐቅን አለው፥ “አባቴ ሆይ፥ በረከትህ አንዲት ብቻ ናትን? አባቴ ሆይ፥ እኔንም ደግሞ ባርከኝ።” ዔሳውም ጮሆ አለቀሰ።'),
  ('e3374d5b-95e1-5dd7-a050-17d2e53d8959', '15dd107e-c14f-5752-ae60-46eb9c3e6453', '4884c9ba-39db-5b4f-ab96-9abe893bcbbb', 10, 39, 'አባቱ ይስሐቅም መለሰ፤ አለውም፥ “እነሆ መኖሪያህ ከላይ ከሰማይ ጠል፥ ከምድርም ስብ ይሁን፤'),
  ('6adf2882-766c-5e0e-ac26-6466bfdd121b', '15dd107e-c14f-5752-ae60-46eb9c3e6453', '4884c9ba-39db-5b4f-ab96-9abe893bcbbb', 11, 40, 'በሰይፍህም ትኖራለህ፤ ለወንድምህም ትገዛለህ፤ ነገር ግን ቀንበሩን ከአንገትህ ልትጥል ብትወድድ ከእርሱ ጋር ተስማማ።”'),
  ('b927932d-3a16-56e5-a912-75e00d4912b3', '15dd107e-c14f-5752-ae60-46eb9c3e6453', '4884c9ba-39db-5b4f-ab96-9abe893bcbbb', 12, 41, 'ዔሳውም አባቱ ስለ ባረከው በያዕቆብ ቂም ያዘበት፤ ዔሳውም በልቡ አለ፥ “ለአባቴ የልቅሶ ቀን ትቅረብ፤ ወንድሜን ያዕቆብን እገድለዋለሁ።”'),
  ('0f2c6aa2-48fa-5de6-a6bf-003e08934d86', '15dd107e-c14f-5752-ae60-46eb9c3e6453', '4884c9ba-39db-5b4f-ab96-9abe893bcbbb', 13, 42, 'ለርብቃም ታላቁ ልጅዋ ዔሳው ያለው ተነገራት፤ ታናሹን ልጅዋን ያዕቆብንም ልካ ጠራችው፤ አለችውም፥ “እነሆ ወንድምህ ዔሳው ያድድንሃል፤ ሊገድልህም ይፈልጋል።'),
  ('2d32565e-8c18-5fa2-afbd-ffa4385eed21', '15dd107e-c14f-5752-ae60-46eb9c3e6453', '4884c9ba-39db-5b4f-ab96-9abe893bcbbb', 14, 43, 'አሁንም ልጄ ሆይ፥ ቃሌን ስማ፤ ተነሣና በሶርያ ወንዞች መካከል ወደ ካራን ምድር ወደ ወንድሜ ወደ ላባ ሂድ፤'),
  ('b192eeb9-7fde-5238-a1c2-cd9f3462e80a', '15dd107e-c14f-5752-ae60-46eb9c3e6453', '4884c9ba-39db-5b4f-ab96-9abe893bcbbb', 15, 44, 'በእርሱም ዘንድ ጥቂት ቀን ተቀመጥ። የወንድምህ ቍጣ ከአንተ እስኪበርድ ድረስ፥'),
  ('17b300f9-fc2f-586c-a87d-af9623c329c5', '15dd107e-c14f-5752-ae60-46eb9c3e6453', '4884c9ba-39db-5b4f-ab96-9abe893bcbbb', 16, 45, 'ያደረግህበትንም እስኪረሳው ድረስ፤ በአንድ ቀን ሁለታችሁን እንዳላጣ፥ ከዚያም ልኬ አመጣሃለሁ።”'),
  ('3c79d9d2-dfb3-5d04-a29f-4eee5403f835', '15dd107e-c14f-5752-ae60-46eb9c3e6453', '2f2abe8d-a5ec-5c14-af67-b9d124ca0c1a', 1, 46, 'ርብቃም ይስሐቅን አለችው፥ “ከኬጢ ሴቶች ልጆች የተነሣ ሕይወቴን ጠላሁት፤ ያዕቆብ ከዚህ ሀገር ሴቶች ልጆች ሚስትን የሚያገባ ከሆነ በሕይወት መኖር ለእኔ ምኔ ነው?”'),
  ('b1b09c1d-468a-5a01-ad13-451f684af9ee', '964d2d6a-fa95-55d4-a71d-ceb9beeb37ce', '261b200e-b483-5119-a9bd-3c835d6abfb1', 1, 1, 'ይስሐቅም ያዕቆብን ጠራው፤ ባረከውም፥ እንዲህም ብሎ አዘዘው፥ “ከከነዓናውያን ሴቶች ልጆች ሚስትን አታግባ፤'),
  ('50fa9961-4552-50d7-a127-c15cdc896137', '964d2d6a-fa95-55d4-a71d-ceb9beeb37ce', '261b200e-b483-5119-a9bd-3c835d6abfb1', 2, 2, 'ተነሣና ወደ እናትህ አባት ወደ ባቱኤል ቤት ወደ ሁለቱ ወንዞች መካከል ሂድ፤ ከዚያም ከእናትህ ከርብቃ ወንድም ከላባ ሴቶች ልጆች ሚስትን አግባ።'),
  ('570516e4-8572-5d37-a49d-e1edfeba7c6c', '964d2d6a-fa95-55d4-a71d-ceb9beeb37ce', '261b200e-b483-5119-a9bd-3c835d6abfb1', 3, 3, 'አምላኬ ከአንተ ጋር ይሂድ፤ ከፍ ከፍም ያድርግህ፤ ይባርክህ፤ ያብዛህ፤ ብዙ ሕዝብም ሁን ፤'),
  ('19c5aea5-24d7-5d9c-ad69-8dfa360c89a8', '964d2d6a-fa95-55d4-a71d-ceb9beeb37ce', '261b200e-b483-5119-a9bd-3c835d6abfb1', 4, 4, 'ስደተኛ ሆነህ የተቀመጥህባትን፥ እግዚአብሔር ለአብርሃም የሰጣትን ምድር ትወርስ ዘንድ የአባቴን የአብርሃምን በረከት ለአንተ ይስጥህ፤ ከአንተም በኋላ ለዘርህ።”'),
  ('0947337d-157d-59eb-a88f-4a3758409f51', '964d2d6a-fa95-55d4-a71d-ceb9beeb37ce', '261b200e-b483-5119-a9bd-3c835d6abfb1', 5, 5, 'ይስሐቅም ልጁ ያዕቆብን ላከው፤ እርሱም የያዕቆብና የዔሳው እናት የርብቃ ወንድም የሚሆን የሶርያዊው ባቱኤል ልጅ ላባ ወዳለበት ወደ ሁለቱ ወንዞች መካከል ሄደ።'),
  ('fbfac41e-7141-577b-a7aa-b6b845c80a11', '964d2d6a-fa95-55d4-a71d-ceb9beeb37ce', 'fc00c069-f213-506c-a300-e1273b2695b1', 1, 6, 'ዔሳውም ይስሐቅ ያዕቆብን እንደ ባረከው በአየ ጊዜ ከዚያም ሚስትን ያገባ ዘንድ ወደ ሁለቱ የሶርያ ወንዞች መካከል እንደ ላከው፥ በባረከውም ጊዜ፥ “ከከነዓን ሴቶች ልጆች ሚስትን አታግባ” ብሎ እንዳዘዘው፥'),
  ('16508794-9157-5c22-a21f-f051007aa5ae', '964d2d6a-fa95-55d4-a71d-ceb9beeb37ce', 'fc00c069-f213-506c-a300-e1273b2695b1', 2, 7, 'ያዕቆብም የአባቱንና የእናቱን ቃል ሰምቶ ወደ ሁለቱ ወንዞች መካከል እንደ ሄደ፥'),
  ('1350ab56-5a44-5fd2-aa0c-bdf1ad4462e4', '964d2d6a-fa95-55d4-a71d-ceb9beeb37ce', 'fc00c069-f213-506c-a300-e1273b2695b1', 3, 8, 'የከነዓናውያንም ሴቶች ልጆች በአባቱ በይስሐቅ ፊት የተጠሉ እንደ ሆኑ ዔሳው በአየ ጊዜ፥'),
  ('a770b692-12b7-5192-a97f-a558fe766cb2', '964d2d6a-fa95-55d4-a71d-ceb9beeb37ce', 'fc00c069-f213-506c-a300-e1273b2695b1', 4, 9, 'ዔሳው ወደ ይስማኤል ሄደ፤ ቤሴሞትንም በፊት ካሉ ሚስቶቹ ጋር ሚስት ትሆነው ዘንድ ወሰዳት፤ እርስዋም የናኮር ወንድም የአብርሃም ልጅ የሆነው የይስማኤል ልጅና የናቡዓት እኅት ናት።'),
  ('9bf3ae46-56fb-5b4c-af2c-0d8d0484f4fe', '964d2d6a-fa95-55d4-a71d-ceb9beeb37ce', '3bf5bc33-6d43-5a9f-a8e2-45cd6bd1686f', 1, 10, 'ያዕቆብም ከአዘቅተ መሐላ ወጥቶ ወደ ካራን ሄደ።'),
  ('758c936a-906f-538c-ab50-be199e66dffa', '964d2d6a-fa95-55d4-a71d-ceb9beeb37ce', '3bf5bc33-6d43-5a9f-a8e2-45cd6bd1686f', 2, 11, 'ወደ አንድ ስፍራም ደረሰ፤ ፀሐይም ጠልቃ ነበርና በዚያ አደረ፤ ከዚያም ስፍራ ድንጋዮች አንድ ድንጋይ አነሣ፤ ከራሱም በታች ተንተርሶ በዚያ ስፍራ ተኛ።'),
  ('ac801598-68b8-5518-aa1a-0e9805ead7a1', '964d2d6a-fa95-55d4-a71d-ceb9beeb37ce', '3bf5bc33-6d43-5a9f-a8e2-45cd6bd1686f', 3, 12, 'ሕልምም አለመ፤ እነሆም መሰላል በምድር ላይ ተተክሎ፥ ራሱም ወደ ሰማይ ደርሶ፥ እነሆም የእግዚአብሔር መላእክት ይወጡበትና ይወርዱበት ነበር።'),
  ('45bef4a3-66b4-5509-ad05-96734fac15d8', '964d2d6a-fa95-55d4-a71d-ceb9beeb37ce', '3bf5bc33-6d43-5a9f-a8e2-45cd6bd1686f', 4, 13, 'እነሆም፥ እግዚአብሔር በላዩ ቆሞበት ነበር፥ እንዲህም አለ፥ “የአባትህ የአብርሃም አምላክ የይስሐቅም አምላክ እኔ እግዚአብሔር ነኝ፤ አትፍራ፥ ይህችን አንተ የተኛህባትን ምድር ለአንተም ለዘርህም እሰጣለሁ፤'),
  ('3f487f54-9359-5833-a44f-38e71f7788f3', '964d2d6a-fa95-55d4-a71d-ceb9beeb37ce', '3bf5bc33-6d43-5a9f-a8e2-45cd6bd1686f', 5, 14, 'ዘርህም እንደ ባሕር አሸዋ ይሆናል፤ እስከ ባሕርና እስከ አዜብ እስከ መስዕና እስከ ምሥራቅ ይበዛል፤ ይሞላልም፤ የምድርም ሕዝቦች ሁሉ በአንተ፥ በዘርህም ይባረካሉ።'),
  ('564bf298-0c35-5313-af81-ec332087ee78', '964d2d6a-fa95-55d4-a71d-ceb9beeb37ce', '3bf5bc33-6d43-5a9f-a8e2-45cd6bd1686f', 6, 15, 'እነሆም፥ እኔ ከአንተ ጋር እሄዳለሁ፤ በምትሄድበትም መንገድ ሁሉ እጠብቅሃለሁ፤ ወደዚያችም ምድር እመልስሃለሁ፤ የነገርሁህን ሁሉ እስካደርግልህ ድረስ አልተውህምና።”'),
  ('cd062a53-f7a0-5329-a977-add0176daf77', '964d2d6a-fa95-55d4-a71d-ceb9beeb37ce', '3bf5bc33-6d43-5a9f-a8e2-45cd6bd1686f', 7, 16, 'ያዕቆብም ከእንቅልፉ ተነሥቶ፥ “በእውነት እግዚአብሔር በዚህ ስፍራ አለ፤ እኔ አላወቅሁም ነበር” አለ።'),
  ('19d8f4a8-a88b-596e-ad55-6acc7ff235b0', '964d2d6a-fa95-55d4-a71d-ceb9beeb37ce', '3bf5bc33-6d43-5a9f-a8e2-45cd6bd1686f', 8, 17, 'ፈራ፤ እንዲህም አለ፥ “ይህ ስፍራ እንዴት ያስፈራ፤ ይህ ስፍራ የእግዚአብሔር ቤት ነው እንጂ ሌላ አይደለም፤ ይህችም የሰማይ ደጅ ናት።”'),
  ('f4f356fc-7fad-56e0-a420-27351e181bbb', '964d2d6a-fa95-55d4-a71d-ceb9beeb37ce', '3bf5bc33-6d43-5a9f-a8e2-45cd6bd1686f', 9, 18, 'ያዕቆብም ማልዶ ተነሣ፤ ተንተርሷት የነበረችውንም ድንጋይ ወስዶ ሐውልት አድርጎ አቆማት፥ በላይዋም ዘይትን አፈሰሰባት።'),
  ('3cd384f1-5933-5a6a-abf6-dc4f94d72380', '964d2d6a-fa95-55d4-a71d-ceb9beeb37ce', '3bf5bc33-6d43-5a9f-a8e2-45cd6bd1686f', 10, 19, 'ያዕቆብም ያን ስፍራ ቤቴል ብሎ ጠራው፤ አስቀድሞ ግን የዚያ ከተማ ስም ሎዛ ነበረ።'),
  ('554fdecb-a135-5654-ae51-959ed88a39e0', '964d2d6a-fa95-55d4-a71d-ceb9beeb37ce', '3bf5bc33-6d43-5a9f-a8e2-45cd6bd1686f', 11, 20, 'ያዕቆብም እንዲህ ብሎ ስእለት ተሳለ፥ “እግዚአብሔር ከእኔ ጋር ቢሆን፥ በምሄድባትም በዚች መንገድ ቢጠብቀኝ፥ የምበላውንም እንጀራ፥ የምለብሰውንም ልብስ ቢሰጠኝ፥'),
  ('232eaf30-8005-5691-af5f-ee6db010e83b', '964d2d6a-fa95-55d4-a71d-ceb9beeb37ce', '3bf5bc33-6d43-5a9f-a8e2-45cd6bd1686f', 12, 21, 'ወደ አባቴም ቤት በጤና ቢመልሰኝ፥ እግዚአብሔር አምላኬ ይሆንልኛል፤'),
  ('ceddb742-b489-5880-a3de-a7b7bfbd205a', '964d2d6a-fa95-55d4-a71d-ceb9beeb37ce', '3bf5bc33-6d43-5a9f-a8e2-45cd6bd1686f', 13, 22, 'ለሐውልት ያቆምኋት ይህችም ድንጋይ የእግዚአብሔር ቤት ትሆንልኛለች፤ ከሰጠኸኝም ሁሉ ለአንተ ከዐሥር እጅ አንዱን እሰጥሃለሁ።”'),
  ('98b0709b-7b67-5ba2-a8c0-ad51385dba3f', '21ef10c8-e722-5ded-ae70-412ae45f638b', 'd3fa5f2c-1781-5db9-ae9b-4c7ed3be6797', 1, 1, 'ያዕቆብም በማለዳ ተነሥቶ የያዕቆብና የዔሳው እናት የርብቃ ወንድም የሶርያ ሰው የባቱኤል ልጅ ወደሚሆን ወደ ላባ ሄደ።'),
  ('3d839b33-1add-5284-a806-efb4c614b755', '21ef10c8-e722-5ded-ae70-412ae45f638b', 'd3fa5f2c-1781-5db9-ae9b-4c7ed3be6797', 2, 2, 'በተመለከተም ጊዜ በሜዳው እነሆ ጕድጓድን አየ፤ በዚያም ሦስት የበጎች መንጎች በላዩ ተመስገው ነበር፤ ከዚያች ጕድጓድ በጎቹን ያጠጡ ነበርና፤ በጕድጓድዋም አፍ ታላቅ ድንጋይ ነበረች።'),
  ('1c6ecaf3-ed7d-5920-a7d8-8c50706c872c', '21ef10c8-e722-5ded-ae70-412ae45f638b', 'd3fa5f2c-1781-5db9-ae9b-4c7ed3be6797', 3, 3, 'መንጎችም ሁሉ ከዚያ በተሰበሰቡ ጊዜ እረኞች ድንጋይዋን ከጕድጓዱ አፍ ገለል አድርገው በጎቹን ያጠጡ ነበር፤ ድንጋይዋንም ወደ ስፍራው መልሰው በጕድጓዱ አፍ እንደገና ይገጥሙት ነበር።'),
  ('e5a1df35-a618-5948-ac36-7e84745f7895', '21ef10c8-e722-5ded-ae70-412ae45f638b', 'd3fa5f2c-1781-5db9-ae9b-4c7ed3be6797', 4, 4, 'ያዕቆብም፥ “ወንድሞች ሆይ፥ እናንት ከወዴት ናችሁ?” አላቸው።'),
  ('dec16477-cded-52e4-a9cd-4652c4835054', '21ef10c8-e722-5ded-ae70-412ae45f638b', 'd3fa5f2c-1781-5db9-ae9b-4c7ed3be6797', 5, 5, 'እነርሱም፥ “እኛ ከካራን ነን” አሉት። “የናኮርን ልጅ ላባን ታውቁታላችሁን?” አላቸው። እነርሱም፥ “እናውቀዋለን” አሉት።'),
  ('a79f5e0c-2625-57aa-a6ac-5b831ec19446', '21ef10c8-e722-5ded-ae70-412ae45f638b', 'd3fa5f2c-1781-5db9-ae9b-4c7ed3be6797', 6, 6, '“እርሱ ደኅና ነውን?” አላቸው። እነርሱም፥ “አዎ ደኅና ነው፤ አሁንም ልጁ ራሔል የአባቷን በጎች ይዛ ትመጣለች” አሉት።'),
  ('4cfe4e3b-b862-5655-af71-c4b9f440fb85', '21ef10c8-e722-5ded-ae70-412ae45f638b', 'd3fa5f2c-1781-5db9-ae9b-4c7ed3be6797', 7, 7, 'እርሱም፥ “ቀኑ ገና ቀትር ነው፥ ከብቶቹ የሚሰበሰቡበት ሰዓቱም ገና አልደረሰም፤ አሁንም በጎቹን አጠጡና ሄዳችሁ አሰማሩአቸው” አላቸው።'),
  ('596752f0-6faa-5d38-a23c-afef5128dc5a', '21ef10c8-e722-5ded-ae70-412ae45f638b', 'd3fa5f2c-1781-5db9-ae9b-4c7ed3be6797', 8, 8, 'እነርሱም አሉ፥ “እረኞች ሁሉ ካልተሰበሰቡና ድንጋዪቱን ከጕድጓዱ አፍ ካላነሡአት በቀር አንችልም፤ ከዚያም በኋላ በጎቹን እናጠጣለን።”'),
  ('f851d3ac-0e7c-5da8-aab3-687995dd4f19', '21ef10c8-e722-5ded-ae70-412ae45f638b', 'd3fa5f2c-1781-5db9-ae9b-4c7ed3be6797', 9, 9, 'እርሱም ገና ከእነርሱ ጋር ሲነጋገር እነሆ፥ የላባ ልጅ ራሔል የአባትዋን በጎች ይዛ ደረሰች፤ እርስዋ የአባቷን በጎች ትጠብቅ ነበርና።'),
  ('700fbe76-c20d-5999-a6dc-ba11a770eedb', '21ef10c8-e722-5ded-ae70-412ae45f638b', 'd3fa5f2c-1781-5db9-ae9b-4c7ed3be6797', 10, 10, 'ያዕቆብም የእናቱን ወንድም የላባን ልጅ ራሔልንና የአጎቱን የላባን በጎች በአየ ጊዜ ቀረበ፤ ከጕድጓዱም አፍ ድንጋዩን አነሣ፤ የአጎቱን የላባን በጎችም አጠጣ።'),
  ('86380b42-6591-52a5-a8d2-3e017b33b055', '21ef10c8-e722-5ded-ae70-412ae45f638b', 'd3fa5f2c-1781-5db9-ae9b-4c7ed3be6797', 11, 11, 'ያዕቆብም ራሔልን ሳማት፤ ቃሉንም ከፍ አድርጎ አለቀሰ።'),
  ('c3ff5d80-313a-5197-a7a7-be41a28f41ed', '21ef10c8-e722-5ded-ae70-412ae45f638b', 'd3fa5f2c-1781-5db9-ae9b-4c7ed3be6797', 12, 12, 'ያዕቆብም የአባቷ ዘመድና የርብቃ ልጅ መሆኑን ለራሔል አስታወቃት፤ እርስዋም ሮጣ ሄዳ ለአባቷ ይህን ነገር ነገረችው።'),
  ('16e1fc9a-33d8-553e-ae50-3476d516722b', '21ef10c8-e722-5ded-ae70-412ae45f638b', 'd3fa5f2c-1781-5db9-ae9b-4c7ed3be6797', 13, 13, 'ላባም የእኅቱን የርብቃን ልጅ የያዕቆብን ስም በሰማ ጊዜ ሊቀበለው ሮጠ፥ አቅፎም ሳመው፥ ወደ ቤቱም አገባው። ነገሩንም ሁሉ ለላባ ነገረው።'),
  ('fe28197b-5084-5b5d-ae74-61942aa5fbfc', '21ef10c8-e722-5ded-ae70-412ae45f638b', 'd3fa5f2c-1781-5db9-ae9b-4c7ed3be6797', 14, 14, 'ላባም ያዕቆብን፥ “በእውነት አንተ አጥንቴ ሥጋዬም ነህ፤ ከእኔ ጋር ተቀመጥ” አለው። አንድ ወር የሚያህልም ከእርሱ ጋር ተቀመጠ።'),
  ('834a6ef3-4e0d-593a-aa30-fe7181902c0b', '21ef10c8-e722-5ded-ae70-412ae45f638b', '2cf1fb11-23b7-5187-aa65-f5f28d683c88', 1, 15, 'ላባም ያዕቆብን፥ “ወንድሜ ስለሆንህ በከንቱ አታገለግለኝም ደመወዝህ ምንድን ነው? ንገረኝ” አለው'),
  ('19c65715-2ff9-5f33-a0b3-8cacf258fc9a', '21ef10c8-e722-5ded-ae70-412ae45f638b', '2cf1fb11-23b7-5187-aa65-f5f28d683c88', 2, 16, 'ለላባም ሁለት ሴቶች ልጆች ነበሩት፤ የታላቂቱ ስም ልያ የታናሺቱም ስም ራሔል ነበረ።'),
  ('d1870189-4bb4-5942-abdb-66e343495835', '21ef10c8-e722-5ded-ae70-412ae45f638b', '2cf1fb11-23b7-5187-aa65-f5f28d683c88', 3, 17, 'ልያም ዓይነ ልም ነበረች፤ ራሔል ግን መልከ መልካም ነበረች፥ ፊቷም ውብ ነበረ።'),
  ('2f598c7d-f932-5a42-a7bc-2d6a988ca8c4', '21ef10c8-e722-5ded-ae70-412ae45f638b', '2cf1fb11-23b7-5187-aa65-f5f28d683c88', 4, 18, 'ያዕቆብም ራሔልን ወደዳት፤ ያዕቆብም ላባን እንዲህ አለው፥ “ስለ ታናሺቱ ልጅህ ስለ ራሔል ሰባት ዓመት እገዛልሃለሁ። ሚስት ትሆነኝ ዘንድ እርስዋን ስጠኝ” አለው።'),
  ('9ad103ce-7023-58be-a824-351ae659bae6', '21ef10c8-e722-5ded-ae70-412ae45f638b', '2cf1fb11-23b7-5187-aa65-f5f28d683c88', 5, 19, 'ላባም፥ “ለሌላ ሰው ከምሰጣት ይልቅ ለማውቅህ ለዘመዴ ለአንተ ብሰጣት ይሻላል፤ ከእኔ ጋር ተቀመጥ” አለው።'),
  ('202437ce-14fd-54ad-a00f-5fb191af9b82', '21ef10c8-e722-5ded-ae70-412ae45f638b', '2cf1fb11-23b7-5187-aa65-f5f28d683c88', 6, 20, 'ያዕቆብም ስለ ራሔል ሰባት ዓመት ተገዛ፤ እርስዋንም ይወድዳት ስለነበረ በእርሱ ዘንድ ጥቂት ቀን ሆነለት።'),
  ('fb8919c9-4c66-5c5a-a982-a267d4b1452b', '21ef10c8-e722-5ded-ae70-412ae45f638b', '2cf1fb11-23b7-5187-aa65-f5f28d683c88', 7, 21, 'ያዕቆብም ላባን፥ “እንግዲህ ወደ እርስዋ እገባ ዘንድ ሚስቴን ስጠኝ፥ ቀኔ ተፈጽሞአልና አለው።”'),
  ('6173e68e-2b68-5301-aca0-a2775d73e1b7', '21ef10c8-e722-5ded-ae70-412ae45f638b', '2cf1fb11-23b7-5187-aa65-f5f28d683c88', 8, 22, 'ላባም የዚያን ስፍራ ሰዎች ሁሉ ሰበሰበ፥ ሰርግም አደረገ።'),
  ('306d66c9-37fe-503a-ac5e-1cb860eeafb2', '21ef10c8-e722-5ded-ae70-412ae45f638b', '2cf1fb11-23b7-5187-aa65-f5f28d683c88', 9, 23, 'በመሸም ጊዜ ልጁን ልያን ወስዶ ወደ ያዕቆብ አስገባት፤ ያዕቆብም ወደ እርስዋ ገባ።'),
  ('8891e0c0-ca83-55f3-a0a3-5bfc7dd43136', '21ef10c8-e722-5ded-ae70-412ae45f638b', '2cf1fb11-23b7-5187-aa65-f5f28d683c88', 10, 24, 'ላባም ለልጁ ልያ አገልጋዪቱን ዘለፋን አገልጋይ ትሆናት ዘንድ ሰጣት።'),
  ('a7f156ec-3eff-5a46-a73c-e4b83bf7fb38', '21ef10c8-e722-5ded-ae70-412ae45f638b', '2cf1fb11-23b7-5187-aa65-f5f28d683c88', 11, 25, 'በነጋም ጊዜ እነሆ ልያ ነበረች፤ ያዕቆብም ላባን፥ “ምነው እንደዚህ አደረግህብኝ? ያገለገልሁህ ስለ ራሔል አልነበረምን? ለምን አታለልኸኝ?” አለው።'),
  ('fe0bf961-0ebf-5ded-a2ff-32e13974a750', '21ef10c8-e722-5ded-ae70-412ae45f638b', '2cf1fb11-23b7-5187-aa65-f5f28d683c88', 12, 26, 'ላባም እንዲህ አለ፥ “በሀገራችን ታላቂቱ ሳለች፥ ታናሺቱን እንሰጥ ዘንድ ወግ አይደለም፤'),
  ('ab061708-184f-5524-a119-3d6bd167494e', '21ef10c8-e722-5ded-ae70-412ae45f638b', '2cf1fb11-23b7-5187-aa65-f5f28d683c88', 13, 27, 'ለዚችም ሰባት ዓመት ፈጽም፤ ሌላ ሰባት ዓመት ደግሞ እኔን ስለምታገለግለኝ አገልግሎት እርስዋን ደግሞ እሰጥሃለሁ።”'),
  ('6ee73f7b-692e-5acb-aaed-64d4e5cc2dc1', '21ef10c8-e722-5ded-ae70-412ae45f638b', '2cf1fb11-23b7-5187-aa65-f5f28d683c88', 14, 28, 'ያዕቆብም እንዲህ አደረገ፤ ለዚችም ሰባት ዓመት ፈጸመ፤ ልጁን ራሔልንም ለእርሱ ሚስት ትሆነው ዘንድ ሰጠው።'),
  ('d155e954-8e3f-5b41-a7e4-f6a6eef4825e', '21ef10c8-e722-5ded-ae70-412ae45f638b', '2cf1fb11-23b7-5187-aa65-f5f28d683c88', 15, 29, 'ላባም ለልጁ ለራሔል አገልጋዪቱን ባላን አገልጋይ ትሆናት ዘንድ ሰጣት።'),
  ('02b5160b-e319-54dc-ac43-1a63c0d94d3e', '21ef10c8-e722-5ded-ae70-412ae45f638b', '2cf1fb11-23b7-5187-aa65-f5f28d683c88', 16, 30, 'ያዕቆብም ወደ ራሔል ደግሞ ገባ። ራሔልንም ከልያ ይልቅ ወደዳት፤ ሌላ ሰባት ዓመትም ተገዛለት።'),
  ('39689e0c-938f-5be5-a84c-8d29a113e287', '21ef10c8-e722-5ded-ae70-412ae45f638b', '60c6c0a5-a9f2-5ffd-ac03-e124c67dc188', 1, 31, 'እግዚአብሔርም ልያ የተጠላች መሆንዋን በአየ ጊዜ ማኅፀንዋን ከፈተላት፤ ራሔል ግን መካን ነበረች።'),
  ('3a610a4d-69eb-5eed-a7e6-d9973ccd0d8e', '21ef10c8-e722-5ded-ae70-412ae45f638b', '60c6c0a5-a9f2-5ffd-ac03-e124c67dc188', 2, 32, 'ልያም ፀነሰች፤ ወንድ ልጅንም ወለደች፥ ስሙንም ሮቤል ብላ ጠራችው፥ “እግዚአብሔር መዋረዴን አይቶአልና፥ እንግዲህስ ወዲህ ባሌ ይወድደኛል” ስትል።'),
  ('5a7a9226-2b92-5320-a282-d687017f3504', '21ef10c8-e722-5ded-ae70-412ae45f638b', '60c6c0a5-a9f2-5ffd-ac03-e124c67dc188', 3, 33, 'ልያም ዳግመኛ ፀነሰች፤ ሁለተኛ ወንድ ልጅንም ለያዕቆብ ወለደችለት፤ “እኔ እንደ ተጠላሁ እግዚአብሔር ስለ ሰማ ይህን ጨመረልኝ” አለች፤ ስሙንም ስምዖን ብላ ጠራችው ።'),
  ('502849f3-4713-5742-a72a-edb7f2d86ad6', '21ef10c8-e722-5ded-ae70-412ae45f638b', '60c6c0a5-a9f2-5ffd-ac03-e124c67dc188', 4, 34, 'ደግሞም ፀነሰች፤ ወንድ ልጅንም ወለደች፤ “ከእንግዲህ ወዲህስ ባሌ ወደ እኔ ይጠጋል፤ ሦስት ወንዶች ልጆችን ወልጄለታለሁና” አለች፤ ስለዚህም ስሙን ሌዊ ብላ ጠራችው።'),
  ('07b5b909-d53a-5fd7-a5b5-b45574ebb072', '21ef10c8-e722-5ded-ae70-412ae45f638b', '60c6c0a5-a9f2-5ffd-ac03-e124c67dc188', 5, 35, 'ደግሞም ፀነሰች፤ ወንድ ልጅንም ወለደች፤ በዚህም ጊዜ “እግዚአብሔርን አመሰግናለሁ” አለች፤ ስለዚህም ስሙን ይሁዳ ብላ ጠራችው። መውለድንም አቆመች።'),
  ('6cbe4113-cc82-51ef-a14d-d2ce8f4b3ef3', '16cefb1f-f767-5d65-a12c-77c072311e34', 'bde51cac-278c-5c47-aeef-a76786633569', 1, 1, 'ራሔልም ለያዕቆብ ልጅ እንዳልወለደች በአየች ጊዜ በእኅቷ ላይ ቀናችባት፤ ያዕቆብንም “ልጅ ስጠኝ፤ ይህስ ከአልሆነ እሞታለሁ” አለችው።'),
  ('54d7ca1a-61b7-516f-ad3d-a756ba7dbe01', '16cefb1f-f767-5d65-a12c-77c072311e34', 'bde51cac-278c-5c47-aeef-a76786633569', 2, 2, 'ያዕቆብም፥ “የማኅፀንሽን ፍሬ የምከለክልሽ እኔ እንደ እግዚአብሔር ነኝን?” ብሎ ራሔልን ተቈጣት።'),
  ('fc01bba8-9838-5b20-ab32-e7cfa788c614', '16cefb1f-f767-5d65-a12c-77c072311e34', 'bde51cac-278c-5c47-aeef-a76786633569', 3, 3, 'እርስዋም፥ “ባሪያዬ ባላ እነሆ አለች፤ ወደ እርስዋ ግባ፤ በእኔም ጭን ላይ ትውለድ፤ የእርስዋም ልጆች ለእኔ ደግሞ ይሁኑልኝ” አለች።'),
  ('26f09311-3e23-5c34-a7a1-e2c0a6c61e5f', '16cefb1f-f767-5d65-a12c-77c072311e34', 'bde51cac-278c-5c47-aeef-a76786633569', 4, 4, 'አገልጋይዋን ባላንም ሚስት ትሆነው ዘንድ ለእርሱ ሰጠችው፤ ያዕቆብም ወደ እርስዋ ገባ።'),
  ('ba573681-067c-5cde-a6a7-83505d8104fe', '16cefb1f-f767-5d65-a12c-77c072311e34', 'bde51cac-278c-5c47-aeef-a76786633569', 5, 5, 'የራሔል አገልጋይ ባላም ፀነስች፤ ወንድ ልጅንም ለያዕቆብ ወለደችለት።'),
  ('5b9b0bab-20bf-588b-adc6-19cd846d8f6b', '16cefb1f-f767-5d65-a12c-77c072311e34', 'bde51cac-278c-5c47-aeef-a76786633569', 6, 6, 'ራሔልም፥ “እግዚአብሔር ፈረደልኝ፤ ቃሌንም ደግሞ ሰማ፤ ወንድ ልጅንም ሰጠኝ” አለች፤ ስለዚህ ስሙን ዳን ብላ ጠራችው።'),
  ('bb8c31c7-8639-54bc-aa05-94d36716f4f6', '16cefb1f-f767-5d65-a12c-77c072311e34', 'bde51cac-278c-5c47-aeef-a76786633569', 7, 7, 'የራሔልም አገልጋይ ባላ ደግማ ፀነስች፤ ለያዕቆብም ሁለተኛ ወንድ ልጅን ወለደች።'),
  ('e97ac36d-f57f-5a09-a534-800b3da27f91', '16cefb1f-f767-5d65-a12c-77c072311e34', 'bde51cac-278c-5c47-aeef-a76786633569', 8, 8, 'ራሔልም፥ “እግዚአብሔር ከፍ ከፍ አደረገኝ፤ ብርቱ ትግልንም ከእኅቴ ጋር ታገልሁ፤ አሸነፍሁም፤ እኅቴንም መሰልኋት” አለች፤ ስሙንም ንፍታሌም ብላ ጠራችው።'),
  ('4bd407eb-4703-5a4b-a827-5cbe7bfd3015', '16cefb1f-f767-5d65-a12c-77c072311e34', 'bde51cac-278c-5c47-aeef-a76786633569', 9, 9, 'ልያም መውለድን እንዳቆመች በአየች ጊዜ አገልጋይዋን ዘለፋን ወሰደች፤ ሚስት ትሆነውም ዘንድ ለያዕቆብ ሰጠችው፤ ያዕቆብም ወደ እርስዋ ገባ።'),
  ('a045ddfc-3aa5-57ac-a9db-1a5690feb55f', '16cefb1f-f767-5d65-a12c-77c072311e34', 'bde51cac-278c-5c47-aeef-a76786633569', 10, 10, 'የልያ አገልጋይ ዘለፋም ፀነሰች፤ ወንድ ልጅንም ለያዕቆብ ወለደች።'),
  ('c1590974-f667-5a63-ad42-fc461bcc2348', '16cefb1f-f767-5d65-a12c-77c072311e34', 'bde51cac-278c-5c47-aeef-a76786633569', 11, 11, 'ልያም፥ “እኔም ራሴን ብፅዕት አሰኘሁ” ስትል ስሙን ጋድ ብላ ጠራችው።'),
  ('4666f72a-e0c3-5a0d-afbc-9794e21ecab8', '16cefb1f-f767-5d65-a12c-77c072311e34', 'bde51cac-278c-5c47-aeef-a76786633569', 12, 12, 'የልያ አገልጋይ ዘለፋም ዳግመኛ ለያዕቆብ ወንድ ልጅን ወለደች።'),
  ('69acad3c-47c5-5550-a0b0-9d4df39f2431', '16cefb1f-f767-5d65-a12c-77c072311e34', 'bde51cac-278c-5c47-aeef-a76786633569', 13, 13, 'ልያም፥ “እኔ ብፅዕት ነኝ፤ ሴቶች ያመሰግኑኛልና” አለች፤ ስሙንም አሴር ብላ ጠራችው።'),
  ('823c05d0-6c6a-5e88-aa23-47782360dc7a', '16cefb1f-f767-5d65-a12c-77c072311e34', 'bde51cac-278c-5c47-aeef-a76786633569', 14, 14, 'ሮቤል ስንዴ በሚታጨድበት ወራት ወጣ፤ በእርሻም እንኮይ አገኘ፥ ለእናቱ ለልያም አመጣላት። ራሔልም ልያን፥ “የልጅሽን እንኮይ ስጪኝ” አለቻት።'),
  ('79bb4720-d3ac-5fb5-a1fa-4a0d58589f26', '16cefb1f-f767-5d65-a12c-77c072311e34', 'bde51cac-278c-5c47-aeef-a76786633569', 15, 15, 'ልያም፥ “ባሌን መውሰድሽ አይበቃሽምን? አሁን ደግሞ የልጄን እንኮይ ልትወስጂ ትፈልጊያለሽን?” አለቻት። ራሔልም “እንኪያስ ስለ ልጅሽ እንኮይ በዚህች ሌሊት ከአንቺ ጋር ይደር” አለች፤ ሰጠቻትም።'),
  ('5f9fcb22-030c-532c-a5a0-61306dc5d59a', '16cefb1f-f767-5d65-a12c-77c072311e34', 'bde51cac-278c-5c47-aeef-a76786633569', 16, 16, 'ያዕቆብም ሲመሽ ከዱር ገባ፤ ልያም ልትቀበለው ወጣች፤ እንዲህም አለችው፥ “እኔ ዘንድ ታድራለህ፤ በልጄ እንኮይ በእርግጥ ተስማምቼሃለሁና።”'),
  ('ae8647c0-8563-5285-a1ba-945dc80e19b5', '16cefb1f-f767-5d65-a12c-77c072311e34', 'bde51cac-278c-5c47-aeef-a76786633569', 17, 17, 'በዚያችም ሌሊት ከእርስዋ ጋር አደረ። እግዚአብሔርም የልያን ጸሎት ሰማ፤ ፀነሰችም፤ አምስተኛ ወንድ ልጅንም ለያዕቆብ ወለደች።'),
  ('fda5f82e-af8e-583a-a83c-752f37be8ebf', '16cefb1f-f767-5d65-a12c-77c072311e34', 'bde51cac-278c-5c47-aeef-a76786633569', 18, 18, 'ልያም፥ “የልጄን እንኮይ ስለ ሰጠሁ እግዚአብሔር ዋጋዬን ሰጠኝ” አለች፤ ስሙንም ይሳኮር ብላ ጠራችው።'),
  ('9ffed619-16fa-505c-a9d5-2e489169e225', '16cefb1f-f767-5d65-a12c-77c072311e34', 'bde51cac-278c-5c47-aeef-a76786633569', 19, 19, 'ልያም ደግማ ፀነስች፤ ስድስተኛ ወንድ ልጅንም ለያዕቆብ ወለደች።'),
  ('9cdc4865-9e0d-5c99-af6b-6ab58f778f66', '16cefb1f-f767-5d65-a12c-77c072311e34', 'bde51cac-278c-5c47-aeef-a76786633569', 20, 20, 'ልያም፥ “እግዚአብሔር መልካም ስጦታን ሰጠኝ፤ እንግዲህስ ከዛሬ ጀምሮ ባሌ ይወደድኛል ስድስት ልጆችን ወልጄለታለሁና” አለች፤ ስሙንም ዛብሎን ብላ ጠራችው።'),
  ('580425bd-18c7-59a0-a17b-59e52307a585', '16cefb1f-f767-5d65-a12c-77c072311e34', 'bde51cac-278c-5c47-aeef-a76786633569', 21, 21, 'ከዚያም በኋላ ሴት ልጅን ወለደች፤ ስምዋንም ዲና አለቻት።'),
  ('49483699-417c-5512-a499-1816af9c7630', '16cefb1f-f767-5d65-a12c-77c072311e34', 'bde51cac-278c-5c47-aeef-a76786633569', 22, 22, 'እግዚአብሔርም ራሔልን አሰባት፤ እግዚአብሔርም ተለመናት፤ ማኅፀንዋንም ከፈተላት፤ ፀነሰችም፤'),
  ('5f8b2fe1-c34b-5cfc-ac4a-e6eb4d37dab0', '16cefb1f-f767-5d65-a12c-77c072311e34', 'bde51cac-278c-5c47-aeef-a76786633569', 23, 23, 'ወንድ ልጅንም ለያዕቆብ ወለደችና፥ “እግዚአብሔር ሽሙጤን ከእኔ አስወገደ” አለች፤'),
  ('143c2d11-de64-5353-ae84-deef6e470bc0', '16cefb1f-f767-5d65-a12c-77c072311e34', 'bde51cac-278c-5c47-aeef-a76786633569', 24, 24, 'ስሙንም፥ “እግዚአብሔር ሁለተኛ ወንድ ልጅን ይጨምርልኝ” ስትል ዮሴፍ ብላ ጠራችው።'),
  ('6e099975-4125-55b3-a39b-3fd797712a21', '16cefb1f-f767-5d65-a12c-77c072311e34', 'ca9d0890-4f5d-5ff7-a27c-e6bf8e3f446e', 1, 25, 'ራሔልም ዮሴፍን ከወለደች በኋላ ያዕቆብ ላባን እንዲህ አለው፥ “ወደ ስፍራዬ፥ ወደ ሀገሬም እመለስ ዘንድ አሰናብተኝ።'),
  ('686e265c-8d3f-53a0-a330-7b4b3abe26e9', '16cefb1f-f767-5d65-a12c-77c072311e34', 'ca9d0890-4f5d-5ff7-a27c-e6bf8e3f446e', 2, 26, 'ስለ እነርሱ የተገዛሁላቸውን ሚስቶቼንና ልጆችን ስጠኝና ልሂድ፤ የተገዛሁልህን መገዛት ታውቃለህና።”'),
  ('73f1e251-21ca-5b43-a463-2fd621ff8700', '16cefb1f-f767-5d65-a12c-77c072311e34', 'ca9d0890-4f5d-5ff7-a27c-e6bf8e3f446e', 3, 27, 'ላባም፥ “በዐይንህ ፊት ሞገስን የማገኝ ብሆንስ ከዚሁ ተቀመጥ፤ እግዚአብሔር በአንተ ምክንያት እንደ ባረከኝ ተመልክቼአለሁና።'),
  ('7830bcee-d184-53cd-aee8-116c53664943', '16cefb1f-f767-5d65-a12c-77c072311e34', 'ca9d0890-4f5d-5ff7-a27c-e6bf8e3f446e', 4, 28, 'ደመወዝህን ንገረኝ፤ እርሱንም እሰጥሃለሁ” አለው።'),
  ('883b2063-16c3-55f1-a622-e1502ad4a155', '16cefb1f-f767-5d65-a12c-77c072311e34', 'ca9d0890-4f5d-5ff7-a27c-e6bf8e3f446e', 5, 29, 'ያዕቆብም አለው፥ “እንዴት እንዳገለገልሁህ፥ በእኔ ዘንድ ያሉ ከብቶችህ ምን ያህል እንደ ሆኑ አታውቅምን? ጥቂት ሆነው አግኝቻቸዋለሁና፤'),
  ('c4799e3e-6d7b-5d4a-a3c8-0c10e28e370e', '16cefb1f-f767-5d65-a12c-77c072311e34', 'ca9d0890-4f5d-5ff7-a27c-e6bf8e3f446e', 6, 30, 'አሁን ግን ፈጽመው በዝተዋል፤ እግዚአብሔርም በእኔ መምጣት ባርኮአቸዋል፤ አሁን ደግሞ ለቤቴ የምሠራው መቼ ነው?”'),
  ('491b9a60-de10-50bd-a8e4-aea0f3015160', '16cefb1f-f767-5d65-a12c-77c072311e34', 'ca9d0890-4f5d-5ff7-a27c-e6bf8e3f446e', 7, 31, 'ላባም፥ “የምሰጥህ ምንድን ነው?” አለው። ያዕቆብም አለው፥ “ምንም አትስጠኝ፤ ይህንም ነገር ብታደርግልኝ እንደገና በጎችህን አሰማራለሁ፤ እጠብቃለሁም።'),
  ('4b3a8662-4f42-5d9e-a4d8-ffd10214fff0', '16cefb1f-f767-5d65-a12c-77c072311e34', 'ca9d0890-4f5d-5ff7-a27c-e6bf8e3f446e', 8, 32, 'ዛሬ በጎችህ ሁሉ ይለፉ፤ በዚያም ከበጎችህ መካከል ዝንጕርጕርና ነቍጣ ያለበትን ጥቁሩንም በግ ሁሉ፥ ከፍየሎቹም ነቍጣና ዝንጕርጕር ያለበትን ለይልኝ፤ እነርሱም ደመወዜ ይሆናሉ።'),
  ('2172476c-27ae-58fb-a6b5-7e93db49d503', '16cefb1f-f767-5d65-a12c-77c072311e34', 'ca9d0890-4f5d-5ff7-a27c-e6bf8e3f446e', 9, 33, 'ስለዚህም በፊትህ ያለውን ደመወዜን ለመመልከት በመጣህ ጊዜ ወደፊት ጻድቅነቴን ይመሰክርልኛል፤ ከፍየሎች ዝንጕርጕርና ነቍጣ የሌለበት፥ ከበግ ጠቦቶችም ጥቁር ያልሆኑ ሁሉ፥ እርሱ በእኔ ዘንድ ቢገኝ እንደ ተሰረቀ ይቈጠርብኝ።”'),
  ('584b7b5d-b858-5770-a978-dfb98ebd66ea', '16cefb1f-f767-5d65-a12c-77c072311e34', 'ca9d0890-4f5d-5ff7-a27c-e6bf8e3f446e', 10, 34, 'ላባም፥ “እነሆ እንደ ቃልህ ይሁን” አለ።'),
  ('417de12f-be9f-51fb-a1a0-44e8495cc768', '16cefb1f-f767-5d65-a12c-77c072311e34', 'ca9d0890-4f5d-5ff7-a27c-e6bf8e3f446e', 11, 35, 'በዚያም ቀን ከተባቶቹ ፍየሎች ሽመልመሌ መሳይና ነቍጣ ያለባቸውን፥ ከእንስቶቹ ፍየሎች ዝንጕርጕርና ነቍጣ ያለባቸውን፥ ነጭ ያለበትን ማንኛውንም ሁሉ፥ ከበጎቹም መካከል ጥቁሩን በግ ሁሉ ለይቶ ለልጆቹ ሰጣቸው።'),
  ('26bfdaad-3f9b-5952-a6f2-e07d48714a78', '16cefb1f-f767-5d65-a12c-77c072311e34', 'ca9d0890-4f5d-5ff7-a27c-e6bf8e3f446e', 12, 36, 'በእርሱና በያዕቆብ መካከልም የሦስት ቀን መንገድ ያህል አራቃቸው፤ ያዕቆብም የቀሩትን የላባን በጎች ይጠብቅ ነበር።'),
  ('32c62125-ae8b-53a4-ad3f-7805c1ed03e1', '16cefb1f-f767-5d65-a12c-77c072311e34', 'ca9d0890-4f5d-5ff7-a27c-e6bf8e3f446e', 13, 37, 'ያዕቆብም ልብን፥ ለውዝ፥ ኤርሞን ከሚባሉ ዕንጨቶች ርጥብ በትርን ወስዶ በበትሮቹ ውስጥ ያለው ነጭ እንዲታይ ነጭ ሽመልመሌ አድርጎ ላጣቸው።'),
  ('ce65db02-e63d-5055-a67b-20ee8ffcfe27', '16cefb1f-f767-5d65-a12c-77c072311e34', 'ca9d0890-4f5d-5ff7-a27c-e6bf8e3f446e', 14, 38, 'በጎቹም ውኃ ሊጠጡ በመጡ ጊዜ በትሮቹ በፊታቸው ይሆኑ ዘንድ የላጣቸውን በትሮች በውኃ ማጠጫ ገንዳው ውስጥ አኖራቸው፤'),
  ('8b6ec069-0867-5243-a141-e4737f62f9ac', '16cefb1f-f767-5d65-a12c-77c072311e34', 'ca9d0890-4f5d-5ff7-a27c-e6bf8e3f446e', 15, 39, 'በጎቹም መጥተው በጠጡ ጊዜ ሽመልመሌ መሳይና ዝንጕርጕር፥ ነቍጣም ያለበትን በበትሮቹ አምሳል ፀነሱ።'),
  ('2d21faf8-fe34-514b-a21c-63f16053405c', '16cefb1f-f767-5d65-a12c-77c072311e34', 'ca9d0890-4f5d-5ff7-a27c-e6bf8e3f446e', 16, 40, 'ያዕቆብም ተባት በጎችንና እንስት በጎችን ለይቶ ነጭና ሐመደ ክቦ በሆኑ አውራዎች ፊት አቆማቸው፤ መንጎቹንም ለብቻቸው አቆማቸው። ከላባ በጎች ጋርም አልጨመራቸውም።'),
  ('427f586b-f6a4-599f-a509-964e436f2c88', '16cefb1f-f767-5d65-a12c-77c072311e34', 'ca9d0890-4f5d-5ff7-a27c-e6bf8e3f446e', 17, 41, 'እንዲህም ሆነ፦ በጎቹ በሚፀንሱበት ወራት በበትሮቹ አምሳል ይፀንሱ ዘንድ ያዕቆብ በትሮቹን በበጎቹ ፊት በውኃ ማጠጫ ገንዳው ውስጥ ያኖራቸው ነበር።'),
  ('4d1771b9-04d7-5246-abc5-2b8fe4197de5', '16cefb1f-f767-5d65-a12c-77c072311e34', 'ca9d0890-4f5d-5ff7-a27c-e6bf8e3f446e', 18, 42, 'በጎችም ከወለዱ በኋላ በፊታቸው በትሩን አያደርገውም ነበር፤ ምልክት ያላቸው ለያዕቆብ፥ ምልክት የሌላቸውም ለላባ ሆኑ።'),
  ('d8208601-3e85-500f-a697-965748e5a670', '16cefb1f-f767-5d65-a12c-77c072311e34', 'ca9d0890-4f5d-5ff7-a27c-e6bf8e3f446e', 19, 43, 'ያዕቆብም እጅግ ባለጠጋ ሆነ፤ ሴቶችም ወንዶችም አገልጋዮች፥ ብዙ ከብትም፤ ላሞችም፥ በጎችም፥ ግመሎችና አህዮችም ሆኑለት።'),
  ('758612d2-7ec4-5a67-a8b5-e68efa52fa4a', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', 'c5a8aca3-0f5d-5447-a04c-70cc5d272bda', 1, 1, 'ያዕቆብም የላባ ልጆች ያሉትን ነገር፥ “ያዕቆብ ለአባታችን የሆነውን ሁሉ ወሰደ፤ ይህንም ሁሉ ክብር ከአባታችን ከብት አገኘ” ሲሉ ሰማ።'),
  ('c5f9ebb5-4225-5613-aaf2-d7baf46af5cf', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', 'c5a8aca3-0f5d-5447-a04c-70cc5d272bda', 2, 2, 'ያዕቆብም የላባን ፊት አየ፤ እነሆም፥ ከእርሱ ጋር እንደ ዱሮው አልሆነም።'),
  ('238b4a2c-0343-5436-a41f-193ad4266631', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', 'c5a8aca3-0f5d-5447-a04c-70cc5d272bda', 3, 3, 'እግዚአብሔርም ያዕቆብን፥ “ወደ አባትህና ወደ ዘመዶችህ ሀገር ተመለስ፤ እኔም ከአንተ ጋር እሆናለሁ” አለው።'),
  ('c56beda7-7165-5ef1-ab29-3af9f693deb4', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', 'c5a8aca3-0f5d-5447-a04c-70cc5d272bda', 4, 4, 'ያዕቆብም ልኮ ራሔልንና ልያን ወደ በጎቹ መሰማሪያ ወደ ሜዳ ጠራቸው፤'),
  ('d10361b9-e307-5b4c-ab5c-bfaff862e33d', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', 'c5a8aca3-0f5d-5447-a04c-70cc5d272bda', 5, 5, 'እንዲህም አላቸው፥ “እነሆ፥ የአባታችሁ ፊት እንደ ዱሮ ከእኔ ጋር እንዳልሆነ አያለሁ፤ ነገር ግን የአባቴ አምላክ ከእኔ ጋር ነው።'),
  ('60082788-7060-59c2-a4b1-9ff6d0ed0ae2', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', 'c5a8aca3-0f5d-5447-a04c-70cc5d272bda', 6, 6, 'እኔ ባለኝ ጕልበቴ ሁሉ አባታችሁን እንዳገለገልሁ ታውቃላችሁ።'),
  ('8992e630-60de-59ab-a95e-b7c51bdbe68f', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', 'c5a8aca3-0f5d-5447-a04c-70cc5d272bda', 7, 7, 'አባታችሁ ግን አሳዘነኝ፥ ደመወዜንም ዐሥር ጊዜ ለወጠ፤ እግዚአብሔር ግን ክፉን ያደርግብኝ ዘንድ አልፈቀደለትም።'),
  ('8230fb98-f241-5090-acc8-cd2b33752a4d', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', 'c5a8aca3-0f5d-5447-a04c-70cc5d272bda', 8, 8, 'ደመወዝህ ዝንጕርጕሮቹ ይሁኑ ቢለኝ በጎቹ ሁሉ ዝንጕርጕሮችን ወለዱ፤ ነጫጮቹ ደመወዝህ ይሁኑ ቢለኝ በጎቹ ሁሉ ነጫጮችን ወለዱ።'),
  ('cfb0bc72-3129-5d58-ac24-7c37023691b9', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', 'c5a8aca3-0f5d-5447-a04c-70cc5d272bda', 9, 9, 'እግዚአብሔርም የአባታችሁን በጎች ሁሉ ነሥቶ ለእኔ ሰጠኝ።'),
  ('28ddf198-f48b-523f-ad8a-9e3b4e7a6329', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', 'c5a8aca3-0f5d-5447-a04c-70cc5d272bda', 10, 10, 'እንዲህም ሆነ፤ በጎቹ በሚፀንሱ ጊዜ ዐይኔን አንሥቼ በሕልም አየሁ፤ እነሆም፥ በበጎችና በፍየሎች ላይ የሚንጠላጠሉት የበጎችና የፍየሎች አውራዎች ነጭ፥ ዝንጕርጕሮችና ሐመደ ክቦ ነበሩ።'),
  ('19700d5e-fcb1-5d04-a49f-8076b7cb488a', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', 'c5a8aca3-0f5d-5447-a04c-70cc5d272bda', 11, 11, 'እግዚአብሔርም በሕልም፦ ‘ያዕቆብ ያዕቆብ’ አለኝ፤ እኔም፦ ‘እነሆኝ ምንድን ነው?’ አልሁት።'),
  ('310c550a-0ebf-5b05-a807-86c931693c1c', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', 'c5a8aca3-0f5d-5447-a04c-70cc5d272bda', 12, 12, 'እንዲህም አለኝ፦ ዐይንህን አቅንተህ እይ፤ በበጎችና በፍየሎች ላይ የሚንጠላጠሉት የበጎችና የፍየሎች አውራዎች ነጭ፥ ሐመደ ክቦና ዝንጕርጕሮች ናቸው፤ ላባ በአንተ ላይ የሚያደርገውን አይቻለሁና።'),
  ('eca7255d-1b88-56bb-a853-b0cdf6b68196', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', 'c5a8aca3-0f5d-5447-a04c-70cc5d272bda', 13, 13, 'ሐውልቱን ዘይት በቀባህባት፥ በዚያች ለእኔ ስእለት በተሳልህባት ሀገር የተገለጥሁልህ ፈጣሪህ እግዚአብሔር እኔ ነኝ። አሁንም ተነሥተህ ከዚህ ሀገር ውጣ፤ ወደ ተወለድህባትም ምድር ተመለስ፤ እኔም ከአንተ ጋር እኖራለሁ።”'),
  ('0c66a3b4-288f-5668-afda-f0a889d54224', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', 'c5a8aca3-0f5d-5447-a04c-70cc5d272bda', 14, 14, 'ራሔልና ልያም መልሰው እንዲህ አሉት፥ “በአባታችን ቤት ለእኛ ድርሻ ወይም ርስት በውኑ አለን?'),
  ('23b4b693-2121-5b5f-adc5-d9b7434d2b9c', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', 'c5a8aca3-0f5d-5447-a04c-70cc5d272bda', 15, 15, 'እኛ በእርሱ ዘንድ እንደ ባዕድ የተቈጠርን አይደለምን? እርሱ እኛን ሽጦ ዋጋችንን በልቶአልና።'),
  ('77493f82-fcca-5c1b-a870-8fc94c5098ee', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', 'c5a8aca3-0f5d-5447-a04c-70cc5d272bda', 16, 16, 'ስለዚህም እግዚአብሔር ከአባታችን የነሣው ይህ ሁሉ ሀብትና ክብር ለእኛና ለልጆቻችን ነው፤ አሁንም እግዚአብሔር ያለህን ሁሉ አድርግ።”'),
  ('f78fc270-3c94-5066-a827-a6d803d14118', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', 'c5a8aca3-0f5d-5447-a04c-70cc5d272bda', 17, 17, 'ያዕቆብም ተነሣ፤ ልጆቹንና ሚስቶቹንም በግመሎች ላይ አስቀመጠ።'),
  ('0518bac9-50e2-5d8b-a3a6-b80ccfb63b2c', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', 'c5a8aca3-0f5d-5447-a04c-70cc5d272bda', 18, 18, 'መንጎቹንም ሁሉ፥ የቤቱንም ዕቃ ሁሉ፥ በሁለቱ ወንዞች መካከል ሳለ ያገኛቸውን ከብቶች ሁሉ ይዞ ወደ አባቱ ወደ ይስሐቅ ወደ ከነዓን ምድር ሄደ።'),
  ('c9d0b66b-41fd-5336-a5de-c50bad80622d', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', 'c5a8aca3-0f5d-5447-a04c-70cc5d272bda', 19, 19, 'ላባ ግን በጎቹን ለመሸለት ሄዶ ነበር፤ ራሔልም የአባቷን ጣዖቶች ሰረቀች።'),
  ('9b570aad-dc66-594f-a841-569cd80f1b3c', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', 'c5a8aca3-0f5d-5447-a04c-70cc5d272bda', 20, 20, 'ያዕቆብም ነገሩን ከሶርያዊው ከላባ ሰወረ፤ እንደሚሄድም አልነገረውም።'),
  ('0ed75162-e81e-5f08-a70e-7b669d601306', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', 'c5a8aca3-0f5d-5447-a04c-70cc5d272bda', 21, 21, 'እርሱም ያለውን ሁሉ ይዞ ኰበለለ፤ ተነሥቶም ወንዙን ተሻገረ፤ በገለዓድ ተራራም አደረ።'),
  ('9ec39fd8-9d56-59ca-a18a-8c31c9baa35c', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '509531bb-a9d3-5ce5-ab77-088b7b77c3fa', 1, 22, 'ለሶርያዊው ላባም ያዕቆብ እንደ ኰበለለ ነገሩት።'),
  ('dd0f64ac-3b40-5bfa-a604-684fbe298673', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '509531bb-a9d3-5ce5-ab77-088b7b77c3fa', 2, 23, 'ላባም ወንድሞቹን ሁሉ ይዞ የሦስት ቀን መንገድ ተከተላቸው፤ በገለዓድ ተራራም ላይ አገኛቸው።'),
  ('605067d7-4c74-540b-a7b1-1254f50329f9', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '509531bb-a9d3-5ce5-ab77-088b7b77c3fa', 3, 24, 'እግዚአብሔርም ወደ ሶርያዊው ወደ ላባ በሌሊት በሕልም መጥቶ፥ “በባሪያዬ በያዕቆብ ላይ ክፉ ነገር እንዳትናገር ተጠንቀቅ” አለው።'),
  ('be61eb85-b1e7-5981-a093-71a9e4a23a08', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '509531bb-a9d3-5ce5-ab77-088b7b77c3fa', 4, 25, 'ላባም ያዕቆብን አገኘው፤ ያዕቆብም ድንኳኑን በተራራው ላይ ተክሎ ነበር፤ ላባም ወንድሞቹን በገለዓድ ተራራ አስቀመጣቸው።'),
  ('9233ffdc-0de0-5364-aefa-eddad0627876', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '509531bb-a9d3-5ce5-ab77-088b7b77c3fa', 5, 26, 'ላባም ያዕቆብን አለው፥ “ለምን እንዲህ አደረግህ? ከእኔ በስውር የኰበለልህ? ልጆችንስ ሰርቀህ በሰይፍ እንደማረከ የወሰድኻቸው?'),
  ('b7daf24d-edec-50a7-a614-7f5a2222d5ef', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '509531bb-a9d3-5ce5-ab77-088b7b77c3fa', 6, 27, 'ብትነግረኝ ኑሮ በደስታና በሐሴት፥ በዘፈን፥ በከበሮና በበገና በሸኘሁህ ነበር።'),
  ('1fa7a457-b65b-52c4-ad6e-cbd69ea8cb00', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '509531bb-a9d3-5ce5-ab77-088b7b77c3fa', 7, 28, 'ወይስ ወንዶቹንና ሴቶቹን ልጆችን እስም ዘንድ አይገባኝምን? አሁንም ይህን እንደ አላዋቂ አደረግህ።'),
  ('a7d665cb-475e-501a-af5b-227cf35b713f', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '509531bb-a9d3-5ce5-ab77-088b7b77c3fa', 8, 29, 'አሁንም በአንተ ላይ ክፉ ማድረግ በቻልሁ ነበር፤ ነገር ግን የአባትህ አምላክ ትናንት፦ በያዕቆብ ላይ ክፉ እንዳታደርግ ተጠንቀቅ ብሎ ነገረኝ።'),
  ('1389711e-202f-5b3c-a1ec-5f03bb72fbe6', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '509531bb-a9d3-5ce5-ab77-088b7b77c3fa', 9, 30, 'አሁንም የአባትህን ቤት ከናፈቅህ ሂድ፤ ነገር ግን አምላኮቼን ለምን ሰረቅህ?”'),
  ('b57e9c79-b6fd-5338-a466-a28129543a26', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '509531bb-a9d3-5ce5-ab77-088b7b77c3fa', 10, 31, 'ያዕቆብም መለሰ፤ ላባንም እንዲህ አለው፥ “ልጆችህንና ገንዘቤን ሁሉ ከእኔ የምትቀማኝ ስለመሰለኝና ስለፈራሁ ይህን አደረግሁ።”'),
  ('ae1ccb22-117e-54b4-a3ed-b718ae887710', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '509531bb-a9d3-5ce5-ab77-088b7b77c3fa', 11, 32, 'ያዕቆብም አለ፥ “አምላኮችህን የምታገኝበት ሰው ግን እርሱ ይሙት፤ ገንዘብህም በእኔ ዘንድ ካለ በወንድሞቻችን ፊት እይ፤ ለአንተም ውሰደው” አለ። ያዕቆብ ሚስቱ ራሔል እንደ ሰረቀቻቸው አያውቅም ነበርና።'),
  ('33f6121a-f530-5403-a139-8468ccae67da', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '509531bb-a9d3-5ce5-ab77-088b7b77c3fa', 12, 33, 'ላባም ወደ ያዕቆብ ድንኳንና ወደ ልያም ድንኳን ገባና በረበረ፤ አላገኘምም፤ ከዚያም ወጣና ወደ ሁለቱ ዕቁባቶቹ ድንኳን ገባ፤ ነገር ግን አላገኘም። ወደ ራሔልም ድንኳን ገባ።'),
  ('56940f84-d0ac-52f2-af93-46eede15c5b8', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '509531bb-a9d3-5ce5-ab77-088b7b77c3fa', 13, 34, 'ራሔልም የአባቷን ጣዖቶች ወስዳ ከግመል ኮርቻ በታች ሸሸገች፤ በላዩም ተቀመጠችበት። ላባም ድንኳኑን ሁሉ ፈለገ፤ አንዳችም አላገኘም።'),
  ('912ba4f4-8f3f-5fd8-a808-fc21dccab20f', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '509531bb-a9d3-5ce5-ab77-088b7b77c3fa', 14, 35, 'እርስዋም አባቷን፥ “ጌታዬ በፊትህ ለመቆም ስላልቻልሁ የአቀለልሁህ አይምሰልህ፤ በሴቶች የሚደርስ ግዳጅ ደርሶብኛልና” አለችው። ላባም የራሔልን ድንኳን በረበረ፤ ነገር ግን ጣዖቶቹን አላገኘም።'),
  ('d19f6947-bf8e-5173-a0a8-d7527c50095a', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '509531bb-a9d3-5ce5-ab77-088b7b77c3fa', 15, 36, 'ያዕቆብም ተቈጣ፤ ላባንም ወቀሰው፤ ያዕቆብም መለሰ፤ ላባንም እንዲህ አለው፥ “የበደልሁህ በደል ምንድን ነው? ኀጢአቴስ ምንድን ነው? ይህን ያህል ያሳደድኸኝ?'),
  ('ad6112aa-f40a-59cd-aa66-77b75c0d2b14', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '509531bb-a9d3-5ce5-ab77-088b7b77c3fa', 16, 37, 'አሁንም ዕቃዬን ሁሉ በረበርህ፤ ከቤትህስ ዕቃ ሁሉ ምን አገኘህ? እነርሱ በእኛ በሁለታችን መካከል ይፈርዱ ዘንድ በወንድሞችና በወንድሞችህ ፊት አቅርበው።'),
  ('5bdc010d-fdb0-5df8-aca3-c6a598cfbade', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '509531bb-a9d3-5ce5-ab77-088b7b77c3fa', 17, 38, 'ሃያ አንድ ዓመት በጎችህንና ፍየሎችህን ስጠብቅ ኖርሁ፥ ከበጎችህም ጠቦቶችን አልበላሁም፤'),
  ('62633ecd-12c7-5a47-ae5a-691ab4d5bd52', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '509531bb-a9d3-5ce5-ab77-088b7b77c3fa', 18, 39, 'አውሬ የሰበረውንም አላመጣሁልህም ነበር፤ በቀንም ሆነ በሌሊት የተሰረቀ ቢኖር ከእኔ እከፍልህ ነበር።'),
  ('0ead6991-97d4-584d-a367-f7fd77887f84', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '509531bb-a9d3-5ce5-ab77-088b7b77c3fa', 19, 40, 'የቀን ሐሩር፥ የሌሊት ቍር ይበላኝ ነበር፤ ዕንቅልፍም ከዐይኔ ጠፋ።'),
  ('b7c73bf5-d11e-53d2-a241-a97613910186', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '509531bb-a9d3-5ce5-ab77-088b7b77c3fa', 20, 41, 'ለአንተ ቤት የተገዛሁልህ ዛሬ ሃያ አንድ ዓመት ነው፤ ዐሥራ አራት ዓመት ስለ ሁለቱ ሴቶች ልጆችህ፥ ሰባት ዓመት ስለ በጎችህ ተገዛሁልህ፤ ደመወዜንም ዐሥር ጊዜ ለዋወጥኸው።'),
  ('0343dee8-1008-5392-af9c-789c9329adb9', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '509531bb-a9d3-5ce5-ab77-088b7b77c3fa', 21, 42, 'የአባቴ የአብርሃም አምላክ የይስሐቅም ፍርሀት ከእኔ ጋር ባይሆንስ ዛሬ ባዶ እጄን በሰደድኸኝ ነበር፤ እግዚአብሔር መዋረዴንና የእጆችን ድካም አየ፤ ትናንትም ገሠጸህ።”'),
  ('045fa2d4-08e3-51c4-aa0e-85424edc22e7', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '699ebe0e-88de-5387-addc-08238b39c42f', 1, 43, 'ላባም ለያዕቆብ እንዲህ ብሎ መለሰለት፥ “ሴቶቹ ልጆች ልጆች ናቸው፤ ወንዶቹም ልጆች ልጆች ናቸው፤ መንጎቹም ከብቶች ናቸው፤ ይህ የምታየው ሁሉ የእኔ ነው፤ የልጆችም ሀብት ነው፤ ዛሬም በእነዚህ በሴቶች ልጆችና በወለዱአቸው ልጆቻቸው ላይ ምን አደርጋለሁ?'),
  ('8db614ca-cd17-52ed-aa16-f8f5d78e9499', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '699ebe0e-88de-5387-addc-08238b39c42f', 2, 44, 'አሁንም ና፤ አንተና እኔ ቃል ኪዳን እንጋባ፤ በእኔና በአንተ መካከል ምስክር ይሁን።”'),
  ('a4d2257b-2aa1-54ba-ae91-adfcaabbb6aa', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '699ebe0e-88de-5387-addc-08238b39c42f', 3, 45, 'ያዕቆብም ድንጋይ ወስዶ ሐውልት አቆመ።'),
  ('51103d44-4871-5e52-af3b-3a231e125320', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '699ebe0e-88de-5387-addc-08238b39c42f', 4, 46, 'ያዕቆብም ወንድሞቹን፥ “ድንጋይ ሰብስቡ” አላቸው፤ እነርሱም ድንጋይ ሰብስበው ከመሩ፤ በድንጋዩም ክምር ላይ በሉ።'),
  ('dfa91027-1d69-5235-a2b8-fcfb9c1ab9c9', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '699ebe0e-88de-5387-addc-08238b39c42f', 5, 47, 'ላባም፥ “ይህች የድንጋይ ክምር በእኔና በአንተ መካከል ምስክር ትሁን” አለው። ላባም “ወግረ ስምዕ” ብሎ ጠራት፤ ያዕቆብም እንዲሁ አላት።'),
  ('5a9e2a76-2a8b-5745-a140-b43d69bcad0e', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '699ebe0e-88de-5387-addc-08238b39c42f', 6, 48, 'ላባም፥ “ይህች ያቆምኋት የድንጋይ ክምር በእኔና በአንተ መካከል ዛሬ ምስክር ናት” አለ። ስለዚህም ስምዋ ወግረ ስምዕ ተባለ።'),
  ('46116606-4bef-5aa4-a661-8fe398ef961f', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '699ebe0e-88de-5387-addc-08238b39c42f', 7, 49, 'ላባም አለው፥ “እኛ አንዳችን ከሌላው እንለያያለንና ራእይን የገለጠልኝ እግዚአብሔር በእኔና በአንተ መካከል ሆኖ ይመልከት።'),
  ('3cdfa570-da40-59fb-ae03-35dc6db01c58', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '699ebe0e-88de-5387-addc-08238b39c42f', 8, 50, 'ልጆችን ብትበድላቸው ወይም በላያቸው ላይ ሚስቶችን ብታገባባቸው እነሆ፥ ከእኛ ጋር ያለ ሰው እንደሌለ አስተውል፤ እግዚአብሔር በእኔና በአንተ መካከል ምስክር ነው።”'),
  ('db7e9f53-3458-5189-ab99-380659265aad', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '699ebe0e-88de-5387-addc-08238b39c42f', 9, 51, 'ላባም ያዕቆብን አለው፥ “እነሆ፥ ይህች የድንጋይ ክምርና ይህችም ሐውልት ምስክሮች ናቸው።'),
  ('08f2ee50-da50-5079-ae82-d68738d95fd7', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '699ebe0e-88de-5387-addc-08238b39c42f', 10, 52, 'እኔ ወደ አንተ በክፋት ባልፍ ይህች የድንጋይ ክምር፥ ይህችም ሐውልት በክፉ ነገር ትከተለኝ።'),
  ('5bb06812-2ef9-520d-ab1b-ba5dd8217228', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '699ebe0e-88de-5387-addc-08238b39c42f', 11, 53, 'አንተም ወደ እኔ ብታልፍ የአብርሃም አምላክ የናኮርም አምላክ በእኛ መካከል ይፍረድ።” ያዕቆብም በአባቱ በይስሐቅ አምላክ ማለ።'),
  ('18ec6e31-5327-5d65-a7c1-d802a9cde5d6', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '699ebe0e-88de-5387-addc-08238b39c42f', 12, 54, 'ያዕቆብም በተራራው ላይ መሥዋዕትን ሠዋ፤ ወንድሞቹንም ጠራ፤ እነርሱም በሉ፤ ጠጡም፤ በዚያም በተራራው አደሩ።'),
  ('f140de9d-1836-57b0-a7cb-e1237fab05a6', '9bcf337f-99b0-5340-ad5a-1a6429d37bd7', '699ebe0e-88de-5387-addc-08238b39c42f', 13, 55, 'ላባም ማልዶ ተነሥቶ ወንዶችንና ሴቶችን ልጆቹን ሳመ፤ ባረካቸውም፤ ላባም ተመልሶ ወደ ስፍራው ሄደ።'),
  ('26b3f9d2-4e53-516e-a424-a9fb25ab5885', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', '6108a9f1-3619-521e-a805-118d17bfd132', 1, 1, 'ያዕቆብም መንገዱን ሄደ፤ በዐይኖቹም የእግዚአብሔርን ሠራዊት ከትመው አየ፤ የእግዚአብሔር መላእክትም ተገናኙት።'),
  ('dcc34259-480a-5bbc-aa12-8634e3caf3f5', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', '6108a9f1-3619-521e-a805-118d17bfd132', 2, 2, 'ያዕቆብም በአያቸው ጊዜ፥ “እነዚህ የእግዚአብሔር ሠራዊት ናቸው” አለ፤ የዚያንም ስፍራ ስም “ተዓይን” ብሎ ጠራው።'),
  ('33062fbc-711b-5a07-a67c-849721fcbc8e', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', '6108a9f1-3619-521e-a805-118d17bfd132', 3, 3, 'ያዕቆብም ወደ ወንድሙ ወደ ዔሳው ወደ ሴይር ምድር ወደ ኤዶም ሀገር በፊቱ መልእክተኞችን ላከ፤'),
  ('66b75aee-71ef-552a-aa44-02f1e0c3e4d7', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', '6108a9f1-3619-521e-a805-118d17bfd132', 4, 4, 'እንዲህም ብሎ አዘዛቸው፥ “ለጌታዬ ለዔሳው፦ ባሪያህ ያዕቆብ እንዲህ አለ ብላችሁ ንገሩት፦ በላባ ዘንድ በስደት ተቀመጥሁ፤ እስከ ዛሬ ድረስ ቈየሁ፤'),
  ('f57a9204-7495-5e17-a083-0577d3d5db3e', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', '6108a9f1-3619-521e-a805-118d17bfd132', 5, 5, 'ላሞችንም፥ ግመሎችንም፥ አህዮችንም፥ በጎችንም፥ ወንዶች አገልጋዮችንም፥ ሴቶች አገልጋዮችንም አገኘሁ፤ አሁንም በፊትህ ሞገስን አገኝ ዘንድ ለጌታዬ ለዔሳው ለመንገር ላክሁ።”'),
  ('4615322d-83de-532a-af6c-c9a1c24fed42', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', '6108a9f1-3619-521e-a805-118d17bfd132', 6, 6, 'የላካቸው መልእክተኞችም ወደ ያዕቆብ ተመልሰው እንዲህ አሉት፥ “ወደ ወንድምህ ወደ ዔሳው ሄደን ነበር፤ እርሱም ደግሞ ሊቀበልህ ይመጣል፤ ከእርሱም ጋር አራት መቶ ሰዎች አሉ።”'),
  ('64a1381d-5762-5b4a-a1e1-cd2f72d2a0e6', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', '6108a9f1-3619-521e-a805-118d17bfd132', 7, 7, 'ያዕቆብም እጅግ ፈራ፤ የሚያደርገውንም አጣ። ከእርሱም ጋር ያሉትን ሰዎች ላሞችንም፥ ግመሎችንም፥ በጎችንም ሁለት ወገን አድርጎ ከፈላቸው፤'),
  ('d10bf23b-2e8e-555c-a131-bf36e7487e1d', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', '6108a9f1-3619-521e-a805-118d17bfd132', 8, 8, 'ያዕቆብም እንዲህ አለ፥ “ዔሳው መጥቶ አንዱን ወገን የመታ እንደ ሆነ የቀረው ወገን ይድናል።”'),
  ('9cb6527c-1664-5278-aef6-f50b984eb9d7', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', '6108a9f1-3619-521e-a805-118d17bfd132', 9, 9, 'ያዕቆብም አለ፥ “የአባቴ የአብርሃም አምላክ ሆይ፥ የአባቴ የይስሐቅ አምላክ ሆይ፥ ‘ወደ ምድርህ ወደ ተወለድህበትም ስፍራ ተመለስ፤ በጎነትንም አደርግልሃለሁ’ ያልኸኝ እግዚአብሔር ሆይ፥'),
  ('f355a103-a8b6-543d-a7da-a405879c39ba', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', '6108a9f1-3619-521e-a805-118d17bfd132', 10, 10, 'ለባሪያህ በአደረግኸው በምሕረትህና በእውነትህም ሁሉ በጎውን አድርግልኝ፤ በትሬን ብቻ ይዤ ይህን ዮርዳኖስን ተሻግሬ ነበርና፥ አሁን ግን የሁለት ክፍል ሠራዊት ሆንሁ።'),
  ('da7d2c9c-117d-56ce-abd5-535c02a0ac83', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', '6108a9f1-3619-521e-a805-118d17bfd132', 11, 11, 'አቤቱ ከወንድሜ ከዔሳው እጅ አድነኝ፤ መጥቶ እንዳያጠፋኝ፥ እናትን ከልጆችዋ ጋር እንዳያጠፋ እኔ እፈራዋለሁና።'),
  ('fdaa52df-ce24-5960-abfd-81696840a454', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', '6108a9f1-3619-521e-a805-118d17bfd132', 12, 12, 'አንተም፦ ‘በርግጥ መልካም አደርግልሃለሁ፥ ዘርህንም ከብዛቱ የተነሣ እንደማይቈጠር እንደ ባሕር አሸዋ አደርጋለሁ ብለህ ነበር።’ ”'),
  ('e75eeae1-79a8-5c3e-a083-2b4108c4c5ea', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', '6108a9f1-3619-521e-a805-118d17bfd132', 13, 13, 'በዚያችም ሌሊት በዚያው አደረ። ለወንድሙ ለዔሳውም የሚወስደውን እጅ መንሻ አወጣ፤'),
  ('906540c2-acc1-5708-a9d0-9171db4b2733', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', '6108a9f1-3619-521e-a805-118d17bfd132', 14, 14, 'ሁለት መቶ እንስት ፍየሎችንና ሃያ የፍየል አውራዎችን፥ ሁለት መቶ እንስት በጎችንና ሃያ የበግ አውራዎችን፥'),
  ('4ad044d6-aba6-59e0-aed9-8e447a340111', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', '6108a9f1-3619-521e-a805-118d17bfd132', 15, 15, 'ሃምሳ የሚያጠቡ ግመሎችን ከግልገሎቻቸው ጋር፥ አርባ ላም፥ ዐሥር በሬ፥ ሃያ እንስት አህያ፥ ዐሥርም የአህያ ውርንጫዎች፤'),
  ('b68d079b-32f8-5e71-a5f7-8f9efe6b85da', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', '6108a9f1-3619-521e-a805-118d17bfd132', 16, 16, 'መንጎቹንም ለየብቻ ከፍሎ ለብላቴኖቹ ሰጣቸው፤ ብላቴኖቹንም፥ “በፊቴ እለፉ፤ መንጋውን ከመንጋው አርቁ” አላቸው።'),
  ('45bb2d5e-2d03-5490-af45-ea29748f5aa7', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', '6108a9f1-3619-521e-a805-118d17bfd132', 17, 17, 'የፊተኛውንም እንዲህ ብሎ አዘዘው፥ “ወንድሜ ዔሳው ያገኘህ እንደ ሆነ፦ ‘አንተ የማን ነህ? ወዴትስ ትሄዳለሀ? በፊትህ ያለው ይህስ መንጋ የማን ነው?’ ብሎ የጠየቀህም እንደሆነ፥'),
  ('d195266f-73c9-5d8d-a400-3d178d2bf0fd', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', '6108a9f1-3619-521e-a805-118d17bfd132', 18, 18, 'በዚያ ጊዜ አንተ፦ ‘ለጌታዬ ለዔሳው እጅ መንሻ የላከው የአገልጋይህ የያዕቆብ ነው፤ እርሱም ደግሞ እነሆ ከኋላችን ተከትሎናል’ በለው።”'),
  ('8c31d097-49ff-5255-a910-9ef7f1d41f80', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', '6108a9f1-3619-521e-a805-118d17bfd132', 19, 19, 'እንዲሁም ሁለተኛውንና ሦስተኛውን፥ በፊቱ የሚሄዱትንና መንጋውን የሚነዱትን ሁሉ እንዲሁ ብሎ አዘዘ፦“ ወንድሜ ዔሳውን ባገኛችሁት ጊዜ ይህንኑ ነገር ንገሩት፤'),
  ('18c357b7-2e6a-52ec-aaba-8d3dc1af5079', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', '6108a9f1-3619-521e-a805-118d17bfd132', 20, 20, 'እንዲህም በሉ፦ እነሆ አገልጋይህ ያዕቆብ ከኋላችን ነው። በፊቴ በሚሄደው እጅ መንሻ እታረቀዋለሁ፤ ከዚያም በኋላ ምናልባት ይራራልኛል፤ ፊቱንም አያለሁ ብሎአልና።”'),
  ('7148b5f1-a2f9-50d0-a80b-64bf8ffe0f9e', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', '6108a9f1-3619-521e-a805-118d17bfd132', 21, 21, 'እጅ መንሻውን ከእርሱ አስቀድሞ ላከ፤ እርሱ ግን በዚያች ሌሊት በሰፈር አደረ።'),
  ('3ca20597-4927-5023-adf7-fd6d57420378', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', 'd698ba74-7ec1-52f3-a325-353806831c8b', 1, 22, 'በዚያችም ሌሊት ተነሣ፥ ሁለቱን ሚስቶቹንና ሁለቱን ዕቁባቶቹን ዐሥራ አንዱንም ልጆቹን ይዞ የያቦቅን ወንዝ ተሻገረ።'),
  ('52d19807-5680-562e-a51a-83a20643cbae', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', 'd698ba74-7ec1-52f3-a325-353806831c8b', 2, 23, 'ወሰዳቸውም፤ ወንዙንም አሻገራቸው፤ ገንዘቡንም ሁሉ አሻገረ።'),
  ('8405d0f6-ff3e-558e-a142-2beaf60b26f7', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', 'd698ba74-7ec1-52f3-a325-353806831c8b', 3, 24, 'ያዕቆብ ግን ለብቻው ቀረ፤ አንድ ሰውም እስከ ንጋት ድረስ ይታገለው ነበር።'),
  ('ae5c1b08-0fca-5d4e-af30-207114087b74', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', 'd698ba74-7ec1-52f3-a325-353806831c8b', 4, 25, 'እንዳላሸነፈውም ባየ ጊዜ የጭኑን ሹልዳ ያዘው፤ የያዕቆብም የጭኑ ሹልዳ ሲታገለው ደነዘዘ።'),
  ('5e95cb42-90ca-5ff9-a4fe-5f9ab9caf232', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', 'd698ba74-7ec1-52f3-a325-353806831c8b', 5, 26, 'እንዲህም አለው፥ “ሊነጋ ጎሕ ቀድዶአልና ልቀቀኝ።” እርሱም “ከአልባረክኸኝ አልለቅህም” አለው።'),
  ('ffe10f41-86b5-5e99-a7a5-d48cb5228698', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', 'd698ba74-7ec1-52f3-a325-353806831c8b', 6, 27, 'እንዲህም አለው፥ “ስምህ ማን ነው?” እርሱም፥ “ያዕቆብ ነኝ” አለው።'),
  ('6320483d-2932-59fd-a707-3e0c64309633', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', 'd698ba74-7ec1-52f3-a325-353806831c8b', 7, 28, 'አለውም፥ “ከእንግዲህ ወዲህ ስምህ እስራኤል ይባል እንጂ ያዕቆብ አይባል፤ ከእግዚአብሔርና ከሰው ጋር ታግለህ በርትተሃልና።”'),
  ('56cf147f-5271-5354-a29d-8c632791fec2', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', 'd698ba74-7ec1-52f3-a325-353806831c8b', 8, 29, 'ያዕቆብም፥ “ስምህን ንገረኝ” ብሎ ጠየቀው። እርሱም፥ “ስሜን ለምን ትጠይቃለህ? ድንቅ ነውና” አለው።'),
  ('1ad16c9a-e541-520e-a12d-821b8e648582', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', 'd698ba74-7ec1-52f3-a325-353806831c8b', 9, 30, 'በዚያም ስፍራ ባረከው። ያዕቆብም፥ “እግዚአብሔርን ፊት ለፊት አየሁ፤ ሰውነቴም ዳነች” ሲል የዚያን ቦታ ስም “ራእየ እግዚአብሔር” ብሎ ጠራው።'),
  ('1f562ea8-a763-5929-a9e0-413cd492affa', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', 'd698ba74-7ec1-52f3-a325-353806831c8b', 10, 31, 'ራእየ እግዚአብሔርንም በተወ ጊዜ ፀሐይ ወጣችበት። እርሱም በጭኑ ምክንያት ያነክስ ነበር።'),
  ('cb4443ae-d24e-5ded-a4b2-dd3df211195c', '9fd13f7f-fe96-5e09-af34-ca76f014bf3d', 'd698ba74-7ec1-52f3-a325-353806831c8b', 11, 32, 'ስለዚህም የእስራኤል ልጆች እስከ ዛሬ ድረስ የወርችን ሹልዳ አይበሉም፤ የያዕቆብን ጭን ይዞ የወርቹን ሹልዳ አደንዝዞአልና።'),
  ('8ef8d7f7-a740-57db-a62e-16439d50bde5', '2869276e-5c02-55b1-a9ca-5b9200962a57', 'b8d8cb01-409e-5638-a6a4-3ab2a206d7a0', 1, 1, 'ያዕቆብም ዐይኑን አነሣ፤ እነሆም፥ ዔሳውን ሲመጣ አየው፤ ከእርሱም ጋር አራት መቶ ሰዎች ነበሩ፤ ልጆቹንም ከፍሎ ወደ ልያና ወደ ራሔል ወደ ሁለቱም ዕቁባቶቹ አደረጋቸው፤'),
  ('025f71c1-03d9-5c3c-a6f2-422b3fa5f603', '2869276e-5c02-55b1-a9ca-5b9200962a57', 'b8d8cb01-409e-5638-a6a4-3ab2a206d7a0', 2, 2, 'ዕቁባቶቹንና ልጆቻቸውንም በፊት አደረገ፤ ልያንና ልጆችዋን በኋላ፥ ራሔልንና ዮሴፍንም ከሁሉ በኋላ አደረገ።'),
  ('f4261ee8-d693-54e9-ae5d-ac64a450cd7c', '2869276e-5c02-55b1-a9ca-5b9200962a57', 'b8d8cb01-409e-5638-a6a4-3ab2a206d7a0', 3, 3, 'እርሱም በፊታቸው አለፈ፤ ወደ ወንድሙ ወደ ዔሳውም እስኪደርስ ድረስ ወደ ምድር ሰባት ጊዜ ሰገደ።'),
  ('d5f9044c-9fcc-5bf0-ac32-cae1f7a78be0', '2869276e-5c02-55b1-a9ca-5b9200962a57', 'b8d8cb01-409e-5638-a6a4-3ab2a206d7a0', 4, 4, 'ዔሳውም ሊገናኘው ሮጠ፤ አንገቱንም አቅፎ ሳመው፤ ሁለቱም በአንድነት አለቀሱ።'),
  ('fc9dfe16-214a-5e82-a612-39898f3aa7cf', '2869276e-5c02-55b1-a9ca-5b9200962a57', 'b8d8cb01-409e-5638-a6a4-3ab2a206d7a0', 5, 5, 'ዔሳውም ዐይኑን አነሣና ሴቶችንና ልጆችን አየ፤ እንዲህም አለ፥ “እነዚህ ምኖችህ ናቸው?” እርሱም፥ “እግዚአብሔር ለእኔ ለአገልጋይህ የሰጠኝ ልጆች ናቸው” አለ።'),
  ('3b24691a-5968-5966-a7cb-b2994beb5614', '2869276e-5c02-55b1-a9ca-5b9200962a57', 'b8d8cb01-409e-5638-a6a4-3ab2a206d7a0', 6, 6, 'ዕቁባቶቹም ከልጆቻቸው ጋር ቀርበው ሰገዱ፤'),
  ('df5ccc8a-1296-5fba-ac27-e5582736a03a', '2869276e-5c02-55b1-a9ca-5b9200962a57', 'b8d8cb01-409e-5638-a6a4-3ab2a206d7a0', 7, 7, 'ደግሞም ልያና ልጆችዋ ቀርበው ሰገዱለት፤ ከዚያም በኋላ ዮሴፍና ራሔል ቀርበው ሰገዱ።'),
  ('3adb59d1-8c9d-5aa6-a62c-1b1180eb87a9', '2869276e-5c02-55b1-a9ca-5b9200962a57', 'b8d8cb01-409e-5638-a6a4-3ab2a206d7a0', 8, 8, 'ዔሳውም፥ “ያገኘሁት ይህ ሠራዊት ሁሉ ምንህ ነው?” አለ። እርሱም፥ “በጌታዬ ፊት ሞገስን አገኝ ዘንድ ያደረግሁልህ ነው” አለ።'),
  ('a4a6747d-6205-5633-ace9-a8260ecf7cd0', '2869276e-5c02-55b1-a9ca-5b9200962a57', 'b8d8cb01-409e-5638-a6a4-3ab2a206d7a0', 9, 9, 'ዔሳውም፥ “ለእኔ ብዙ አለኝ፤ ወንድሜ ሆይ፥ የአንተ ለአንተ ይሁን” አለ።'),
  ('4a1a5073-0612-5780-a3bd-7a815e51b37f', '2869276e-5c02-55b1-a9ca-5b9200962a57', 'b8d8cb01-409e-5638-a6a4-3ab2a206d7a0', 10, 10, 'ያዕቆብም አለ፥ “እንደዚህ አይደለም፤ ነገር ግን በፊትህ ሞገስን አግኝቼ እንደ ሆንሁ እጅ መንሻዬን ከእጄ ተቀበለኝ፤ የእግዚአብሔርን ፊት እንደሚያይ ፊትህን አይቻለሁና፥ በቸርነትም ተቀብለኸኛልና።'),
  ('fe67ef36-f0b5-57dd-acaf-7911bc5fca96', '2869276e-5c02-55b1-a9ca-5b9200962a57', 'b8d8cb01-409e-5638-a6a4-3ab2a206d7a0', 11, 11, 'ከወደድኸኝስ ይህችን ያመጣሁልህን በረከቴን ተቀበል፤ እግዚአብሔር ራርቶልኛልና፥ ለእኔም ብዙ አለኝና።” እስኪቀበለውም ድረስ ግድ አለው፤ ተቀበለውም።'),
  ('a9062d22-abf4-5f6f-a899-4f89a81412de', '2869276e-5c02-55b1-a9ca-5b9200962a57', 'b8d8cb01-409e-5638-a6a4-3ab2a206d7a0', 12, 12, 'እርሱም፥ “ተነሣና ወደ ፊት እንሂድ” አለው።'),
  ('71ce3a96-9328-5c58-a9f3-58b7d6d27ad2', '2869276e-5c02-55b1-a9ca-5b9200962a57', 'b8d8cb01-409e-5638-a6a4-3ab2a206d7a0', 13, 13, 'እርሱም አለው፥ “ጌታዬ ሆይ፥ ልጆቹ ደካሞች እንደ ሆኑ ታውቃለህ፤ በጎችና ላሞችም ግልገሎቻቸውን ያጠባሉ፤ ሰዎችም በአንድ ወይም በሁለት ቀን በችኮላ የነዱአቸው እንደ ሆነ ከብቶቹ ሁሉ ይሞታሉ።'),
  ('0477f87f-05cd-5325-a506-a0472ea3fca0', '2869276e-5c02-55b1-a9ca-5b9200962a57', 'b8d8cb01-409e-5638-a6a4-3ab2a206d7a0', 14, 14, 'ጌታዬ ከአገልጋዩ ፊት ቀድሞ ይለፍ፤ እኛም እንደ ቻልን እንሄዳለን፤ በጎዳናም እንውላለን፤ ወደ ጌታችን ወደ ሴይር እስክንደርስም በሕፃናቱ ርምጃ መጠን እንሄዳለን” አለው።'),
  ('cc105fa1-8e16-559a-a8ca-66b68397aa9d', '2869276e-5c02-55b1-a9ca-5b9200962a57', 'b8d8cb01-409e-5638-a6a4-3ab2a206d7a0', 15, 15, 'ዔሳውም፥ “ከእኔ ጋር ካሉ ሰዎች ከፍዬ ልተውልህን?” አለ። እርሱም፥ “ይህ ለምንድን ነው? በጌታዬ ዘንድ ሞገስን ማግኘቴ ይበቃኛል” አለ።'),
  ('e517f91d-6118-59ac-a70f-3c41311be6eb', '2869276e-5c02-55b1-a9ca-5b9200962a57', 'b8d8cb01-409e-5638-a6a4-3ab2a206d7a0', 16, 16, 'ዔሳውም በዚያ ቀን ወደ ሴይር ተመለሰ።'),
  ('31c41b77-66bc-5e1f-ae88-e035b66fd7f4', '2869276e-5c02-55b1-a9ca-5b9200962a57', 'b8d8cb01-409e-5638-a6a4-3ab2a206d7a0', 17, 17, 'ያዕቆብ ግን በሰፈሩ አደረ፤ በዚያም ለእርሱ ቤትን ሠራ፤ ለከብቶቹም ዳሶችን አደረገ፤ ስለዚህም የዚያን ቦታ ስም ማኅደር ብሎ ጠራው።'),
  ('e187d35d-f1ff-5f4e-ad1b-056dd3bf20bc', '2869276e-5c02-55b1-a9ca-5b9200962a57', 'b8d8cb01-409e-5638-a6a4-3ab2a206d7a0', 18, 18, 'ያዕቆብም ከሁለቱ ወንዞች መካከል በተመለሰ ጊዜ በከነዓን ምድር ወዳለችው ወደ ሰቂሞን ከተማ ወደ ሴሎም መጣ፤ በከተማዪቱም ፊት ለፊት ሰፈረ።'),
  ('e84affd6-06f3-5414-ae92-9369b8127dab', '2869276e-5c02-55b1-a9ca-5b9200962a57', 'b8d8cb01-409e-5638-a6a4-3ab2a206d7a0', 19, 19, 'ድንኳኑን ተክሎበት የነበረውንም የእርሻ ክፍል ከሴኬም አባት ከኤሞር ልጆች በመቶ በጎች ገዛው።'),
  ('b6f30e52-d7cb-51ac-aae6-7e6d500d6eaf', '2869276e-5c02-55b1-a9ca-5b9200962a57', 'b8d8cb01-409e-5638-a6a4-3ab2a206d7a0', 20, 20, 'በዚያም መሠውያዉን አቆመ፤ የእስራኤልንም አምላክ ጠራ።'),
  ('52f1a1b1-3cb9-5228-adc9-0a4a839b66e0', '90925ae1-848c-562e-a257-9dd6d175f9a6', 'c932bdb5-080f-573b-a163-3eca4818e562', 1, 1, 'ለያዕቆብ የተወለደች የልያ ልጅ ዲናም የዚያን ሀገር ሴቶች ልጆችን ለማየት ወጣች።'),
  ('c808dba7-25b5-5c7b-a9a2-eb68611b2271', '90925ae1-848c-562e-a257-9dd6d175f9a6', 'c932bdb5-080f-573b-a163-3eca4818e562', 2, 2, 'የሀገሩ አለቃ የኤዊያዊው ሰው የኤሞር ልጅ ሴኬም አያት፤ ወሰዳትም፤ ከእርስዋም ጋር ተኛ፤ አስነወራትም።'),
  ('c3fa37f3-dbcb-5e5e-a261-fbfcdbe162d7', '90925ae1-848c-562e-a257-9dd6d175f9a6', 'c932bdb5-080f-573b-a163-3eca4818e562', 3, 3, 'ልቡናውም በያዕቆብ ልጅ በዲና ፍቅር ተነደፈ፤ ብላቴናዪቱንም ወደዳት፤ ልብዋንም ደስ በሚያሰኛት ነገር ተናገራት።'),
  ('1bfb1347-d2e9-5db6-af09-f89190674a67', '90925ae1-848c-562e-a257-9dd6d175f9a6', 'c932bdb5-080f-573b-a163-3eca4818e562', 4, 4, 'ሴኬምም አባቱን ኤሞርን፥ “ይህችን ብላቴና አጋባኝ” ብሎ ነገረው።'),
  ('f68a2ce5-ec83-513a-a067-ee304e8d7460', '90925ae1-848c-562e-a257-9dd6d175f9a6', 'c932bdb5-080f-573b-a163-3eca4818e562', 5, 5, 'ያዕቆብም ልጁን ዲናን የኤሞር ልጅ እንዳስነወራት ሰማ፤ ልጆቹም ከከብቶቻቸው ጋር በምድረ በዳ ነበሩ፤ ያዕቆብም ልጆቹ እስኪመጡ ድረስ ዝም አለ።'),
  ('4e8377ed-2a43-5f61-acbf-b3a00e3da726', '90925ae1-848c-562e-a257-9dd6d175f9a6', 'c932bdb5-080f-573b-a163-3eca4818e562', 6, 6, 'የሴኬም አባት ኤሞርም ይነግረው ዘንድ ወደ ያዕቆብ መጣ።'),
  ('6a710fbb-ac56-5fd4-ac15-a6c18bd267cf', '90925ae1-848c-562e-a257-9dd6d175f9a6', 'c932bdb5-080f-573b-a163-3eca4818e562', 7, 7, 'የያዕቆብም ልጆች ከምድረ በዳ መጡ፤ ይህንም በሰሙ ጊዜ ፈጽመው ደነገጡ፤ የያዕቆብን ልጅ በመተኛቱ በእስራኤል ላይ ኀፍረትን ስላደረገ አዘኑ፤ እጅግም ተቈጡ፤ እንዲህ አይደረግምና።'),
  ('68a712e1-236c-56a8-a2e3-ba84ce21b76b', '90925ae1-848c-562e-a257-9dd6d175f9a6', 'c932bdb5-080f-573b-a163-3eca4818e562', 8, 8, 'ኤሞርም እንዲህ ብሎ ነገራቸው፥ “ልጄ ሴኬም ልጃችሁን ወዶአታልና ሚስት እንድትሆነው እርስዋን ስጡት።'),
  ('40b2ddf6-c9e5-5203-a03b-9261bc466a5b', '90925ae1-848c-562e-a257-9dd6d175f9a6', 'c932bdb5-080f-573b-a163-3eca4818e562', 9, 9, 'ጋብቾችም ሁኑን፤ ሴቶች ልጆቻችሁን ስጡን፤ እናንተም የእኛን ሴቶች ልጆች ለልጆቻችሁ ውሰዱ።'),
  ('7477fbaa-6be4-5a48-a088-f2511ebc5e30', '90925ae1-848c-562e-a257-9dd6d175f9a6', 'c932bdb5-080f-573b-a163-3eca4818e562', 10, 10, 'ከእኛም ጋር ተቀመጡ፤ ምድራችንም በፊታችሁ ሰፊ ናት፤ ኑሩባት፤ ነግዱም፤ ግዙአትም።”'),
  ('055d4f7a-f868-5553-a0e7-46194df9e0c0', '90925ae1-848c-562e-a257-9dd6d175f9a6', 'c932bdb5-080f-573b-a163-3eca4818e562', 11, 11, 'ሴኬምም አባቷንና ወንድሞችዋን እንዲህ አለ፥ “በፊታችሁ ሞገስን በአገኝ የምትሉትን ሁሉ እሰጣለሁ።'),
  ('9c774f9b-66cd-5ad1-a46e-6c7c8757bbc0', '90925ae1-848c-562e-a257-9dd6d175f9a6', 'c932bdb5-080f-573b-a163-3eca4818e562', 12, 12, 'ብዙ ማጫ አምጣ በሉኝ፤ በምትጠይቁኝም መጠን እሰጣለሁ፤ ይህችን ብላቴና ግን ሚስት ትሆነኝ ዘንድ ስጡኝ።”'),
  ('615eb500-76ea-5d3b-ab37-2cf1938953f7', '90925ae1-848c-562e-a257-9dd6d175f9a6', 'c932bdb5-080f-573b-a163-3eca4818e562', 13, 13, 'የያዕቆብም ልጆች ለሴኬምና ለአባቱ ለኤሞር በተንኰል መለሱ፤ እኅታቸውን ዲናን አስነውሮአታልና፤'),
  ('e3f9fcd2-a957-5f78-abf9-7458b522bacd', '90925ae1-848c-562e-a257-9dd6d175f9a6', 'c932bdb5-080f-573b-a163-3eca4818e562', 14, 14, 'የዲና ወንድሞች ስምዖንና ሌዊም እንዲህ አሉአቸው፥ “እኅታችንን ላልተገረዘ ሰው ለመስጠት ይህን ነገር እናደርግ ዘንድ አይቻለንም፤ ይህ ነውር ይሆንብናልና።'),
  ('05c998a6-22e8-53a1-a839-a3f0875eef78', '90925ae1-848c-562e-a257-9dd6d175f9a6', 'c932bdb5-080f-573b-a163-3eca4818e562', 15, 15, 'እናንተም እንደ እኛ ወንዶቻችሁን ሁሉ ብትገርዙ በዚህ ብቻ እንመስላችኋለን፤ ከእናንተም ጋር እንኖራለን፤'),
  ('dae2afa1-27af-53ee-a313-1a613e2578e1', '90925ae1-848c-562e-a257-9dd6d175f9a6', 'c932bdb5-080f-573b-a163-3eca4818e562', 16, 16, 'ሴቶች ልጆቻችንንም እንሰጣችኋለን፤ የእናንተንም ሴቶች ልጆች ለሚስትነት እንወስዳለን፤ አንድ ሕዝብም ሆነን ከእናንተ ጋር እንኖራለን።'),
  ('f8907e2c-ca81-570d-ad89-e6750a47c1df', '90925ae1-848c-562e-a257-9dd6d175f9a6', 'c932bdb5-080f-573b-a163-3eca4818e562', 17, 17, 'ትገረዙ ዘንድ እኛን ባትሰሙ ግን ልጃችንን ይዘን እንሄዳለን።”'),
  ('7f91f6d2-0b3a-5dcb-ac7b-4ff1fb9d7fb0', '90925ae1-848c-562e-a257-9dd6d175f9a6', 'c932bdb5-080f-573b-a163-3eca4818e562', 18, 18, 'ነገራቸውም ኤሞርንና የኤሞርን ልጅ ሴኬምን ደስ አሰኛቸው።'),
  ('8c2764d5-ab3d-59d5-a472-4df5c6f981bf', '90925ae1-848c-562e-a257-9dd6d175f9a6', 'c932bdb5-080f-573b-a163-3eca4818e562', 19, 19, 'ብላቴናውም ይህን ነገር ያደርግ ዘንድ አልዘገየም፤ የያዕቆብን ልጅ ወድዶአልና፤ እርሱም ከአባቱ ቤተ ሰብእ ሁሉ የከበረ ነበረ።')
